    pthread_mutex_lock(&config_lock);

    if (config == NULL || config->ports == NULL) {
        // Handle edge case where configuration is invalid or not initialized
        pthread_mutex_unlock(&config_lock);
        return;
    }

    int new_size = config->num_ports + 1;
    struct port_config** new_ports = (struct port_config**) realloc(config->ports, sizeof(struct port_config*) * new_size);

    if (new_ports == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&config_lock);
        return;
    }

    config->ports = new_ports;
    config->num_ports = new_size;
    config->ports[config->num_ports - 1] = port;

    pthread_mutex_unlock(&config_lock);
}

void remove_port_configuration(NetworkInterfaceConfig* config, int port_number) {
    pthread_mutex_lock(&config_lock);

    if (config == NULL || config->ports == NULL || port_number < 0 || port_number >= config->num_ports) {
        // Handle edge case where configuration is invalid or port number is out of bounds
        pthread_mutex_unlock(&config_lock);
        return;
    }

    int i;
    for (i = port_number; i < config->num_ports - 1; i++) {
        config->ports[i] = config->ports[i + 1];
    }

    free(config->ports[config->num_ports - 1]);
    config->num_ports--;
    config->ports = (struct port_config**) realloc(config->ports, sizeof(struct port_config*) * config->num_ports);

    pthread_mutex_unlock(&config_lock);
}

