#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024
#define SUMMARY_REPORT_FILE "summary_report.txt"

int main(int argc, char *argv[]) {
    int lineCount = 0;
    FILE *outputFile = NULL;
    int processFlag = 0;

    // Parse command-line flags
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            usage();
            return 0;
        } else if (strcmp(argv[i], "-l") == 0 || strcmp(argv[i], "--lines") == 0) {
            processFlag |= 1;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            outputFile = fopen(argv[++i], "w");
            if (outputFile == NULL) {
                perror("Error opening output file");
                return 1;
            }
        }
    }

    // Process input files
    for (int i = 1; i < argc; i++) {
        FILE *file = fopen(argv[i], "r");
        if (file == NULL) {
            perror("Error opening file");
            continue;
        }

        int skippedLines = 0;
        char line[MAX_LINE_LENGTH];
        while (fgets(line, MAX_LINE_LENGTH, file)) {
            // Process the line
            if (processFlag & 1) {
                printf("%s", line);
            }

            if (strlen(line) > MAX_LINE_LENGTH) {
                skippedLines++;
            } else {
                lineCount++;
            }
        }

        fclose(file);

        if (outputFile != NULL) {
            fprintf(outputFile, "%d lines processed\n", lineCount - skippedLines);
            fprintf(outputFile, "%d lines skipped due to exceeding maximum length\n", skippedLines);
        }
    }

    // Generate summary report
    FILE *summaryReport = fopen(SUMMARY_REPORT_FILE, "w");
    if (summaryReport == NULL) {
        perror("Error opening summary report file");
        return 1;
    }

    fprintf(summaryReport, "Total lines processed: %d\n", lineCount);
    fclose(summaryReport);

    return 0;
}

void usage() {
    printf("Usage: %s [-h|--help] [-l|--lines] [-o|--output output_file]\n", argv[0]);
}
