        printf("Error opening file\n");
        return;
    }

    while (1) {
        char line[1024];
        if (!fgets(line, 1024, file)) break;

        char hostname[64], ip_addr[16];
        int latency, bandwidth;

        // Extract values from the CSV file
        sscanf(line, "%63s,%15s,%d,%d", hostname, ip_addr, &latency, &bandwidth);

        if (strlen(hostname) == 0 || strlen(ip_addr) == 0) {
            printf("Error parsing CSV line\n");
            continue;
        }

        // Perform DNS resolution for the given hostname
        struct hostent* entry = gethostbyname(hostname);
        if (!entry) {
            printf("DNS resolution failed: %s\n", hostname);

            // Check local cache for IP address
            // ...

            continue;
        }

        Node* node = (Node*) malloc(sizeof(Node));
        node->hostname = strdup(hostname);
        node->ip = (u_char*) strdup((char*) inet_ntoa(*(struct in_addr*) entry->h_addr));
        node->bandwidth = bandwidth;

        if (!head) head = node;
        else {
            Node* temp = head;
            while (temp->next) temp = temp->next;
            temp->next = node;
        }
    }

    fclose(file);
}

