int* array;
size_t array_size = 0;

int main() {
    // Initialize an empty array and continue reading values until user decides to stop.
    array = NULL;

    while (1) {
        int val = read_int();
        if (!val)
            break;

        // Validate the value
        if (!(val >= -1000 && val <= 1000)) {
            fprintf(stderr, "Error: Out of range\n");
            free_array(&array);
            exit(1);
        }

        array = safe_realloc(array, ++array_size * sizeof(int));
        *(array + array_size - 1) = val;
    }

    // Find and print the largest integer
    int max_int = find_max_int(array, array_size);
    printf("Largest integer: %d\n", max_int);

    // Find and print the smallest float
    float min_float = find_min_float(array, array_size);
    printf("Smallest float: %.2f\n", min_float);

    free_array(&array);
    return 0;
}

// Read an integer from standard input
int read_int() {
    int val;
    scanf("%d", &val);
    return val;
}

// Read a float from standard input
float read_float() {
    float val;
    scanf("%f", &val);
    return val;
}

// Safely allocate memory for the array
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);

    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(1);
    }

    return ptr;
}

// Safely reallocate the array
void* safe_realloc(void* ptr, size_t size) {
    ptr = realloc(ptr, size);

    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(1);
    }

    return ptr;
}

// Free the array and its memory
void free_array(void** array) {
    free(*array);
    *array = NULL;
}
