#define LOG_MAX_LENGTH 1024
#define RATE_LIMIT_INTERVAL 1000 // in milliseconds
#define RATE_LIMIT_QUOTA 10

typedef enum {
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

// Global variables for rate limiting and thread safety
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static int current_log_quota = 0;
static clock_t last_log_timestamp = 0;

void log_message(LogLevel level, const char *format, ...) {
    // Acquire the mutex to ensure thread safety
    pthread_mutex_lock(&log_mutex);

    // Check rate limiting and quota management
    if (clock() - last_log_timestamp < RATE_LIMIT_INTERVAL / 1000.0) {
        current_log_quota--;
        if (current_log_quota <= 0) {
            printf("Rate limit exceeded! Waiting for %d ms...\n",
                   RATE_LIMIT_INTERVAL - (clock() - last_log_timestamp));
            // Simulate delay to prevent overwhelming the logging infrastructure
            usleep((RATE_LIMIT_INTERVAL / 1000.0) * 1000);
            current_log_quota = RATE_LIMIT_QUOTA;
        }
    } else {
        current_log_quota = RATE_LIMIT_QUOTA;
        last_log_timestamp = clock();
    }

    // Log the message based on its level and priority
    if (level == LOG_LEVEL_ERROR) {
        printf("CRITICAL: ");
    } else if (level == LOG_LEVEL_WARNING) {
        printf("WARNING: ");
    }
    va_list args;
    va_start(args, format);
    vsnprintf((char *)malloc(LOG_MAX_LENGTH), LOG_MAX_LENGTH, format, args);
    va_end(args);

    // Release the mutex
    pthread_mutex_unlock(&log_mutex);
}

