import yaml
import os
import datetime
import subprocess
import logging

class NetworkConfigManager:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config = self.read_config()
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def read_config(self):
        try:
            with open(self.config_file, 'r') as f:
                return yaml.safe_load(f)
        except FileNotFoundError:
            return {}

    def write_config(self):
        with open(self.config_file, 'w') as f:
            yaml.dump(self.config, f)

    def backup_config(self):
        timestamp = datetime.datetime.now().strftime('%Y-%m-%d_%H-%M-%S')
        backup_file = f'{self.config_file}.bak.{timestamp}'
        os.rename(self.config_file, backup_file)
        self.logger.info(f'Config backed up to {backup_file}')

    def apply_config(self):
        for interface, settings in self.config.items():
            command = f'setup_interface_{interface}( )'
            try:
                subprocess.run(command.split(), check=True)
            except subprocess.CalledProcessError as e:
                self.logger.error(f'Failed to set up {interface}: {e}')
            else:
                self.logger.info(f'Successfully set up {interface}')

    def update_config(self):
        while True:
            user_input = input('Enter interface name (or "quit" to exit): ')
            if user_input.lower() == 'quit':
                break
            try:
                settings = {'interface': user_input}
                for key, value in self.config.get(user_input, {}).items():
                    if key not in ['ip', 'subnet_mask']:
                        continue
                    command = f'configure_{key}_{user_input}({value})'
                    subprocess.run(command.split(), check=True)
                    self.config[user_input][key] = value
                self.write_config()
            except KeyError:
                print(f'{user_input} is not a valid interface.')
            except Exception as e:
                self.logger.error(f'Failed to update {user_input}: {e}')
        self.apply_config()

def main():
    manager = NetworkConfigManager('network_config.yml')
    try:
        manager.backup_config()
        manager.update_config()
    except KeyboardInterrupt:
        print('\nInterrupted. Backing up and exiting.')
        manager.backup_config()
    except Exception as e:
        print(f'\nError: {e}')
        manager.backup_config()

if __name__ == '__main__':
    main()
