    int i;
    for (i = 0; i < sizeof(Algorithm) / sizeof(Algorithm); i++) {
        printf("Algorithm: %s, Speed: %d, Security Level: %d, Compatibility: %d\n", 
              algorithms[i].name, algorithms[i].speed, algorithms[i].security_level, algorithms[i].compatibility);
    }
}

int compare_algorithms(const void *a, const void *b) {
    Algorithm* algorithm_a = (Algorithm*)a;
    Algorithm* algorithm_b = (Algorithm*)b;

    if (algorithm_a->security_level > algorithm_b->security_level)
        return -1;
    else if (algorithm_a->security_level < algorithm_b->security_level)
        return 1;

    // If security level is the same, prioritize algorithms with higher speed
    if (algorithm_a->speed > algorithm_b->speed)
        return -1;
    else if (algorithm_a->speed < algorithm_b->speed)
        return 1;

    // If speed is the same, prioritize algorithms with higher compatibility
    if (algorithm_a->compatibility > algorithm_b->compatibility)
        return -1;
    else if (algorithm_a->compatibility < algorithm_b->compatibility)
        return 1;

    return 0;
}
