#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    pthread_mutex_t mutex;
    int value;
    int timeout_acquire;
    int timeout_release;
} semaphore_t;

semaphore_t* create_semaphore(int initial_value, int timeout_acquire, int timeout_release) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    sem->value = initial_value;
    sem->timeout_acquire = timeout_acquire;
    sem->timeout_release = timeout_release;
    pthread_mutex_init(&sem->mutex, NULL);
    return sem;
}

void destroy_semaphore(semaphore_t* sem) {
    pthread_mutex_destroy(&sem->mutex);
    free(sem);
}

int acquire_semaphore(semaphore_t* sem) {
    struct timespec timeout;
    int ret = pthread_mutex_lock_timeout(&sem->mutex, &timeout, sem->timeout_acquire);
    if (ret == 0) {
        if (--sem->value <= 0) {
            return -1; // Semaphore is exhausted
        }
    } else if (ret > 0) {
        return ret; // Timeout exceeded
    }
    return 0;
}

int release_semaphore(semaphore_t* sem) {
    struct timespec timeout;
    int ret = pthread_mutex_unlock_timeout(&sem->mutex, &timeout, sem->timeout_release);
    if (ret == 0) {
        ++sem->value;
    } else if (ret > 0) {
        return ret; // Timeout exceeded
    }
    return 0;
}

int main() {
    semaphore_t* sem = create_semaphore(5, 1000, 500);

    // Use the semaphore...

    destroy_semaphore(sem);
    return 0;
}
