using System;
using System.Collections.Generic;
using System.IO;
using System.Xml;
using System.Xml.XPath;

public class ConfigLoader
{
    private static readonly Dictionary<string, XPathNodeIterator> _configCache = new Dictionary<string, XPathNodeIterator>();

    public static Dictionary<string, string> LoadConfigFromXML(string filePath, string configSectionName)
    {
        try
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException($"The file {filePath} does not exist.");

            XmlDocument doc = new XmlDocument();
            doc.Load(filePath);

            XPathDocument xpathDoc = new XPathDocument(doc);
            XPathNavigator nav = xpathDoc.CreateNavigator();

            XPathExpression expr = nav.Compile("/" + configSectionName);
            XPathNodeIterator iterator = expr.Evaluate();

            Dictionary<string, string> configSettings = new Dictionary<string, string>();

            while (iterator.MoveNext())
            {
                XPathElement element = (XPathElement)iterator.Current;
                foreach (XPathNavigator child in element.GetElementsByTagName("*"))
                {
                    configSettings.Add(child.Name, child.Value);
                }
            }

            return configSettings;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading config from XML file: {ex.Message}");
            throw;
        }
    }
}
