import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class MD5Cache {
    private ConcurrentHashMap<String, String> cache;
    private AtomicInteger sizeLimit;
    private int maxSize;
    private int maxStringsPerSecond;

    public MD5Cache(int maxSize, int maxStringsPerSecond) {
        this.cache = new ConcurrentHashMap<>();
        this.sizeLimit = new AtomicInteger(maxSize);
        this.maxSize = maxSize;
        this.maxStringsPerSecond = maxStringsPerSecond;
    }

    public void processBatch(String[] strings) {
        for (String s : strings) {
            try {
                String hash = computeMD5Hash(s);
                if (!cache.containsKey(hash)) {
                    cache.putIfAbsent(hash, s);
                    sizeLimit.getAndIncrement();
                }
                logOperation("Cached " + s);
            } catch (Exception e) {
                logError("Failed to process string: " + s, e);
            }
        }
    }

    private String computeMD5Hash(String s) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = s.getBytes();
        return bytesToHex(md.digest(bytes));
    }

    private String bytesToHex(byte[] bytes) {
