    public class UserManagementSystem : IUserManagementSystem
    {
        private readonly UserManager<IdentityUser> _userManager;
        private readonly RoleManager<IdentityRole> _roleManager;
        private readonly ITenantConfigurationService _tenantConfigService;
        private readonly ILogger<UserManagementSystem> _logger;

        public UserManagementSystem(UserManager<IdentityUser> userManager, RoleManager<IdentityRole> roleManager, ITenantConfigurationService tenantConfigService, ILogger<UserManagementSystem> logger)
        {
            _userManager = userManager;
            _roleManager = roleManager;
            _tenantConfigService = tenantConfigService;
            _logger = logger;
        }

        public async Task ManageUserAsync(string userName, string password, int? lockoutDurationMinutes, int? failedLoginAttemptsThreshold, int? alertThreshold)
        {
            var user = await _userManager.FindByNameAsync(userName);
            if (user == null) throw new InvalidOperationException($"User {userName} not found");

            // Configure account and password policies based on tenant settings
            var policy = await GetTenantPolicyAsync(user.TenantId);

            // Update username and password policies as needed
            user.PasswordHash = await _userManager.PasswordHasher.HashPasswordAsync(password);
            user.UserName = policy.UsernamePolicy;

            if (lockoutDurationMinutes.HasValue)
                await LockUserAsync(user, lockoutDurationMinutes.Value);

            // Configure failed login attempts threshold
            if (failedLoginAttemptsThreshold.HasValue)
                await SetFailedLoginAttemptsThresholdAsync(user, failedLoginAttemptsThreshold.Value);

            // Configure alert threshold for lockout events
            if (alertThreshold.HasValue)
                await SetAlertThresholdAsync(user, alertThreshold.Value);
        }

        public async Task LogUserInteractionAsync(UserLog logType, string userName, DateTime timestamp)
        {
            // Log successful and unsuccessful login attempts, password updates, and account modifications
            await _logger.LogInformationAsync($"User {userName} logged in {(logType == UserLog.Success ? "successfully" : "unsuccessfully")} at {timestamp}");
        }

        public async Task LockUserAsync(IdentityUser user, int lockoutDurationMinutes)
        {
            // Implement flexible lockout mechanism with configurable parameters
            await _userManager.SetLockoutEnabledAsync(user, true);
            await _userManager.SetLockoutEndDateAsync(user, DateTime.UtcNow.AddMinutes(lockoutDurationMinutes));
        }

        public async Task SetFailedLoginAttemptsThresholdAsync(IdentityUser user, int threshold)
        {
            // Configure failed login attempts threshold
            await _userManager.SetFailedLoginAttemptsAsync(user, threshold);
        }

        public async Task SetAlertThresholdAsync(IdentityUser user, int threshold)
        {
            // Configure alert threshold for lockout events
            await _userManager.SetAlertThresholdAsync(user, threshold);
        }

        private async Task<TenantPolicy> GetTenantPolicyAsync(string tenantId)
        {
            // Retrieve custom policy settings from database or external service
            var tenantPolicy = await _tenantConfigService.GetTenantPolicyAsync(tenantId);
            return tenantPolicy;
        }
    }

    public enum UserLog
    {
        Success,
        Failure
    }
}
