const fs = require('fs');
const path = require('path');

function processFiles(directory, supportedExtensions) {
  return new Promise((resolve, reject) => {
    let successfulCount = 0;
    let unsuccessfulCount = 0;

    fs.readdir(directory, (err, files) => {
      if (err) {
        reject(`Error reading directory: ${err.message}`);
        return;
      }

      const promises = files.map(file => {
        const filePath = path.join(directory, file);
        const stat = fs.statSync(filePath);

        if (!stat.isDirectory() && supportedExtensions.includes(path.extname(file))) {
          return fs.readFile(filePath, 'utf8').then(content => {
            successfulCount++;
            return content;
          }).catch(err => {
            unsuccessfulCount++;
            console.error(`Error reading file: ${file} - ${err.message}`);
          });
        } else {
          return Promise.resolve();
        }
      });

      Promise.all(promises).then(contents => {
        const concatenatedContent = contents.reduce((acc, content) => acc + content, '');
        resolve({ successfulCount, unsuccessfulCount, concatenatedContent });
      }).catch(err => {
        reject(`Error processing files: ${err.message}`);
      });
    });
  });
}

module.exports = processFiles;
