function executeTests(label, f, timeout, maxConcurrency) {
  const require = require('require');
  const { log } = require('./logger');
  const blueSlip = require('./blueslip');
  const testReporter = require('./test-reporter');

  async function runTest(testName) {
    try {
      await f();
      return 'pass';
    } catch (error) {
      if (error.name === 'TimeoutError') {
        throw error;
      }
      return 'fail';
    } finally {
      blueSlip.reset();
    }
  }

  async function executeTestsParallel(maxConcurrency, tests) {
    const concurrencyQueue = [];
    let inProgress = 0;

    for (const test of tests) {
      if (inProgress >= maxConcurrency) {
        await new Promise((resolve) => setTimeout(resolve, 100));
      } else {
        inProgress++;
      }

      concurrencyQueue.push(test);
    }

    while (concurrencyQueue.length > 0) {
      const testName = concurrencyQueue.shift();
      try {
        const result = await runTest(testName);
        log.info(`Test ${testName} ${result}`);
      } catch (error) {
        log.error(`Test ${testName} failed: ${error}`);
        throw error;
      } finally {
        inProgress--;
      }
    }
  }

  async function executeModuleTests(label, tests, timeout, maxConcurrency) {
    try {
      const module = await require(label);
      await executeTestsParallel(maxConcurrency, tests.map((test) => test.label));
    } catch (error) {
      log.error(`Error loading module ${label}: ${error}`);
      throw error;
    }
  }

  async function runModuleTests() {
    try {
      const label = process.argv[2];
      if (!label) {
        log.error('No module label provided');
        return;
      }
      const tests = require('./test-collection')[label];
      if (!tests) {
        log.error(`No tests found for module ${label}`);
        return;
      }

      await executeModuleTests(label, tests, process.env.TEST_TIMEOUT || 30000, parseInt(process.env.MAX_CONCURRENCY, 10));
    } catch (error) {
      log.error(error);
      process.exit(1);
    }
  }

  runModuleTests();
}
