void processForwardList(std::forward_list<std::string>& list, int resourceID, const std::string& url) {
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == std::to_string(resourceID)) {
            HWND hWnd = ::GetParentWindow();
            SendMessage(hWnd, WM_USER_ACKNOWLEDGE, resourceID, reinterpret_cast<LPARAM>(url.c_str()));
            auto newIt = it;
            ++newIt;
            list.insert_after(it, url);
            break;
        }
    }
    if (list.empty() || std::none_of(list.begin(), list.end(), [resourceID](const std::string& s) { return s == std::to_string(resourceID); })) {
        list.append(url);
    }
}
