    public DynamicDataCollectionService(int numThreads, int queueCapacity) {
        this.executor = new ThreadPoolExecutor(numThreads, numThreads, 0, TimeUnit.MILLISECONDS);
        this.buffer = new LinkedBlockingQueue<>(queueCapacity);
    }

    public void start() {
        executor.execute(() -> {
            while (!isPaused) {
                String data = getDataFromSensors();
                buffer.put(data);
                try {
                    Thread.sleep(1); // Simulate processing time
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    public void pause() {
        isPaused = true;
        pauseDuration = System.currentTimeMillis();
    }

    public void resume() {
        isPaused = false;
        long duration = System.currentTimeMillis() - pauseDuration;
        sendNotifications(duration);
        executor.execute(() -> {
            while (!isPaused) {
                String data = buffer.take(); // Resume from where paused
                processAndStoreData(data);
                try {
                    Thread.sleep(1); // Simulate processing time
