const {
  EventEmitter,
  Transform,
} = require('stream');
const { 
  EventEmitter: { on }, 
  createWriteStream 
} = require('fs');

class DataAggregator extends Transform {
  constructor(options) {
    super({
      writableObjectMode: true,
    });
    this.options = options;
    this.streams = [];
    this.bufferSize = options.bufferSize || 1024 * 1024; // default buffer size
    this.dataTypes = options.dataTypes || ['json', 'buffer'];
    this.retryPolicy = options.retryPolicy || { retries: 3, delay: 100 };
  }

  _transform(chunk, encoding, callback) {
    this.streams.forEach((stream) => stream.emit('data', chunk));
    callback();
  }

  addStream(stream) {
    stream.pipe(this);
    this.streams.push(stream);
  }

  removeStream(stream) {
    stream.unpipe(this);
    this.streams = this.streams.filter((s) => s !== stream);
  }
}

class StreamBuffer extends Transform {
  constructor(options) {
    super({
      writableObjectMode: true,
    });
    this.bufferSize = options.bufferSize || this.bufferSize;
    this.dataType = options.dataType || 'buffer';
    this.maxBuffer = Buffer.alloc(this.bufferSize);
  }

  _transform(chunk, encoding, callback) {
    if (this.dataType === 'json') {
      try {
        const jsonData = JSON.parse(chunk.toString());
        this.push(Buffer.from(jsonData));
      } catch (error) {
        // invalid JSON, skip
      }
    } else {
      this.maxBuffer.write(chunk);
    }
    callback();
  }

  drain() {
    this.push(this.maxBuffer);
    this.maxBuffer = Buffer.alloc(this.bufferSize);
  }
}

class DataProcessor extends Transform {
  constructor(options) {
    super({
      writableObjectMode: true,
    });
    this.dataTypes = options.dataTypes || ['json', 'buffer'];
  }

  _transform(chunk, encoding, callback) {
    if (this.dataTypes.includes('json')) {
      try {
        const jsonData = JSON.parse(chunk.toString());
        // process JSON data
      } catch (error) {
        // invalid JSON, skip
      }
    } else {
      // process buffer data
    }
    callback();
  }
}

class DataWriter extends Transform {
  constructor(options) {
    super({
      writableObjectMode: true,
    });
    this.filePath = options.filePath;
  }

  _transform(chunk, encoding, callback) {
    createWriteStream(this.filePath)
      .write(chunk, (error) => {
        if (error) {
          // handle write error
        }
      });
    callback();
  }
}

class DataAggregatorService {
  constructor(options) {
    this.aggregator = new DataAggregator(options);
    this.streamBuffers = [];
    this.dataProcessor = new DataProcessor(options);
    this.dataWriter = new DataWriter(options);
  }

  addStream(stream) {
    this.aggregator.addStream(stream);
  }

  removeStream(stream) {
    this.aggregator.removeStream(stream);
  }

  start() {
    this.aggregator.pipe(this.dataProcessor).pipe(this.dataWriter);
  }
}

// Example usage
