const { performance } = require('perf_hooks');
const cache = new Map();
const selectors = [];

class DOMTraverser {
  constructor({ mode = 'sync', cacheTTL = 30000, selectorTester = () => true }) {
    this.mode = mode;
    this.cacheTTL = cacheTTL;
    this.selectorTester = selectorTester;
  }

  async querySelectorAll(selector) {
    if (cache.has(selector)) {
      const cachedResult = await cache.get(selector);
      return cachedResult;
    }

    let result;

    switch (this.mode) {
      case 'sync':
        result = document.querySelectorAll(selector);
        break;
      case 'async':
        result = await Promise.all(
          Array.from(document.querySelectorAll(selector), (el) =>
            this.selectorTester(el)
              ? el
              : null
          )
        );
        break;
    }

    if (result.length > 0) {
      cache.set(selector, performance.now() + this.cacheTTL);
    } else {
      cache.delete(selector);
    }

    return result;
  }
}

module.exports = DOMTraverser;
