import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import javax.sql.DataSource;
import com.google.common.collect.Maps;

public class DatabaseConnection {

    private static final String JDBC_URL = "jdbc:postgresql://localhost:5432/mydatabase";
    private static final String DB_USER = "myuser";
    private static final String DB_PASSWORD = "mypassword";

    public static Connection establishConnection() throws SQLException {
        // Load the PostgreSQL JDBC driver
        Class.forName("org.postgresql.Driver");

        // Create a DataSource instance for connection pooling
        DataSource dataSource = Maps.newHashMap();
        dataSource.put("url", JDBC_URL);
        dataSource.put("user", DB_USER);
        dataSource.put("password", DB_PASSWORD);

        // Set idle timeout and maximum pool size
        ((BasicDataSource) dataSource).setValidationQuery("SELECT 1");
        ((BasicDataSource) dataSource).setTimeout(30000); // 30 seconds
        ((BasicDataSource) dataSource).setMaxActive(20);

        // Acquire a connection from the pool
        Connection conn = dataSource.getConnection();
        return conn;
    }

    public static void closeConnection(Connection conn) {
        try {
            conn.close();
        } catch (SQLException e) {
            // Handle error
        }
    }
}
