package com.example.theme.cache;

import android.graphics.Bitmap;
import android.os.Bundle;
import android.util.Log;
import androidx.annotation.NonNull;
import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;

public class ThemeCache {
    private static final String TAG = "ThemeCache";
    private static final int MAX_BITMAP_CACHE_SIZE = 100;
    private static final long MAX_CACHE_AGE = 30000L; // 30 seconds
    private static final String DEFAULT_THEME_DIR = "/default_theme";

    private Map<String, Bitmap> bitmapCache = new ConcurrentHashMap<>();
    private AtomicInteger cacheHits = new AtomicInteger(0);
    private AtomicInteger cacheMisses = new AtomicInteger(0);
    private Gson gson = new GsonBuilder().create();
    private File cacheDir;
    private Bundle themeConfig;

    public ThemeCache(Bundle themeConfig) {
        this.themeConfig = themeConfig;
        this.cacheDir = getCacheDir(themeConfig.getString("cache_dir"));
        loadCachedBitmaps();
    }

    private File getCacheDir(String cacheDirPath) {
        File cacheDir = new File(cacheDirPath);
        if (!cacheDir.exists()) {
            cacheDir.mkdirs();
        }
        return cacheDir;
    }

    public Bitmap getBitmap(@NonNull String themeId) {
        Bitmap bitmap = bitmapCache.get(themeId);
        if (bitmap != null) {
            cacheHits.incrementAndGet();
            Log.d(TAG, "Bitmap hit: " + themeId);
            return bitmap;
        } else {
            cacheMisses.incrementAndGet();
            Log.d(TAG, "Bitmap miss: " + themeId);
            return loadBitmapFromDisk(themeId);
        }
    }

    private Bitmap loadBitmapFromDisk(String themeId) {
        // Load bitmap from disk and recycle it
        File file = new File(cacheDir, themeId + ".bitmap");
        if (file.exists()) {
            try {
                return BitmapFactory.decodeFile(file.getAbsolutePath());
            } catch (Exception e) {
                Log.e(TAG, "Failed to load bitmap: " + e.getMessage());
            }
        }
        return null;
    }

    public void putBitmap(@NonNull String themeId, Bitmap bitmap) {
        bitmapCache.put(themeId, bitmap);
        // Store bitmap in cache dir
        File file = new File(cacheDir, themeId + ".bitmap");
        try {
            bitmap.compress(Bitmap.CompressFormat.WEBP, 100, new FileOutputStream(file));
        } catch (IOException e) {
            Log.e(TAG, "Failed to store bitmap: " + e.getMessage());
        }
    }

    public void invalidateBitmap(@NonNull String themeId) {
        bitmapCache.remove(themeId);
        // Remove cached bitmap file
        File file = new File(cacheDir, themeId + ".bitmap");
        if (file.exists()) {
            file.delete();
        }
    }

    public Bundle getThemeConfig() {
        return themeConfig;
    }

    private void loadCachedBitmaps() {
        // Load cached bitmaps from disk and populate cache
        File[] files = cacheDir.listFiles();
        for (File file : files) {
            try {
                Bitmap bitmap = BitmapFactory.decodeFile(file.getAbsolutePath());
                String themeId = file.getName().replace(".bitmap", "");
                putBitmap(themeId, bitmap);
            } catch (Exception e) {
                Log.e(TAG, "Failed to load cached bitmap: " + e.getMessage());
            }
        }
    }

    public void clearCache() {
        // Clear cache dir and bitmap cache
        for (File file : cacheDir.listFiles()) {
            file.delete();
        }
        bitmapCache.clear();
    }

    public Bundle getCacheStats() {
        Bundle bundle = new Bundle();
        bundle.putInt("hits", cacheHits.get());
        bundle.putInt("misses", cacheMisses.get());
        return bundle;
    }
}
