use tokio::net::TcpStream;
use reqwest::blocking::{get, put};
use hyper_tls::HttpsConnector;

async fn send_request(req: &RequestBuilder) -> Result<String, reqwest::Error> {
    let url = req.url.clone();
    match get(&url).send().await {
        Ok(response) => {
            if response.status().is_success() {
                return Ok(response.text().await.unwrap());
            } else {
                Err(reqwest::Error::new(400, "Invalid Request"))?;
            }
        }
        Err(err) => Err(err),
    };
}

async fn send_request_with_data(
    req: &RequestBuilder,
    data: &str,
) -> Result<String, reqwest::Error> {
    let url = req.url.clone();
    match put(&url).body(data).send().await {
        Ok(response) => {
            if response.status().is_success() {
                return Ok(response.text().await.unwrap());
            } else {
                Err(reqwest::Error::new(400, "Invalid Request"))?;
            }
        }
        Err(err) => Err(err),
    };
}

#[derive(Debug)]
pub struct RequestBuilder {
    pub method: reqwest::Method,
    pub url: String,
    pub headers: Vec<reqwest::header::HeaderValue>,
    pub timeout: u64,
    pub proxy_url: Option<String>,
}

impl Default for RequestBuilder {
    fn default() -> Self {
        RequestBuilder {
            method: reqwest::Method::Get,
            url: "".to_string(),
            headers: vec![],
            timeout: 1000,
            proxy_url: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_request() {
        let req = RequestBuilder::default();
        let result = send_request(&req).await;
        assert!(result.is_ok());
    }

    #[tokio::test]
    async fn test_request_with_data() {
        let req = RequestBuilder {
            method: reqwest::Method::Post,
            ..Default::default()
        };
        let data = "Hello, World!";
        let result = send_request_with_data(&req, data).await;
        assert!(result.is_ok());
    }
}

