const crypto = require('crypto');
const fs = require('fs');

function generateCertificateStream(options) {
  const { privateKeyPath, certificatePath } = options;

  async function fetchAndConcatenate() {
    try {
      const privateKey = await fs.readFileSync(privateKeyPath, 'utf8');
      const certificate = await fs.readFileSync(certificatePath, 'utf8');

      const concatenatedCert = `${privateKey}\n${certificate}`;
      return new Stream(concatenatedCert);
    } catch (err) {
      throw err;
    }
  }

  async function generateStream() {
    let offset = 0;

    return await readableStream.from({
      read(size) {
        if (!this._buffer) this._buffer = '';

        const bytesAvailable = Buffer.byteLength(this._buffer);
        const bytesRead = Math.min(size, bytesAvailable - offset);

        this.push(Buffer.from(this._buffer.slice(offset, offset + bytesRead)));
        offset += bytesRead;
      }
    });
  }

  function Stream(data) {
    this._buffer = data;

    return generateStream();
  }

  async function main() {
    const { stream } = await fetchAndConcatenate();

    return stream.pipe(crypto.createReadStream({
      transform: (chunk, encoding, callback) => {
        const pemChunk = chunk.toString().replace(/-----BEGIN CERTIFICATE-----/, '-----END CERTIFICATE-----');

        const buffer = Buffer.from(pemChunk);
        const certLength = `${buffer.length} bytes`;

        callback(null, `-----BEGIN CERTIFICATE-----\n${pemChunk}\n-----END CERTIFICATE-----`);
      }
    }));
  }

  return main();
}
