import re
from datetime import datetime
import heapq
from threading import Thread, Lock
from queue import Queue
import logging

logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

class LogEntry:
    def __init__(self, sequence_number, timestamp):
        self.sequence_number = sequence_number
        self.timestamp = timestamp

def process_log_file(file_path):
    log_entries = []
    last_entry = None

    def parse_timestamp(line):
        match = re.search(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})', line)
        if match:
            return datetime.strptime(match.group(1), '%Y-%m-%d %H:%M:%S')
        return None

    def process_log_entry(line):
        timestamp = parse_timestamp(line)
        if timestamp:
            sequence_number = int(re.search(r'sequence_number=(\d+)', line).group(1))
            log_entries.append(LogEntry(sequence_number, timestamp))

    with open(file_path, 'r') as file:
        for line in file:
            process_log_entry(line.strip())

    sorted_entries = []
    min_heap = []

    def sort_entries():
        nonlocal sorted_entries, min_heap
        while log_entries:
            entry = heapq.heappop(log_entries)
            if not min_heap or entry.timestamp < min_heap[0].timestamp:
                min_heap.append(entry)
            else:
                sorted_entries.extend(min_heap)
                min_heap = [entry]

        sorted_entries.extend(min_heap)

    def extract_last_sequence_number():
        nonlocal last_entry
        last_entry = sorted_entries[-1]

    Thread(target=sort_entries).start()
    Thread(target=extract_last_sequence_number).start()

    while True:
        try:
            if queue.get(timeout=0.1):
                break
        except Queue.Empty:
            pass

    logger.info(f'Last sequence number: {last_entry.sequence_number}')
