typedef struct state {
    int id;
    struct state* next;
} State;

State* create_state_list(int** states, int num_states, int last_state) {
    State* head = NULL;
    for (int i = 0; i <= last_state; i++) {
        State* new_state = (State*)malloc(sizeof(State));
        if (!new_state) return NULL;
        new_state->id = states[i][0];
        new_state->next = head;
        head = new_state;
    }
    return head;
}

void free_state_list(State* head) {
    while (head) {
        State* temp = head;
        head = head->next;
        free(temp);
    }
}
