#define ANOMALY_THRESHOLD 3.5 // Initial anomaly detection threshold

typedef struct {
    float signal_strength;
    int timestamp;
} SensorData;

SensorData* process_sensors(SensorData *data, int num_data) {
    static float avg_signal = 0;
    static int num_anomalies = 0;
    static float max_variance = 0;
    static int anomaly_timestamp = 0;

    // Process local sensor data
    for (int i = 0; i < num_data; i++) {
        SensorData* current_data = &data[i];
        if (current_data->timestamp > WINDOW_SIZE) {
            continue; // Ignore old data points
        }

        float variance = (current_data->signal_strength - avg_signal) * (current_data->signal_strength - avg_signal);
        avg_signal += (current_data->signal_strength - avg_signal) / i;

        if (variance > ANOMALY_THRESHOLD) {
            num_anomalies++;
            anomaly_timestamp = current_data->timestamp;
        }

        max_variance = fmax(max_variance, variance);
    }

    return data;
}

int main() {
    // Simulate sensor data streams
    SensorData sensor_data[MAX_SENSOR];
    for (int i = 0; i < MAX_SENSOR; i++) {
        sensor_data[i].signal_strength = rand() / (float)RAND_MAX * 10;
        sensor_data[i].timestamp = time(NULL);
    }

    int num_sensor_data = sizeof(sensor_data) / sizeof(SensorData);

    SensorData* processed_data = process_sensors(sensor_data, num_sensor_data);

    printf("Highest Variance: %f\n", max_variance);
    printf("Timestamp of Most Anomalous Data Point: %d\n", anomaly_timestamp);

    return 0;
}
