using System;
using System.Collections.Concurrent;
using System.Threading;

namespace DynamicValueGenerator
{
    public class DynamicValueGenerator : IDisposable
    {
        private readonly ConcurrentDictionary<int, RandomValueGenerator> _generators = new ConcurrentDictionary<int, RandomValueGenerator>();

        public void InitializeRange(int id, int min, int max, bool inclusive)
        {
            if (min > max) throw new ArgumentException("Minimum value cannot exceed maximum value.");
            _generators.AddOrUpdate(id, CreateGenerator(min, max, inclusive), (id, generator) => generator);
        }

        public float GenerateFloat(int id)
        {
            return _generators.TryGetValue(id, out var generator) ? generator.NextFloat() : 0;
        }

        public int GenerateInt(int id)
        {
            return _generators.TryGetValue(id, out var generator) ? generator.NextInt() : 0;
        }

        public void ResetGenerator(int id)
        {
            _generators.AddOrUpdate(id, CreateGenerator(_generators[id].Min, _generators[id].Max, _generators[id].Inclusive), (id, _) => _);
        }

        public override string ToString()
        {
            var sb = new StringBuilder();
            foreach (var generator in _generators.Values)
            {
                sb.AppendLine($"Range {generator.Id}: [{generator.Min}, {(generator.Inclusive ? "inclusive" : "exclusive")}]");
            }
            return sb.ToString();
        }

        private RandomValueGenerator CreateGenerator(int min, int max, bool inclusive)
        {
            return new RandomValueGenerator(min, max, inclusive);
        }

        public void Dispose()
        {
            foreach (var generator in _generators.Values)
                generator.Dispose();
            _generators.Clear();
        }
    }

    public class RandomValueGenerator : IDisposable
    {
        public int Id { get; }
        public int Min { get; }
        public int Max { get; }
        public bool Inclusive { get; }

        private readonly System.Random _random;

        public RandomValueGenerator(int id, int min, int max, bool inclusive)
        {
            Id = id;
            Min = min;
            Max = max;
            Inclusive = inclusive;
            _random = new System.Random();
        }

        public float NextFloat()
        {
            return (float)_random.NextDouble() * (Inclusive ? (Max - Min) : Math.Abs(Max - Min)) + Min;
        }

        public int NextInt()
        {
            return _random.Next(Inclusive ? Max - Min + 1 : Max - Min);
        }

        public void Dispose()
        {
            _random.Dispose();
        }
    }
}
