#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Define a struct to represent a configuration key-value pair
typedef struct {
    char* key;
    int type; // 0: string, 1: integer, 2: boolean
    void* value;
} ConfigPair;

// Define a struct to manage the configuration data structure
typedef struct {
    ConfigPair** pairs;
    int size;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager* configManagerCreate(int initialSize) {
    ConfigManager* manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    manager->pairs = (ConfigPair**)malloc(initialSize * sizeof(ConfigPair*));
    manager->size = initialSize;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void configManagerDestroy(ConfigManager* manager) {
    for(int i = 0; i < manager->size; i++) {
        free(manager->pairs[i]->key);
        if(manager->pairs[i]->type == 1) {
            int* value = (int*)manager->pairs[i]->value;
            free(value);
        } else if(manager->pairs[i]->type == 2) {
            bool* value = (bool*)manager->pairs[i]->value;
            free(value);
        }
    }
    free(manager->pairs);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Parse a configuration file into the ConfigManager
void configManagerParse(ConfigManager* manager, FILE* file) {
    char line[1024];
    int lineNumber = 0;
    while(fgets(line, sizeof(line), file)) {
        lineNumber++;
        // Skip comments and empty lines
        if(strncmp(line, "#", 1) == 0 || strlen(line) <= 2) continue;

        // Split the line into key-value pair
        char* token = strtok(line, " =");
        char* key = strdup(token);
        token = strtok(NULL, " =");
        int type;
        if(strncmp(token, "true", 4) == 0 || strncmp(token, "TRUE", 4) == 0)
            type = 2;
        else if(strncmp(token, "false", 6) == 0 || strncmp(token, "FALSE", 6) == 0)
            type = 2;
        else {
            int value;
            sscanf(token, "%d", &value);
            type = 1;
        }

        // Allocate memory for the ConfigPair
        ConfigPair* pair = (ConfigPair*)malloc(sizeof(ConfigPair));
        pair->key = key;
        pair->type = type;
        if(type == 2) {
            bool* value = (bool*)malloc(sizeof(bool));
            *value = type == 1; // Initialize to false for integers and true for booleans
            pair->value = value;
        } else if(type == 1) {
            int* value = (int*)malloc(sizeof(int));
            *value = value; // Initialize with the parsed integer value
            pair->value = value;
        } else { // type == 0: string
            pair->value = strdup(token);
        }

        // Add the ConfigPair to the manager's data structure
        if(manager->size <= lineNumber) {
            ConfigManager* newManager = configManagerCreate(lineNumber * 2);
            configManagerDestroy(manager);
            manager = newManager;
        }
        manager->pairs[lineNumber] = pair;
    }
}

// Retrieve a configuration value by key from the ConfigManager
void* configManagerGet(ConfigManager* manager, char* key) {
    pthread_mutex_lock(&manager->lock);
    for(int i = 0; i < manager->size; i++) {
        if(strcmp(manager->pairs[i]->key, key) == 0) {
            void* value = manager->pairs[i]->value;
            pthread_mutex_unlock(&manager->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int main() {
    ConfigManager* manager = configManagerCreate(10);
    FILE* file = fopen("config.txt", "r");
    if(file) configManagerParse(manager, file);
    fclose(file);

    // Example usage:
    char* key = "serverAddress";
    void* value = configManagerGet(manager, key);
    if(value) {
        printf("%s: %s\n", key, (char*)value);
    }

    configManagerDestroy(manager);
    return 0;
}
