void traverse_dom(struct html_element* root, char* str, int size_limit) {
    if (root == NULL || strlen(str) >= size_limit) return;

    char temp[1024];
    strcpy(temp, str);
    strcat(temp, "/");
    if (callback(temp) != 0) {
        printf("Non-compliant element encountered: %s\n", temp);
    }

    for (int i = 0; i < root->num_children; i++) {
        struct html_element* child = root->children[i];
        char new_str[1024];
        strcpy(new_str, str);
        strcat(new_str, "/");
        traverse_dom(child, new_str, size_limit);
    }
}

