typedef struct {
    int width;
    int height;
    int samplesPerPixel;
    unsigned char bitsPerSample[5];
    int numSamplesPerPixel;
} ImageMetadata;

ImageMetadata processImageAndGenerateHash(const char* inputFile, const char* inputString) {
    TIFF *tif = TIFFOpen(inputFile, "r");
    if (!tif) return (ImageMetadata){0};

    ImageMetadata metadata;
    metadata.width = TIFFGetFieldAsShort(tif, TIFF_FIELD_IMAGE_WIDTH);
    metadata.height = TIFFGetFieldAsShort(tif, TIFF_FIELD_IMAGE_LENGTH);

    int samplesPerPixel = TIFFGetFieldAsShort(tif, TIFF_FIELD_SAMPLES_PER_PIXEL);
    for (int i = 0; i < samplesPerPixel; ++i) {
        metadata.bitsPerSample[i] = TIFFGetFieldAsShort(tif, TIFF_FIELD_BITSPERSAMPLE + i);
    }
    metadata.numSamplesPerPixel = samplesPerPixel;

    unsigned char buffer[1024];
    size_t bytesRead;
    while ((bytesRead = TIFFReadRGBAImage(tif, 0, 0, buffer, &metadata.width)) > 0);

    // Generate MD5 hash for input string
    unsigned char md5Hash[16];
    uint8_t* stringBytes = (uint8_t*)inputString;
    size_t stringLength = strlen(inputString);
    uint64_t* data = malloc((stringLength + 1) * sizeof(uint8_t));
    memcpy(data, stringBytes, stringLength * sizeof(uint8_t));
    data[stringLength] = '\0';
    MD5_CTX md5Context;
    MD5Init(&md5Context);
    MD5Update(&md5Context, data, (unsigned int)(stringLength + 1) * sizeof(uint8_t));
    MD5Final(md5Hash, &md5Context);

    free(data);

    TIFFClose(tif);
    return metadata;
}
