#include <string.h>

char* dynamicRename(char *filename) {
    char *path = malloc(strlen(filename));
    strcpy(path, filename);

    size_t i = strlen(filename);
    while (i > 0 && path[i-1] == '/') i--;
    path[i] = '\0';

    char new_filename[256];
    strncpy(new_filename, path, 255);

    char *extension;
    if ((extension = strrchr(path, '.'))) {
        size_t extension_len = strlen(extension) + 1;
        memmove(&new_filename[strcspn(new_filename, "/")], extension, extension_len);
    } else {
        strcpy(extension, ".txt");
        strncat(new_filename, extension, 255 - strlen(new_filename));
    }

    char new_name[7];
    strncpy(new_name, &path[strcspn(path, "/")], 6);
    for (i = 0; i < 6; i++) {
        if (!isalnum(new_name[i])) new_name[i] = '_';
    }
    strncat(new_filename, new_name, 255 - strlen(new_filename));

    free(path);
    return new_filename;
}
