#include <sys/types.h>
#include <sys/wait.h>

void handle_sigchld(int sig) {
    int status;
    waitpid(-1, &status, WNOHANG);
}

int execute_command(char *command, char **args, char *envp[]) {
    pid_t pid = fork();
    if (pid == -1) {
        return -1; // Fork failed
    } else if (pid == 0) { // Child process
        signal(SIGCHLD, handle_sigchld);
        setenv("EXTERNAL_SERVICE_API_KEY", "your_api_key");
        execvp(command, args);
        perror("execvp"); // Error in executing command
        exit(1); // Terminate the child process
    } else { // Parent process
        int retries = 0;
        while (retries < 3) {
            pid_t api_pid = fork();
            if (api_pid == -1) {
                return -1; // Fork failed
            } else if (api_pid == 0) { // Child API process
                signal(SIGCHLD, handle_sigchld);
                char *api_args[] = {"your_api_command", NULL};
                setenv("EXTERNAL_SERVICE_API_KEY", "your_api_key");
                execvp(api_args[0], api_args);
                perror("execvp"); // Error in executing API command
                exit(1); // Terminate the child API process
            } else { // Parent process for API
                int status;
                waitpid(api_pid, &status, 0);
                if (WEXITSTATUS(status) != 0) {
                    retries++;
                    sleep(1); // Wait before retrying
                } else {
                    break; // API call successful, exit loop
                }
            }
        }
        return pid; // Return the original command process ID
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <command> [args]\n", argv[0]);
        return -1;
    }
    char *envp[] = {"PATH=/usr/local/bin:$PATH", NULL};
    int result = execute_command(argv[1], &argv[2], envp);
    if (result == -1) {
        fprintf(stderr, "Error executing command\n");
        return -1;
    } else {
        waitpid(result, 0, 0); // Wait for the original command process
        return 0; // Successful execution
    }
}
