import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class SSHExecutor {

    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MILLIS = 1000; // 1 second

    public void executeTasks(String remoteHost, String username, String password, List<String> tasks) {
        Connection connection = new Connection(remoteHost, username, password);
        for (String task : tasks) {
            while (!connection.executeTask(task)) {
                if (connection.getRetries() >= MAX_RETRIES) {
                    break;
                }
                try {
                    Thread.sleep(RETRY_DELAY_MILLIS * (1 << connection.getRetries()));
                } catch (InterruptedException e) {
                    // Handle interrupt
                }
                connection.reconnect();
            }
        }
        connection.close();
    }

    private class Connection {

        private SSHClient sshClient;
        private int retries = 0;

        public Connection(String remoteHost, String username, String password) {
            sshClient = new SSHClient(remoteHost, username, password);
        }

        public boolean executeTask(String task) {
            try (Session session = sshClient.startSession()) {
                session.executeCommand(task);
                return true;
            } catch (IOException e) {
                retries++;
                return false;
            }
        }

        public int getRetries() {
            return retries;
        }

        public void reconnect() {
            sshClient.reconnect();
        }

        public void close() {
            sshClient.close();
        }
    }

    private class SSHClient {

        private JSch jsch;

        public SSHClient(String remoteHost, String username, String password) {
            jsch = JSch.getInstance();
            Session session = jsch.getSession(username, remoteHost, 22);
            session.setPassword(password);
            // Add logging service integration
            session.setUserInfo(new UserInfo() {
                @Override
                public void setPassphrase(String s) {
                    // Handle passphrase
                }

                @Override
                public String getPassphrase() {
                    return null;
                }
            });
        }

        public void reconnect() {
            try {
                Thread.sleep(RETRY_DELAY_MILLIS * (1 << SSHExecutor.this.MAX_RETRIES));
            } catch (InterruptedException e) {
                // Handle interrupt
            }
            Session session = jsch.getSession(username, remoteHost, 22);
            session.setPassword(password);
            session.connect();
        }

        public void close() {
            jsch.removeAllSession();
        }
    }

    private class UserInfo implements UserInfo, UIKeyboardInteractive {

        @Override
        public String getPassphrase() {
            return null;
        }

        @Override
        public void setPassphrase(String s) {}

        @Override
        public boolean getPasswordEchoed() {
