int processConfiguration(struct Configuration *config) {
    if (config->password == NULL || strlen(config->password) == 0) {
        return EINVAL; // Password is empty or NULL
    }

    if (strlen(config->connection_settings->title) == 0) {
        return ECONNRESET; // Connection settings title not set
    }

    if (config->callback_function == NULL) {
        return EBADF; // Callback function is NULL
    }

    if (!validateConnectionSettings(config->connection_settings)) {
        return EINVAL; // Connection settings invalid
    }

    int decrypted_password_size = decryptPassword(config->password, config->key, config->iv);
    char *decrypted_password = malloc(decrypted_password_size + 1);
    if (decrypted_password == NULL) {
        return ENOMEM; // Memory allocation failed for decrypted password
    }

    memcpy(decrypted_password, config->password, decrypted_password_size);
    decrypted_password[decrypted_password_size] = '\0';

    int integrity_status = validatePasswordIntegrity(decrypted_password);
    if (integrity_status != 0) {
        free(decrypted_password);
        return EINTR; // Password integrity failed
    }

    free(decrypted_password);
    config->callback_function(config); // Call the callback function

    return 0; // Success
}
