    // Get the session ID, expiration time, and user role
    char *session_id = cJSON_GetStringValue(cJSON_GetObjectItem(session, "session_id"));
    int64_t expiration_time = cJSON_GetInt64Value(cJSON_GetObjectItem(session, "expiration_time"));
    enum role user_role;

    if (strcmp(cJSON_GetStringValue(cJSON_GetObjectItem(session, "user_role")), "admin") == 0) {
        user_role = ADMIN;
    } else if (strcmp(cJSON_GetStringValue(cJSON_GetObjectItem(session, "user_role")), "editor") == 0) {
        user_role = EDITOR;
    } else if (strcmp(cJSON_GetStringValue(cJSON_GetObjectItem(session, "user_role")), "viewer") == 0) {
        user_role = VIEWER;
    } else {
        return 0; // Invalid user role
    }

    // Validate expiration time and user role
    if (expiration_time <= time(NULL)) {
        return 0; // Session has expired
    }
    if (user_role != ADMIN && user_role != EDITOR && user_role != VIEWER) {
        return 0; // Invalid user role
    }

    // Check for optional device token
    cJSON *device_token = cJSON_GetObjectItem(session, "device_token");
    if (device_token && !cJSON_IsString(device_token)) {
        return 0; // Invalid device token
    }

    // Validate session ID uniqueness and consistency
    // This involves querying the distributed cache and reconciling potential discrepancies

    // If all checks pass, the session is valid
    return 1;
}

