public IDataReader storeImageAndComputeHash(byte[] imageBytes, string input)
{
    using (SqlConnection conn = new SqlConnection("Server=database_cluster;Database=image_database;User Id=username;Password=password;"))
    {
        conn.Open();

        SqlCommand cmd = new SqlCommand("INSERT INTO images VALUES (@imageData, @input, @hash) RETURNING *", conn);
        cmd.Parameters.AddWithValue("@imageData", imageBytes);
        cmd.Parameters.AddWithValue("@input", input);

        using (MD5 md5 = MD5.Create())
        {
            byte[] hashValue = md5.ComputeHash(Encoding.ASCII.GetBytes(input));
            cmd.Parameters.AddWithValue("@hash", BitConverter.ToString(hashValue).Replace("-", ""));
        }

        using (SqlDataReader reader = ExecuteReader(conn, cmd))
        {
            return reader;
        }
    }
}

private IDataReader ExecuteReader(SqlConnection conn, SqlCommand cmd)
{
    SqlDataReader reader = null;
    try
    {
        reader = cmd.ExecuteReader(CommandBehavior.CloseConnection);
    }
    catch (Exception ex)
    {
        // Handle errors here
    }
    finally
    {
        if (reader != null)
        {
            reader.Close();
        }
    }
    return reader;
}
