using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Base64EncryptionProcessor
{
    public Dictionary<string, string> ProcessBase64Messages(string inputString, byte[] key, byte[] iv, int checksumSize)
    {
        var result = new Dictionary<string, string>();

        foreach (var base64Message in inputString.Split(','))
        {
            if (!string.IsNullOrEmpty(base64Message))
            {
                try
                {
                    // Decrypt the message
                    var decryptedBytes = TripleDESCryptoProcessor.DecryptBase64String(base64Message, key, iv);

                    // Validate the checksum
                    int checksumLength;
                    byte[] checksumBytes;
                    if (decryptedBytes.Length - checksumSize > 0)
                    {
                        checksumLength = Math.Min(checksumSize, decryptedBytes.Length - checksumSize);
                        checksumBytes = new byte[checksumLength];
                        Array.Copy(decryptedBytes, decryptedBytes.Length - checksumLength, checksumBytes, 0, checksumLength);
                    }
                    else
                    {
                        checksumBytes = null;
                    }

                    // Verify the checksum
                    var expectedChecksum = GetChecksumFromMessage(decryptedBytes);
                    if (checksumBytes != null && !VerifyChecksum(expectedChecksum, checksumBytes))
                    {
                        continue; // Message has invalid or missing checksum, skip it
                    }

                    // Add the decrypted message and its checksum to the result
                    result.Add(base64Message, Encoding.ASCII.GetString(checksumBytes));
                }
                catch
                {
                    // Ignore decryption failures due to invalid IV or key mismatches
                }
            }
        }

        return result;
    }

    private byte[] GetChecksumFromMessage(byte[] message)
    {
        // Implement your checksum calculation logic here
        // For example, you can use a simple hash function like SHA256
        using (var sha256 = new SHA256CryptoServiceProvider())
        {
            var checksumBytes = sha256.ComputeHash(message);
            return checksumBytes;
        }
    }

    private bool VerifyChecksum(byte[] expectedChecksum, byte[] actualChecksum)
    {
        // Implement your checksum verification logic here
        // For example, you can compare the two checksums using a simple equality check
        return !actualChecksum.SequenceEqual(expectedChecksum);
    }
}

public static class TripleDESCryptoProcessor
{
    public static byte[] DecryptBase64String(string base64Message, byte[] key, byte[] iv)
    {
        using (var tripleDES = new TripleDESCryptoServiceProvider { Key = key, IV = iv })
        {
            var encryptedBytes = Convert.FromBase64String(base64Message);
            using (var memoryStream = new MemoryStream(encryptedBytes))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, tripleDES.CreateDecryptor()))
                {
                    var decryptedBytes = new byte[cryptoStream.Length];
                    cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes;
                }
            }
        }
    }
}
