using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Redis;
using Microsoft.Extensions.Logging;

public class ApiStringProcessor
{
    private readonly IRedisCache _cache;
    private readonly ILogger _logger;

    public ApiStringProcessor(IRedisCache cache, ILogger logger)
    {
        _cache = cache;
        _logger = logger;
    }

    public async Task ProcessApiStringsAsync(List<string> apiStrings)
    {
        foreach (var stringToProcess in apiStrings)
        {
            try
            {
                var sha256Hash = GetSha256Hash(stringToProcess);
                await WriteCacheAsync(sha256Hash, stringToProcess);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing API string");
                await RetryWriteCacheAsync(sha256Hash, stringToProcess);
            }
        }
    }

    private string GetSha256Hash(string input)
    {
        using var sha256 = System.Security.Cryptography.SHA256.Create();
        var bytes = Encoding.UTF8.GetBytes(input);
        var hashBytes = sha256.ComputeHash(bytes);
        return Convert.ToBase64String(hashBytes);
    }

    private async Task WriteCacheAsync(string key, string value)
    {
        await _cache.SetStringAsync(key, value, TimeSpan.FromDays(1));
    }

    private async Task RetryWriteCacheAsync(string key, string value)
    {
        int retries = 3;
        while (retries > 0)
        {
            try
            {
                await WriteCacheAsync(key, value);
                return;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error writing to cache");
                retries--;
                await Task.Delay(1000); // Wait for 1 second before retrying
            }
        }
    }
}
