using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryption
{
    public byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv)
    {
        if (key.Length != 32) throw new ArgumentException("Invalid key size. AES-256-CBC requires a 32-byte key.");
        if (iv.Length < 16 || iv.Length > 32) throw new ArgumentException("Invalid IV size. AES-256-CBC requires an 16-byte or 32-byte IV.");

        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.BlockSize = 128;

            if (iv.Length == 16)
                aes.IV = iv;
            else
                using (var rng = RandomNumberGenerator.Create())
                {
                    aes.IV = new byte[16];
                    rng.GetBytes(aes.IV);
                }

            using (MemoryStream ms = new MemoryStream(ciphertext))
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    int bytesRead;
                    byte[] buffer = new byte[1024];
                    StringBuilder decryptedText = new StringBuilder();

                    while ((bytesRead = cs.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        string text = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                        decryptedText.Append(text);
                    }

                    return ms.ToArray();
                }
            }
        }
    }
}
