function loadModule(moduleName) {
  const cache = {};

  async function loadFromServer() {
    try {
      const response = await fetch(`https://example.com/modules/${moduleName}.js`);
      const moduleCode = await response.text();
      return moduleCode;
    } catch (error) {
      console.error(`Error loading ${moduleName} from server:`, error);
      return null;
    }
  }

  async function loadFromCache() {
    if (!cache[moduleName]) {
      try {
        const cacheResponse = await fetch(`https://example.com/modules/${moduleName}.js`);
        cache[moduleName] = await cacheResponse.text();
      } catch (error) {
        console.error(`Error loading ${moduleName} from cache:`, error);
        return null;
      }
    }
    return cache[moduleName];
  }

  async function loadAndCacheModule() {
    let moduleCode;

    // Try to load from cache
    const cachedModule = await loadFromCache();
    if (cachedModule) {
      moduleCode = cachedModule;
    } else {
      // Load from server, and then cache it
      const remoteModule = await loadFromServer();
      if (remoteModule) {
        moduleCode = remoteModule;
        cache[moduleName] = remoteModule;
      }
    }

    return moduleCode;
  }

  async function executeModule(moduleCode) {
    try {
      // Evaluate the loaded module code as JavaScript
      const module = new Function(`module.exports=${moduleCode}`)();
      return module();
    } catch (error) {
      console.error(`Error executing ${moduleName}:`, error);
      return null;
    }
  }

  async function loadAndExecuteModule(moduleName) {
    const moduleCode = await loadAndCacheModule();
    if (moduleCode) {
      await executeModule(moduleCode);
    }
  }

  loadAndExecuteModule('myModule');
