use tokio::prelude::*;
use log::{info, error};
use slog::{Logger, Drain};

async fn main() {
    // Initialize Tokio runtime
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap();

    // Create a Tokio executor
    let mut executor = runtime.executor();

    // Define the logging mechanism
    let log_level = env!("LOG_LEVEL");
    let drain = slog_stream::StreamSinkInfo {
        mode: slog_stream::Mode::Async,
        level: log_level.parse().unwrap_or(log::max_level()),
        ..Default::default()
    };
    let logger = Logger::new(drain).build();

    // Define the functions to execute based on command-line arguments
    let mut args = std::iter::FromIterator::from_iter(std::env::args());
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "task1" => task1().await,
            "task2" => task2().await,
            _ => error!(logger, "Invalid command-line argument: {}", arg),
        }
    }

    // Shutdown Tokio runtime
    executor.shutdown();
}

async fn task1() {
    for i in 0..10 {
        info!(logger, "Processing task1 for iteration {}", i);
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    }
}

async fn task2() {
    for i in 0..5 {
        info!(logger, "Processing task2 for iteration {}", i);
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    }
}
