impl DirectoryManager {
    fn new(config_file_path: &str) -> Self {
        DirectoryManager {
            config_file_path: config_file_path.to_string(),
        }
    }

    fn create_directory(&self, directory_name: &str) {
        let dir_path = self.get_configured_dir_path(directory_name);
        if !fs::create_dir_all(dir_path.clone()).is_ok() {
            error!("Directory {} already exists", dir_path.display());
        } else {
            info!("Created new directory {}", dir_path.display());
        }
    }

    fn get_configured_dir_path(&self, directory_name: &str) -> PathBuf {
        let config = self.load_config();
        if !config.allowed_paths.contains(&directory_name) {
            error!("Invalid directory name {}", directory_name);
            return PathBuf::new();
        }
        let dir_path = config.base_path.join(directory_name);
        info!("Configured directory path for {} is {}", directory_name, dir_path.display());
        dir_path
    }

    fn load_config(&self) -> Config {
        // Load configuration from file and validate
        // ...
    }
}

struct Config {
    base_path: PathBuf,
    allowed_paths: Vec<String>,
}

fn main() {
    let manager = DirectoryManager::new("path/to/config/file");
    let dir_name = "my_directory";
    manager.create_directory(dir_name);
}
