from collections import defaultdict
from functools import lru_cache

class ThreadSafeRegistry(metaclass=ABCMeta):
    def __init__(self):
        self._registry = defaultdict(dict)
        self._lock = threading.Lock()

    @abstractmethod
    def register_factory(self, factory_id: str, factory_function):
        pass

    @abstractmethod
    def get_factory(self, factory_id: str) -> callable:
        pass

class FactoryRegistry(ThreadSafeRegistry):
    def __init__(self):
        super().__init__()

    def register_factory(self, factory_id: str, factory_function):
        with self._lock:
            self._registry[factory_id] = factory_function

    def get_factory(self, factory_id: str) -> callable:
        with self._lock:
            return self._registry.get(factory_id)

class ResourceTracker:
    def __init__(self):
        self.active_instances = defaultdict(int)

    def track_instance(self, factory_id: str):
        self.active_instances[factory_id] += 1

    def release_instance(self, factory_id: str):
        if self.active_instances[factory_id] > 0:
            self.active_instances[factory_id] -= 1
        if self.active_instances[factory_id] == 0:
            del self.active_instances[factory_id]

class CustomSerializationMixin:
