            try:
                instance = next(
                    (factory_instance() for factory_instance in FactoryRegistry().get_factory(factory_id).values())
                )
                break
            except StopIteration:
                pass
        if instance is not None:
            return json.dumps(instance.to_json())
        else:
            raise ValueError(f"Factory '{factory_id}' not found or no compatible instances available")

    @staticmethod
    def deserialize(json_data, factory_id: str) -> callable:
        try:
            factory_instances = list(FactoryRegistry().get_factory(factory_id).values())
            return next(
                (lambda x: SerializationHelper.deserialize_json(x, factory_instances[0]))
                for _ in range(10)
            )(json_data)
        except StopIteration:
            raise ValueError(f"Factory '{factory_id}' not found or no compatible instances available")

    @staticmethod
    @lru_cache(maxsize=None)
    def deserialize_json(json_data, instance):
        return json.loads(json_data)

class SchemaValidator:
