typedef struct {
    int value;
    time_t timestamp;
} Record;

// Function to allocate memory for arrays and initialize records
int* initializeArrays(size_t numRecords) {
    // Allocate memory for offset values array
    long* offsets = (long*) malloc(numRecords * sizeof(long));

    // Allocate memory for keys array
    int* keys = (int*) malloc(numRecords * sizeof(int));

    // Allocate memory for record structures array
    Record** records = (Record**) malloc(numRecords * sizeof(Record*));

    // Initialize each record with timestamp and value
    for(size_t i = 0; i < numRecords; i++) {
        records[i] = (Record*) malloc(sizeof(Record));
        records[i]->value = i;
        records[i]->timestamp = time(NULL);
    }

    return keys;
}

// Function to free allocated memory
void cleanUpArrays(int* keys, long* offsets, Record** records, size_t numRecords) {
    for(size_t i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}
