typedef struct {
    char* name;
    char* ip_addr;
    char* subnet_mask;
    int num_ports;
    struct PortConfig** ports;
} NetworkInterface;

typedef struct PortConfig {
    int port_num;
    char* protocol;
} PortConfig;

NetworkInterface* create_network_interface(char* name, char* ip_addr, char* subnet_mask) {
    NetworkInterface* iface = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    iface->name = strdup(name);
    iface->ip_addr = strdup(ip_addr);
    iface->subnet_mask = strdup(subnet_mask);
    iface->num_ports = 0;
    return iface;
}

void add_port_config(NetworkInterface* iface, int port_num, char* protocol) {
    PortConfig* new_port = (PortConfig*)malloc(sizeof(PortConfig));
    new_port->port_num = port_num;
    new_port->protocol = strdup(protocol);
    iface->ports = realloc(iface->ports, sizeof(PortConfig*) * (iface->num_ports + 1));
    iface->ports[iface->num_ports] = new_port;
    iface->num_ports++;
}

void remove_port_config(NetworkInterface* iface, int port_num) {
    for(int i = 0; i < iface->num_ports; i++) {
        if(iface->ports[i]->port_num == port_num) {
            free(iface->ports[i]->protocol);
            free(iface->ports[i]);
            memmove(&iface->ports[i], &iface->ports[i+1], sizeof(PortConfig*) * (iface->num_ports - i));
            iface->num_ports--;
            break;
        }
    }
}

void update_port_config(NetworkInterface* iface, int port_num, char* new_protocol) {
    for(int i = 0; i < iface->num_ports; i++) {
        if(iface->ports[i]->port_num == port_num) {
            free(iface->ports[i]->protocol);
            iface->ports[i]->protocol = strdup(new_protocol);
            break;
        }
    }
}

NetworkInterface* get_network_interface(char* name, char* ip_addr, char* subnet_mask) {
    // Fetch the latest network settings from the external configuration server
    // ...
    return create_network_interface(name, ip_addr, subnet_mask);
}

void update_network_interfaces() {
