    // ...
}

void free_network_interface(NetworkInterface* iface) {
    for(int i = 0; i < iface->num_ports; i++) {
        free(iface->ports[i]->protocol);
        free(iface->ports[i]);
    }
    free(iface->name);
    free(iface->ip_addr);
    free(iface->subnet_mask);
    free(iface->ports);
    free(iface);
}

