**Python: `verify_file_hash` Function**
```python
import hashlib
import os
from tqdm import tqdm

def verify_file_hash(file_path, expected_hash=None):
    chunk_size = 1024 * 1024  # 1MB chunks
    hash_object = hashlib.sha256()

    with open(file_path, 'rb') as file:
        for i in tqdm(range(0, os.path.getsize(file_path), chunk_size)):
            chunk = file.read(chunk_size)
            hash_object.update(chunk)

    calculated_hash = hash_object.hexdigest()
    if expected_hash is not None and calculated_hash != expected_hash:
        raise ValueError(f"File integrity failed. Calculated hash '{calculated_hash}' does not match the expected hash '{expected_hash}'")
    return calculated_hash
```

