import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.ExecutionException;

public class NetworkUtil {
    public static void establishConnection(InetSocketAddress address, int retryAttempts) throws IOException, InterruptedException {
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();

        channel.connect(address, new CompletionHandler<Void, Void>() {
            @Override
            public void completed(Void result, Void attachment) {
                try {
                    // Connection established, send data or handle further operations
                    channel.write();
                } catch (IOException e) {
                    // Handle connection write errors
                }
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                if (retryAttempts > 0) {
                    retryConnect(address, retryAttempts - 1);
                } else {
                    throw new IOException("Connection establishment failed", exc);
                }
            }
        });
    }

    private static void retryConnect(InetSocketAddress address, int attempts) throws IOException, InterruptedException {
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();
        channel.connect(address, new CompletionHandler<Void, Void>() {
            // Same completion handler as above
        }, null);

        // Rate-limit connection attempts to avoid overwhelming the remote server
        if (attempts > 0) {
            Thread.sleep(1000); // Wait for 1 second before retrying
            retryConnect(address, attempts - 1);
        }
    }
}
