    private readonly HttpClient _httpClient;
    private readonly string _apiKey;
    private readonly int _maxRetryCount;
    private readonly TimeSpan _cooldownPeriod;

    public async Task<WeatherData> FetchWeatherDataAsync(string location, bool useMetricUnits)
    {
        try
        {
            for (int retry = 0; retry < _maxRetryCount; retry++)
            {
                await Task.Delay(_cooldownPeriod);
                using var requestMessage = new HttpRequestMessage(HttpMethod.Get, $"https://weather-api.com/{location}?units={useMetricUnits ? "metric" : "imperial"}");
                requestMessage.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _apiKey);

                try
                {
                    var response = await _httpClient.SendAsync(requestMessage);
                    if (response.IsSuccessStatusCode)
                    {
                        return await DeserializeWeatherDataAsync(response.Content.ReadAsStreamAsync());
                    }
                    else
                    {
                        // Log warning and retry if necessary
                        Console.WriteLine($"Error fetching weather data: {response.StatusCode}");
                    }
                }
                catch (HttpRequestException ex)
                {
                    // Log error and rethrow if necessary
                    Console.WriteLine("Error sending HTTP request:");
                    Console.WriteLine(ex.Message);
                    throw;
                }
            }

            // Return default values or throw exception if all retries fail
        }
        catch (Exception ex)
        {
            // Log error and rethrow if necessary
            Console.WriteLine("Error fetching weather data:");
            Console.WriteLine(ex.Message);
            throw;
        }
    }

    private async Task<WeatherData> DeserializeWeatherDataAsync(Stream stream)
    {
        using var serializer = new DataContractSerializer(typeof(WeatherData));
        return await serializer.ReadObjectAsync(stream);
    }
}

