```php
<?php

function generateHashedContent($fileContent, $hashAlgorithm = 'sha256', $characterSet = 'abcdefghijklmnopqrstuvwxyz') {
  $randomString = '';
  for ($i = 0; $i < 10; $i++) {
    $randomString .= substr(str_shuffle($characterSet), 0, 1);
  }
  $hash = hash($hashAlgorithm, $fileContent . $randomString);
  return array('content' => $fileContent, 'hashed_content' => $hash);
}

?>
