**Java: countDisjointPairs**
```java
import java.util.Arrays;
import java.util.Random;

public class CountDisjointPairs {
    public static int countDisjointPairs(int[] arr) {
        UnionFind uf = new UnionFind(arr.length);
        for (int i = 0; i < arr.length; i++) {
            uf.makeSet(i);
        }
        for (int i = 0; i < arr.length - 1; i++) {
            if (!uf.isConnected(i, i + 1)) {
                uf.union(i, i + 1);
            }
        }
        return uf.getCount() - 1;
    }

    public static class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public void makeSet(int x) {
            parent[x] = x;
        }

        public boolean isConnected(int x, int y) {
            return find(x) == find(y);
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
        }

        public int find(int x) {
            return parent[x];
        }

        public int getCount() {
            int count = 0;
            for (int i = 0; i < parent.length; i++) {
                if (parent[i] == i) {
                    count++;
                }
            }
            return count;
        }
    }
}
```

