#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the transaction structure
typedef struct {
    int timestamp;
    double amount;
} Transaction;

// Define the sliding window structure
typedef struct {
    size_t capacity;
    size_t size;
    Transaction* transactions;
} SlidingWindow;

// Define the metrics structure
typedef struct {
    size_t total_transactions;
    double average_amount;
    size_t above_threshold;
    double max_variance;
    time_t variance_timestamp;
} Metrics;

// Function to process transaction logs in real-time
Metrics* process_transactions(Transaction* transactions, size_t num_transactions) {
    // Initialize the sliding window and metrics
    SlidingWindow sw = { .capacity = 10000, .size = 0, .transactions = NULL };
    Metrics metrics = { .total_transactions = 0, .average_amount = 0.0, .above_threshold = 0, .max_variance = 0.0, .variance_timestamp = 0 };

    // Initialize the thread-safe lock
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Process transactions
    for (size_t i = 0; i < num_transactions; i++) {
        Transaction* transaction = &transactions[i];
        // Filter transactions based on temporal proximity and amount threshold
        if (transaction->timestamp > (time(NULL) - 300)) { // Last 5 minutes
            if (transaction->amount >= 100 && transaction->amount <= 10000) {
                // Update the sliding window
                pthread_mutex_lock(&lock);
                size_t new_size = sw.size + 1;
                Transaction* new_transactions = realloc(sw.transactions, new_size * sizeof(Transaction));
                if (!new_transactions) {
                    printf("Memory allocation error\n");
                    return NULL;
                }
                memcpy(new_transactions + (sw.size - 1), transaction, sizeof(Transaction));
                sw.transactions = new_transactions;
                sw.size = new_size;
                pthread_mutex_unlock(&lock);

                // Update the metrics
                metrics.total_transactions++;
                if (transaction->amount > 500) {
                    metrics.above_threshold++;
                }
                double sum_amount = 0.0;
                for (size_t j = 0; j < sw.size; j++) {
                    sum_amount += sw.transactions[j].amount;
                }
                metrics.average_amount = sum_amount / sw.size;

                // Calculate the variance
                double var_sum = 0.0;
                for (size_t j = 0; j < sw.size; j++) {
                    double diff = sw.transactions[j].amount - metrics.average_amount;
                    var_sum += diff * diff;
                }
                metrics.max_variance = sqrt(var_sum / sw.size);
                if (metrics.max_variance > metrics.max_variance) {
                    metrics.variance_timestamp = transaction->timestamp;
                }
            }
        }
    }

    // Return the metrics
    return &metrics;
}

int main() {
    // Example usage
    Transaction transactions[] = {{1643723400, 200}, {1643723401, 300}, {1643723402, 400}};
    size_t num_transactions = sizeof(transactions) / sizeof(transactions[0]);
    Metrics* metrics = process_transactions(transactions, num_transactions);
    printf("Total Transactions: %zu\n", metrics->total_transactions);
    printf("Average Amount: %.2f\n", metrics->average_amount);
    printf("Above Threshold: %zu\n", metrics->above_threshold);
    printf("Max Variance: %.2f\n", metrics->max_variance);
    time_t timestamp = metrics->variance_timestamp;
    printf("Variance Timestamp: %lu\n", timestamp);

    return 0;
}

