#include <unistd.h>
#include <libtiff/tiffio.h>
#include <crypto/crypt_md5.h>

int executeTaskAndAnalyzeMedia(char* command, char* mediaFile) {
    pid_t childPID = fork();

    if (childPID == 0) {
        // Child process
        system(command);
        exit(0);
    } else {
        // Parent process
        int status;
        wait(&status);

        if (WEXITSTATUS(status) != 0) {
            return 0;
        }

        TIFF* tiff = TIFFOpen(mediaFile, "r");
        if (!tiff) {
            printf("Error: Failed to open media file.\n");
            return 0;
        }

        uint16_t bitsPerSample;
        uint32_t samplesPerPixel;
        TIFFGetField(tiff, TIFF_FIELD_BITSPERSAMPLE, &bitsPerSample);
        TIFFGetField(tiff, TIFF_FIELD_SAMPLESPERPIXEL, &samplesPerPixel);

        printf("Bits per sample: %d\n", bitsPerSample);
        printf("Samples per pixel: %d\n", samplesPerPixel);

        for (uint32_t i = 0; i < samplesPerPixel; i++) {
            TIFFDirectory directory;
            TIFFReadDIR(tiff, &directory, i);
            printf("Sample %d:\n", i + 1);
            printf("\tNumber of bits: %d\n", directory.bits_per_sample);
            printf("\tValue: 0x%x\n", directory.value);
        }

        TIFFClose(tiff);

        char* str = "Hello, World!";
        unsigned char md5[16];
        int result = crypt_md5(str, strlen(str), md5);
        if (result != 0) {
            printf("Error: Failed to calculate MD5 hash.\n");
            return 0;
        }

        char hexStr[33];
        for (int i = 0; i < 16; i++) {
            sprintf(&hexStr[i*2], "%02x", md5[i]);
        }

        printf("MD5 Hash: %s\n", hexStr);

        return 1;
    }
}
