#define MAX_IDENTIFIER_LENGTH 16
#define TIMESTAMP_FORMAT "%Y%m%d-%H%M%S"
#define TIME_WINDOW 5 // seconds
typedef struct {
    char *filename;
    time_t timestamp;
} FileEntry;

// Function to calculate the frequency of characters in a string
int* calculateFrequency(char* str, int len) {
    int* freq = (int*)malloc((len + 1) * sizeof(int));
    for (int i = 0; i <= len; i++)
        freq[i] = 0;
    for (int i = 0; i < len; i++) {
        freq[str[i]]++;
    }
    return freq;
}

// Function to generate a unique identifier based on character frequency and timestamp
char* generateIdentifier(char* filename, time_t timestamp) {
    int len = strlen(filename);
    int* freq = calculateFrequency(filename, len);
    char* id = (char*)malloc((MAX_IDENTIFIER_LENGTH + 1) * sizeof(char));
    sprintf(id, "%x%x", timestamp % (1 << 32), *(int*)&freq[0]);
    free(freq);
    return id;
}

// Function to rename files in a directory by modifying their extensions
void renameFilesInDirectory(char* dirPath) {
    DIR *dir = opendir(dirPath);
    if (!dir) {
        printf("Error opening directory %s\n", dirPath);
        return;
    }

    time_t lastTimestamp = 0;

    while (1) {
        struct dirent *ent = readdir(dir);
        if (!ent)
            break; // end of the list

        char filePath[256];
        sprintf(filePath, "%s/%s", dirPath, ent->d_name);

        FileEntry file;
        file.filename = ent->d_name;

        time_t now = time(NULL);
        if (now - lastTimestamp >= TIME_WINDOW) {
            lastTimestamp = now;
        } else {
            // Generate a unique identifier within the specified time window
            char* id = generateIdentifier(file.filename, lastTimestamp);
            // ...
            file.timestamp = lastTimestamp;

        }
    }

    closedir(dir);
}
