['```c
#include <stdlib.h>
#include <stdio.h>

// Define a record structure with an integer value
typedef struct {
    int value;
} Record;

// Define a hash table node with key-value pair and next pointer
typedef struct _hashNode {
    int key;
    Record* value;
    struct _hashNode* next;
} HashNode;

// Define a hash table with dynamic resizing and thread-safe access
HashNode** ht = NULL; // Initialize the hash table

void init_hash_table(int size) {
    ht = (HashNode**)malloc((size + 1) * sizeof(HashNode*));
    for (int i = 0; i <= size; i++) {
        ht[i] = NULL;
    }
}

void resize_hash_table() {
    int new_size = ht[0]->key + 10;
    HashNode** new_ht = (HashNode**)malloc((new_size + 1) * sizeof(HashNode*));
    for (int i = 0; i <= new_size; i++) {
        new_ht[i] = NULL;
    }
    for (int i = 0; i < ht[0]->key + 1; i++) {
        HashNode* node = ht[i];
        while (node) {
            HashNode* next = node->next;
            int idx = node->key % new_size;
            if (!new_ht[idx]) {
                new_ht[idx] = node;
            } else {
                HashNode* cur = new_ht[idx];
                while (cur->next) {
                    cur = cur->next;
                }
                cur->next = node;
            }
            node = next;
        }
    }
    free(ht);
    ht = new_ht;
}

void cleanup() {
    for (int i = 0; i < ht[0]->key + 1; i++) {
        HashNode* node = ht[i];
        while (node) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }
}

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

int main() {
    int offset_size = 1000;
    long* offsets = (long*)my_malloc(offset_size * sizeof(long));
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }

    int key_size = 2000;
    int* keys = (int*)my_malloc(key_size * sizeof(int));
    for (int i = 0; i < key_size; i++) {
        keys[i] = i;
    }

    int record_size = 3000;
    Record* records = (Record*)my_malloc(record_size * sizeof(Record));
    for (int i = 0; i < record_size; i++) {
        records[i].value = i;
    }

    init_hash_table(key_size);
    // Insert key-value pairs into the hash table
    for (int i = 0; i < key_size; i++) {
        int idx = keys[i] % ht[0]->key + 1;
        HashNode* node = (HashNode*)my_malloc(sizeof(HashNode));
        node->key = keys[i];
        node->value = &records[i];
        node->next = ht[idx];
        ht[idx] = node;
    }

    // Periodically clean up unused resources and optimize performance
    cleanup();

    return 0;
}

