#define MAX_EVENTS 10000
#define BATCH_SIZE (1 << 20) // 1MB
#define DNS_PORT 53
#define LOG_FILE_MAX_SIZE (1024 * 1024 * 1024) // 1GB

typedef struct {
    char hostname[256];
    char ipaddr[17]; // 16 bytes for IP address and 1 byte for null terminator
} Event;

Event* process_log_file(const char* file_path, int* total_events) {
    FILE* file = fopen(file_path, "r");
    if (file == NULL)
        return NULL;

    *total_events = 0;

    Event* events = NULL;
    size_t event_count = 0;
    size_t batch_size = BATCH_SIZE;
    size_t bytes_read = 0;
    char buffer[BATCH_SIZE];
    int error_code = 0;

    while (1) {
        if (bytes_read >= batch_size) {
            // Process the current batch
            *total_events += event_count;
            process_batch(events, event_count);

            // Reset for the next batch
            free(events);
            events = NULL;
            event_count = 0;
            bytes_read = 0;
        }

        int bytes_to_read = MIN(batch_size - bytes_read, (int)(LOG_FILE_MAX_SIZE - bytes_read));
        if ((bytes_to_read = fread(buffer, 1, bytes_to_read, file)) <= 0) {
            if (feof(file))
                break; // End of file
            else if (ferror(file)) {
                error_code = 1;
                break;
            }
        }

        size_t pos = 0;
        while (pos < bytes_to_read) {
            // Parse log event from buffer
            Event* event = malloc(sizeof(Event));
            if (event == NULL)
                return NULL; // Out of memory

            // ... parse the event ...

            pos += strlen(buffer) + 1; // Move to next event

            if (pos >= bytes_to_read) {
                free(event);
                break;
            }
        }

        event_count += (pos / sizeof(Event)) - 1; // Adjust for null terminator
        events = realloc(events, (event_count + 1) * sizeof(Event));
        memcpy(events + event_count - 1, buffer, pos); // Copy the last event

        bytes_read += pos;
    }

    fclose(file);

    if (error_code)
        return NULL; // File parsing error

    process_batch(events, event_count);

    free(events);
    return NULL;
}

int get_dns_ip(const char* hostname, u_char* ipaddr) {
    struct hostent* host = gethostbyname(hostname);
    if (host == NULL)
        return -1;

    inet_ntop(AF_INET, host->h_addr, ipaddr, 16);
    return 0;
}

int process_batch(Event* events, size_t count) {
