    int result = ((void (*)(char*, char*, void*))conversionUtility)(jpegFilePath, pdfFilePath);

    // Check for errors
    if (result == -1) {
        fprintf(errorLog, "JPEG to PDF conversion failed: %s\n", strerror(errno));
    } else if (result != 0) {
        fprintf(errorLog, "Unknown error during JPEG to PDF conversion\n");
    }

    fclose(errorLog);
}

