// Predefined list of approved skills
const char* APPROVED_SKILLS[] = {"Java", "Python", "C++", "JavaScript"};

typedef struct {
    char name[256];
    int age;
    char email[128];
    char** skills; // dynamically allocated array
    size_t skill_count;
} UserProfile;

// Function to manage a dynamic set of user profiles
UserProfile* create_user_profile(const char* name, int age, const char* email) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    strcpy(profile->name, name);
    profile->age = age;
    strcpy(profile->email, email);
    profile->skill_count = 0;
    profile->skills = NULL; // initialize dynamic array later

    return profile;
}

// Function to add a skill to a user profile
void add_skill(UserProfile* profile, const char* skill) {
    size_t i;
    for (i = 0; i < profile->skill_count; i++) {
        if (strcmp(profile->skills[i], skill) == 0)
            return; // skill already exists in the list
    }

    // Allocate memory for a new skill and append to the array
    profile->skills = (char**)realloc(profile->skills, (profile->skill_count + 1) * sizeof(char*));
    profile->skills[profile->skill_count] = strdup(skill);
    profile->skill_count++;
}

// Function to remove a skill from a user profile
void remove_skill(UserProfile* profile, const char* skill) {
    size_t i;
    for (i = 0; i < profile->skill_count; i++) {
        if (strcmp(profile->skills[i], skill) == 0) {
            // Remove the skill from the array and re-allocate memory
            free(profile->skills[i]);
            memmove(&profile->skills[i], &profile->skills[i + 1], (profile->skill_count - i - 1) * sizeof(char*));
            profile->skill_count--;
            break;
        }
    }

    // Re-allocate the skills array if necessary
    if (profile->skill_count > 0)
        profile->skills = (char**)realloc(profile->skills, profile->skill_count * sizeof(char*));
}

// Function to validate a user profile and its skills
bool validate_user_profile(UserProfile* profile) {
    size_t i;
    for (i = 0; i < profile->skill_count; i++) {
        bool skill_found = false;
        for (size_t j = 0; j < sizeof(APPROVED_SKILLS) / sizeof(const char*); j++) {
            if (strcmp(profile->skills[i], APPROVED_SKILLS[j]) == 0) {
                skill_found = true;
                break;
            }
        }

        if (!skill_found)
            return false; // invalid skill found
    }

    return true; // profile is valid
}

// Function to import user profiles from a CSV file
UserProfile* import_profiles_from_csv(const char* csv_file_name) {
    FILE* file = fopen(csv_file_name, "r");
    if (file == NULL)
        return NULL;

    UserProfile* profiles = NULL;
    size_t total_profiles = 0;

    while (1) {
        UserProfile profile;
        if (!fscanf(file, "%s %d %s", profile.name, &profile.age, profile.email)) {
            break; // end of file
        }

        for (size_t i = 0; i < profile.skill_count; i++) {
            fscanf(file, "%s", profile.skills[i]);
        }

        // Check if the email is unique across all profiles
        bool duplicate_email = false;
        UserProfile* current_profile = profiles;
        while (current_profile != NULL) {
            if (strcmp(current_profile->email, profile.email) == 0) {
                duplicate_email = true;
                break;
            }
            current_profile = current_profile->next;
        }

        if (duplicate_email)
            return NULL; // email is not unique

        // Allocate memory for the new user profile and append to the list
        profiles = (UserProfile*)realloc(profiles, (total_profiles + 1) * sizeof(UserProfile));
        profiles[total_profiles] = profile;

        total_profiles++;
    }

    fclose(file);
    return profiles;
}
