#include <arpa/inet.h>

#define MAX_INT 1000
#define MAX_FLOAT 10000.0f
#define BUFFER_SIZE 1024
#define NUM_BUFFERS 10

int compare_float(const void *a, const void *b) {
    return (*(float*)a > *(float*)b) - (*(float*)a < *(float*)b);
}

int compare_int(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

void process_numbers(int sockfd) {
    int i = 0, j = 0;
    float max_float = -MAX_FLOAT;
    int max_int = INT_MIN;
    char buffer[BUFFER_SIZE];
    struct sockaddr_in addr;
    socklen_t len = sizeof(addr);

    // Create a pool of buffers
    char **buffers = (char **)malloc(NUM_BUFFERS * sizeof(char *));
    for (int k = 0; k < NUM_BUFFERS; k++) {
        buffers[k] = (char *)malloc(BUFFER_SIZE);
    }

    while (1) {
        int bytes_read = recv(sockfd, buffer, BUFFER_SIZE, 0);

        if (bytes_read == -1) {
            perror("recv");
            break;
        } else if (bytes_read == 0) {
            printf("Connection closed\n");
            break;
        }

        // Process numbers in the buffer
        for (int k = 0; k < bytes_read; k++) {
            char c = buffer[k];

            if (c >= '0' && c <= '9') {
                int num;

                // Read integer number
                while (k < bytes_read && c >= '0' && c <= '9') {
                    c = buffer[++k];
                }
                if (k - 1 > 0) {
                    num = atoi(&buffer[0]);

                    if (num >= -MAX_INT && num <= MAX_INT) {
                        int *int_array;
                        float *float_array;

                        // Check if memory allocation failed
                        if (!(int_array = (int *)realloc(NULL, sizeof(int))) || 
                            !(float_array = (float *)realloc(NULL, sizeof(float)))) {
                            perror("Memory allocation");
                            break;
                        }

                        int_array[i++] = num;
                        max_int = *std::max_element(int_array, int_array + i);

                        if (!(c & 0x40)) { // Assume float number
                            while (k < bytes_read && c <= '.' && c >= '0' || c >= '1') {
                                c = buffer[++k];
                            }
                            if (k - 1 > 0) {
                                float num;
                                char *end;

                                num = strtod(&buffer[0], &end);
                                if (*end == '\0' && num <= MAX_FLOAT) {
                                    float_array[j++] = num;
                                    max_float = *std::max_element(float_array, float_array + j);
                                }
                            }
                        }
                    } else {
                        printf("Invalid integer value: %d\n", num);
                        break;
                    }
                }
            } else if (c >= 'a' && c <= 'z') {
                // Assume string
                int len_str = 0;
                while (k < bytes_read && c >= 'a' && c <= 'z') {
                    c = buffer[++k];
                    len_str++;
                }

                printf("Invalid input: %s\n", &buffer[0]);
                break;
            } else if (c == '\0') {
                // End of message
                break;
            }
        }
    }

    free(buffers);

    printf("Maximum integer value: %d\n", max_int);
    printf("Maximum float value: %f\n", max_float);
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        return -1;
    }

    process_numbers(sockfd);

    close(sockfd);
    return 0;
}
