Metadata parseTIFF(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return (Metadata){0, 0, ""};

    Metadata metadata;
    int bytesRead = fread(&metadata.bitsPerSample, sizeof(int), 1, file);
    bytesRead += fread(&metadata.samplesPerPixel, sizeof(int), 1, file);
    bytesRead += fread(metadata.colorSpace, sizeof(char), 9, file);

    if (bytesRead != 12) {
        // Handle corrupted or truncated file
        fclose(file);
        return metadata;
    }

    int pages = 0;
    while (!feof(file)) {
        Metadata pageMetadata;
        bytesRead = fread(&pageMetadata.bitsPerSample, sizeof(int), 1, file);
        bytesRead += fread(&pageMetadata.samplesPerPixel, sizeof(int), 1, file);
        bytesRead += fread(pageMetadata.colorSpace, sizeof(char), 9, file);

        if (bytesRead != 12) break;

        // Handle non-standard values
        if ((metadata.bitsPerSample < 1 || metadata.bitsPerSample > 16) ||
            (metadata.samplesPerPixel < 1 || metadata.samplesPerPixel > 4)) {
            fprintf(stderr, "Warning: Non-standard value for bits per sample or samples per pixel\n");
        }

        // Handle different compression methods
        int compressionMethod = fgetc(file);
        if (compressionMethod == 1) { // PackBits
            // ...
        } else if (compressionMethod == 2) { // LZW
            // ...
        } else if (compressionMethod == 3) { // JPEG
            // ...
        } else {
            fclose(file);
            return metadata;
        }

        pages++;
    }

    fclose(file);

    return metadata;
}
