void process_filenames(char **filenames, int num_files) {
    // Define the possible extension patterns and corresponding directories
    const char *extensions[] = {"jpg", "png", "pdf"};
    const char *directories[] = {"images", "photos", "docs"};

    for (int i = 0; i < num_files; i++) {
        char filename[1024];
        strcpy(filename, filenames[i]);

        // Analyze the filename to determine the appropriate directory path
        int extension_index = -1;
        for (int j = 0; j < sizeof(extensions) / sizeof(extensions[0]); j++) {
            if (strcmp(&filename[strlen(filename) - strlen(extensions[j])], extensions[j]) == 0) {
                extension_index = j;
                break;
            }
        }

        // Construct the directory path using sprintf
        char dir_path[1024];
        sprintf(dir_path, "/%s/%s", directories[extension_index], filename);

        // Print or store the processed filename and directory path as needed
        printf("%s -> %s\n", filenames[i], dir_path);
    }
}

int main() {
    int num_files = 10;
    char *filenames[] = {"image1.jpg", "doc1.pdf", "photo2.png", ...}; // Add more filenames as needed

    process_filenames(filenames, num_files);

    return 0;
}
