// Define the structure to represent network interface configuration settings
typedef struct {
    char* name;
    char* ip_address;
    char* subnet_mask;
    int num_ports;
    struct port_config** ports;
} net_interface;

// Define a structure to represent port configurations
typedef struct {
    int port_number;
    char* protocol;
} port_config;

// Function to add a new network interface configuration
void add_net_interface(net_interface** interfaces, int* size) {
    // Allocate memory for the new interface
    *size += 1;
    *interfaces = (net_interface*) realloc(*interfaces, sizeof(net_interface) * (*size));

    // Initialize the new interface with default values
    (*interfaces)[*size - 1].name = NULL;
    (*interfaces)[*size - 1].ip_address = NULL;
    (*interfaces)[*size - 1].subnet_mask = NULL;
    (*interfaces)[*size - 1].num_ports = 0;
    (*interfaces)[*size - 1].ports = NULL;

    // Update the size of the array
    *size -= 1;
}

// Function to remove a network interface configuration
void remove_net_interface(net_interface** interfaces, int* size) {
    if (*size > 0) {
        // Free memory for the removed interface
        free((*interfaces)[--(*size)].name);
        free((*interfaces)[*size].ip_address);
        free((*interfaces)[*size].subnet_mask);
        free((*interfaces)[*size].ports);

        // Shift remaining interfaces down by one position
        memmove(&(*interfaces)[0], &(*interfaces)[1], sizeof(net_interface) * (*size));
    }
}

// Function to update a network interface configuration
void update_net_interface(net_interface** interfaces, int size, char* name, char* ip_address, char* subnet_mask) {
    for (int i = 0; i < size; i++) {
        if (strcmp((*interfaces)[i].name, name) == 0) {
            // Update the interface's IP address and subnet mask
            free((*interfaces)[i].ip_address);
            (*interfaces)[i].ip_address = strdup(ip_address);
            free((*interfaces)[i].subnet_mask);
            (*interfaces)[i].subnet_mask = strdup(subnet_mask);
            return;
        }
    }
}

// Function to add a port configuration
void add_port_config(net_interface* interface, int port_number, char* protocol) {
    // Allocate memory for the new port configuration
    interface->num_ports += 1;
    interface->ports = (port_config**) realloc(interface->ports, sizeof(port_config*) * (interface->num_ports + 1));
    interface->ports[interface->num_ports - 1] = malloc(sizeof(port_config));
    (*interface->ports)[interface->num_ports - 1]->port_number = port_number;
    (*interface->ports)[interface->num_ports - 1]->protocol = strdup(protocol);

    // Update the size of the array
    interface->ports = (port_config**) realloc(interface->ports, sizeof(port_config*) * interface->num_ports);
}

// Function to remove a port configuration
void remove_port_config(net_interface* interface) {
    if (interface->num_ports > 0) {
        free((*interface->ports)[--(interface->num_ports)].protocol);

        // Shift remaining ports down by one position
        memmove(&(*interface->ports)[0], &(*interface->ports)[1], sizeof(port_config*) * interface->num_ports);
    }
}

