#include <stdlib.h>
#include <string.h>

typedef struct {
    char* interface_name;
    char* ip_address;
    char* subnet_mask;
    int port_config[5];
    double latency;
    double throughput;
} NetworkInterfaceConfig;

// Thread-safe dynamic array of network configurations
typedef struct {
    NetworkInterfaceConfig** configs;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize a new dynamic array with the given initial capacity
DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->configs = (NetworkInterfaceConfig**)malloc(initial_capacity * sizeof(NetworkInterfaceConfig*));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Add a new network configuration to the array
void dynamic_array_add(DynamicArray* arr, NetworkInterfaceConfig* config) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        arr->configs = (NetworkInterfaceConfig**)realloc(arr->configs, new_capacity * sizeof(NetworkInterfaceConfig*));
        arr->capacity = new_capacity;
    }

    arr->configs[arr->size++] = config;

    pthread_mutex_unlock(&arr->lock);
}

// Remove the network configuration at the given index from the array
void dynamic_array_remove(DynamicArray* arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index >= arr->size) return;

    for (size_t i = index; i < arr->size - 1; ++i) {
        arr->configs[i] = arr->configs[i + 1];
    }

    free(arr->configs[--arr->size]);

    pthread_mutex_unlock(&arr->lock);
}

// Update the network configuration at the given index
void dynamic_array_update(DynamicArray* arr, size_t index, NetworkInterfaceConfig* config) {
    pthread_mutex_lock(&arr->lock);

    if (index >= arr->size) return;

    arr->configs[index] = config;

    pthread_mutex_unlock(&arr->lock);
}

// Get the network configuration at the given index
NetworkInterfaceConfig* dynamic_array_get(DynamicArray* arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index >= arr->size) return NULL;

    NetworkInterfaceConfig* config = arr->configs[index];

    pthread_mutex_unlock(&arr->lock);

    return config;
}

// Compact the array to reduce memory fragmentation
void dynamic_array_compact(DynamicArray* arr) {
    pthread_mutex_lock(&arr->lock);

    size_t new_capacity = arr->size * 2 + 1;
    NetworkInterfaceConfig** new_configs = (NetworkInterfaceConfig**)malloc(new_capacity * sizeof(NetworkInterfaceConfig*));

    for (size_t i = 0; i < arr->size; ++i) {
        new_configs[i] = arr->configs[i];
    }

    free(arr->configs);
    arr->configs = new_configs;
    arr->capacity = new_capacity;

    pthread_mutex_unlock(&arr->lock);
}

void dynamic_array_free(DynamicArray* arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->configs[i]->interface_name);
        free(arr->configs[i]->ip_address);
        free(arr->configs[i]->subnet_mask);
    }

    pthread_mutex_destroy(&arr->lock);

    free(arr->configs);

    free(arr);
}
