#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 1024
#define DEFAULT_FORMAT "%d lines, %d words, longest line length: %d"

int main(int argc, char *argv[]) {
    int helpFlag = 0;
    int caseSensitiveFlag = 1;
    const char *outputFile = NULL;
    const char *formatString = DEFAULT_FORMAT;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            helpFlag = 1;
        } else if (strcmp(argv[i], "-s") == 0) {
            caseSensitiveFlag = 1;
        } else if (strstarts(argv[i], "-o")) {
            outputFile = argv[i] + 2;
        } else if (strstarts(argv[i], "-f")) {
            formatString = argv[i] + 2;
        }
    }

    FILE *inputFile = stdin;
    int lineCount = 0;
    int wordCount = 0;
    int maxLength = 0;

    if (!helpFlag) {
        for (char *line = NULL; getline(&line, &inputFile); line++) {
            int length = strlen(line);
            int words = 1 + countWords(line, caseSensitiveFlag);
            lineCount++;
            wordCount += words;
            maxLength = max(length, maxLength);
        }

        if (outputFile) {
            FILE *output = fopen(outputFile, "w");
            fprintf(output, formatString, lineCount, wordCount, maxLength);
            fclose(output);
        } else {
            printf(formatString, lineCount, wordCount, maxLength);
        }
    } else {
        printf("Usage: %s [-h|--help] [-s] [-o output_file] [-f format_string] input_file\n"
               "  -h|--help: Display this help message.\n"
               "  -s: Case-sensitive mode (default is case-insensitive).\n"
               "  -o output_file: Write results to the specified file.\n"
               "  -f format_string: Customize the output format string.\n\n", argv[0]);
    }

    return 0;
}

int countWords(const char *line, int caseSensitive) {
    int words = 1;
    for (char c = line[0]; c; c = *(++line)) {
        if (!isspace(c) || !caseSensitive) {
            continue;
        }
        words++;
    }
    return words;
}

int max(int a, int b) {
    return a > b ? a : b;
}
