typedef struct {
    int value;
} record;

// Function to initialize records with unique values
record* initRecords(int numRecords, int minVal, int maxVal) {
    record* records = (record*)malloc(numRecords * sizeof(record));
    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % ((maxVal - minVal) + 1) + minVal;
    }

    return records;
}

// Function to free allocated memory
void freeMemory(record* records, int numRecords) {
    if (records != NULL) {
        for (int i = 0; i < numRecords; i++) {
            free(&records[i]);
        }
        free(records);
    }
}

// Example usage:
int main() {
    int numRecords = 50000;
    int minVal = 1, maxVal = 100;

    record* records = initRecords(numRecords, minVal, maxVal);

    // Use the initialized records...

    freeMemory(records, numRecords);
    return 0;
}
