#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} log_level;

typedef struct {
    int type;
    log_level level;
    char* tag;
} event_type_config;

event_type_config* event_types = NULL;
int num_event_types = 0;

void init_event_logging(int num_types, event_type_config* types) {
    if (num_types > 0) {
        num_event_types = num_types;
        event_types = malloc(num_types * sizeof(event_type_config));
        memcpy(event_types, types, num_types * sizeof(event_type_config));
    }
}

int get_max_log_level(int type) {
    for (int i = 0; i < num_event_types; i++) {
        if (event_types[i].type == type) {
            return event_types[i].level;
        }
    }
    return DEBUG;
}

void log_event(int type, char* message) {
    int max_level = get_max_log_level(type);
    if (max_level <= INFO && rand() % 100 < 50) {
        // Log with error level
        printf("Error: %s\n", message);
    } else if (max_level > WARNING) {
        printf("Warning: %s\n", message);
    } else if (max_level >= DEBUG) {
        printf("Debug: %s\n", message);
    }
}

void* logging_thread(void* arg) {
    // Simulate concurrent access and logging
    for (int i = 0; i < 10000; i++) {
        int type = rand() % num_event_types;
        char message[50];
        sprintf(message, "Event type: %d", type);
        log_event(type, message);
    }
    return NULL;
}

void start_logging_threads(int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, logging_thread, NULL);
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    event_type_config types[] = {{1, DEBUG, "System"},
                                 {2, WARNING, "Network"},
                                 {3, ERROR, "Database"}};
    init_event_logging(sizeof(types) / sizeof(event_types[0]), types);
    start_logging_threads(4);
    return 0;
}
