typedef struct {
    int integer;
    char* string;
    long offset;
} record_t;

record_t* init_records(int size) {
    int real_size = (size * 5 / 4);
    record_t* records = (record_t*)malloc(real_size * sizeof(record_t));
    if (!records) return NULL;

    int* keys = (int*)malloc(size * sizeof(int));
    long* offsets = (long*)malloc(size * sizeof(long));

    for (int i = 0; i < size; i++) {
        keys[i] = rand();
        offsets[i] = (long)i;
    }

    // Initialize records with random values
    for (int i = 0; i < real_size; i++) {
        records[i].integer = rand() % 100;
        while (records[i].integer > 0) {
            for (int j = 0; j < i; j++) {
                if (records[j].integer == records[i].integer) {
                    records[i].integer = rand() % 100;
                    break;
                }
            }
        }

        // Set string pointers
        char str[16];
        sprintf(str, "Record %d", i);
        records[i].string = str;

        // Set offset and key
        records[i].offset = offsets[rand() % size];
        records[i].integer %= 5;
    }

    for (int i = real_size; i < size; i++) {
        free(records[i].string); // Ensure string memory is released
    }
    free(keys);
    free(offsets);

    return &records[0];
}

void delete_records(record_t* records, int size) {
    if (!records) return;

    for (int i = 0; i < size; i++) {
        free(records[i].string); // Ensure string memory is released
    }
    free((record_t*)records);
}
