        // Add the new structure to the array
        pdus[num_elements++] = pdu;
    }

    return pdus;
}

// Function to validate uniqueness of RX_UE_INFORMATION_TAG values
int validate_uniqueness(NFAPI_CRC_INDICATION_PDU_T* pdus, int num_elements) {
    uint32_t* tags = (uint32_t*) malloc(num_elements * sizeof(uint32_t));
    for (int i = 0; i < num_elements; i++) {
        tags[i] = pdus[i].rx_ue_info_tag;
    }

    // Sort the RX_UE_INFORMATION_TAG values
    qsort(tags, num_elements, sizeof(uint32_t), compare_tags);

    int duplicate_count = 0;
    for (int i = 1; i < num_elements; i++) {
        if (tags[i] == tags[i - 1]) {
            duplicate_count++;
        }
    }

    free(tags);
    return duplicate_count;
}

// Compare function to sort RX_UE_INFORMATION_TAG values
int compare_tags(const void* a, const void* b) {
    uint32_t tagA = *(const uint32_t*) a;
    uint32_t tagB = *(const uint32_t*) b;

    if (tagA < tagB) return -1;
    else if (tagA > tagB) return 1;
    else return 0;
}

// Function to remove duplicates while preserving the order of first occurrences
NFAPI_CRC_INDICATION_PDU_T* remove_duplicates(NFAPI_CRC_INDICATION_PDU_T* pdus, int num_elements) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc((num_elements - validate_uniqueness(pdus, num_elements)) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
