    for (int i = 1; i < num_elements; i++) {
        if (pdus[i].rx_ue_info_tag != prev_tag) {
            new_pdus[new_num_elements++] = pdus[i];
            prev_tag = pdus[i].rx_ue_info_tag;
        }
    }

    free(pdus);
    return new_pdus;
}

// Main function to demonstrate the code
