        int num_elements = 0;
        while (num_elements < max_pdu_count) {
            if (!validate_uniqueness(pdus, num_elements)) break;
            pdus = remove_duplicates(pdus, num_elements + 1);
            num_elements++;
        }

        // Print the array contents for demonstration
