} database;

database* initializeDatabase(const char* configFile) {
    FILE *file = fopen(configFile, "r");
    if (file == NULL) {
        return NULL;
    }

    int numOffsets = 0, numKeys = 0;
    fscanf(file, "%d %d", &numOffsets, &numKeys);

    database* db = (database*)malloc(sizeof(database));
    if (db == NULL) {
        fclose(file);
        return NULL;
    }

    db->offsets = (long*)calloc(numOffsets, sizeof(long));
    if (db->offsets == NULL) {
        free(db);
        fclose(file);
        return NULL;
    }

    db->keys = (int*)calloc(numKeys, sizeof(int));
    if (db->keys == NULL) {
        free(db->offsets);
        free(db);
        fclose(file);
        return NULL;
    }

    db->records = (record*)calloc(numOffsets, sizeof(record));
    if (db->records == NULL) {
        free(db->offsets);
        free(db->keys);
        free(db);
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < numOffsets; i++) {
        db->records[i].valuePointer = &db->offsets[i];
        int keyIndex = rand() % numKeys;
        db->records[i].key = db->keys[keyIndex];
        sprintf(db->records[i].description, "Record %d: Key %d", i, db->records[i].key);
    }

    db->numOffsets = numOffsets;
    db->numKeys = numKeys;
    db->maxKey = (int)ceil(sqrt(numKeys));
    db->numRecords = numOffsets;

    fclose(file);

    return db;
}
