#define MAX_SIZE 1024

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int *array_size = NULL;
NFAPI_CRC_INDICATION_PDU_T **array = NULL;
pthread_once_t once_init = PTHREAD_ONCE_INIT;

void once_init_func(void) {
    array_size = malloc(sizeof(int));
    *array_size = 0;
    array = malloc(MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    for (int i = 0; i < MAX_SIZE; i++) {
        array[i] = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T **nfapi_crc_indication_pdu_array_init(void) {
    pthread_once(&once_init, once_init_func);
    return array;
}

void nfapi_crc_indication_pdu_array_deinit(NFAPI_CRC_INDICATION_PDU_T **array) {
    for (int i = 0; i < *array_size; i++) {
        if (array[i] != NULL)
            free(array[i]);
    }
    free(array);
    free(array_size);
}

void nfapi_crc_indication_pdu_array_add(NFAPI_CRC_INDICATION_PDU_T **array, NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&mutex);
    if (*array_size >= MAX_SIZE) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    array[*array_size] = new_element;
    (*array_size)++;
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu_array_get(NFAPI_CRC_INDICATION_PDU_T **array, int index) {
    if (index < 0 || index >= *array_size) {
        return NULL;
    }
    return array[index];
}

void nfapi_crc_indication_pdu_array_remove(NFAPI_CRC_INDICATION_PDU_T **array, int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= *array_size) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (int i = index; i < *array_size - 1; i++) {
        array[i] = array[i + 1];
    }
    free(array[*array_size - 1]);
    (*array_size]--;
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T **nfapi_crc_indication_pdu_array_update(NFAPI_CRC_INDICATION_PDU_T **array, NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&mutex);
    if (*array_size >= MAX_SIZE) {
        pthread_mutex_unlock(&mutex);
        return array;
    }
    for (int i = 0; i < *array_size; i++) {
        if (array[i] == NULL || memcmp((void *)&(array[i]->rx_ue_info), (void *)&(new_element->rx_ue_info), sizeof(RX_UE_INFORMATION_TAG)) == 0) {
            array[i] = new_element;
            pthread_mutex_unlock(&mutex);
            return array;
        }
    }
    for (int i = *array_size; i > index && i < MAX_SIZE; i--) {
        array[i - 1] = array[i];
    }
    array[0] = new_element;
    (*array_size)++;
    pthread_mutex_unlock(&mutex);
    return array;
}
