typedef struct {
    int key;
    long offset;
} record_t;

void rename_files(char **filenames, int num_files) {
    for (int i = 0; i < num_files; i++) {
        char *filename = filenames[i];
        char *new_filename = malloc(strlen(filename) + 17); // max length including extension
        time_t now = time(NULL);
        struct tm *current_time = localtime(&now);

        sprintf(new_filename, "%04d%02d%02d-%02d%02d%S%s", current_time->tm_year + 1900, current_time->tm_mon + 1, current_time->tm_mday,
                current_time->tm_hour % 24, current_time->tm_min, current_time->tm_sec, get_extension(filename));

        int unique_identifier_length = strlen(new_filename);
        for (int j = 0; j < 16 && j < unique_identifier_length; j++) {
            new_filename[j] = filename[j];
        }
        new_filename[unique_identifier_length > 16 ? 16 : unique_identifier_length] = '\0';

        // check if a duplicate identifier exists within the last minute
        for (int k = i - 1; k >= 0 && k < num_files; k--) {
            char *old_filename = filenames[k];
            if (strcmp(get_extension(old_filename), get_extension(new_filename)) == 0) {
                int old_identifier_length = strlen(old_filename);
                for (int j = 0; j < unique_identifier_length && j < old_identifier_length; j++) {
                    if (new_filename[j] != old_filename[old_identifier_length - j - 1]) break;
                }
                if (j == unique_identifier_length) {
                    // duplicate identifier found, increment timestamp
                    now += 60; // add one minute
                    current_time = localtime(&now);
                    sprintf(new_filename, "%04d%02d%02d-%02d%02d%S%s", current_time->tm_year + 1900, current_time->tm_mon + 1, current_time->tm_mday,
                            current_time->tm_hour % 24, current_time->tm_min, current_time->tm_sec, get_extension(filename));
                    break;
                }
            }
        }

        // allocate memory for and initialize the record array
        int num_records = 0;
        char *extension = get_extension(new_filename);
        size_t extension_length = strlen(extension);

        FILE *file = fopen(new_filename, "w");
        if (file != NULL) {
            srand(time(NULL));
            record_t *records = malloc((num_records + 1) * sizeof(record_t));

            for (int i = 0; i < num_records; i++) {
                int key = rand() % 100;
                long offset = rand() % 10000;

                records[i].key = key;
                records[i].offset = offset;

                fprintf(file, "%d %ld\n", key, offset);
            }

            free(records);

            fclose(file);

            // rename file
            char *new_extension = malloc(extension_length + 4);
            sprintf(new_extension, ".%s-%d", extension, i);
            rename(new_filename, new_filename);

            free(new_extension);
        }

        free(new_filename);
    }
}

char *get_extension(char *filename) {
    int dot_pos = strlen(filename) - 1;
    while (dot_pos > 0 && filename[dot_pos] != '.') {
        dot_pos--;
    }
    char *extension = malloc(dot_pos + 2);
    memcpy(extension, &filename[dot_pos], dot_pos - dot_pos);
    extension[dot_pos - dot_pos] = '\0';
    return extension;
}
