        line_count++;
    }

    close(file_fd);

    FILE* output_file = fopen("output.txt", "w");
    if (output_file) {
        for (int i = 0; i < line_count; i++) {
            fwrite(lines[i].buffer, sizeof(char), lines[i].size, output_file);
            printf("\n");
        }
        fclose(output_file);
    } else {
        // Handle file writing error
        return 1;
    }

    free(lines);
    return 0;
}

