#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[3];
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe dynamic list to manage NFAPI_CRC_INDICATION_PDU_T structures
typedef struct DynamicList {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

void dynamic_list_init(DynamicList* list, size_t initial_capacity) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        // Double the capacity to handle growth
        list->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity *= 2;
    }

    // Validate and sanitize input
    if (new_entry->RNTI > 0 && !is_valid_CRC_INDICATION_REL8_TAG(new_entry->CRC_INDICATION_REL8_TAG)) {
        printf("Invalid CRC indication received\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Add new entry to the end of the list
    list->data[list->size] = *new_entry;
    (list->size)++;

    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_update(DynamicList* list, uint16_t RNTI, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            // Update existing entry
            list->data[i] = *new_entry;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_remove(DynamicList* list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            // Shift elements down to fill the gap
            memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            (list->size)--;

            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
