#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
    int value;
} Record;

// Function to initialize and manage records array
Record** initRecords(int capacity) {
    Record** records = (Record**)malloc((capacity+1)*sizeof(Record*));
    for(int i=0; i<=capacity; i++) {
        records[i] = NULL;
    }
    return records;
}

// Function to set record values
void setRecordValues(Record** records, int capacity) {
    srand(time(NULL)); // Seed random number generator
    for(int i=1; i<=capacity; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->key = rand() % 100;
        record->value = rand() % 1000;
        records[i] = record;
    }
}

// Function to handle HTTP PUT request
int putRequest(int id, int value, Record** records) {
    for(int i=1; i<=*records; i++) {
        if(records[i]->key == id) {
            free(records[i]);
            records[i] = (Record*)malloc(sizeof(Record));
            records[i]->key = id;
            records[i]->value = value;
            return 0; // Successful update
        }
    }
    return -1; // Resource not found
}

// Function to handle HTTP DELETE request
int deleteRequest(int id, Record** records) {
    for(int i=1; i<=*records; i++) {
        if(records[i]->key == id) {
            free(records[i]);
            records[i] = NULL;
            return 0; // Successful deletion
        }
    }
    return -1; // Resource not found
}

// Function to handle HTTP GET request
int getRequest(Record** records, int id) {
    for(int i=1; i<=*records; i++) {
        if(records[i]->key == id) {
            printf("Key: %d, Value: %d\n", records[i]->key, records[i]->value);
            return 0; // Successful retrieval
        }
    }
    return -1; // Resource not found
}

int main() {
    int capacity = 100;
    Record** records = initRecords(capacity);
    setRecordValues(records, capacity);

    // Handle HTTP requests
    while(1) {
        int id;
        printf("Enter ID (0 to quit): ");
        scanf("%d", &id);
        if(id == 0) break;

        char method[3];
        printf("Enter method (PUT or DELETE): ");
        scanf("%s", method);

        if(strcmp(method, "PUT") == 0) {
            int value;
            printf("Enter new value: ");
            scanf("%d", &value);
            putRequest(id, value, records);
        } else if(strcmp(method, "DELETE") == 0) {
            deleteRequest(id, records);
        }
    }

    // Deallocate memory
    for(int i=1; i<=capacity; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}
