['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int value;
    char *key;
    struct record *next;
} record;

record *records = NULL;
int record_count = 0;

void add_record(int value, const char *key) {
    record *new_rec = (record *)malloc(sizeof(record));
    new_rec->value = value;
    new_rec->key = strdup(key);
    new_rec->next = records;
    records = new_rec;
    record_count++;
}

void update_value(int index, int new_value) {
    if (index < 0 || index >= record_count)
        return;

    record *curr = &records;
    for (int i = 0; i < index; i++)
        curr = curr->next;

    curr->value = new_value;
}

void print_records() {
    record *curr = records;
    while (curr != NULL) {
        printf("Value: %d, Key: %s\n", curr->value, curr->key);
        curr = curr->next;
    }
}

void free_memory() {
    record *curr = records;
    record *prev = NULL;

    while (curr != NULL) {
        record *temp = curr;
        curr = curr->next;
        if (prev != NULL)
            free(prev->key);
        free(temp);
        prev = temp;
    }
}

void handle_out_of_memory() {
    printf("Out of memory! Aborting.\n");
    exit(1);
}
