// Define a struct to represent a node in the linked list
typedef struct {
    char *ip;
    struct Node* next;
} Node;

// Function to resolve hostname to IP addresses
int resolve_hostname(char* hostname, int max_addresses) {
    // Create a linked list to store the IP addresses
    Node* head = NULL;
    Node* current = NULL;

    // Perform DNS resolution using getaddrinfo()
    struct addrinfo hints, *res;
    int retcode = 0;
    char error_message[1024];
    size_t length = 0;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;  // IPv4
    hints.ai_socktype = SOCK_STREAM;

    getaddrinfo(hostname, NULL, &hints, &res);

    if (res != NULL) {
        // Allocate memory for the IP address string
        char* ip = (char*)malloc(50);
        strcpy(ip, inet_ntop(AF_INET, &((struct sockaddr_in*)res->ai_addr)->sin_addr, ip, 40));

        // Create a new node in the linked list and add it to the end
        if (head == NULL) {
            head = current = (Node*)malloc(sizeof(Node));
            current->ip = ip;
            current->next = NULL;
        } else {
            Node* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = (Node*)malloc(sizeof(Node));
            temp->next->ip = ip;
            temp->next->next = NULL;
        }

        // Resolve the next address in the list
        getaddrinfo(NULL, NULL, res, &res);
    } else {
        retcode = -1;  // Error code for DNS resolution failure
    }

    freeaddrinfo(res);

    // Check if the maximum number of addresses has been reached
    Node* temp2 = head;
    int count = 0;

    while (temp2 != NULL) {
        temp2 = temp2->next;
        count++;
    }

    if (count >= max_addresses) {
        retcode = -1;  // Error code for maximum address limit exceeded
    }

    return retcode;
}

// Function to print the linked list of IP addresses
void print_ip_list(Node* head) {
    Node* current = head;

    while (current != NULL) {
        printf("%s\n", current->ip);
        current = current->next;
    }
}

int main() {
    // Test the function with a sample hostname
    char* hostname = "example.com";
    int max_addresses = 10;

    int retcode = resolve_hostname(hostname, max_addresses);

    if (retcode == -1) {
        printf("Error: DNS resolution failed or maximum address limit exceeded\n");
    } else {
        print_ip_list(head);
    }

    return 0;
}
