        float latency;
        float throughput;
    } *port_configs;
} network_config;

network_config *configurations = NULL;
int configurations_size = 0;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void add_config(network_config **configs, int size, char *name, char *ip, char *mask) {
    pthread_mutex_lock(&config_lock);
    if (*configs == NULL || size > configurations_size) {
        *configs = realloc(*configs, (size + 1) * sizeof(network_config));
        configurations_size = size;
    }
    network_config *new_config = &(*configs)[size];
    new_config->name = name;
    new_config->ip = ip;
    new_config->mask = mask;
    new_config->port_configs_size = 0;
    pthread_mutex_unlock(&config_lock);
}

void update_config(network_config **configs, int index, char *new_name) {
    pthread_mutex_lock(&config_lock);
    if (index >= configurations_size || configs == NULL) {
        pthread_mutex_unlock(&config_lock);
        return;
    }
    network_config *config = &(*configs)[index];
    free(config->name);
    config->name = new_name;
    pthread_mutex_unlock(&config_lock);
}

void remove_config(network_config **configs, int index) {
    pthread_mutex_lock(&config_lock);
    if (index >= configurations_size || configs == NULL) {
        pthread_mutex_unlock(&config_lock);
        return;
    }
    network_config *new_configs = realloc(*configs, --configurations_size * sizeof(network_config));
    memmove(&new_configs[index], &new_configs[index + 1], (configurations_size - index) * sizeof(network_config));
    free(new_configs[index].name);
    pthread_mutex_unlock(&config_lock);
}

network_config *query_config(network_config **configs, int index) {
    if (index >= configurations_size || configs == NULL) return NULL;
    return &(*configs)[index];
}

void* worker_thread(void* arg) {
