use std::collections::HashMap;
use std::fs::OpenOptions;
use std::path::PathBuf;
use std::sync::{mpsc, Mutex};
use std::time::Duration;

struct Semaphore {
    value: u32,
    waiters: HashMap<u32, mpsc::Receiver<()>>,
}

impl Semaphore {
    fn new(initial_value: u32) -> Self {
        Semaphore { value: initial_value, waiters: HashMap::new() }
    }

    fn down(&mut self) -> Option<(u32, &mut Semaphore)> {
        let timeout = Duration::from_millis(100);
        let (tx, rx) = mpsc::channel();
        *self.waiters.entry(tx.as_raw_socket()).or_insert(tx).1 = Some(rx);

        match tx.send(()).timeout(timeout) {
            Ok(_) => self.value -= 1,
            Err(_) => return None,
        }

        Some((self.value, self))
    }

    fn up(&mut self) -> Option<(u32, &mut Semaphore)> {
        let timeout = Duration::from_millis(100);
        let mut to_return = None;
        for (tx, rx) in self.waiters.iter() {
            if let Ok(_) = tx.recv_timeout(timeout) {
                *self.waiters.get_mut(tx.as_raw_socket()).unwrap().1 = None;
                to_return = Some((self.value + 1, self));
                break;
            }
        }

        to_return
    }

    fn wait(&mut self) -> Option<(u32, &mut Semaphore)> {
        let timeout = Duration::from_millis(100);
        let (tx, rx) = mpsc::channel();
        *self.waiters.entry(tx.as_raw_socket()).or_insert(tx).1 = Some(rx);

        match tx.send(()).timeout(timeout) {
            Ok(_) => self.value -= 1,
            Err(_) => return None,
        }

        Some((self.value, self))
    }
}

