}

// Function to populate roles field with random role names
void populate_roles(user_profile* profile, int num_roles) {
    char** roles = (char**)malloc(num_roles * sizeof(char*));
    if (!roles) return;

    for (int i = 0; i < num_roles; i++) {
        roles[i] = malloc(10 * sizeof(char));
        sprintf(roles[i], "Role-%d", i);
    }

    profile->roles = roles;
}

// Function to update an existing user profile
user_profile* update_user_profile(user_profile* profiles, int id) {
    for (int i = 0; i < strlen(profiles); i++) {
        if (profiles[i].id == id) {
            // Update profile name and roles
            profiles[i].name = "New Name";
            populate_roles(&profiles[i], 5);
            return &profiles[i];
        }
    }

    return NULL;
}

// Function to delete a user profile
user_profile* delete_user_profile(user_profile* profiles, int id) {
    for (int i = 0; i < strlen(profiles); i++) {
        if (profiles[i].id == id) {
            // Reset profile values to default
            free(profiles[i].name);
            profiles[i].name = malloc(20 * sizeof(char));
            strcpy(profiles[i].name, "Default Name");
            free(profiles[i].roles);
            return &profiles[i];
        }
    }

    return NULL;
}

int main() {
    int num_users = 10;
    user_profile* profiles = init_user_profiles(num_users);
    if (!profiles) return -1;

    // Populate roles field with random role names
    for (int i = 0; i < num_users; i++) {
        populate_roles(&profiles[i], 5);
    }

    int id = 3;
    user_profile* updated_profile = update_user_profile(profiles, id);
    if (!updated_profile) return -1;

    // Delete a profile
    updated_profile = delete_user_profile(profiles, id);
    if (!updated_profile) return -1;

    free(profiles);
    return 0;
}
