enum class AttackType {
    ATTACK_A,
    ATTACK_B
};

struct ActionRecord {
    AttackType attackType;
    int cooldownTime;
};

int handleCharacterActions() {
    srand(time(0)); // seed random number generator

    std::vector<ActionRecord*> actionRecords;

    for (int i = 0; i < 10; ++i) { // generate a sequence of 10 actions
        ActionRecord* record = new ActionRecord;
        record->attackType = static_cast<AttackType>(rand() % 2); // randomly select attack type
        record->cooldownTime = rand() % 16; // random cooldown time between 0 and 15 seconds

        actionRecords.push_back(record);
    }

    int totalCooldownTime = 0;
    AttackType previousAttack = (ActionRecord*)nullptr->attackType;

    for (auto& record : actionRecords) {
        if (record->attackType == previousAttack) { // ensure different attacks are not consecutive
            int cooldownIndex = rand() % 16; // random index within the range of cooldown times

            while (cooldownIndex > record->cooldownTime) {
                cooldownIndex -= record->cooldownTime;
                totalCooldownTime += record->cooldownTime;
                previousAttack = record->attackType;

                if (record == &actionRecords.back()) { // handle last action in sequence
                    break;
                }

                ++record; // move to the next action in the sequence
            }
        } else {
            totalCooldownTime += record->cooldownTime; // add cooldown time for new attack type

            previousAttack = record->attackType;
        }
    }

    std::cout << "Selected sequence of actions: ";
    for (auto& record : actionRecords) {
        if (record->attackType == AttackType::ATTACK_A) {
            std::cout << "A ";
        } else {
            std::cout << "B ";
        }
    }
    std::cout << std::endl;

    return totalCooldownTime;
}
