#include <sys/wait.h>

#define MAX_NICS 10
#define RETRY_COUNT 3

typedef struct {
    char mac_address[18];
    char ip_address[16];
    int port_number;
} NIC_CONFIG_T;

void configure_nic(NIC_CONFIG_T* nic, int id) {
    // Configure MAC, IP and PORT for the given NIC
    sprintf(nic->mac_address, "00:11:%02x:%02x", (id % 256), ((id / 256) % 256));
    strcpy(nic->ip_address, "192.168.1.");
    nic->port_number = id;
}

void start_nic(NIC_CONFIG_T* nic, int id) {
    // Simulate the process of starting a NIC
    printf("Starting NIC %d: MAC - %s, IP - %s, PORT - %d\n", id, nic->mac_address, nic->ip_address, nic->port_number);
    sleep(rand() % 2 + 1); // Random delay between 1-2 seconds
}

void stop_nic(NIC_CONFIG_T* nic, int id) {
    // Simulate the process of stopping a NIC
    printf("Stopping NIC %d: MAC - %s, IP - %s, PORT - %d\n", id, nic->mac_address, nic->ip_address, nic->port_number);
    sleep(rand() % 2 + 1); // Random delay between 1-2 seconds
}

int configure_nics(int num_nics) {
    NIC_CONFIG_T* nics = (NIC_CONFIG_T*)malloc(num_nics * sizeof(NIC_CONFIG_T));
    if (!nics) return -ENOMEM; // Allocation failed

    for (int i = 0; i < num_nics; i++) {
        configure_nic(&nics[i], i);
    }

    int retry_count = RETRY_COUNT;
    while (retry_count--) {
        for (int i = 0; i < num_nics; i++) {
            start_nic(&nics[i], i);
            sleep(rand() % 2 + 1); // Random delay between 1-2 seconds
            stop_nic(&nics[i], i);
        }
    }

    free(nics);
    return 0;
}

int main(int argc, char* argv[]) {
    int num_nics = atoi(argv[1]);
    if (num_nics < 1 || num_nics > MAX_NICS) {
        printf("Invalid number of NICs. Must be between 1 and %d.\n", MAX_NICS);
        return -EINVAL; // Invalid input
    }

    configure_nics(num_nics);

    return 0;
}
