#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* ifname;
    char* ipaddr;
    char* subnet_mask;
    int num_ports;
    struct port_config* ports;
} net_iface_config;

typedef struct port_config {
    int port_num;
    char* proto; // e.g., "HTTP", "HTTPS"
    char* crypt_algo; // e.g., "AES", "Camellia"
    char* hash_func; // e.g., "MD5", "SHA1"
} port_config;

net_iface_config* create_net_iface_config(char* ifname, char* ipaddr, char* subnet_mask) {
    net_iface_config* config = malloc(sizeof(net_iface_config));
    config->ifname = strdup(ifname);
    config->ipaddr = strdup(ipaddr);
    config->subnet_mask = strdup(subnet_mask);
    config->num_ports = 0;
    config->ports = NULL;
    return config;
}

void free_net_iface_config(net_iface_config* config) {
    if (config != NULL) {
        for (int i = 0; i < config->num_ports; i++) {
            free(config->ports[i].proto);
            free(config->ports[i].crypt_algo);
            free(config->ports[i].hash_func);
        }
        free(config->ifname);
        free(config->ipaddr);
        free(config->subnet_mask);
        free(config->ports);
        free(config);
    }
}

net_iface_config* add_port(net_iface_config* config, int port_num, char* proto, char* crypt_algo, char* hash_func) {
    // Allocate space for the new port configuration
    port_config* new_port = malloc(sizeof(port_config));
    new_port->port_num = port_num;
    new_port->proto = strdup(proto);
    new_port->crypt_algo = strdup(crypt_algo);
    new_port->hash_func = strdup(hash_func);

    // Reallocate space for the updated list of ports
    config->ports = realloc(config->ports, (config->num_ports + 1) * sizeof(port_config));
    config->ports[config->num_ports] = new_port;
    config->num_ports++;

    return config;
}

net_iface_config* remove_port(net_iface_config* config, int port_num) {
    // Find the port configuration to be removed
    for (int i = 0; i < config->num_ports; i++) {
        if (config->ports[i]->port_num == port_num) {
            // Reallocate space without removing the last element
            memmove(&config->ports[i], &config->ports[i + 1], (config->num_ports - i - 1) * sizeof(port_config));
            config->num_ports--;
            free(config->ports[i]->proto);
            free(config->ports[i]->crypt_algo);
            free(config->ports[i]->hash_func);
            free(config->ports[i]);
            return config;
        }
    }

    // Port not found, return the original configuration
    return config;
}

net_iface_config* update_port(net_iface_config* config, int port_num, char* proto, char* crypt_algo, char* hash_func) {
    // Find the port configuration to be updated
    for (int i = 0; i < config->num_ports; i++) {
        if (config->ports[i]->port_num == port_num) {
            // Update the existing port configuration
            free(config->ports[i]->proto);
            free(config->ports[i]->crypt_algo);
            free(config->ports[i]->hash_func);

            config->ports[i]->proto = strdup(proto);
            config->ports[i]->crypt_algo = strdup(crypt_algo);
            config->ports[i]->hash_func = strdup(hash_func);

            return config;
        }
    }

    // Port not found, return the original configuration
    return config;
}

int main() {
    net_iface_config* config = create_net_iface_config("eth0", "192.168.1.100", "255.255.255.0");
    config = add_port(config, 80, "HTTP", "AES", "SHA1");
    config = add_port(config, 443, "HTTPS", "Camellia", "MD5");

    printf("Number of ports: %d\n", config->num_ports);
    for (int i = 0; i < config->num_ports; i++) {
        printf("Port %d: Proto - %s, Crypt - %s, Hash - %s\n",
               config->ports[i]->port_num,
               config->ports[i]->proto,
               config->ports[i]->crypt_algo,
               config->ports[i]->hash_func);
    }

    // Update a port configuration
    config = update_port(config, 443, "HTTP", "AES", "SHA1");
    printf("\nUpdated Port Configuration:\n");
    for (int i = 0; i < config->num_ports; i++) {
        printf("Port %d: Proto - %s, Crypt - %s, Hash - %s\n",
               config->ports[i]->port_num,
               config->ports[i]->proto,
               config->ports[i]->crypt_algo,
               config->ports[i]->hash_func);
    }

    // Remove a port configuration
    config = remove_port(config, 443);

    printf("\nAfter Removing Port Configuration:\n");
    for (int i = 0; i < config->num_ports; i++) {
        printf("Port %d: Proto - %s, Crypt - %s, Hash - %s\n",
               config->ports[i]->port_num,
               config->ports[i]->proto,
               config->ports[i]->crypt_algo,
               config->ports[i]->hash_func);
    }

    free_net_iface_config(config);

    return 0;
}

