        // Append to line
        size_t new_len = strlen(line) + strlen(avg_str) + 1;
        char *new_line = malloc(new_len * sizeof(char));
        strcpy(new_line, line);
        strcat(new_line, avg_str);
        free(avg_str);

        printf("%s\n", new_line);

        free(new_line);

        // Clean up
        free(last_field);
    }

    fclose(file);

    return 0;
}

