// Memory pool for managing NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* memory_pool = NULL;
size_t memory_pool_size = 0;
int memory_pool_free = MIN_MEMORY_POOL_SIZE;

// Function to validate and add an NFAPI_CRC_INDICATION_PDU_T structure to the array
int add_pdu(NFAPI_CRC_INDICATION_PDU_T** pdus, int pdu_count, NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    if (pdu_count >= MAX_PDU_COUNT || !memory_pool_free) {
        return -1; // Exceeded maximum size or memory allocation failed
    }

    for (int i = 0; i < pdu_count; ++i) {
        if (!strcmp(&((*pdus)[i]->rx_ue_info), &new_pdu->rx_ue_info)) {
            free(new_pdu); // Duplicate detected, remove and return error
            return -2;
        }
    }

    for (int i = 0; i < memory_pool_size; ++i) {
        if (!memory_pool[i].rx_ue_info) { // Free slot found in memory pool
            memcpy(&memory_pool[i], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return 1; // Successfully added to the array and memory pool
        }
    }

    // Memory pool is full, allocate more memory
    NFAPI_CRC_INDICATION_PDU_T* new_memory = (NFAPI_CRC_INDICATION_PDU_T*)malloc((memory_pool_size + MIN_MEMORY_POOL_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_memory) {
        return -1; // Memory allocation failed
    }

    memcpy(new_memory, memory_pool, memory_pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(memory_pool);
    memory_pool = new_memory;
    memory_pool_size += MIN_MEMORY_POOL_SIZE;

    return 1; // Successfully added to the array and expanded memory pool
}

// Function to print logs for debugging purposes
void log(int level, const char* message) {
    if (level <= LOG_LEVEL) {
        printf("%s\n", message);
    }
}
