ActionRecord* executeCharacterActions(const std::string& label, const std::function<void()> f, const std::function<AttackType()>& dataSource) {
    srand(time(0));

    // Dynamically allocate and initialize an array of ActionRecord structures
    size_t numActions = 10;  // Adjust this value as needed
    auto actionRecords = new ActionRecord[numActions];

    for (size_t i = 0; i < numActions; ++i) {
        AttackType attackType;
        do {
            attackType = dataSource();
        } while (attackType == getPreviousAttackType(actionRecords, i));

        int cooldownTime = rand() % 15 + 1; // Randomly generate a cooldown time
        actionRecords[i].attackType = attackType;
        actionRecords[i].cooldownTime = cooldownTime;
    }

    f(); // Execute the test function

    delete[] actionRecords;

    return nullptr;
}

AttackType getPreviousAttackType(const ActionRecord* actionRecords, size_t index) {
    if (index == 0) {
        return AttackType::ATTACK_A;  // Handle edge case for the first action
    }
    return actionRecords[index - 1].attackType;
}
