event_t **read_events(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL; // file not found or permission denied
    }

    int num_events = 0;
    fseek(file, 0, SEEK_END);
    size_t filesize = ftell(file);
    rewind(file);

    event_t **events = (event_t **)calloc((filesize / sizeof(event_t)) + 1, sizeof(event_t *));
    if (events == NULL) {
        fclose(file);
        return NULL; // memory allocation failed
    }

    char buffer[8];
    while (fread(buffer, 1, 8, file) > 0) {
        event_t *event = (event_t *)malloc(sizeof(event_t));
        if (event == NULL) {
            fclose(file);
            free(events);
            return NULL; // memory allocation failed
        }

        event->timestamp = *(time_t *)buffer;
        fread(&event->size, sizeof(size_t), 1, file);
        fread(buffer, 1, 1, file); // buffer_id
        event->buffer_id = (char *)malloc(event->size + 1);
        if (event->buffer_id == NULL) {
            fclose(file);
            free(events);
            return NULL; // memory allocation failed
        }
        fread(event->buffer_id, 1, event->size, file);
        event->buffer_id[event->size] = '\0';
        events[num_events++] = event;
    }

    fclose(file);
    return events;
}
