// Define the maximum number of network interfaces
#define MAX_CONFIGS 1000

// Structure to represent a network interface configuration
typedef struct {
    char *name;
    char *ip_address;
    char *subnet_mask;
    int num_ports;
    port_config_t *ports;
    connection_status_t status;
} interface_t;

// Define the maximum number of ports for each interface
#define MAX_PORTS 10

// Structure to represent a network configuration
typedef struct {
    int index;
    interface_t **interfaces;
    pthread_mutex_t lock;
} network_config_t;

void add_interface(network_config_t *config, interface_t *interface) {
    if (!config || config->index >= MAX_CONFIGS) {
        return;
    }

    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&config->lock);

    // Allocate memory for a new interface
    config->interfaces[config->index++] = (interface_t *)malloc(sizeof(interface_t));
    *config->interfaces[config->index - 1] = interface;

    // Release the lock to allow other threads to access the configuration
    pthread_mutex_unlock(&config->lock);
}

void remove_interface(network_config_t *config, int index) {
    if (!config || index < 0 || index >= config->index) {
        return;
    }

    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&config->lock);

    // Free the memory allocated for the removed interface
    free(config->interfaces[index]);
    memmove(config->interfaces + index, config->interfaces + index + 1, (config->index - index - 1) * sizeof(interface_t *));
    config->index--;

    // Release the lock to allow other threads to access the configuration
    pthread_mutex_unlock(&config->lock);
}

void update_interface(network_config_t *config, int index, interface_t *interface) {
    if (!config || index < 0 || index >= config->index) {
        return;
    }

