using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.XPath;

public class XmlProcessor
{
    private readonly object _lock = new object();
    private readonly Dictionary<string, XPathNode> _cache = new Dictionary<string, XPathNode>();
    private readonly ILogger _logger;

    public XmlProcessor(ILogger logger)
    {
        _logger = logger;
    }

    public XPathNode GetElement(XPathExpression expression)
    {
        try
        {
            using (XmlReader reader = XmlReader.Create("path_to_xml_file.xml"))
            {
                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == expression.Name)
                    {
                        XPathNode node = new XPathNode(reader);
                        if (_cache.TryGetValue(node.XPath, out XPathNode cachedNode) && cachedNode == node)
                        {
                            return node;
                        }
                        _cache.Add(node.XPath, node);
                        return node;
                    }
                }
            }
        }
        catch (XmlException ex)
        {
            _logger.LogError(ex);
        }
        catch (MultipleElementsFoundException ex)
        {
            _logger.LogError(ex);
        }
        return null;
    }

    public void RefreshCache()
    {
        // implement cache refresh logic here
    }

    public class XPathNode
    {
        public string XPath { get; set; }
        public XmlReader Reader { get; set; }

        public XPathNode(XmlReader reader)
        {
            Reader = reader;
        }
    }
}

public interface ILogger
{
    void LogError(Exception ex);
}

public class MultipleElementsFoundException : Exception
{
    public string ElementName { get; set; }
    public int Count { get; set; }

    public MultipleElementsFoundException(string elementName, int count)
        : base($"Multiple elements found with name '{elementName}' ({count})")
    {
        ElementName = elementName;
        Count = count;
    }
}
