#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to represent a record
typedef struct {
    int value;
} Record;

// Define a structure to manage the collection of records
typedef struct {
    Record **records;  // Array of pointers to records
    size_t capacity;    // Current capacity of the array
    size_t size;        // Number of records currently stored
} RecordCollection;

// Initialize an empty record collection
RecordCollection* init_record_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    collection->records = (Record**)(calloc(initial_capacity, sizeof(Record*)));
    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

// Insert a new record into the collection
void insert_record(RecordCollection *collection, Record *record) {
    if (collection->size == collection->capacity) {
        // Resize the array when it's full
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = (Record**)(realloc(collection->records, new_capacity * sizeof(Record*)));
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    collection->records[collection->size++] = record;
}

// Find a specific record by its value
Record* find_record_by_value(RecordCollection *collection, int target_value) {
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i]->value == target_value) {
            return collection->records[i];
        }
    }
    return NULL;
}

// Remove a record from the collection
void remove_record(RecordCollection *collection, Record *record) {
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i] == record) {
            // Move all records after this one forward by one position
            memmove(&collection->records[i], &collection->records[i+1], (collection->size - i - 1) * sizeof(Record*));
            collection->size--;
            break;
        }
    }
}

// Serialize the record collection to a file
void serialize_collection_to_file(const RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file != NULL) {
        // Write the number of records and their values
        fwrite(&collection->size, sizeof(size_t), 1, file);
        for (int i = 0; i < collection->size; i++) {
            fwrite(&collection->records[i]->value, sizeof(int), 1, file);
        }
        fclose(file);
    }
}

// Deserialize the record collection from a file
RecordCollection* deserialize_collection_from_file(const char *filename) {
    RecordCollection *collection = init_record_collection(16); // Initial capacity of 16 records

    FILE *file = fopen(filename, "rb");
    if (file != NULL) {
        size_t num_records;
        fread(&num_records, sizeof(size_t), 1, file);
        for (int i = 0; i < num_records; i++) {
            Record *record = (Record*)malloc(sizeof(Record));
            fread(&record->value, sizeof(int), 1, file);
            insert_record(collection, record);
        }
        fclose(file);
    }
    return collection;
}

// Example usage:
int main() {
    RecordCollection *collection = init_record_collection(16);

    // Insert some records
    for (int i = 0; i < 10; i++) {
        Record *record = (Record*)malloc(sizeof(Record));
        record->value = i;
        insert_record(collection, record);
    }

    // Find a specific record
    Record *found_record = find_record_by_value(collection, 5);
    printf("Found record: %d\n", found_record->value);

    // Remove a record
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i]->value == 8) {
            remove_record(collection, collection->records[i]);
            break;
        }
    }

    // Serialize the collection to a file
    serialize_collection_to_file(collection, "record_collection.dat");

    // Deserialize the collection from the file
    RecordCollection *deserialized_collection = deserialize_collection_from_file("record_collection.dat");
    printf("Deserialized record count: %zu\n", deserialized_collection->size);

    return 0;
}
