#include <stdlib.h>
#include <stdio.h>

typedef struct Node {
    int id;
    char* str;
    int num;
    struct Node* next;
    struct Node* prev;
} Node;

Node* create_node(int id, const char* str, int num) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->id = id;
    node->str = strdup(str);
    node->num = num;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void delete_node(Node* node) {
    free(node->str);
    free(node);
}

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL || new_node->id < (*head)->id) {
        new_node->next = *head;
        new_node->prev = NULL;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->id <= new_node->id) {
            current = current->next;
        }
        new_node->next = current->next;
        new_node->prev = current;
        if (new_node->next != NULL)
            new_node->next->prev = new_node;
        else
            current->next = new_node;
        *head = new_node;
    }
}

void remove_node(Node** head, Node* node) {
    if (node == *head)
        *head = node->next;
    else {
        node->prev->next = node->next;
        if (node->next != NULL)
            node->next->prev = node->prev;
    }
}

void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("ID: %d, String: %s, Number: %d\n", current->id, current->str, current->num);
        current = current->next;
    }
}

Node* find_node(Node* head, int id) {
    Node* current = head;
    while (current != NULL && current->id != id)
        current = current->next;
    return current;
}
