void allocate_arrays() {
    // Allocate arrays for double, unsigned long, and enum values
    double* arr_double = (double*)malloc(5 * sizeof(double));
    unsigned long* arr_unsigned_long = (unsigned long*)malloc(5 * sizeof(unsigned long));
    enum_status_code* arr_enum_status_code = (enum_status_code*)malloc(5 * sizeof(enum_status_code));
    timestamp_metadata* arr_timestamp_metadata = (timestamp_metadata*)malloc(5 * sizeof(timestamp_metadata));

    // Allocate array for struct data_point
    struct_data_point* arr_struct_data_point = (struct_data_point*)malloc(5 * sizeof(struct_data_point));

    // Validate the size of the identifier array against the total number of elements being allocated
    unsigned long* p = arr_unsigned_long;
    while (*p++ < 5) {
        // Populate the timestamp field of each struct data_point with a monotonically increasing sequence of timestamps starting from the current time, adjusted for sampling frequency and error margin.
        clock_gettime(CLOCK_REALTIME, &clock);
        int64_t now = clock.tv_sec * 1000 + clock.tv_nsec / 1000000;
        arr_struct_data_point->timestamp = now;

        // Initialize enum status_code values based on the corresponding operation mode
        arr_enum_status_code[*p] = STATUS_OK; // assume operation mode is OK

        // Configure timestamp_metadata records according to user-defined parameters
        arr_timestamp_metadata[*p].sampling_frequency = 10;
        arr_timestamp_metadata[*p].error_margin = 0.1;

        p++;
    }

    free(arr_double);
    free(arr_unsigned_long);
    free(arr_enum_status_code);
    free(arr_timestamp_metadata);
    free(arr_struct_data_point);
}

