        // Handle error when allocating memory
        return NULL;
    }

    // Initialize each record with 0 value
    for (int i = 0; i < m; i++) {
        records[i].value = 0;
    }

    return records;
}

long* initializeOffsets(int n) {
    long* offsets = NULL;

    // Allocate memory for array of offsets
    if ((offsets = (long*) malloc(n * sizeof(long))) == NULL) {
        // Handle error when allocating memory
        return NULL;
    }

    // Initialize each offset with a valid value
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
    }

    return offsets;
}

int* initializeKeys(int n) {
    int* keys = NULL;

    // Allocate memory for array of keys
    if ((keys = (int*) malloc(n * sizeof(int))) == NULL) {
        // Handle error when allocating memory
        return NULL;
    }

    // Initialize each key with a valid value
    for (int i = 0; i < n; i++) {
        keys[i] = i;
    }

    return keys;
}

void* initializeMemoryStructures(int n, int m) {
    if (n <= 0 || m <= 0) {
        // Handle error when n or m is invalid
        return NULL;
    }

    long* offsets = initializeOffsets(n);
    int* keys = initializeKeys(n);
    record* records = initializeRecords(m);

    // Return the pointer to the first element of the 'records' array
