import { importModule } from 'module-importer';
import blueslip from 'blueslip';
import { logTestResults, refreshToken } from 'test-reporting-service';
import { parallelizeTests } from 'parallel-testing';
import { monitorResources } from 'resource-monitor';

const testExecutor = async (moduleName) => {
  try {
    // Dynamically load the module
    const module = await importModule(moduleName);

    // Run tests in a loop
    for (const test of Object.values(module)) {
      if (!test.name.includes('test')) continue;

      try {
        // Reset mocking library
        blueslip.reset();

        // Execute test and measure duration
        const start = Date.now();
        await test();
        const end = Date.now();
        const duration = end - start;

        // Log test result
        console.log(`Test ${test.name} took ${duration}ms`);

        // If test fails, handle the error
      } catch (error) {
        console.error(`Test ${test.name} failed:`, error);
      }
    }

    // Log summary report
    console.log(`Total tests executed: ${Object.values(module).length}`);
  } catch (error) {
    console.error('Error executing tests:', error);
  }
};

const main = async () => {
  try {
    // Execute tests in parallel
    await parallelizeTests(testExecutor, process.argv.slice(2));

    // Log summary report
    console.log('Test execution complete');
  } catch (error) {
    console.error('Error executing tests:', error);
  }
};

main();
