['Here is the C code for managing memory for three separate data structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure to hold a record with a pointer to an int, long timestamp and reference to an element in the int key array
typedef struct {
    int *ptr;
    long timestamp;
    int key_index;
} record;

// Function to manage memory for three separate data structures: offset array of long, key array of int and record array
void manage_memory(int num_offsets, int num_keys) {
    // Initialize arrays with specific sizes using dynamic memory allocation
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    int *keys = (int *)malloc(num_keys * sizeof(int));
    record *records = (record *)malloc(num_offsets * sizeof(record));

    // Seed random number generator for populating record structures with random values within a specified range
    srand(time(NULL));

    // Populate record structures with random values and initialize timestamp, key_index, and pointer to an int
    for (int i = 0; i < num_offsets; i++) {
        records[i].ptr = &keys[rand() % num_keys];
        records[i].timestamp = rand() % 10000;
        records[i].key_index = rand() % num_keys;
    }

    // Release memory dynamically allocated to prevent memory leaks
    free(offsets);
    free(keys);
    free(records);
}

// Function to retrieve the number of elements currently active in the record structures
int get_active_records(int *num_offsets) {
    return *num_offsets;
}

// Function to query statistics about the distribution of timestamps in the record structures
long get_timestamp_stats(long **timestamps, int *num_offsets) {
    long max_timestamp = 0;
    long min_timestamp = INT_MAX;

    for (int i = 0; i < *num_offsets; i++) {
        if ((*timestamps)[i] > max_timestamp)
            max_timestamp = (*timestamps)[i];
        else if ((*timestamps)[i] < min_timestamp)
            min_timestamp = (*timestamps)[i];
    }

    return min_timestamp;
}

// Function to reinitialize all data structures atomically and safely
