Record* allocateRecords(int count) {
    return (Record*)malloc(count * sizeof(Record));
}

void initializeRecords(Record* records, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].key = rand() % 1000000;
        records[i].value = (float)(rand() / (RAND_MAX + 1.0));
        if (records[i].key % 2 == 0) {
            records[i].status = 'A';
        } else {
            records[i].status = 'B';
        }
    }
}

void serializeRecords(Record* records, int count, FILE* file) {
    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }
}

void deserializeRecords(FILE* file, Record** records, int* count) {
    *count = 0;
    fseek(file, sizeof(int), SEEK_SET);
    while (fread(records[*count], sizeof(Record), 1, file)) {
        (*count)++;
    }
}

void updateRecords(Record* records, int start, int end) {
    for (int i = start; i <= end; i++) {
        if (records[i].status == 'A') {
            records[i].status = 'B';
        } else {
            records[i].status = 'A';
        }
    }
}

void* lock;
void acquireLock() {
    pthread_mutex_lock(&lock);
}

void releaseLock() {
