void executeGameActions(std::string label, std::function<void()> f, DataSource& dataSource) {
    GameAction* gameActions = new (std::nothrow) GameAction[20];

    if (!gameActions) {
        std::cerr << "Memory allocation failed." << std::endl;
        return;
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dist(0, 15);

    for (int i = 0; i < 20; i++) {
        gameActions[i].attackType = static_cast<AttackType>(std::rand() % 2);
        gameActions[i].cooldownTime = dist(gen);
        gameActions[i].key = i;
