    strcpy(newTask->dueDate, dueDate);
    newTask->priorityLevel = priorityLevel;
    newTask->resourceAllocations = (int *)malloc(resourceCount * sizeof(int));
    for (int i = 0; i < resourceCount; i++) {
        newTask->resourceAllocations[i] = i;
    }
    if (!taskSchedules) {
        taskSchedules = newTask;
    } else {
        TaskSchedule *prev = taskSchedules;
        while (prev->next != NULL) {
            prev = prev->next;
        }
        prev->next = newTask;
    }
}

void removeTask(int taskID) {
    TaskSchedule *current = taskSchedules;
    TaskSchedule *previous = NULL;
    while (current && current->taskID != taskID) {
        previous = current;
        current = current->next;
    }
    if (!current) return; // task not found
    if (previous) {
        previous->next = current->next;
    } else {
        taskSchedules = current->next;
    }
    free(current->dueDate);
    free(current->resourceAllocations);
    free(current);
}

void updateTask(int taskID, char *newDueDate, int newPriorityLevel, int resourceCount) {
    TaskSchedule *current = taskSchedules;
    while (current && current->taskID != taskID) {
        current = current->next;
    }
    if (!current) return; // task not found
    free(current->dueDate);
    current->dueDate = (char *)malloc(strlen(newDueDate) + 1);
    strcpy(current->dueDate, newDueDate);
    current->priorityLevel = newPriorityLevel;
    free(current->resourceAllocations);
    current->resourceAllocations = (int *)malloc(resourceCount * sizeof(int));
    for (int i = 0; i < resourceCount; i++) {
        current->resourceAllocations[i] = i;
    }
}

void printTaskStatus() {
    TaskSchedule *current = taskSchedules;
    int overdueTasks = 0, pendingTasks = 0;
    while (current) {
        if (strcmp(current->dueDate, "OVERDUE") == 0) {
            overdueTasks++;
        } else if (strcmp(current->dueDate, "PENDING") == 0) {
            pendingTasks++;
        }
        current = current->next;
    }
    printf("Overdue Tasks: %d\n", overdueTasks);
    printf("Pending Tasks: %d\n", pendingTasks);
}

int main() {
    addTask(1, "2022-01-01", 1, 3);
    addTask(2, "2022-01-15", 2, 4);
    updateTask(1, "2022-01-10", 1, 3);
    printTaskStatus();
    removeTask(2);
    return 0;
}
