        records[i]->next = NULL;

        // Check if any two records share the same key
        bool duplicate_key = false;
        for (size_t j = 0; j < i; j++) {
            if (records[j]->key == records[i]->key) {
                duplicate_key = true;
                break;
            }
        }

        if (duplicate_key) {
            // Handle error: duplicate key found
            printf("Error: Duplicate key detected!\n");
            exit(1);
        }
    }

    // Read and print the largest integer from standard input
    int max_int = read_and_print_largest_integer();

    // Deallocate memory to prevent leaks
