    // Allocate memory for the new session
    Session* new_session = (Session*)malloc(sizeof(Session));

    // Initialize fields with default values or 0
    new_session->session_id = -1;
    new_session->user_id = -1;
    new_session->login_time = time(NULL);
    new_session->last_activity_time = time(NULL);

    // Add the new session to the array and update num_sessions
    *sessions = (Session**)realloc(*sessions, (num_sessions + 1) * sizeof(Session*));
    (*sessions)[num_sessions] = new_session;
    return new_session;
}

// Function to remove a session
void remove_session(Session** sessions, int num_sessions, int session_id) {
    // Find the session with the matching ID
    for(int i = 0; i < num_sessions; i++) {
        if((*sessions)[i]->session_id == session_id) {
            // Remove the session from the array and free its memory
            free((*sessions)[i]->permissions);
            free((*sessions)[i]);
            memmove(*sessions, *sessions + 1, (num_sessions - 1) * sizeof(Session*));
            num_sessions--;
            break;
        }
    }
}

// Function to update a session's permissions
void update_permissions(Session** sessions, int num_sessions, int session_id, char **permissions) {
    // Find the session with the matching ID
    for(int i = 0; i < num_sessions; i++) {
        if((*sessions)[i]->session_id == session_id) {
            // Update the permissions and free any old list
            free((*sessions)[i]->permissions);
            (*sessions)[i]->permissions = (char**)malloc(sizeof(char*) * (strlen(permissions[0]) + 1));
            strcpy((*sessions)[i]->permissions, permissions[0]);
            break;
        }
    }
}

// Function to log a session event
void log_event(int session_id, int log_level) {
    // Format the log message
    time_t current_time = time(NULL);
    char* log_message = (char*)malloc(100 * sizeof(char));
    sprintf(log_message, "[%ld] Session %d: %s", current_time, session_id, (log_level == 1)? "started" : "ended");

    // Append the log message to a rolling log file
    FILE* log_file = fopen("session_log.log", "a+");
    fprintf(log_file, "%s\n", log_message);
    fclose(log_file);
    free(log_message);
}

