```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTERFACES 1000 // configurable limit
#define CACHE_LINE_SIZE 64

typedef struct {
    char *name;
    char *ipAddress;
    char *subnetMask;
    int portCount;
    struct {
        int latency;
        int throughput;
    } metrics;
} NetworkInterfaceConfig;

NetworkInterfaceConfig *interfaceConfigs = NULL;
int numInterfaces = 0;
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;
sem_t semaphore;

void addInterface(char *name, char *ipAddress, char *subnetMask) {
    // Lock for writing
    pthread_rwlock_wrlock(&lock);

    if (numInterfaces >= MAX_INTERFACES) {
        printf("Maximum number of interfaces reached.\n");
        exit(1);
    }

    NetworkInterfaceConfig *newInterface = malloc(sizeof(NetworkInterfaceConfig));
    newInterface->name = strdup(name);
    newInterface->ipAddress = strdup(ipAddress);
    newInterface->subnetMask = strdup(subnetMask);
    newInterface->portCount = 0;

    if (interfaceConfigs == NULL) {
        interfaceConfigs = newInterface;
    } else {
        NetworkInterfaceConfig *currentInterface = interfaceConfigs;
        while (currentInterface->name != NULL) {
            currentInterface = currentInterface->next;
        }
        currentInterface->next = newInterface;
    }

    numInterfaces++;

    // Unlock for writing
    pthread_rwlock_unlock(&lock);
}

void removeInterface(char *name) {
    // Lock for reading and writing
    pthread_rwlock_wrlock(&lock);

    NetworkInterfaceConfig *currentInterface = interfaceConfigs;
    while (currentInterface != NULL) {
        if (strcmp(currentInterface->name, name) == 0) {
            NetworkInterfaceConfig *temp = currentInterface;
            currentInterface = currentInterface->next;
            free(temp->name);
            free(temp->ipAddress);
            free(temp->subnetMask);
            free(temp);
            break;
        }
        currentInterface = currentInterface->next;
    }

    // Unlock for reading and writing
    pthread_rwlock_unlock(&lock);
}

int main() {
    // Initialize semaphore
    sem_init(&semaphore, 0, MAX_INTERFACES);

    return 0;
