#include <string.h>
#include <stdbool.h>

// Structure to represent a data point
typedef struct {
    double measurement;
    int timestamp;
    char* description;
} dataPoint;

// Function to read integers from file, filter out duplicates and find smallest integer
int* readFilterAndFindSmallest(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return NULL;

    int max_size = 100; // arbitrary initial size
    int* integers = (int*)malloc(max_size * sizeof(int));
    int top = 0;

    while (fscanf(file, "%d", &integers[top]) == 1) {
        if (top >= max_size) {
            max_size *= 2;
            integers = (int*)realloc(integers, max_size * sizeof(int));
        }
        top++;
    }

    fclose(file);

    // filter out duplicates
    int* filtered = (int*)malloc(top * sizeof(int));
    int filtered_top = 0;
    for (int i = 0; i < top; i++) {
        bool duplicate = false;
        for (int j = 0; j < filtered_top; j++) {
            if (integers[i] == filtered[j]) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            filtered[filtered_top++] = integers[i];
        }
    }

    // find smallest integer
    int smallest = filtered[0];
    for (int i = 1; i < filtered_top; i++) {
        if (filtered[i] < smallest) {
            smallest = filtered[i];
        }
    }

    free(integers);
    return filtered;
}

// Function to process and filter data
void processAndFilterData(const char* filename, int size, dataPoint** output) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return;

    *output = (dataPoint*)malloc(size * sizeof(dataPoint));

    int i = 0;
    while (fscanf(file, "%lf %d \"%[^\"]\"", &(*output)[i].measurement, &(*output)[i].timestamp, (*output)[i].description) == 3) {
        if (i >= size - 1) break; // ensure no two entries have the same timestamp
        i++;
    }

    fclose(file);

    for (int j = 0; j < i; j++) {
        printf("Measurement: %f, Timestamp: %d, Description: %s\n", (*output)[j].measurement, (*output)[j].timestamp, (*output)[j].description);
    }
}

int main() {
    int size = 10;
    dataPoint* output;

    processAndFilterData("data.csv", size, &output);

    free(output);

    return 0;
}
