#define MAX_LOG_ENTRIES 10000
#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3

typedef struct LOG_EVENT_RECORD {
    uint32_t log_sequence_number;
    time_t log_timestamp;
    const char* log_module_name;
    int log_severity;
} LOG_EVENT_RECORD;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
LOG_EVENT_RECORD** log_events = NULL;
size_t log_event_count = 0;

void add_log_event(const LOG_EVENT_RECORD* event) {
    pthread_mutex_lock(&mutex);

    LOG_EVENT_RECORD* new_event = (LOG_EVENT_RECORD*)malloc(sizeof(LOG_EVENT_RECORD));
    *new_event = *event;

    if (log_events == NULL || log_event_count >= MAX_LOG_ENTRIES) {
        // Reallocate the array and reset the count
        log_events = (LOG_EVENT_RECORD**)realloc(log_events, sizeof(LOG_EVENT_RECORD*) * (log_event_count + 1));
        log_events[log_event_count] = new_event;
    } else {
        // Replace duplicate sequence number with next available one
        uint32_t next_sequence_number = event->log_sequence_number + 1;
        while (find_log_event_by_sequence_number(next_sequence_number) != NULL) {
            next_sequence_number++;
        }
        new_event->log_sequence_number = next_sequence_number;
    }

    log_event_count++;

    pthread_mutex_unlock(&mutex);
}

LOG_EVENT_RECORD* find_log_event_by_sequence_number(uint32_t sequence_number) {
    for (size_t i = 0; i < log_event_count; i++) {
        if (log_events[i]->log_sequence_number == sequence_number) {
            return log_events[i];
        }
    }
    return NULL;
}

void print_log_events() {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < log_event_count; i++) {
        LOG_EVENT_RECORD* event = log_events[i];
        printf("Sequence Number: %u, Timestamp: %lu, Module Name: %s, Severity: %d\n",
               event->log_sequence_number, event->log_timestamp, event->log_module_name, event->log_severity);
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize log events
    srand(time(NULL));

    for (size_t i = 0; i < MAX_LOG_ENTRIES; i++) {
        LOG_EVENT_RECORD* event = (LOG_EVENT_RECORD*)malloc(sizeof(LOG_EVENT_RECORD));
        event->log_sequence_number = i;
        event->log_timestamp = time(NULL);
        const char* module_name = "module_name";
        int severity = rand() % 4;
        *event = (LOG_EVENT_RECORD){i, time(NULL), module_name, severity};

        add_log_event(event);
    }

    print_log_events();

    return 0;
}
