typedef struct {
    double measurement;
    float timestamp;
    char* id;
} Sensor;

// Linked list node to manage sensor data
typedef struct Node {
    Sensor sensor;
    struct Node* next;
} Node;

// Thread-safe linked list to store sensor data
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new sensor structure with unique identifier
Sensor* create_sensor(double measurement, float timestamp) {
    Sensor* sensor = (Sensor*)malloc(sizeof(Sensor));
    char id[10];
    int id_count = 0;
    do {
        sprintf(id, "Sens%04d", id_count++);
    } while (id_count < 10000); // Reserve IDs up to 9999
    sensor->measurement = measurement;
    sensor->timestamp = timestamp;
    sensor->id = strdup(id);
    return sensor;
}

// Function to insert a new sensor into the linked list
void insert_sensor(Sensor* sensor) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->sensor = *sensor;
    node->next = head;
    pthread_mutex_lock(&lock);
    head = node;
    pthread_mutex_unlock(&lock);
}

// Function to remove a sensor from the linked list
void remove_sensor(Sensor* sensor) {
    Node* current = head;
    Node* previous = NULL;
    while (current && current->sensor.id != sensor->id) {
        previous = current;
        current = current->next;
    }
    if (current) {
        pthread_mutex_lock(&lock);
        if (previous)
            previous->next = current->next;
        else
            head = current->next;
        free(current);
        pthread_mutex_unlock(&lock);
    }
}

// Function to iterate over sensor data in the linked list
void iterate_sensors() {
    Node* current = head;
    while (current) {
        printf("Measurement: %f, Timestamp: %f, ID: %s\n", current->sensor.measurement, current->sensor.timestamp, current->sensor.id);
        current = current->next;
    }
}

