    if (*records) free(*records);
}

int serialize_records(const record_t* records, int num_records, char* file_path) {
    FILE* f = fopen(file_path, "wb");
    if (!f) return -1; // unable to open file

    fwrite(records, RECORD_SIZE, num_records, f);

    fclose(f);
    return 0;
