    const int TIMESTAMP_ARRAY_SIZE = 1000;
    const int TEMPERATURE_READINGS_SIZE = 1000;
    const int EVENTS_ARRAY_SIZE = 1000;

    long* timestamps = (long*)malloc(TIMESTAMP_ARRAY_SIZE * sizeof(long));
    double* temperatures = (double*)malloc(TEMPERATURE_READINGS_SIZE * sizeof(double));
    event_t** events = (event_t**)malloc(EVENTS_ARRAY_SIZE * sizeof(event_t*));

    // Read CSV file and initialize structures
    FILE* file = fopen(filename, "r");
    if (!file) {
        LOG_ERROR("Failed to open file: %s", filename);
        return NULL;
    }

    csv_reader reader(file);

    int i = 0, j = 0, k = 0;
    while (reader.read_record()) {
        timestamps[i] = reader.get_timestamp();
        temperatures[j] = reader.get_temperature();
        event_t* current_event = &events[k][0];
        current_event->timestamp = timestamps[i];
        current_event->temperature = temperatures[j];
        if (current_event->temperature > threshold) {
            // Filter events based on temperature threshold
            events[k] = &current_event;
            k++;
        }
    }

    fclose(file);
    return events;
}

