// Function to serialize the data structure to a binary file
void serialize_data_structure(Record** records, size_t record_count, const char* filename) {
    // Open file for writing in binary mode
    FILE* file = fopen(filename, "wb");

    // Write record count and offsets to file
    fwrite(&record_count, sizeof(size_t), 1, file);
    fwrite(offsets, sizeof(size_t), record_count, file);

    // Write records to file
    for (size_t i = 0; i < record_count; i++) {
        Record* record = records[i];
        fwrite(&record->integer_field, sizeof(int), 1, file);
        fwrite(record->string_ptr, strlen(record->string_ptr) + 1, 1, file); // Write string length and data
    }

    fclose(file);
}

// Function to deserialize the data structure from a binary file
Record** deserialize_data_structure(const char* filename) {
    // Open file for reading in binary mode
    FILE* file = fopen(filename, "rb");

    // Read record count and offsets from file
    size_t record_count;
    fread(&record_count, sizeof(size_t), 1, file);
    size_t* offsets = (size_t*)my_malloc(record_count * sizeof(size_t));
    fread(offsets, sizeof(size_t), record_count, file);

    // Read records from file
    Record** records = (Record**)my_malloc(record_count * sizeof(Record*));
    for (size_t i = 0; i < record_count; i++) {
        Record* record = (Record*)my_malloc(sizeof(Record));
        fread(&record->integer_field, sizeof(int), 1, file);
        // Read string length and data from file
        int string_length;
        fread(&string_length, sizeof(int), 1, file);
        char* string_ptr = (char*)my_malloc(string_length + 1);
        fread(string_ptr, string_length + 1, 1, file); // Read string data
        record->string_ptr = string_ptr;

        records[i] = record;
    }

    fclose(file);

    return records;
}

int main() {
    // Example usage:
