Transaction* transaction_generate_random(size_t capacity, double min_value, double max_value) {
    Transaction* transaction = transaction_new(capacity);

    // Generate random float values within the specified range
    srand(time(NULL)); // Seed random number generator with current time
    for (size_t i = 0; i < capacity; ++i) {
        transaction->values[i] = (float)(min_value + (max_value - min_value) * rand() / (RAND_MAX + 1.0));
    }

    return transaction;
}

int main() {
    // Example usage
    Transaction* transaction = transaction_generate_random(10, -5.0, 5.0);
    printf("Transaction values: ");
    for (size_t i = 0; i < 10; ++i) {
        printf("%f ", transaction->values[i]);
    }
    printf("\n");

    // Free allocated memory
    transaction_free(transaction);

    return 0;
}
