import java.util.*;
import java.text.SimpleDateFormat;

public class SessionManager {
    private Map<String, Session> sessions = new HashMap<>();
    private int sessionTimeout;
    private int maxSessions;
    private int maxRequestsPerSession;
    private boolean useCaching;

    public SessionManager(int sessionTimeout, int maxSessions, int maxRequestsPerSession, boolean useCaching) {
        this.sessionTimeout = sessionTimeout;
        this.maxSessions = maxSessions;
        this.maxRequestsPerSession = maxRequestsPerSession;
        this.useCaching = useCaching;
    }

    public void addSession(String userId, String token, long expirationTimestamp, long lastActivityTimestamp) {
        if (sessions.size() >= maxSessions) {
            throw new RuntimeException("Maximum number of sessions reached");
        }

        Session session = new Session(userId, token, expirationTimestamp, lastActivityTimestamp);
        sessions.put(token, session);
    }

    public void updateSession(String token, String userId, long lastActivityTimestamp) {
        if (!sessions.containsKey(token)) {
            throw new RuntimeException("Invalid session token");
        }

        Session session = sessions.get(token);
        session.setLastActivityTimestamp(lastActivityTimestamp);
    }

    public void removeSession(String token) {
        if (!sessions.containsKey(token)) {
            return; // No-op
        }

        sessions.remove(token);
    }

    public List<Session> getSessions() {
        return new ArrayList<>(sessions.values());
    }

    private class Session {
        private String userId;
        private String token;
        private long expirationTimestamp;
        private long lastActivityTimestamp;
        private List<String> requests = new ArrayList<>();

        public Session(String userId, String token, long expirationTimestamp, long lastActivityTimestamp) {
            this.userId = userId;
            this.token = token;
            this.expirationTimestamp = expirationTimestamp;
            this.lastActivityTimestamp = lastActivityTimestamp;
        }

        public void addRequest(String request) {
            requests.add(request);

            if (requests.size() > maxRequestsPerSession) {
                throw new RuntimeException("Maximum number of requests per session reached");
            }
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expirationTimestamp;
        }
    }
}
