import java.util.concurrent.atomic.AtomicInteger;
import java.net.InetAddress;
import java.util.ArrayList;
import java.util.List;

public class HostResolutionBundle {
    private String hostname;
    private byte[] ipAddress;

    public HostResolutionBundle(String hostname, byte[] ipAddress) {
        this.hostname = hostname;
        this.ipAddress = ipAddress;
    }

    public String getHostname() {
        return hostname;
    }

    public byte[] getIpAddress() {
        return ipAddress;
    }
}

public class ResolveHostname {
    private static final int MAX_BUNDLE_SIZE = 1024;
    private static AtomicInteger bundleCount = new AtomicInteger(0);

    public int resolveHostname(String[] hostnames) {
        int errorCode = 0;

        List<HostResolutionBundle> bundles = new ArrayList<>();

        for (String hostname : hostnames) {
            try {
                InetAddress address = InetAddress.getByName(hostname);
                byte[] ipAddress = address.getAddress();
                HostResolutionBundle bundle = new HostResolutionBundle(hostname, ipAddress);

                // Ensure the bundle size does not exceed the maximum
                if (bundleCount.getAndIncrement() >= MAX_BUNDLE_SIZE) {
                    throw new RuntimeException("Maximum number of bundles exceeded");
                }

                bundles.add(bundle);
            } catch (Exception e) {
                errorcode = 1;
                System.out.println("Error: " + e.getMessage());
            }
        }

        return errorCode;
    }
}
