    }

    // Set random values for each record's int field
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*records)[i]->value = rand() % 100;
    }
}

// Function to validate integrity of records after initialization
void validate_records(Record** records, int size) {
    // Check for duplicate keys
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if ((*records)[i]->key == (*records)[j]->key) {
                printf("Error: Duplicate key found.\n");
                // Handle error as needed
            }
        }
    }
}

// Function to dynamically resize the record arrays
void resize_records(Record*** records, int* size, int new_size) {
    Record** new_records = (Record**)malloc(new_size * sizeof(Record*));

    for (int i = 0; i < new_size && i < *size; i++) {
        new_records[i] = (*records)[i];
    }

    // Free old records
    free(*records);
    *records = new_records;
    *size = new_size;
}

// Function to support batch updates where multiple records can be modified simultaneously
void update_records(Record** records, int size) {
    // Example: Update all record values by 10
    for (int i = 0; i < size; i++) {
        (*records)[i]->value += 10;
    }
