#include <time.h>

typedef struct {
    int value;
} record;

void initializeArrays(long numEntries, long maxOffsetValue, int numKeys, int* keys, record** records) {
    // Allocate memory for the offset array
    long* offsets = (long*) malloc(numEntries * sizeof(long));
    if (!offsets) {
        printf("Error allocating memory for offsets.\n");
        return;
    }

    // Initialize offset values
    srand(time(NULL));
    for (int i = 0; i < numEntries; i++) {
        offsets[i] = rand() % maxOffsetValue;
    }

    // Allocate memory for the key array
    int* keySet = (int*) malloc((numKeys + 1) * sizeof(int));
    if (!keySet) {
        printf("Error allocating memory for keys.\n");
        free(offsets);
        return;
    }

    bool keysExist[numKeys];
    for (int i = 0; i < numKeys; i++) {
        int key = rand() % (numKeys * 2) + 1;
        if (keySet[key] == 0) {
            keySet[key]++;
            keys[i] = key;
            keysExist[i] = true;
        } else {
            i--;
        }
    }

    // Allocate memory for the record array
    record* recordsArray = (record*) malloc(numEntries * sizeof(record));
    if (!recordsArray) {
        printf("Error allocating memory for records.\n");
        free(keySet);
        free(offsets);
        return;
    }

    // Initialize record values
    for (int i = 0; i < numEntries; i++) {
        recordsArray[i].value = rand() % 100 + 50;
    }

    *records = recordsArray;
}

void cleanup(record** records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}
