typedef struct {
    int key;
    long offset;
} Record;

Record** initArrays(int *size, int cacheSize) {
    size_t required = sizeof(Record) + 1; // size of Record plus null terminator
    size_t alignment = (required + 7) & ~7; // align to a multiple of 8 bytes

    // allocate memory for arrays
    Record** records = (Record**)malloc(sizeof(Record*) * cacheSize);
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < cacheSize; i++) {
        Record* recordArray = (Record*)calloc(i + 1, alignment); // allocate memory for array
        if (!recordArray) {
            free(records);
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }

        records[i] = recordArray;

        // initialize array with random values
        for (int j = 0; j <= i; j++) {
            Record* record = &recordArray[j];
            record->key = rand() % 100 + 1;
            record->offset = (long)rand() * (i + 1);
        }
    }

    return records;
}

void validateArrays(Record** records, int cacheSize) {
    for (int i = 0; i < cacheSize; i++) {
        Record* recordArray = records[i];
        for (int j = 0; j <= i; j++) {
            if (!recordArray[j].key || !recordArray[j].offset) {
                fprintf(stderr, "Array element not initialized.\n");
                exit(1);
            }
        }
    }
}

void logInitialization(int cacheSize) {
    printf("Initialized arrays with %d elements.\n", cacheSize);
}
