    new_config->num_ports = num_ports;

    // Add the new interface to the list
    *config = (interface_config *)realloc(*config, (*config ? sizeof(interface_config) : 0) + sizeof(interface_config));
    if (!*config) return NULL;
    (**config).name = name;
    (**config).ip = ip;
    (**config).subnet_mask = subnet_mask;
    (**config).num_ports = num_ports;
    (**config).ports = new_config->ports;

    return *config;
}

void remove_interface(interface_config **config, const char *name) {
    // Find the interface to be removed
    interface_config *curr = *config;
    while (curr && strcmp(curr->name, name)) curr = curr->next;
    if (!curr) return;

    // Remove the port configurations for this interface
    free(curr->ports);
    curr->num_ports = 0;
    curr->ports = NULL;

    // Remove the interface from the list
    *config = (interface_config *)realloc(*config, sizeof(interface_config));
}

void update_interface(interface_config **config, const char *name, const char *new_name) {
    // Find the interface to be updated
    interface_config *curr = *config;
    while (curr && strcmp(curr->name, name)) curr = curr->next;
    if (!curr) return;

    // Update the name and other fields as needed
    free(curr->name);
    curr->name = strdup(new_name);

    return;
}

void print_interfaces(interface_config *config) {
    interface_config *curr = config;
    while (curr) {
        printf("Interface Name: %s\n", curr->name);
        printf("IP Address: %s\n", curr->ip);
        printf("Subnet Mask: %s\n", curr->subnet_mask);
        for (int i = 0; i < curr->num_ports; i++) {
            printf("Port Configuration: %s\n", curr->ports[i]);
        }
        curr = curr->next;
    }
}

void free_interfaces(interface_config **config) {
    interface_config *curr = *config;
    while (curr) {
        // Free the port configurations
        for (int i = 0; i < curr->num_ports; i++) free(curr->ports[i]);
        free(curr->ports);

        // Free the current interface
        free(curr->name);
        free(curr->ip);
        free(curr->subnet_mask);
        free(curr);

        *config = NULL;
    }
}

int main() {
    // Initialize an empty list of interfaces
    interface_config *config = NULL;

    // Add some sample interfaces
    config = add_interface(&config, "eth0", "192.168.1.1", "255.255.255.0", 2);
    config = add_interface(&config, "wlan0", "10.10.10.1", "255.255.255.0", 3);

    // Print the current list of interfaces
    print_interfaces(config);

    // Update an interface
    update_interface(&config, "eth0", "eth1");

    // Remove an interface
    remove_interface(&config, "wlan0");

    // Print the updated list of interfaces
    print_interfaces(config);

    // Free all memory allocated for the interfaces
    free_interfaces(&config);

    return 0;
}
