// Define a structure for a file system directory
typedef struct {
    char* name;
    void* parent;
    void* child;
    char** files;
    int file_count;
} Directory;

// Initialize the file system with specified number of directories and files
Directory* init_file_system(int num_dirs, int num_files) {
    // Allocate memory for each directory
    Directory* dirs = (Directory*)malloc(num_dirs * sizeof(Directory));

    // Check if allocation failed
    if (!dirs) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize directories with parent and child pointers set to NULL
    for (int i = 0; i < num_dirs; i++) {
        dirs[i].name = (char*)malloc(32 * sizeof(char)); // Assuming max name length of 31 characters
        dirs[i].parent = NULL;
        dirs[i].child = NULL;
        dirs[i].files = (char**)malloc(num_files * sizeof(char*));
        for (int j = 0; j < num_files; j++) {
            dirs[i].files[j] = (char*)malloc(32 * sizeof(char)); // Assuming max file name length of 31 characters
        }
        dirs[i].file_count = num_files;
    }

    // Validate the integrity of the directory hierarchy
    validate_hierarchy(dirs, num_dirs);

    return dirs;
}

// Function to set unique identifiers for each file and directory
void set_identifiers(Directory* root) {
    int id = 1;
    traverse_tree(root, &id);
}

// Recursively traverse the tree to set unique identifiers
void traverse_tree(void* node, int* id) {
    if (!node)
        return;

    // Set identifier for directory
    ((Directory*)node)->name[strlen(((Directory*)node)->name)] = 'A' + *id - 1;

    (*id)++;

    // Recursively traverse child directories and files
    Directory* dir = (Directory*)node;
    if (dir->child)
        traverse_tree(dir->child, id);
    for (int i = 0; i < dir->file_count; i++)
        traverse_tree(dir->files[i], id);
}

// Validate the integrity of the directory hierarchy
void validate_hierarchy(Directory* root, int num_dirs) {
    // Check if all directories have unique names and file lists are valid
    for (int i = 0; i < num_dirs; i++) {
        Directory* dir = &root[i];
        if (!dir->name || !strlen(dir->name))
            printf("Invalid directory name.\n");
        if (!dir->files || dir->file_count <= 0)
            printf("Invalid file list.\n");
    }

    // Check if all files have unique names
    for (int i = 0; i < num_dirs; i++) {
        Directory* dir = &root[i];
        for (int j = 0; j < dir->file_count; j++) {
            char* file = dir->files[j];
            if (!file || !strlen(file))
                printf("Invalid file name.\n");
        }
    }
}

// Example usage
int main() {
    Directory* root = init_file_system(5, 10);

    // Set unique identifiers for each file and directory
    set_identifiers(root);

    // Validate the integrity of the directory hierarchy
    validate_hierarchy(root, 5);

    return 0;
}
