} event_t;

event_t* event_array_create(int size) {
    event_t* array = (event_t*)malloc(size * sizeof(event_t));
    if (!array) return NULL;

    pthread_mutex_init(&mutex, NULL);

    return array;
}

void event_array_destroy(event_t* array) {
    free(array);
    pthread_mutex_destroy(&mutex);
}

void log_event(event_t* event) {
    // Implement logging mechanism here
    // For example:
    FILE *log_file = fopen("events.log", "a");
    fwrite(&event->value, sizeof(double), 1, log_file);
    fwrite(&event->ts, sizeof(struct timestamp), 1, log_file);
    fwrite(event->message, 1, strlen(event->message), log_file);
    fclose(log_file);
}

void* event_array_manage(void* arg) {
    int* size = (int*)arg;
    event_t* array = event_array_create(*size);

    // Initialize the events
    for (int i = 0; i < *size; i++) {
        array[i].value = (double)i;
        array[i].ts = (struct timestamp){.sec = i, .nsec = 0};
        strcpy(array[i].message, "Event ");
        sprintf(array[i].message + strlen("Event "), "%d", i);
    }

    // Log the events
    for (int i = 0; i < *size; i++) {
        pthread_mutex_lock(&mutex);
        log_event(&array[i]);
        pthread_mutex_unlock(&mutex);
    }

    event_array_destroy(array);

    return NULL;
}

pthread_t event_array_thread_create(int size) {
    pthread_t thread;
    pthread_create(&thread, NULL, event_array_manage, (void*)&size);
    return thread;
}
