#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int key;
    int field1;
    int field2;
} Record;

typedef struct {
    int* keys;
    Record** records;
    int size;
    int capacity;
} DynamicArray;

void initDynamicArray(DynamicArray* array, int capacity) {
    array->size = 0;
    array->capacity = capacity;
    array->keys = (int*)malloc(capacity * sizeof(int));
    array->records = (Record**)malloc(capacity * sizeof(Record*));
}

void resizeDynamicArray(DynamicArray* array, int newCapacity) {
    if (newCapacity > array->capacity) {
        int* tempKeys = (int*)realloc(array->keys, newCapacity * sizeof(int));
        Record** tempRecords = (Record**)realloc(array->records, newCapacity * sizeof(Record*));
        array->keys = tempKeys;
        array->records = tempRecords;
        array->capacity = newCapacity;
    }
}

void addRecord(DynamicArray* array, int key, Record record) {
    if (array->size >= array->capacity) {
        resizeDynamicArray(array, array->capacity * 2);
    }
    array->keys[array->size] = key;
    array->records[array->size] = &record;
    array->size++;
}

void removeRecord(DynamicArray* array, int key) {
    for (int i = 0; i < array->size; i++) {
        if (array->keys[i] == key) {
            free(array->records[i]);
            memmove(array->keys + i, array->keys + i + 1, (array->size - i - 1) * sizeof(int));
            memmove(array->records + i, array->records + i + 1, (array->size - i - 1) * sizeof(Record*));
            array->size--;
            return;
        }
    }
}

void updateRecord(DynamicArray* array, int key, Record record) {
    for (int i = 0; i < array->size; i++) {
        if (array->keys[i] == key) {
            free(array->records[i]);
            *array->records[i] = record;
            return;
        }
    }
}

void validateRecords(DynamicArray* array) {
    for (int i = 0; i < array->size; i++) {
        if (array->keys[i] != array->records[i]->key) {
            printf("Record validation failed!\n");
            return;
        }
    }
    printf("Records validated successfully!\n");
}

void logEvent(const char* message) {
    printf("[LOG]: %s\n", message);
}
