    record* records = allocate_records(*n);

    // Initialize the offset and key arrays
    long* offsets = (long*) malloc((*n) * sizeof(long));
    int* keys = (int*) malloc((*n) * sizeof(int));

    for (int i = 0; i < *n; i++) {
        offsets[i] = 0;
        keys[i] = -1;
    }

    // Initialize the records with the offset and key
    for (int i = 0; i < *n; i++) {
        record* r = &records[i];
        r->key = keys[i];
        r->offset = offsets[i];
    }

    free(offsets);
    free(keys);

