// Function to add a new task schedule
TaskSchedule* add_task_schedule(TaskSchedule** schedules, int* size) {
    // Allocate memory for the new task schedule
    *schedules = (TaskSchedule*) realloc(*schedules, (*size + 1) * sizeof(TaskSchedule));
    TaskSchedule* new_schedule = &((*schedules)[*size]);

    // Initialize the new task schedule fields
    printf("Enter ID: ");
    scanf("%d", &new_schedule->id);
    printf("Enter due date (YYYY-MM-DD): ");
    fgets(new_schedule->due_date, 20, stdin);
    printf("Enter priority level (1-5): ");
    scanf("%d", &new_schedule->priority);

    // Initialize resource allocations and metadata
    new_schedule->resource_allocations = (int*)malloc(10 * sizeof(int));
    new_schedule->metadata = 0;

    (*size)++;
    return new_schedule;
}

// Function to remove a task schedule
void remove_task_schedule(TaskSchedule** schedules, int* size) {
    if (*size > 0) {
        // Free the memory of the last task schedule
        free(schedules[(*size) - 1]->resource_allocations);
        memmove(schedules, schedules + 1, (*size) * sizeof(TaskSchedule));
        (*size)--;
    }
}

// Function to update a task schedule
void update_task_schedule(TaskSchedule* schedule, int new_priority) {
