        printf("Task ID: %d\n", schedules[i].id);
        printf("Due Date: %s\n", schedules[i].due_date);
        printf("Priority Level: %d\n", schedules[i].priority);

        // Print resource allocations and metadata
        for (int j = 0; j < 10; j++) {
            printf("Resource Allocation %d: %d\n", j, schedules[i].resource_allocations[j]);
        }
        printf("Metadata: %d\n", schedules[i].metadata);
    }
}

// Function to manage task dependencies
void manage_task_dependencies(TaskSchedule* schedule) {
    // Check for dependencies and update the metadata accordingly
    if (schedule->metadata > 0) {
        printf("Task has dependencies. Please resolve them before proceeding.\n");
    } else {
        printf("Task has no dependencies.\n");
    }
}

