    }
}

void largestInteger(int** array, int size) {
    int max_val = (*array)[0][0];
    for (int i = 1; i < size; i++) {
        if ((*array)[0][i] > max_val)
            max_val = (*array)[0][i];
    }
    printf("Largest integer: %d\n", max_val);
}

void dataManagementSystem(int num_records, int min_value, int max_value, int memory_budget) {
    metadata* metadata_arr = NULL;
    record* record_arr = NULL;

    // Allocate initial memory
    if (memory_budget < sizeof(metadata) + sizeof(record)) {
        printf("Memory budget too low.\n");
        return;
    }

    metadata_arr = (metadata*)malloc(memory_budget / sizeof(metadata));
    record_arr = (record*)malloc(memory_budget / sizeof(record));

    for (int i = 0; i < num_records; i++) {
        record_arr[i].key = rand() % (max_value - min_value) + min_value;
        // Assign a unique key
        while (1) {
            int j;
            for (j = 0; j < i; j++)
                if (record_arr[j].key == record_arr[i].key)
                    break;
            if (j == i)
                break;
            record_arr[i].key = rand() % (max_value - min_value) + min_value;
        }
    }

    // Re-allocate memory as needed
    while ((size_t)(sizeof(metadata) * num_records + sizeof(record) * num_records) > memory_budget) {
        // Re-allocate metadata array
        metadata_arr = (metadata*)realloc(metadata_arr, 2 * (num_records / 2) * sizeof(metadata));
        record_arr = (record*)realloc(record_arr, 2 * (num_records / 2) * sizeof(record));

        num_records /= 2;
    }

    // Initialize metadata structures
    for (int i = 0; i < num_records; i++) {
        metadata_arr[i].ptr = &record_arr[i];
        metadata_arr[i].flag = 1;
    }

    largestInteger(&record_arr, num_records);

    // Release allocated resources
    free(metadata_arr);
    free(record_arr);
}

int main() {
    int num_records, min_value, max_value, memory_budget;

    printf("Enter number of records: ");
    scanf("%d", &num_records);

    printf("Enter range of random values (min and max): ");
    scanf("%d %d", &min_value, &max_value);

    printf("Enter total memory budget in bytes: ");
    scanf("%d", &memory_budget);

    srand(time(NULL));  // Seed the random number generator
    dataManagementSystem(num_records, min_value, max_value, memory_budget);
    return 0;
}
