    if (!file) {
        printf("Failed to open file: %s\n", filePath);
        return -1;  // Return error code indicating file not found
    }

    // Read and validate bundle contents
    int numItems;
    fread(&numItems, sizeof(int), 1, file);  // Read number of items from the file

    // Allocate memory for arrays
    long* offsetValues = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record* records = (record*)malloc(size * sizeof(record));

    if (!offsetValues || !keys || !records) {
        printf("Memory allocation failed\n");
        return -2;  // Return error code indicating memory allocation failure
    }

    for (int i = 0; i < numItems; i++) {
        fread(&offsetValues[i], sizeof(long), 1, file);
        fread(&keys[i], sizeof(int), 1, file);

        record temp;
        temp.key = keys[i];
        temp.intField = (rand() % 100) + 1;  // Set random int value for each record
        records[i] = temp;

        if (!fread(&temp, sizeof(record), 1, file)) {
            printf("Error reading bundle contents\n");
            return -3;  // Return error code indicating corrupted or invalid bundle data
        }
    }

    fclose(file);

    free(offsetValues);
    free(keys);
    free(records);

    return numItems;
}

struct record {
    int key;
    int intField;
};
