dataset* createDataset(int numIndices) {
    dataset* ds = malloc(sizeof(dataset));
    if (!ds) return NULL;  // Allocation failed

    ds->numDataPoints = numIndices;
    ds->minValue = 1.0f;
    ds->maxValue = -1.0f;

    ds->indices = malloc(numIndices * sizeof(int));
    ds->dataPoints = malloc(numIndices * sizeof(dataPoint));

    if (!ds->indices || !ds->dataPoints) {
        free(ds);
        return NULL;  // Allocation failed
    }

    srand(time(NULL));  // Initialize random seed

    for (int i = 0; i < numIndices; ++i) {
        ds->indices[i] = i;
        dataPoint* dp = &ds->dataPoints[i];
        float value = (float)(rand() / (RAND_MAX + 1.0));
        sprintf(dp->label, "Data Point %d at %f", i, value);
        dp->value = value;

        if (i == 0) {
            ds->minValue = ds->maxValue = value;
        } else {
            if (value < ds->minValue) ds->minValue = value;
            if (value > ds->maxValue) ds->maxValue = value;
        }
    }

    free(ds->indices);
    return ds;
}
