void dynamicMemoryManagedRecordSystem(int numRecords, int minRange, int maxRange, int memoryBudget, const char* cipherType) {
    // Initialize arrays for offset values and keys
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    // Initialize the record and metadata structures
    record* records = (record*)malloc(numRecords * sizeof(record));
    metadata* meta = (metadata*)malloc(numRecords * sizeof(metadata));

    // Initialize the memory pool allocator
    void* pool = malloc(memoryBudget);
    size_t poolSize = 0;

    // Populate each record's int field with a random value within the specified range
    for(int i = 0; i < numRecords; i++) {
        records[i].value = rand() % (maxRange - minRange + 1) + minRange;
        keys[i] = i;
    }

    // Ensure no two records share the same key
    for(int i = 0; i < numRecords; i++) {
        for(int j = i+1; j < numRecords; j++) {
            if(keys[j] == keys[i]) {
                // Reallocate memory to accommodate new record
                size_t newSize = poolSize + sizeof(record);
                void* temp = realloc(pool, newSize);
                if(temp != NULL) {
                    pool = temp;
                    poolSize = newSize;
                } else {
                    printf("Error: Memory allocation failed.\n");
                    return;
                }
            }
        }
    }

    // Initialize the EVP_CIPHER structure
    EVP_CIPHER* cipher = (EVP_CIPHER*)malloc(sizeof(EVP_CIPHER));
    if(cipher == NULL) {
        printf("Error: Memory allocation for cipher failed.\n");
        return;
    }

    // Cleanup function to free all allocated memory
    void cleanup() {
        free(offsets);
        free(keys);
        free(records);
        free(meta);
        free(pool);
        EVP_CIPHER_free(cipher);
    }
}
