        deallocate(&nodes, sizeof(Node*) * MAX_NODES);
        return -1;
    }

    buffer = allocate(BUFFER_SIZE);
    if (buffer == NULL) {
        deallocate((void**)&nodes, sizeof(Node*) * MAX_NODES);
        deallocate((void**)&records, sizeof(Record) * MAX_RECORDS);
        return -1;
    }
    return 0;
}

