#include <time.h>

// Structure for metadata associated with each file
typedef struct {
    int size;
    int modification_timestamp;
} Metadata;

// Structure for directory entries
typedef struct DirectoryEntry {
    char* path;
    struct DirectoryEntry* next;
} DirectoryEntry;

// Structure for nodes in the hierarchical data structure
typedef struct Node {
    char* path;
    Metadata metadata;
    DirectoryEntry* directory_entries;
    int depth;
} Node;

// Function to manage dynamic memory allocation and populate the hierarchical data structure
void initialize_hierarchical_data_structure(int max_depth) {
    // Initialize the root node
    Node* root = (Node*)malloc(sizeof(Node));
    root->path = "root";
    root->metadata.size = 0;
    root->metadata.modification_timestamp = time(NULL);
    root->directory_entries = NULL;
    root->depth = 0;

    // Function to recursively populate the hierarchical data structure
    void recursive_populate(int current_depth, Node* current_node) {
        if (current_depth > max_depth) return;

        // Generate random number of directory entries for this node
        int num_entries = rand() % 10 + 1;

        // Create new directory entries and populate the linked list
        DirectoryEntry** entry_pointers = (DirectoryEntry**)malloc(num_entries * sizeof(DirectoryEntry*));
        for (int i = 0; i < num_entries; i++) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            new_node->path = "file";
            new_node->metadata.size = rand() % 100 + 1;
            new_node->metadata.modification_timestamp = time(NULL);
            new_node->directory_entries = NULL;
            new_node->depth = current_depth + 1;

            // Add the new node to the linked list and increment the depth
            DirectoryEntry* new_entry = (DirectoryEntry*)malloc(sizeof(DirectoryEntry));
            new_entry->path = "new_file";
            new_entry->next = current_node->directory_entries;
            current_node->directory_entries = new_entry;

            recursive_populate(current_depth + 1, new_node);
        }
    }

    // Start the recursive population from the root node
    Node* current_node = &root;
    recursive_populate(0, &root);

    // Print the hierarchical data structure
    void print_hierarchical_data_structure(Node* current_node, int indent) {
        printf("%s%s\n", (char*)indent * ' ', current_node->path);
        if (current_node->directory_entries) {
            DirectoryEntry* entry = current_node->directory_entries;
            while (entry) {
                Node* sub_node = (Node*)entry->next;
                print_hierarchical_data_structure(sub_node, indent + 1);
                entry = entry->next;
            }
        }
    }

    // Print the hierarchical data structure
    print_hierarchical_data_structure(&root, "    ");
}
