#define MAX_RECORDS 50000
#define RECORD_SIZE sizeof(record)
#define LOG_BUFFER_SIZE 1024

typedef struct {
    int id;
    char name[32];
    char ip_address[64];
    uint16_t port;
    uint8_t security_profile;
} record;

record *records;
int num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_spinlock_t spin_lock;

void *my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void *my_realloc(void *ptr, size_t size) {
    void *new_ptr = realloc(ptr, size);
    if (!new_ptr) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(1);
    }
    return new_ptr;
}

int add_record(int key, int value) {
    record *new_rec = (record *) my_malloc(RECORD_SIZE);
    if (!new_rec) {
        return -1; // out of memory
    }
    new_rec->id = key;
    new_rec->name[0] = '\0';
    new_rec->ip_address[0] = '\0';
    new_rec->port = 0;
    new_rec->security_profile = 0;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        if (!strcmp(records[i].name, new_rec->name)) {
            free(new_rec);
            pthread_mutex_unlock(&lock);
            return -1; // duplicate name
        }
    }
    if (num_records >= MAX_RECORDS) {
        free(new_rec);
        pthread_mutex_unlock(&lock);
        return -1; // too many records
    }
    records[num_records++] = *new_rec;
    pthread_mutex_unlock(&lock);
    return 0; // success
}

int remove_record(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        if (records[i].id == key) {
            record *rec = &records[i];
            memset(rec, 0, RECORD_SIZE);
            free((void *) rec);
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * RECORD_SIZE);
            num_records--;
            pthread_mutex_unlock(&lock);
            return 0; // success
        }
    }
    pthread_mutex_unlock(&lock);
    return -1; // not found
}

int update_record(int key, int value) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        if (records[i].id == key) {
            // update record
            pthread_mutex_unlock(&lock);
            return 0; // success
        }
    }
    pthread_mutex_unlock(&lock);
    return -1; // not found
}

int main() {
    records = my_malloc(MAX_RECORDS * RECORD_SIZE);
    if (!records) {
        return -1;
    }
    num_records = 0;
    return 0;
}
