NFAPI_CRC_INDICATION_PDU_T* generate_PDUs(int numPDUs, int minRNTI, int maxRNTI, int (*log_func)(const char*, ...), int *err_code) {
    if (numPDUs < 0) {
        *err_code = 1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        *err_code = 2;
        return NULL;
    }

    int RNTI_range = maxRNTI - minRNTI + 1;

    for (int i = 0; i < numPDUs; i++) {
        pdus[i].RNTI = (rand() % RNTI_range) + minRNTI;
        pdus[i].valid_RX_UE_INFORMATION_TAG = rand() % 2;
        pdus[i].CRCFLAG = rand() % 2;

        if (*log_func != NULL)
            (*log_func)("PDU %d created with RNTI %x, valid tag %d, and CRC flag %d.\n", i + 1, pdus[i].RNTI, pdus[i].valid_RX_UE_INFORMATION_TAG, pdus[i].CRCFLAG);
    }

    return pdus;
}

void free_PDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int numPDUs) {
    if (pdus) {
        free(pdus);
        pdus = NULL;
    }
}

int main() {
    srand(time(NULL));

    int minRNTI = 0x0001;
    int maxRNTI = 0xFFFF;

