#define MAX_PDU_COUNT 1000000
#define RNTI_RANGE_START 0x0001
#define RNTI_RANGE_END 0xFFFF
#define CRCFLAG_MAX 0xFFFFFFFF

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rnti;
    int32_t crcflag;
} PDU;

void generateAndManagePDUsAndInitializeRecords(int pduCount, FILE *fp) {
    srand(time(NULL));

    PDU *pdus = (PDU *)malloc(pduCount * sizeof(PDU));
    if (!pdus) {
        printf("Error: Unable to allocate memory for PDUs.\n");
        return;
    }

    int i;
    for (i = 0; i < pduCount; i++) {
        pdus[i].rnti = rand() % ((RNTI_RANGE_END - RNTI_RANGE_START) + 1) + RNTI_RANGE_START;
        pdus[i].crcflag = rand() % CRCFLAG_MAX;
    }

    // Serialize PDUs into binary format
    int bytesWritten = fwrite(pdus, sizeof(PDU), pduCount, fp);
    if (bytesWritten != pduCount) {
        printf("Error: Unable to write PDUs to file.\n");
    }

    free(pdus);

    return;
}
