#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Node structure
typedef struct {
    int key;
    char* data;
    size_t length;
} node;

// Linked list structure
typedef struct {
    node* head;
    node* tail;
    size_t size;
} linked_list;

// Function to insert a new node at the end of the linked list
void insert_node(linked_list* list, int key, char* data, size_t length) {
    node* new_node = (node*) malloc(sizeof(node));
    new_node->key = key;
    new_node->data = (char*) malloc(length + 1);
    memcpy(new_node->data, data, length);
    new_node->data[length] = '\0';
    new_node->length = length;

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;
}

// Function to delete a node with the given key from the linked list
void delete_node(linked_list* list, int key) {
    if (!list->head) return;

    node* current = list->head;
    node* previous = NULL;

    while (current && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (!current) return; // Node not found

    if (previous) {
        previous->next = current->next;
        if (!current->next) list->tail = previous;
    } else {
        list->head = current->next;
        if (!list->head) list->tail = NULL;
    }

    free(current->data);
    free(current);

    list->size--;
}

// Function to search for a node with the given key in the linked list
node* search_node(linked_list* list, int key) {
    node* current = list->head;

    while (current) {
        if (current->key == key) return current;
        current = current->next;
    }

    return NULL; // Node not found
}

// Function to monitor and report on memory consumption periodically
void check_memory(linked_list* list, int threshold) {
    size_t total_memory = 0;

    node* current = list->head;
    while (current) {
        total_memory += sizeof(node);
        free(current->data);
        free(current);
        current = current->next;
    }

    if (total_memory > threshold) printf("Memory usage exceeded %d bytes.\n", threshold);

    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
}

int main() {
    linked_list list;

    // Initialize the linked list
    list.head = NULL;
    list.tail = NULL;
    list.size = 0;

    // Example usage: insert, delete, and search for nodes
    insert_node(&list, 1, "Hello", 5);
    insert_node(&list, 2, "World", 6);
    insert_node(&list, 3, "Foo", 4);

    node* searched_node = search_node(&list, 2);
    if (searched_node) printf("Node found: key=%d, data=%s\n", searched_node->key, searched_node->data);

    delete_node(&list, 1);

    // Monitor and report on memory consumption
    check_memory(&list, 1024);

    return 0;
}

