// Define the record structure
typedef struct {
    int key;
    int value;
    char* string;
} Record;

// Define the custom memory pool structure
typedef struct {
    void** blocks;
    size_t block_size;
    size_t used_blocks;
    size_t total_blocks;
} MemoryPool;

// Function to create a new record and initialize it with given values
Record* create_record(int key, int value, const char* string) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    record->string = malloc(strlen(string) + 1);
    strcpy(record->string, string);
    return record;
}

// Function to create a custom memory pool
MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->used_blocks = 0;
    pool->total_blocks = total_blocks;
    pool->blocks = malloc(total_blocks * sizeof(void*));
    for(int i=0; i<total_blocks; i++) {
        pool->blocks[i] = NULL;
    }
    return pool;
}

// Function to allocate memory from the custom memory pool
void* pool_alloc(MemoryPool* pool) {
    void* result = NULL;
    if(pool->used_blocks < pool->total_blocks) {
        for(int i=0; i<pool->total_blocks; i++) {
            if(!pool->blocks[i]) {
                pool->blocks[i] = malloc(pool->block_size);
                result = pool->blocks[i];
                break;
            }
        }
    } else {
        // Pool is full, need to expand it
        size_t new_total_blocks = pool->total_blocks * 2;
        MemoryPool* new_pool = create_memory_pool(pool->block_size, new_total_blocks);
        for(int i=0; i<new_pool->total_blocks; i++) {
            if(i < pool->total_blocks) {
                new_pool->blocks[i] = pool->blocks[i];
            } else {
                new_pool->blocks[i] = NULL;
            }
        }
        free(pool->blocks);
        pool = new_pool;
    }
    return result;
}

// Function to deallocate memory from the custom memory pool
void pool_free(MemoryPool* pool, void* block) {
    for(int i=0; i<pool->total_blocks; i++) {
        if(pool->blocks[i] == block) {
            free(block);
            pool->blocks[i] = NULL;
            return;
        }
    }
}

// Function to dynamically allocate and initialize an array of record structures
Record** allocate_records(int num_records, MemoryPool* pool) {
    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    for(int i=0; i<num_records; i++) {
        records[i] = create_record(i+1, i+2, "Initial string value");
        // Initialize the memory block for this record
        void* block = pool_alloc(pool);
        if(block) {
            ((Record*)block)->key = i + 1;
            ((Record*)block)->value = i + 2;
            strcpy(((Record*)block)->string, "Initial string value");
        }
    }
    return records;
}

// Function to handle external data source and fetch initial string values
int fetch_strings(Record** records) {
    // Implement your code here to handle the external data source and fetch initial string values
    // You can use APIs, file I/O, network calls, etc. depending on your specific requirements
    return 0;
}

// Function to validate input parameters
void validate_inputs(int num_records, MemoryPool* pool) {
    if(num_records < 1 || num_records > pool->total_blocks) {
        // Error: invalid number of records
        // Handle the error as needed
    }
}

int main() {
    int num_records = 10;
    MemoryPool* pool = create_memory_pool(1024, 100);
    Record** records = allocate_records(num_records, pool);
    fetch_strings(records); // Fetch initial string values from external data source
    validate_inputs(num_records, pool); // Validate input parameters
