#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the node structure
typedef struct {
    int key;
    char* data;
    size_t length;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int version;
} LinkedList;

// Initialize the linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->version = 0;
    return list;
}

// Insert a new node into the linked list
void insert_node(LinkedList* list, int key, char* data, size_t length) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->data = data;
    node->length = length;

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = NULL;
        list->tail->next = node;
        list->tail = node;
    }

    list->version++;
}

// Delete a node from the linked list
void delete_node(LinkedList* list, int key) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->key == key) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }

            if (list->tail == current) {
                list->tail = previous;
            }

            free(current);
            break;
        }

        previous = current;
        current = current->next;
    }

    list->version++;
}

// Search for a node in the linked list
Node* search_node(LinkedList* list, int key) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->key == key) {
            return current;
        }

        current = current->next;
    }

    return NULL;
}

// Free the linked list and its nodes
void free_list(LinkedList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(list);
}
