} NIC_STATE;

// Function prototypes
NIC_STATE* nic_init(int num_nics);
void nic_start(NIC_STATE* nic);
void nic_stop(NIC_STATE* nic);
int nic_check_state(NIC_STATE* nic);
int nic_set_config(NIC_STATE* nic, char* mac_address, char* ip_address, int port_number);

// Global variables
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NIC_STATE* nics = NULL;

int main() {
    // Initialize NIC system with 5 network interfaces
    nics = nic_init(5);

    // Start all NICs in a loop to simulate real-world traffic patterns
    for(int i = 0; i < 10; i++) {
        for(int j = 0; j < 5; j++) {
            nic_start(&nics[j]);
            sleep(rand() % 3 + 1); // random interval between 1-3 seconds
            nic_stop(&nics[j]);
            sleep(rand() % 2 + 1); // random interval between 1-2 seconds
        }
    }

    return 0;
}

// Initialize and configure a flexible network interface control (NIC) system
NIC_STATE* nic_init(int num_nics) {
    NIC_STATE* nics = (NIC_STATE*)malloc(num_nics * sizeof(NIC_STATE));
    for(int i = 0; i < num_nics; i++) {
        nics[i].config.mac_address[17] = '\0'; // initialize MAC address
        nics[i].config.ip_address[15] = '\0'; // initialize IP address
        nics[i].port_number = 0;
        nics[i].state = 0; // inactive state
        nics[i].retry_attempts = 3; // default retry attempts
    }
    return nics;
}

// Start a network interface control (NIC)
void nic_start(NIC_STATE* nic) {
    pthread_mutex_lock(&lock);
    if(nic->state == 0) {
        // perform initialization and configuration tasks here
        printf("NIC started: MAC %s, IP %s, Port %d\n", nic->config.mac_address, nic->config.ip_address, nic->port_number);
        nic->state = 1; // active state
    } else if(nic->state == 1) {
        printf("NIC already active: %s\n", nic->config.mac_address);
    }
    pthread_mutex_unlock(&lock);
}

// Stop a network interface control (NIC)
void nic_stop(NIC_STATE* nic) {
    pthread_mutex_lock(&lock);
    if(nic->state == 1) {
        // perform deinitialization and configuration tasks here
        printf("NIC stopped: %s\n", nic->config.mac_address);
        nic->state = 0; // inactive state
    } else if(nic->state == 0) {
        printf("NIC already inactive: %s\n", nic->config.mac_address);
    }
    pthread_mutex_unlock(&lock);
}

// Check the current state of a network interface control (NIC)
int nic_check_state(NIC_STATE* nic) {
    return nic->state;
}

// Set the configuration for a network interface control (NIC)
int nic_set_config(NIC_STATE* nic, char* mac_address, char* ip_address, int port_number) {
    // validate and set the new configurations
    if(strlen(mac_address) > 17 || strlen(ip_address) > 15) {
        printf("Invalid configuration: MAC %s, IP %s, Port %d\n", mac_address, ip_address, port_number);
        return -1; // error
    }
    strcpy(nic->config.mac_address, mac_address);
    strcpy(nic->config.ip_address, ip_address);
    nic->port_number = port_number;
    return 0; // success
}
