typedef struct {
    int value;
    long *offset;
    int key;
} Record;

void* allocateRecords(int numRecords, int range) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        log_error("Memory allocation failed for records.");
        return NULL;
    }

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (!offsets) {
        free(records);
        log_error("Memory allocation failed for offsets.");
        return NULL;
    }

    int* keys = (int*)malloc(numRecords * sizeof(int));
    if (!keys) {
        free(records);
        free(offsets);
        log_error("Memory allocation failed for keys.");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % range;
        offsets[i] = (long)i;
        keys[i] = i;
    }

    // Initialize the records, offsets, and keys
    for (int i = 0; i < numRecords; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    return records;
}

void deallocateRecords(void* records) {
    Record* record = (Record*)records;
    free(record->offset);
    free(record->key);
    free(records);
}

int main() {
    int numRecords = 1000;
    int range = 100;

    void* allocatedRecords = allocateRecords(numRecords, range);

    // Use the records
    for (int i = 0; i < numRecords; i++) {
        printf("Record %d: Value - %d, Offset - %ld, Key - %d\n", i+1, record[i].value, record[i].offset, record[i].key);
    }

    deallocateRecords(allocatedRecords);

    return 0;
}
