```c
void* network_configurations = NULL;
int configuration_count = 0;

void add_network_configuration(const char* interface_name, const char* ip_address,
                                 const char* subnet_mask, int port_config_count) {
    // allocate memory for new configuration
    void* new_config = malloc(sizeof(network_configuration));
    if (!new_config) {
        // handle out-of-memory error
        return;
    }

    // set fields for the new configuration
    network_configuration* config = (network_configuration*) new_config;
    config->interface_name = interface_name;
    config->ip_address = ip_address;
    config->subnet_mask = subnet_mask;
    config->port_configs = malloc(port_config_count * sizeof(port_configuration));

    // update configuration count and array
    configuration_count++;
    network_configurations = realloc(network_configurations, (configuration_count + 1) * sizeof(void*));
    network_configurations[configuration_count - 1] = new_config;
}

void remove_network_configuration(int index) {
    if (index >= configuration_count || !network_configurations[index]) {
        // handle out-of-bounds error
        return;
    }

    // free memory for removed configuration
    free(network_configurations[index]);
    network_configurations[index] = NULL;
}

int update_network_configuration(int index, const char* new_ip_address) {
    if (index >= configuration_count || !network_configurations[index]) {
        // handle out-of-bounds error
        return -1;
    }

    // update IP address field for the given configuration
    network_configuration* config = (network_configuration*) network_configurations[index];
    config->ip_address = new_ip_address;
    return 0;
}
