    if (dir == NULL) {
        // Handle error
    }
    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) continue;

        char file_path[256];
        sprintf(file_path, "%s/%s", dir_path, ent->d_name);

        int file_size = get_file_size(file_path);
        time_t mod_time = get_file_mod_time(file_path);

