            unique_id[max_id_length] = '\0';

        // Generate new extension
        char* ext = strrchr(ent->d_name, '.');
        if (ext != NULL) {
            size_t len = strlen(ext);
            if (len > 8) {
                // Handle edge case: too long extension
            }
            sprintf(buffer, ".%s_%llu", unique_id, mod_time);
            char* new_ext = malloc(strlen(ent->d_name) - len + strlen(buffer) + 1);
            strcpy(new_ext, ent->d_name);
            strcat(new_ext, buffer);
        } else {
            // Handle edge case: no extension
        }

        // Rename file
        if (rename(file_path, new_ext) != 0) {
            // Handle error
        }
        free(unique_id);
        free(new_ext);

        // Manage dependencies and retries for metadata services
        int retries = 5;
        for (int i = 0; i < retries; i++) {
            if (get_file_size(file_path) == file_size &&
                get_file_mod_time(file_path) == mod_time) break;
            sleep(pow(2, i));
        }
    }

    closedir(dir);
    free(records);
    free(offsets);
    free(keys);
