        if (tasks[i]->id == id) {
            free(tasks[i]);
            memmove(&tasks[i], &tasks[i + 1], (num_tasks - i - 1) * sizeof(Task *));
            num_tasks--;
            return;
        }
    }
}

void reorder_task(int old_id, int new_id) {
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i]->id == old_id) {
            tasks[i]->id = new_id;
            return;
        }
    }
}

