#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define MAX_CAPACITY 1000
#define THRESHOLD 10.0
#define RANDOM_SEED 1234

typedef struct {
    double value;
    int flag;
    // Pointers to other resources managed by external systems
} custom_data;

// Function prototypes
custom_data* init_pool(int capacity);
void add_element(custom_data** pool, int index);
int remove_element(custom_data** pool, int index);
double get_value(custom_data* element);
void set_flag(custom_data* element);

// Global variables
custom_data* pool = NULL;
int current_capacity = 0;

// Function to initialize the data pool
custom_data* init_pool(int capacity) {
    if (capacity > MAX_CAPACITY) {
        printf("Error: Maximum capacity exceeded.\n");
        return NULL;
    }

    custom_data* new_pool = (custom_data*)malloc(sizeof(custom_data) * capacity);
    if (!new_pool) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    current_capacity = capacity;

    // Initialize each element in the pool
    for (int i = 0; i < capacity; i++) {
        new_pool[i].value = pow(i, 2) * 0.5 + RANDOM_SEED;
        set_flag(&new_pool[i]);
    }

    return new_pool;
}

// Function to add an element to the pool
void add_element(custom_data** pool, int index) {
    if (index >= current_capacity || index < 0) {
        printf("Error: Index out of bounds.\n");
        return;
    }

    (*pool)[index].value = pow(index, 2) * 0.5 + RANDOM_SEED;
    set_flag(&(*pool)[index]);
}

// Function to remove an element from the pool
int remove_element(custom_data** pool, int index) {
    if (index >= current_capacity || index < 0) {
        printf("Error: Index out of bounds.\n");
        return -1; // Return an error code
    }

    free(&((*pool)[index]));
    for (int i = index; i < current_capacity - 1; i++) {
        (*pool)[i] = (*pool)[i + 1];
    }
    current_capacity--;

    return 0;
}

// Function to get the value of an element
double get_value(custom_data* element) {
    return element->value;
}

// Function to set the flag of an element
void set_flag(custom_data* element) {
    if (element->value > THRESHOLD) {
        element->flag = 1;
    } else {
        element->flag = 0;
    }
}
