    int flag;
    custom_data* ptr;
} element;

typedef struct component {
    char id[10];
    custom_data* data;
    time_t timestamp;
} component;

void* manage_memory_allocation(void* components) {
    size_t num_components = 100; // initial number of components
    component* comp_pool = (component*)malloc(num_components * sizeof(component));

    if (!comp_pool) {
        printf("Error: Memory allocation failed for component pool.\n");
        return NULL;
    }

    element* elements = (element*)malloc(1000 * sizeof(element));
    if (!elements) {
        free(comp_pool);
        printf("Error: Memory allocation failed for elements array.\n");
        return NULL;
    }

    custom_data* data_pool = (custom_data*)malloc(500 * sizeof(custom_data));
    if (!data_pool) {
        free(elements);
        free(comp_pool);
        printf("Error: Memory allocation failed for custom data pool.\n");
        return NULL;
    }

    // Initialize components and elements
    for (size_t i = 0; i < num_components; ++i) {
        strcpy(comp_pool[i].id, "Component-");
        comp_pool[i].data = &data_pool[2 * i];
        comp_pool[i].timestamp = time(NULL);
    }

    for (size_t i = 0; i < 1000; ++i) {
        elements[i].value = pow(i, 2.0) + 3.14;
        elements[i].flag = (elements[i].value > 10.0) ? 1 : 0;
        elements[i].ptr = &data_pool[2 * i];
    }

    // Free memory periodically to prevent excessive garbage collection
    for (size_t i = 0; i < num_components; ++i) {
        if ((time(NULL) - comp_pool[i].timestamp) > 300) { // adjust the time interval as needed
            free(comp_pool[i].data);
            strcpy(comp_pool[i].id, "Unused-");
        }
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Implement thread-safe access to data structures using mutex locks
    void* func(void* arg) {
        component* comp = (component*)arg;
        pthread_mutex_lock(&lock);

        // Perform read/write operations on components and elements
        for (size_t i = 0; i < num_components; ++i) {
            printf("Component-%d: %s, Data: %p, Timestamp: %ld\n", i, comp_pool[i].id, comp_pool[i].data, comp_pool[i].timestamp);

            // Update elements
            for (size_t j = 0; j < 1000; ++j) {
                if ((time(NULL) - comp_pool[i].timestamp) > 300) {
                    free(elements[j].ptr);
                    strcpy(elements[j].id, "Unused-");
                }
            }
        }

        pthread_mutex_unlock(&lock);
    }

    // Start threads for concurrent access
    pthread_t threads[num_components];

    for (size_t i = 0; i < num_components; ++i) {
        pthread_create(&threads[i], NULL, func, &comp_pool[i]);
    }

    // Wait for threads to finish
    for (size_t i = 0; i < num_components; ++i) {
        pthread_join(threads[i], NULL);
    }

    return comp_pool;
}
