        long** offsets;
        int** keys_array;
        Record** records;
        Record** table;
        pthread_mutex_t mutex;
    }));
}

// Insert a record into the hash table
int insert_record(void* dataset_void, int key, long offset, int value) {
    struct {
        long** offsets;
        int** keys_array;
        Record** records;
        Record** table;
        pthread_mutex_t mutex;
    } *dataset = (struct *)dataset_void;

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&dataset->mutex);

    // Calculate the hash value using custom_hash function
    size_t index = custom_hash(key) % dataset->table_size;

    // Insert the record into the table at the calculated index
    for (Record* r = dataset->records; r < &dataset->records[dataset->table[index]]; r++) {
        if (r->value == value && r->offset == offset) {
            // Record already exists, return 1 to indicate update
            pthread_mutex_unlock(&dataset->mutex);
            return 1;
        }
    }

    // Insert the new record into the table and update offsets and keys arrays
    dataset->records[dataset->table[index]] = (Record*)malloc(sizeof(Record));
    dataset->records[dataset->table[index]]->value = value;
    dataset->records[dataset->table[index]]->offset = offset;

    // Update the keys array to reflect the new record
    dataset->keys_array[key] = &record->value;

    pthread_mutex_unlock(&dataset->mutex);
    return 0; // Record inserted successfully
}

// Retrieve a record from the hash table
int get_record(void* dataset_void, int key, long offset) {
    struct {
        long** offsets;
        int** keys_array;
        Record** records;
        Record** table;
        pthread_mutex_t mutex;
    } *dataset = (struct *)dataset_void;

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&dataset->mutex);

    // Calculate the hash value using custom_hash function
    size_t index = custom_hash(key) % dataset->table_size;

    // Find the record in the table at the calculated index
    for (Record* r = &dataset->records[0]; r < &dataset->records[dataset->table[index]]; r++) {
        if (r->value == value && r->offset == offset) {
            pthread_mutex_unlock(&dataset->mutex);
            return 1; // Record found, return success
        }
    }

    pthread_mutex_unlock(&dataset->mutex);
    return 0; // Record not found
}

// Free allocated memory for the dataset and hash table
void free_dataset(void* dataset_void) {
    struct {
        long** offsets;
        int** keys_array;
        Record** records;
        Record** table;
        pthread_mutex_t mutex;
    } *dataset = (struct *)dataset_void;

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&dataset->mutex);

    // Free memory for offset values and keys array
    free(dataset->offsets);
    free(dataset->keys_array);

    // Free record structures
    for (size_t i = 0; i < dataset->num_records; i++) {
        free(dataset->records[i]);
    }
    free(dataset->records);

    // Free memory for hash table
    for (size_t i = 0; i < dataset->table_size; i++) {
        free(dataset->table[i]);
    }
    free(dataset->table);

    pthread_mutex_unlock(&dataset->mutex);
    free(dataset_void); // Free the main dataset struct
}

