#include <Python.h>
#include <numpy/arrayobject.h>

// ...

static PyObject* calculate_area(PyObject* self, PyObject* args) {
    PyObject* point_list;
    int size;

    if (!PyArg_ParseTuple(args, "iO", &size, &point_list)) {
        return NULL;
    }

    // Convert Python list to C struct Point array
    struct Point* points = (struct Point*)malloc(size * sizeof(struct Point));
    for (int i = 0; i < size; i++) {
        PyObject* point_obj = PyList_GetItem(point_list, i);
        if (!point_obj) continue;

        // Extract coordinates and color from Python point object
        float x = PyObject_GetAttrString(point_obj, "x");
        float y = PyObject_GetAttrString(point_obj, "y");
        char* color = PyObject_GetAttrString(point_obj, "color");

        points[i].x = x;
        points[i].y = y;
        strcpy(points[i].color, color);

        Py_DECREF(point_obj);
    }

    // Calculate area using trapezoidal rule
    double area = 0.0;
    for (int i = 0; i < size - 1; i++) {
        float h = points[i + 1].x - points[i].x;
        area += (points[i].y + points[i + 1].y) * h / 2.0;
    }

    // Generate report
    double avg_x = 0.0, avg_y = 0.0;
    for (int i = 0; i < size; i++) {
        avg_x += points[i].x;
        avg_y += points[i].y;
    }
    avg_x /= size;
    avg_y /= size;

    // Return calculated area and report
    PyObject* result = Py_BuildValue("((d)d)", area, avg_x, avg_y);
    return result;
}

