int add_config(struct config* new_config) {
    if (!new_config)
        return -1;
    if (configs == NULL || configs->size < configs->length + 1) {
        // Reallocate memory for the array
        struct config* old_configs = configs;
        configs = realloc(configs, sizeof(struct config*) * (configs->size + 1));
        if (!configs)
            return -1;
        configs->data[configs->length] = new_config;
    } else {
        // No need to reallocate memory
        configs->data[configs->length] = new_config;
    }
    configs->length++;
    return 0;
}

int update_config(int index, struct config* new_config) {
    if (index < 0 || index >= configs->length)
        return -1;
    if (!new_config)
        return -1;
    // Update the existing configuration
    configs->data[index] = new_config;
    return 0;
}

int remove_config(int index) {
    if (index < 0 || index >= configs->length)
        return -1;
    // Remove the configuration and shift elements to fill the gap
    for (int i = index; i < configs->length - 1; i++) {
        configs->data[i] = configs->data[i + 1];
    }
    configs->length--;
    // Free the removed configuration
    free(configs->data[configs->length]);
    return 0;
}

void export_config_to_xml() {
    xmlDoc* doc = xmlNewDoc(NULL);
    xmlNode* root = xmlNewNode(BAD_CAST "network_interfaces", NULL);
    xmlDocSetRootElement(doc, root);
    for (int i = 0; i < configs->length; i++) {
        xmlNode* interface_node = xmlNewNode(BAD_CAST "interface", NULL);
        xmlSetProp(interface_node, BAD_CAST "name", configs->data[i]->name);
        xmlSetProp(interface_node, BAD_CAST "ip_address", configs->data[i]->ip_address);
        xmlSetProp(interface_node, BAD_CAST "subnet_mask", configs->data[i]->subnet_mask);
        root->children = xmlAddChild(root, interface_node);
    }
    FILE* file = fopen("config.xml", "w");
    xmlDocDumpToFilename(doc, file);
    fclose(file);
}

void validate_config() {
    for (int i = 0; i < configs->length; i++) {
        // Validate each configuration against predefined rules and policies
        if (!validate_interface_name(configs->data[i]->name) ||
            !validate_ip_address(configs->data[i]->ip_address) ||
            !validate_subnet_mask(configs->data[i]->subnet_mask)) {
            // Raise an alert for any discrepancies detected
            printf("Invalid configuration at index %d\n", i);
        }
    }
}

