#define MAX_CAPACITY 1000
#define LOG_WARN(fmt, ...) fprintf(stderr, "Warning: %s\n", fmt)

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} LinkedListNode;

// Function to create a new linked list node
LinkedListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the end of the linked list
void insert_node(LinkedListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* node = create_node(data);
    if (*head == NULL || (*head)->data.rnti != node->data.rnti) {
        node->next = *head;
        *head = node;
    } else {
        LinkedListNode* current = *head;
        while (current->next && current->next->data.rnti != node->data.rnti) {
            current = current->next;
        }
        if (current->next) {
            node->next = current->next;
            current->next = node;
        } else {
            *head = node;
        }
    }
}

// Function to remove duplicates from the linked list
void remove_duplicates(LinkedListNode** head) {
    LinkedListNode* current = *head;
    while (current && current->next) {
        if (current->data.rnti == current->next->data.rnti) {
            LinkedListNode* temp = current->next;
            current->next = current->next->next;
            free(temp);
            LOG_WARN("Removed duplicate entry with RNTI: %d", current->data.rnti);
        } else {
            current = current->next;
        }
    }
}

// Function to handle overflow scenarios
void handle_overflow(LinkedListNode** head) {
    if (list_length(*head) >= MAX_CAPACITY) {
        LOG_WARN("List reached maximum capacity. Removing oldest entry.");
        *head = remove_oldest_entry(head);
    }
}

// Function to remove the oldest entry from the linked list
LinkedListNode* remove_oldest_entry(LinkedListNode** head) {
    LinkedListNode* current = *head;
    if (current) {
        *head = current->next;
        free(current);
    }
    return *head;
}

// Function to get the length of the linked list
int list_length(LinkedListNode* head) {
    int length = 0;
    while (head) {
        length++;
        head = head->next;
    }
    return length;
}
