int create_records(int offset_count, int key_count, int weight_count) {
    // dynamically allocate memory for arrays
    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));
    float* weights = (float*)malloc(weight_count * sizeof(float));
    status_t* statuses = (status_t*)malloc(weight_count * sizeof(status_t));

    // initialize arrays with random values
    for (int i = 0; i < offset_count; ++i) {
        offsets[i] = rand() % 100000;
    }
    for (int i = 0; i < key_count; ++i) {
        keys[i] = rand() % 100;
    }
    for (int i = 0; i < weight_count; ++i) {
        weights[i] = (float)rand() / RAND_MAX;
    }
    for (int i = 0; i < weight_count; ++i) {
        statuses[i] = PENDING;
    }

    // dynamically allocate memory for record array
    size_t record_size = sizeof(record_t);
    record_t* records = (record_t*)malloc(key_count * sizeof(record_t));

    // initialize record array with random values and pending status
    for (int i = 0; i < key_count; ++i) {
        records[i].value = rand() % 100;
        records[i].weight = (float)rand() / RAND_MAX;
        records[i].status = PENDING;
    }

    // persist initialized data using external ingestion service
    for (int i = 0; i < key_count; ++i) {
        if (!ingest_data(&records[i], record_size)) {
            // handle error: partially allocated resources must be released
            free(offsets);
            free(keys);
            free(weights);
            free(statuses);
            free(records);
            return -1;
        }
    }

    // implement retry logic for temporary data ingestion failures
    int retries = 0;
    while (retries < 3) {
        if (!ingest_data(&records[i], record_size)) {
            retries++;
        } else {
            break;
        }
    }
    if (retries >= 3) {
        // handle error: excessive retries
        free(offsets);
        free(keys);
        free(weights);
        free(statuses);
        free(records);
        return -1;
    }

    // optimize memory usage and performance
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // ensure thread safety without significant overhead
    for (int i = 0; i < key_count; ++i) {
        pthread_mutex_lock(&lock);
        if (!ingest_data(&records[i], record_size)) {
            // handle error: partially allocated resources must be released
            free(offsets);
            free(keys);
            free(weights);
            free(statuses);
            free(records);
            return -1;
        }
        pthread_mutex_unlock(&lock);
    }

    // implement logging for critical operations
    FILE* log_file = fopen("logs.txt", "a");
    if (log_file == NULL) {
        // handle error: unable to open log file
        free(offsets);
        free(keys);
        free(weights);
        free(statuses);
        free(records);
        return -1;
    }
    for (int i = 0; i < key_count; ++i) {
        fprintf(log_file, "Record %d ingested successfully\n", i);
    }
    fclose(log_file);

    // handle edge cases: zero-sized arrays
    if (offset_count == 0 || key_count == 0 || weight_count == 0) {
        free(offsets);
        free(keys);
        free(weights);
        free(statuses);
        free(records);
