public class DataManagement {
    private static final int INITIAL_CAPACITY = 100;
    private Map<String, List<Map.Entry<String, Integer>>> dataStructure;

    public DataManagement() {
        this.dataStructure = new ConcurrentHashMap<>();
    }

    public void manageDynamicDataSets(int size) {
        if (size > 0) {
            for (int i = 0; i < size; i++) {
                Map<String, List<Map.Entry<String, Integer>>> innerMap = new ConcurrentSkipListMap<>();
                // Initialize the inner map with a default capacity
                innerMap.put("key" + i, Arrays.asList(new AbstractMap.SimpleEntry<>("value1", 1), new AbstractMap.SimpleEntry<>("value2", 2)));
                // Add the inner map to the data structure
                this.dataStructure.put("outerKey" + i, innerMap);
            }
        }
    }

    public void printData() {
        for (Map.Entry<String, List<Map.Entry<String, Integer>>> entry : this.dataStructure.entrySet()) {
            System.out.println(entry.getKey());
            for (Map.Entry<String, Integer> innerEntry : entry.getValue()) {
                System.out.println(innerEntry.getKey() + ": " + innerEntry.getValue());
            }
        }
    }

    public static void main(String[] args) throws Exception {
        DataManagement dataManager = new DataManagement();
        // Manage dynamic data sets with size 5
        dataManager.manageDynamicDataSets(5);
        // Print the managed data
        dataManager.printData();

        // Simulate concurrent access from multiple threads
        Thread thread1 = new Thread(() -> {
            try {
                // Access the data structure concurrently
                for (Map.Entry<String, List<Map.Entry<String, Integer>>> entry : dataManager.dataStructure.entrySet()) {
                    System.out.println("Thread 1: " + entry.getKey());
                }
            } catch (Exception e) {
                Logger.getLogger(DataManagement.class.getName()).log(Level.SEVERE, null, e);
            }
        });
        thread1.start();

        Thread thread2 = new Thread(() -> {
            try {
                // Access the data structure concurrently
                for (Map.Entry<String, List<Map.Entry<String, Integer>>> entry : dataManager.dataStructure.entrySet()) {
                    System.out.println("Thread 2: " + entry.getKey());
                }
            } catch (Exception e) {
                Logger.getLogger(DataManagement.class.getName()).log(Level.SEVERE, null, e);
            }
        });
        thread2.start();

        // Wait for both threads to finish
        thread1.join();
        thread2.join();

        // Perform garbage collection to reclaim unused memory
        System.gc();

        // Simulate data persistence and user interface interactions
        try (FileOutputStream file = new FileOutputStream("data.txt")) {
            // Write the managed data to a file
            ObjectOutputStream objectOutputStream = new ObjectOutputStream(file);
            objectOutputStream.writeObject(dataManager.dataStructure);
