// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize and manage the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* init_and_manage_list(int max_elements) {
    srand(time(NULL)); // seed for random CRCFLAG generation

    int* RNTI_values = (int*)malloc((max_elements + 1) * sizeof(int));
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < max_elements; i++) {
        RNTI_values[i] = i;
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list[i]->RX_UE_INFORMATION_TAG = i;
        list[i]->RNTI = i;
        list[i]->CRC_INDICATION_REL8_TAG = i;
        list[i]->CRCFLAG = rand() % 100; // randomly set CRCFLAG
    }

    // bubble sort to ensure unique RNTI values and sorted order
    for (int i = 0; i < max_elements - 1; i++) {
        for (int j = 0; j < max_elements - i - 1; j++) {
            if (RNTI_values[j] > RNTI_values[j + 1]) {
                int temp_RNTI = RNTI_values[j];
                NFAPI_CRC_INDICATION_PDU_T* temp_list = list[j];

                RNTI_values[j] = RNTI_values[j + 1];
                list[j] = list[j + 1];

                RNTI_values[j + 1] = temp_RNTI;
                list[j + 1] = temp_list;
            }
        }
    }

    free(RNTI_values);

    return list;
}

// Function to add a new structure to the list, maintaining sorted order and unique RNTI values
int add_to_list(NFAPI_CRC_INDICATION_PDU_T** list, int* max_elements) {
    NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_element->RX_UE_INFORMATION_TAG = (*max_elements)++;
    new_element->RNTI = *max_elements;
    new_element->CRC_INDICATION_REL8_TAG = *max_elements;
    new_element->CRCFLAG = rand() % 100; // randomly set CRCFLAG

    int i;
    for (i = 0; i < *max_elements - 1; i++) {
        if (new_element->RNTI > list[i]->RNTI) break;
    }

    // shift existing elements to make room for the new element
    for (int j = *max_elements - 1; j > i; j--) {
        list[j] = list[j - 1];
    }

    list[i] = new_element;

    return 0;
}

// Function to remove an element from the list, maintaining sorted order and unique RNTI values
void remove_from_list(NFAPI_CRC_INDICATION_PDU_T** list, int* max_elements) {
    free(list[*max_elements - 1]);
    for (int i = *max_elements - 2; i >= 0; i--) {
        list[i]->RNTI--;
    }
    (*max_elements)--;

    return;
}

// Function to retrieve an element from the list by RNTI value
NFAPI_CRC_INDICATION_PDU_T* get_element_by_RNTI(NFAPI_CRC_INDICATION_PDU_T** list, int max_elements, int target_RNTI) {
    for (int i = 0; i < max_elements; i++) {
        if (list[i]->RNTI == target_RNTI) return list[i];
    }

    return NULL;
}

// Function to free the allocated memory and deallocate resources
void free_list(NFAPI_CRC_INDICATION_PDU_T** list, int max_elements) {
    for (int i = 0; i < max_elements; i++) {
        free(list[i]);
    }
    free(list);

    return;
}
