            double* current_transactions = array[index];
            while (*current_transactions != 0.0) {
                current_transactions++;
            }
            *current_transactions = transaction->transaction_amount;
        }
    }

    fclose(file);
}

void free_memory() {
    for (int i = 0; i < MAX_PRODUCTS; i++) {
        linked_list_node* node = hash_table[i];
        while (node != NULL) {
            free(node->data);
            linked_list_node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    for (int i = 0; i < MAX_PRODUCTS; i++) {
        double* transactions = array[i];
        if (transactions != NULL) {
            while (*transactions != 0.0) {
                *transactions = 0.0;
                transactions++;
            }
            free(transactions);
        }
    }

    free(hash_table);
}

int main() {
