#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CAPACITY 1000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *head = NULL;
int size = 0;

// Function to add an element to the list
void insert(NFAPI_CRC_INDICATION_PDU_T* new_node) {
    pthread_mutex_lock(&new_node->mutex);
    if (size >= MAX_CAPACITY) {
        printf("List is full. Cannot add more elements.\n");
        return;
    }

    // Check for duplicate RNTI
    int found = 0;
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL && !found) {
        if (new_node->rnti == current->rnti) {
            printf("Warning: Duplicate RNTI detected. Removing existing entry.\n");
            // Remove the duplicate entry
            NFAPI_CRC_INDICATION_PDU_T* temp = head;
            if (temp->rnti == new_node->rnti) {
                head = temp->next;
            }
            else {
                while (temp->next != NULL && temp->next->rnti != new_node->rnti)
                    temp = temp->next;
                if (temp->next != NULL)
                    temp->next = temp->next->next;
                else
                    temp->next = NULL;
            }
            size--;
            found = 1;
        }
        current = current->next;
    }

    // Insert the new node at the end of the list
    if (head == NULL || head->rnti > new_node->rnti) {
        new_node->next = head;
        head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = head;
        while (current->next != NULL && current->next->rnti < new_node->rnti)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
    size++;

    pthread_mutex_unlock(&new_node->mutex);
}

// Function to remove an element from the list
void remove(NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&node->mutex);
    if (size > 0) {
        if (head == node) {
            head = node->next;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->next != NULL && current->next != node)
                current = current->next;
            current->next = node->next;
        }
        size--;
    }
    pthread_mutex_unlock(&node->mutex);
}

// Function to serialize the linked list
void serialize(NFAPI_CRC_INDICATION_PDU_T* head, FILE* file) {
    // Serialize the list elements into binary format and write it to the file
    fwrite(&head, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
}

// Function to deserialize the linked list from a binary file
NFAPI_CRC_INDICATION_PDU_T* deserialize(FILE* file) {
    // Read the serialized data from the file and reconstruct the linked list
    NFAPI_CRC_INDICATION_PDU_T* new_head = NULL;
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(node, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (new_head == NULL) {
            new_head = node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = new_head;
            while (current->next != NULL)
                current = current->next;
            current->next = node;
        }
    }
    return new_head;
}
