#define SEM_NAME "my_semaphore"
#define DEFAULT_TIMEOUT 5000 // 5 seconds

// Structure to hold semaphore and logging information
typedef struct {
    sem_t *sem;
    int created_count;
    int acquired_count;
    int released_count;
} SemaphoreInfo;

// Function to create a semaphore
void* create_semaphore(void* arg) {
    SemaphoreInfo* info = (SemaphoreInfo*)arg;

    // Create the semaphore with initial value 1
    if (sem_open(SEM_NAME, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, 1) == -1) {
        perror("sem_open");
        return NULL;
    }

    info->created_count++;
    printf("Semaphore created\n");

    // Initialize the semaphore
    sem_init(info->sem, 0, 1);

    return info;
}

// Function to acquire the semaphore with a timeout
void* acquire_semaphore(void* arg) {
    SemaphoreInfo* info = (SemaphoreInfo*)arg;
    int timeout = DEFAULT_TIMEOUT; // Default timeout

    if (pthread_attr_gettimeout(NULL, &timeout)) {
        printf("Acquisition timeout not specified\n");
    }

    // Acquire the semaphore with a timeout
    if (sem_wait_timeout(info->sem, timeout) == -1) {
        perror("sem_wait_timeout");
        return NULL;
    }

    info->acquired_count++;
    printf("Semaphore acquired\n");

    return info;
}

// Function to release the semaphore
void* release_semaphore(void* arg) {
    SemaphoreInfo* info = (SemaphoreInfo*)arg;

    // Release the semaphore
    sem_post(info->sem);

    info->released_count++;
    printf("Semaphore released\n");

    return info;
}

// Function to destroy the semaphore and logging information
void* destroy_semaphore(void* arg) {
    SemaphoreInfo* info = (SemaphoreInfo*)arg;

    // Destroy the semaphore
    sem_destroy(info->sem);

    // Close the semaphore file descriptor
    if (close(sem_open(SEM_NAME, O_RDONLY)) == -1) {
        perror("close");
    }

    printf("Semaphore destroyed\n");

    return NULL;
}

int main() {
    // Create a semaphore with initial value 1
    SemaphoreInfo* info = malloc(sizeof(SemaphoreInfo));
    if (pthread_create(NULL, NULL, create_semaphore, info) != 0) {
        perror("pthread_create");
    }

    // Acquire the semaphore with a timeout
    if (pthread_create(NULL, NULL, acquire_semaphore, info) != 0) {
        perror("pthread_create");
    }

    // Release the semaphore
    if (pthread_create(NULL, NULL, release_semaphore, info) != 0) {
        perror("pthread_create");
    }

    // Destroy the semaphore and logging information
    if (pthread_create(NULL, NULL, destroy_semaphore, info) != 0) {
        perror("pthread_create");
    }

    return 0;
}
