#include <stdlib.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>

#define RECORD_SIZE (sizeof(record) + sizeof(long))
#define MAX_RECORDS 1000
#define MAX_META 10
#define TIMESTAMP 1234
#define LOG_LEVEL 1

typedef struct {
    union {
        long l;
        int i;
    } data;
    uint32_t timestamp;
    int metadata;
} record;

int manage_records(int threshold, int range_min, int range_max, int reseed_interval, int* max_keys, bool debug) {
    // Initialize random seed
    srand(reseed_interval);

    // Initialize mutex for synchronization
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize array of records and metadata
    record* records = malloc(RECORD_SIZE * MAX_RECORDS);
    int* keys = malloc(sizeof(int) * (*max_keys));
    long* offsets = malloc(sizeof(long) * (*max_keys));

    // Initialize metadata and record counts
    int meta_count = 0;
    int record_count = 0;
    int total_size = 0;

    while (1) {
        // Reap unused records if memory usage exceeds threshold
        if (total_size > threshold) {
            for (int i = 0; i < record_count; i++) {
                if ((records + i)->timestamp <= TIMESTAMP - reseed_interval) {
                    free(records + i);
                    total_size -= RECORD_SIZE;
                    record_count--;
                }
            }
        }

        // Allocate new record
        if (record_count < MAX_RECORDS && total_size < threshold) {
            int key = rand() % (*max_keys);
            long offset = rand() % ((range_max - range_min + 1));

            pthread_mutex_lock(&lock);
            if (meta_count < *max_keys) {
                keys[meta_count] = key;
                offsets[meta_count] = offset;
                meta_count++;
            }
            pthread_mutex_unlock(&lock);
        }

        // Log memory allocation and deallocation
        if (debug && record_count % LOG_LEVEL == 0) {
            printf("Allocated/Deallocated %d records.\n", record_count);
        }
    }

    free(records);
    free(keys);
    free(offsets);

    return 0;
}
