            Type pType = Type.getType(type);
            if (!compatibilityMatrix.containsKey(pType)) continue;

            for (Type compatibleType : compatibilityMatrix.get(pType)) {
                if (compatibleType.isStrongAgainst(pType)) strengths.append(compatibleType.getName()).append(", ");
                if (compatibleType.isWeakAgainst(pType)) weaknesses.append(compatibleType.getName()).append(", ");
