public:
    static SimulationRandom& getInstance() {
        static SimulationRandom instance;
        return instance;
    }

    SimulationRandom() : seed_(std::chrono::high_resolution_clock::now().time_since_epoch().count()) {}

    ~SimulationRandom() {}

    double generateUniform(double min, double max) {
        std::uniform_real_distribution<double> dist(min, max);
        return dist(rng_);
    }

    double generateGaussian(double mean, double std_dev) {
        std::normal_distribution<double> dist(mean, std_dev);
        return dist(rng_);
    }

    double generateExponential(double rate) {
        std::exponential_distribution<double> dist(rate);
        return dist(rng_);
    }

private:
    std::mt19937 rng_;
    std::chrono::high_resolution_clock::time_point seed_;

    SimulationRandom(const SimulationRandom&) = delete;
    SimulationRandom& operator=(const SimulationRandom&) = delete;
};
} // namespace SimulationEngine
