    if (!in) {
        printf("Error opening input file: %s\n", input_file);
        return;
    }

    FILE *out = fopen(output_file, "wb");
    if (!out) {
        printf("Error opening output file: %s\n", output_file);
        fclose(in);
        return;
    }

    FILE *rules = fopen(rules_file, "r");
    if (!rules) {
        printf("Error reading transformation rules: %s\n", rules_file);
        fclose(in);
        fclose(out);
        return;
    }

    // Read and apply transformation rules
    char buffer[1024];
    while (fgets(buffer, 1024, rules)) {
        process_rule(buffer);
    }

    fclose(rules);

    // Process the input file according to transformation rules
    int byte;
    while ((byte = fgetc(in)) != EOF) {
        if (is_rule_applicable(byte)) {
            transform_byte(&byte);
        }
        fputc(byte, out);
    }

    fclose(in);
    fclose(out);
}
