            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            return result
        return wrapper

    @timed_cache(ttl=60)  # cache API calls for 1 minute
    def get_weather_data_from_api(api_key, base_url):
        api = WeatherAPI(api_key, base_url)
        data = cached_api_call(lambda: api.fetch_data(city, unit_system))
        if not data:
            raise Exception("Failed to retrieve weather data")
        return data

    for key, base_url in zip(api_keys, base_urls):
        try:
            result = get_weather_data_from_api(key, base_url)
            if "temperature" in result and "humidity" in result and "wind_speed" in result and "precipitation_probability" in result:
