class OctreeNode {
public:
    std::shared_ptr<OctreeNode> child[8];
};

std::shared_ptr<OctreeNode> initializeOctree(size_t featureSize, size_t numLeafNodes, size_t dataCapacity) {
    auto root = std::make_shared<OctreeNode>();

    // Initialize the octree recursively
    initializeOctreeRecursive(root, 0, 0.5, dataCapacity);

    return root;
}

void initializeOctreeRecursive(std::shared_ptr<OctreeNode>& node, int depth, double extent, size_t capacity) {
    if (depth >= maxDepth || extent < minExtent) {
        // Leaf node reached or too small to divide further
        for (int i = 0; i < 8; ++i) {
            node->child[i] = nullptr;
        }
    } else {
        int childIndex = 0;
        for (int i = -1; i <= 1; ++i) {
            for (int j = -1; j <= 1; ++j) {
                if (i || j) {
                    auto childNode = std::make_shared<OctreeNode>();
                    node->child[childIndex++] = childNode;
                    initializeOctreeRecursive(childNode, depth + 1, extent / 2.0, capacity);
                }
            }
        }
    }
}
