namespace DynamicValueGenerator
{
    public class DynamicValueGenerator
    {
        private int _min;
        private int _max;
        private Random _random = new Random();
        private readonly object _lock = new object();

        public DynamicValueGenerator(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Min value cannot be greater than Max value");

            _min = min;
            _max = max;
        }

        public void SetRange(int min, int max)
        {
            lock (_lock)
            {
                if (min > max)
                    throw new ArgumentException("Min value cannot be greater than Max value");
                _min = min;
                _max = max;
            }
        }

        public float GenerateFloatValue(bool exclusive = false)
        {
            var range = _exclusive ? _max : (_max + 1);
            return (float)_random.NextDouble() * (range - _min) + _min;
        }

        public int GenerateIntValue(bool exclusive = false)
        {
            var range = _exclusive ? _max : (_max + 1);
            return _random.Next(_min, range);
        }

        public void GenerateValuesWithStepSize(int stepSize, int count, bool log = true)
        {
            for (int i = 0; i < count; i++)
            {
                var value = (exclusive ? _max : (_max + 1)) - ((i % stepSize) * (range - _min) / stepSize);
                if (log)
                    LogValue Generation(value);

                yield return value;
            }
        }

        public void LogValue(float value)
        {
            // Implement logging mechanism here
        }

        public override string ToString()
        {
            return $"Range: {_min} to {_max}";
        }
    }
}
