// Define structure for node in linked list
typedef struct Node {
    int key;
    char *details;
    size_t length;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to insert a new node at the end of the list
void insertNode(Node** head, int key, char* details, size_t length) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->key = key;
    newNode->details = details;
    newNode->length = length;
    newNode->prev = NULL;
    newNode->next = (*head);
    if (*head) {
        (*head)->prev = &newNode;
    } else {
        (*head) = newNode;
    }
}

// Function to delete a node from the list
void deleteNode(Node** head, int key) {
    Node* current = *head;
    Node* previous = NULL;
    while (current && current->key != key) {
        previous = current;
        current = current->next;
    }
    if (!current) {
        printf("Node not found\n");
        return;
    }
    if (previous) {
        previous->next = current->next;
    } else {
        *head = current->next;
    }
    if (current->next) {
        current->next->prev = previous;
    }
    free(current);
}

// Function to search for a node by its key
Node* searchNode(Node* head, int key) {
    Node* current = head;
    while (current && current->key != key) {
        current = current->next;
    }
    return current;
}

