typedef struct {
    char name[256];
    time_t modified;
    off_t size;
} file_info;

void* xcalloc(size_t size) {
    void* ptr = calloc(1, size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

file_info* get_file_info(const char* path) {
    struct stat sb;
    if (stat(path, &sb) == -1) {
        return NULL; // File not found
    }

    file_info* info = xcalloc(sizeof(file_info));
    strncpy(info->name, path + strlen("/"), 255);
    info->modified = sb.st_mtime;
    info->size = sb.st_size;

    return info;
}

file_info** get_file_info_array(int count) {
    file_info** array = xcalloc(count * sizeof(file_info*));

    for (int i = 0; i < count; i++) {
        array[i] = get_file_info("path/to/file" + i);
    }

    return array;
}

void free_file_info_array(file_info** array, int count) {
    for (int i = 0; i < count; i++) {
        if (array[i]) {
            free(array[i]);
        }
    }

    free(array);
}
