    // Dynamically allocate memory to handle varying lengths efficiently
    size_t line_len = strlen(line);
    void *memory = malloc(line_len + 10); // add some extra space for formatting
    char *result = (char *)memory;

    // Calculate and append the average of the last two numeric fields
    int num1, num2;
    if (sscanf(line, "%*s %d %d", &num1, &num2) == 2) {
        float avg = (num1 + num2) / 2.0f;
        sprintf(result, ",%.2f", avg);
    }

    // Format the result and append it to the end of the line
    sprintf(line + line_len, ",%s", result);

    free(memory);
}

