    FILE *fp = fopen(argv[2], "r");
    if (!fp) {
        perror("Error opening file");
        return 1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        handle_csv_line(line, &config);
        printf("%s", line); // print the processed line
    }

    fclose(fp);

    // Release resources and exit
