typedef enum {
    LOG_MSG,
    LOG_TIMESTAMP,
    LOG_LEVEL
} log_type;

typedef struct {
    union {
        char* message;
        time_t timestamp;
        int level;
    } entry;
    log_type type;
} log_entry;

log_entry** create_log_entries(int num_entries, int* msg_size, int* timestamps_size, int* levels_size) {
    log_entry** log_entries = (log_entry**)malloc(num_entries * sizeof(log_entry*));
    for (int i = 0; i < num_entries; i++) {
        log_entries[i] = (log_entry*)malloc(sizeof(log_entry));
        if (*msg_size > 0) {
            log_entries[i]->entry.message = (char*)malloc(*msg_size * sizeof(char));
        }
        if (*timestamps_size > 0) {
            log_entries[i]->entry.timestamp = (time_t)malloc(*timestamps_size * sizeof(time_t));
        }
        if (*levels_size > 0) {
            log_entries[i]->entry.level = (int*)malloc(*levels_size * sizeof(int));
        }
    }
    return log_entries;
}

void free_log_entries(log_entry** log_entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        if (*log_entries[i].entry.message > 0) {
            free(log_entries[i]->entry.message);
        }
        if (*log_entries[i].entry.timestamp > 0) {
            free(log_entries[i]->entry.timestamp);
        }
        if (*log_entries[i].entry.level > 0) {
            free(log_entries[i]->entry.level);
        }
        free(log_entries[i]);
    }
    free(log_entries);
}

int append_log_entry(log_entry** log_entries, int num_entries, int* msg_size, int* timestamps_size, int* levels_size) {
    if (num_entries >= *msg_size + *timestamps_size + *levels_size) {
        // Error handling
        return -1;
    }
    log_entries[num_entries] = (log_entry*)malloc(sizeof(log_entry));
    if (*msg_size > 0) {
        log_entries[num_entries]->entry.message = (char*)malloc(*msg_size * sizeof(char));
    }
    if (*timestamps_size > 0) {
        log_entries[num_entries]->entry.timestamp = (time_t)malloc(*timestamps_size * sizeof(time_t));
    }
    if (*levels_size > 0) {
        log_entries[num_entries]->entry.level = (int*)malloc(*levels_size * sizeof(int));
    }
    return num_entries + 1;
}

log_entry* create_log_entry(log_type type, char* message, time_t timestamp, int level) {
    log_entry* log_entry = (log_entry*)malloc(sizeof(log_entry));
    log_entry->type = type;
    switch (type) {
        case LOG_MSG:
            log_entry->entry.message = message;
            break;
        case LOG_TIMESTAMP:
            log_entry->entry.timestamp = timestamp;
            break;
        case LOG_LEVEL:
            log_entry->entry.level = level;
            break;
    }
    return log_entry;
}

int main() {
    int num_entries = 10;
    int msg_size = 100, timestamps_size = 8, levels_size = 4;

    // Allocate memory for log entries
    log_entry** log_entries = create_log_entries(num_entries, &msg_size, &timestamps_size, &levels_size);

    // Create a few log entries and append them to the array
