int num_sensors = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_allocations = 0;
size_t total_deallocations = 0;

void add_sensor(sensor_t* new_sensor) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_sensors; i++) {
        if (!sensors[i]) {
            sensors[i] = new_sensor;
            break;
        }
    }
    if (!sensors[num_sensors]) {
        sensors[num_sensors++] = new_sensor;
    }
    pthread_mutex_unlock(&lock);
}

void remove_sensor(sensor_t* sensor) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i] == sensor) {
            sensors[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void compress_data() {
    // implement compression algorithm
}

void aggregate_data() {
    // implement aggregation algorithm
}

void log_data_to_service() {
    FILE* file = fopen(LOGGING_SERVICE, "a");
    if (file) {
        for (int i = 0; i < num_sensors; i++) {
            if (sensors[i]) {
                fprintf(file, "%f %f %s\n", sensors[i]->measurement, sensors[i]->timestamp, sensors[i]->identifier);
            }
        }
        fclose(file);
    }
}

void* thread_func(void* arg) {
    sensor_t* sensor = (sensor_t*)arg;
    add_sensor(sensor);
    // process and compress data
    compress_data();
    aggregate_data();
    log_data_to_service();
    remove_sensor(sensor);
    return NULL;
}

int main() {
    pthread_t threads[MAX_SENSORS];
    for (int i = 0; i < MAX_SENSORS; i++) {
        sensors[i] = malloc(sizeof(sensor_t));
        if (!sensors[i]) {
            printf("Memory allocation failed!\n");
            return -1;
        }
    }
    // simulate sensor data collection
    for (int i = 0; i < MAX_SENSORS; i++) {
        sensor_t* sensor = sensors[i];
        pthread_create(&threads[i], NULL, thread_func, sensor);
    }
    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_join(threads[i], NULL);
    }
    // handle memory deallocation
    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i]) {
            free(sensors[i]->identifier);
            free(sensors[i]);
        }
    }
    return 0;
}

