// Define the record structure
typedef struct {
    int value;
    long *offsets;
    int *keys;
} Record;

// Function to initialize a graph database
void initializeGraphDatabase(int numRecords, int maxVerticesPerRecord) {
    // Create an array of records with dynamic size
    Record *records = (Record *)malloc(numRecords * sizeof(Record));

    // Initialize the offset and key arrays for each record
    for (int i = 0; i < numRecords; i++) {
        records[i].value = i;
        records[i].offsets = (long *)malloc((maxVerticesPerRecord + 1) * sizeof(long));
        records[i].keys = (int *)malloc((maxVerticesPerRecord + 1) * sizeof(int));

        // Initialize the offset and key arrays
        for (int j = 0; j <= maxVerticesPerRecord; j++) {
            records[i].offsets[j] = i * (long)maxVerticesPerRecord + j;
            records[i].keys[j] = j;
        }
    }

    // Validate the integrity of the records
    for (int i = 0; i < numRecords; i++) {
        for (int j = 0; j <= maxVerticesPerRecord; j++) {
            assert(records[i].offsets[j] >= 0 && "Offset out of range");
            assert(records[i].keys[j] >= 0 && "Key out of range");
        }
    }

    // Free the memory
    for (int i = 0; i < numRecords; i++) {
        free(records[i].offsets);
        free(records[i].keys);
    }
    free(records);
}

int main() {
    initializeGraphDatabase(10, 5);
    return 0;
}
