#include <time.h>

// Define a record structure
typedef struct {
    long offset;
    int key;
} record;

// Function to initialize arrays
void initArrays(long **offsets, int **keys, int n) {
    *offsets = (long *)malloc(n * sizeof(long));
    *keys = (int *)malloc(n * sizeof(int));
}

// Function to dynamically allocate memory for records array
record **initRecords(int m, long memory_limit) {
    record **records = (record **)malloc((m + 1) * sizeof(record *));
    for (int i = 0; i <= m; i++) {
        records[i] = (record *)malloc(sizeof(record));
    }
    return records;
}

// Function to generate random values and assign to records
void initRecordsValues(record **records, int m, int min, int max) {
    for (int i = 0; i < m; i++) {
        records[i]->offset = rand() % ((max - min + 1) / sizeof(long)) * sizeof(long);
        records[i]->key = rand() % (max - min + 1);
    }
}

// Function to track memory usage and allocation patterns
void logMemoryUsage(record **records, int m, long memory_limit) {
    printf("Allocated memory: %ld bytes\n", memory_limit);
    for (int i = 0; i <= m; i++) {
        printf("Record %d: Offset - %ld, Key - %d\n", i, records[i]->offset, records[i]->key);
    }
}

// Function to free all allocated memory
void freeMemory(record **records, long **offsets, int **keys, int n) {
    for (int i = 0; i < n; i++) {
        free(offsets[i]);
    }
    free(*offsets);
    for (int i = 0; i <= m; i++) {
        free(records[i]);
    }
    free(*records);
}

// Main function
int main() {
    int n = 10;
    int m = 5;
    long memory_limit = 1000000; // Adjust based on system constraints

    record **records = initRecords(m, memory_limit);
    long *offsets = (long *)malloc(n * sizeof(long));
    int *keys = (int *)malloc(n * sizeof(int));

    initArrays(&offsets, &keys, n);
    initRecordsValues(records, m, 0, 1000); // Random range [0, 1000]

    logMemoryUsage(records, m, memory_limit);

    freeMemory(records, &offsets, &keys, n);

    return 0;
}
