        messages[i].tid = rand() % 65536;
        char* payload = (char*)malloc(max_payload_length);
        if (!payload) return NULL; // Handle allocation failure
        memset(payload, '\0', max_payload_length);
        messages[i].message_content = payload;
    }

    return messages;
}

void lte_mme_message_free(LTE_MME_MESSAGE_T* messages, int num_messages) {
    for (int i = 0; i < num_messages; i++) {
        free(messages[i].message_content);
    }
    free(messages);
}
