        if (!profile || strcmp(profile->username, username)) {
            pthread_mutex_unlock(&hash_table->mutex);
            return;
        }
        // Handle the case where the profile is being updated concurrently
        free(profile);
        hash_table->buckets[index] = NULL;
        break;
    }
}

// Function to update a user profile in the hash table
void update_user_profile(HashTable* hash_table, UserProfile* old_profile, UserProfile* new_profile) {
    int index = hash_function(hash_table->size, old_profile->username);
    while (1) {
        pthread_mutex_lock(&hash_table->mutex);
        if (!hash_table->buckets[index] || strcmp(hash_table->buckets[index]->username, old_profile->username)) {
            pthread_mutex_unlock(&hash_table->mutex);
            return;
        }
        // Handle the case where the profile is being updated concurrently
        free(old_profile);
        hash_table->buckets[index] = new_profile;
        break;
    }
}

// Function to query a user profile from the hash table
UserProfile* get_user_profile(HashTable* hash_table, char* username) {
    int index = hash_function(hash_table->size, username);
    while (1) {
        pthread_mutex_lock(&hash_table->mutex);
        UserProfile* profile = hash_table->buckets[index];
        if (!profile || strcmp(profile->username, username)) {
            pthread_mutex_unlock(&hash_table->mutex);
            return NULL;
        }
        // Handle the case where the profile is being updated concurrently
        break;
    }
}

// Function to resize the hash table
void resize_hash_table(HashTable* hash_table) {
    int new_size = 2 * hash_table->size;
    HashTable* new_hash_table = init_hash_table(new_size);
    for (int i = 0; i < hash_table->size; i++) {
        UserProfile* profile = hash_table->buckets[i];
        while (1) {
            pthread_mutex_lock(&hash_table->mutex);
            if (!profile) {
                break;
