Shape **manage_grid(int size) {
    // Dynamically allocate memory for the grid and shapes
    Shape **grid = (Shape **)malloc(size * sizeof(Shape *));
    for (int i = 0; i < size; i++) {
        grid[i] = (Shape *)malloc(sizeof(Shape));
    }

    return grid;
}

// Function to validate the integrity of each shape after initialization
void validate_shape(Shape *shape) {
    // Check dimensions are logically consistent
    if (shape->type == 0 && shape->dimensions[0] < 0) {
        printf("Error: Negative radius for a circle.\n");
    }
}

// Function to sort the grid of shapes by area in ascending order using custom comparator
void sort_grid(Shape **grid, int size) {
    // Custom comparator function
    int compare_shapes(const void *a, const void *b) {
        Shape *sa = *(Shape **)a;
        Shape *sb = *(Shape **)b;

        double area_a = 0;
        double area_b = 0;

        switch (sa->type) {
            case 0: // Circle
                area_a = M_PI * sa->dimensions[0] * sa->dimensions[0];
                break;
            case 1: // Rectangle
                area_a = sa->dimensions[0] * sa->dimensions[1];
                break;
            case 2: // Triangle
                area_a = 0.5 * sa->dimensions[0] * sa->dimensions[1];
                break;
        }

        switch (sb->type) {
            case 0: // Circle
                area_b = M_PI * sb->dimensions[0] * sb->dimensions[0];
                break;
            case 1: // Rectangle
                area_b = sb->dimensions[0] * sb->dimensions[1];
                break;
            case 2: // Triangle
                area_b = 0.5 * sb->dimensions[0] * sb->dimensions[1];
                break;
        }

        return (area_a - area_b) ? -1 : 1;
    }

    // Sort the grid using the custom comparator
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (compare_shapes(&grid[i], &grid[j]) > 0) {
                Shape *temp = grid[i];
                grid[i] = grid[j];
                grid[j] = temp;
            }
        }
    }
}

// Function to dynamically resize the grid while maintaining the integrity and order of shapes
void resize_grid(Shape **grid, int old_size, int new_size) {
    // Dynamically allocate memory for the resized grid
    Shape **new_grid = (Shape **)realloc(grid, new_size * sizeof(Shape *));
    for (int i = old_size; i < new_size; i++) {
        new_grid[i] = (Shape *)malloc(sizeof(Shape));
    }

    // Copy existing shapes to the new grid
    for (int i = 0; i < old_size; i++) {
        new_grid[i] = grid[i];
    }

    // Free memory from the original grid
    for (int i = old_size; i < size; i++) {
        free(grid[i]);
    }
    free(grid);

    grid = new_grid;
}

