// Helper function to read a list of integers from standard input,
// store them in an array, and compute and print the average and standard deviation.
void processIntegers(int* arr, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    double mean = sum / size;

    double variance = 0.0;
    for (int i = 0; i < size; i++) {
        variance += pow(arr[i] - mean, 2);
    }
    variance /= size;

    double stddev = sqrt(variance);

    printf("Mean: %.2f\n", mean);
    printf("Standard Deviation: %.2f\n", stddev);
}

// Function to manage dynamic memory allocation for four arrays.
void processDataAndComputeStats(int numDataPoints, int* dataPoints, char** labels, time_t* timestamps, enum Status* statuses) {
    // Initialize the arrays with specified sizes
    double* arrDouble = (double*)malloc(numDataPoints * sizeof(double));
    char** arrChar = (char**)malloc(numDataPoints * sizeof(char*));
    time_t* arrTimeT = (time_t*)malloc(numDataPoints * sizeof(time_t));
    enum Status* arrEnumStatus = (enum Status*)malloc(numDataPoints * sizeof(enum Status));

    // Validate the integrity of the data after initialization
    for (int i = 0; i < numDataPoints; i++) {
        if (!arrDouble[i] || !arrChar[i] || !arrTimeT[i] || !arrEnumStatus[i]) {
            printf("Invalid memory allocation.\n");
            return;
        }
    }

    // Validate the timestamps
    for (int i = 0; i < numDataPoints; i++) {
        if (timestamps[i] <= 0) {
            printf("Invalid timestamp.\n");
            return;
        }
    }

    // Validate the statuses
    for (int i = 0; i < numDataPoints; i++) {
        switch (statuses[i]) {
            case active:
                break;
            case inactive:
                break;
            default:
                printf("Invalid status.\n");
                return;
        }
    }

    // Populate each data point's status with a value based on its label,
    // ensuring no two records share the same active timestamp.
    int uniqueTimestamp = 0;
    for (int i = 0; i < numDataPoints; i++) {
        if (!strcasecmp(labels[i], "active")) {
            arrEnumStatus[i] = active;
        } else {
            arrEnumStatus[i] = inactive;
            uniqueTimestamp++;
        }
        timestamps[i] = uniqueTimestamp;
    }

    // Free the memory
    free(arrDouble);
    free(arrChar);
    free(arrTimeT);
    free(arrEnumStatus);
}

int main() {
    int numDataPoints;
    printf("Enter number of data points: ");
    scanf("%d", &numDataPoints);

    int* arrInt = (int*)malloc(numDataPoints * sizeof(int));
    char** arrCharLabels = (char**)malloc(numDataPoints * sizeof(char*));
    time_t* arrTimeT = (time_t*)malloc(numDataPoints * sizeof(time_t));
    enum Status* arrEnumStatus = (enum Status*)malloc(numDataPoints * sizeof(enum Status));

    // Read a list of integers from standard input,
    // store them in an array, and compute and print the average and standard deviation.
    processIntegers(arrInt, numDataPoints);

    // Process data points and compute statistics
    processDataAndComputeStats(numDataPoints, arrInt, arrCharLabels, arrTimeT, arrEnumStatus);

    return 0;
}
