}

void expire_sessions() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].id != NULL && sessions[i].last_activity + sessions[i].timeout <= time(NULL)) {
            // Session timed out, update state and deallocate resources
            sessions[i].state = 1;
            // ...
        }
    }
}

