            printf("Invalid session ID\n");
            continue;
        }

        Session* session = &sessions[session_count];
        session->id = session_id;
        inet_pton(AF_INET, "1.2.3.4", &(session->client_addr));
        session->last_activity = time(NULL);

        session_count++;

        expire_sessions();
    }

    return 0;
