    private static final int MAX_CHUNK_SIZE = 1024 * 10; // 10 MB

    public void processLogs(int threadPoolSize, int chunkSize) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(threadPoolSize);

        for (String logFile : getLogFiles()) {
            try {
                processLogFile(logFile, executor, chunkSize);
            } catch (Exception e) {
                if (MAX_RETRIES > 0) {
                    int retriesLeft = MAX_RETRIES - 1;
                    int waitInterval = (int) Math.pow(2, retriesLeft); // exponential backoff
                    try {
                        Thread.sleep(waitInterval * 1000);
                    } catch (InterruptedException ie) {}
                    processLogFile(logFile, executor, chunkSize);
                } else {
                    System.out.println("Failed to process log file: " + logFile);
                }
            }
        }

        executor.shutdown();
    }

    private void processLogFile(String logFile, ExecutorService executor, int chunkSize) throws Exception {
        for (int i = 0; i < getChunkCount(logFile); i++) {
            try {
                executor.submit(() -> processLogChunk(logFile, i * chunkSize, (i + 1) * chunkSize));
            } catch (Exception e) {
                System.out.println("Error processing log file: " + logFile);
            }
