    long* offsets = (long*) malloc((numRecords + 1) * sizeof(long));
    if (!offsets) return NULL; // Handle allocation error

    // Initialize offset array with incrementing values starting from 0
    for (size_t i = 0; i <= numRecords; i++) {
        offsets[i] = i;
    }

    // Allocate memory for key array
    int* keys = (int*) malloc(numRecords * sizeof(int));
    if (!keys) return NULL; // Handle allocation error

    // Populate key array with unique random values using external seed value
    srand(time(NULL)); // Initialize random number generator
    for (size_t i = 0; i < numRecords; i++) {
        int temp;
        do {
            temp = rand() % 10000; // Generate a random integer between 0 and 9999
        } while (keys[i] == temp); // Ensure uniqueness by retrying until a unique value is found
        keys[i] = temp;
    }

    // Allocate memory for record array
    record* records = (record*) malloc(numRecords * sizeof(record));
    if (!records) return NULL; // Handle allocation error

    // Initialize each record structure with a random integer value within the specified range
    int minRecordValue = 1, maxRecordValue = 100;
    for (size_t i = 0; i < numRecords; i++) {
        records[i].value = rand() % (maxRecordValue - minRecordValue + 1) + minRecordValue;
    }

    // Return the record array and sizes of offset and key arrays as a tuple
    return (record*) malloc((sizeof(record*) * 3) + sizeof(size_t)), &numRecords, numRecords);
}
