            result[hashValue] = (result[hashValue].Item1, result.Count(x => x.Item2 == 0) + 1);
        }
        catch
        {
            // Log errors and continue processing
        }
    }

    var sortedResult = result.OrderBy(x => x.Key).Select((x, i) => new { x.Value.Item1, HashValue = x.Key, Position = i }).ToDictionary(x => x.HashValue, x => (x.Position, x.Position));

    await LogProcessingTimeAsync();

    return sortedResult;
}

