std::unique_ptr<std::vector<int>> initialize_data_arrays(int num_records) {
    std::unique_ptr<std::vector<int>> offsets(new std::vector<int>());
    std::unique_ptr<std::vector<std::string>> keys(new std::vector<std::string>());
    std::unique_ptr<std::vector<std::pair<int, int>>> records(new std::vector<std::pair<int, int>>());

    // Function to maintain data integrity and consistency
    if (offsets->size() != num_records || keys->size() != num_records || records->size() != num_records) {
        throw std::runtime_error("Data inconsistency");
    }

    // Concurrency and thread safety
    std::mutex mtx;
    for (int i = 0; i < num_records; ++i) {
        std::lock_guard<std::mutex> lock(mtx);
        offsets->push_back(i * 10 + 5);
        keys->push_back(std::to_string(i));
        records->push_back({i, i * 2});
    }

    // Performance optimization
    return {offsets.release(), keys.release(), records.release()};
}

int main() {
    int num_records = 100000;
    try {
        std::unique_ptr<std::vector<int>> data_arrays = initialize_data_arrays(num_records);
        std::ofstream file("data.txt");
        for (int i = 0; i < num_records; ++i) {
            file << data_arrays->get(0)[i] << " " << data_arrays->get(1)[i] << " " << data_arrays->get(2)[i] << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

