import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

class TaskSchedule {
    int taskId;
    String dueDate;
    int priorityLevel;
    String resourceAllocations;
}

public class taskManager {
    private TaskSchedule[] tasks;
    private Lock lock = new ReentrantLock();

    public taskManager() {
        this.tasks = new TaskSchedule[0];
    }

    public void addTask(String taskData) throws Exception {
        lock.lock();
        try {
            String[] dataParts = taskData.split(",");
            if (dataParts.length != 4) {
                throw new Exception("Invalid task data format");
            }
            int taskId = Integer.parseInt(dataParts[0].trim());
            String dueDate = dataParts[1].trim();
            int priorityLevel = Integer.parseInt(dataParts[2].trim());
            String resourceAllocations = dataParts[3].trim();

            // Validate and assign task fields
            TaskSchedule newTask = new TaskSchedule();
            newTask.taskId = taskId;
            newTask.dueDate = dueDate;
            newTask.priorityLevel = priorityLevel;
            newTask.resourceAllocations = resourceAllocations;

            // Add the new task to the schedule
            TaskSchedule[] updatedTasks = new TaskSchedule[tasks.length + 1];
            System.arraycopy(tasks, 0, updatedTasks, 0, tasks.length);
            updatedTasks[tasks.length] = newTask;
            this.tasks = updatedTasks;
        } finally {
            lock.unlock();
        }
    }

    public void removeTask(int taskId) throws Exception {
        lock.lock();
        try {
            for (int i = 0; i < tasks.length; i++) {
                if (tasks[i].taskId == taskId) {
                    TaskSchedule[] updatedTasks = new TaskSchedule[tasks.length - 1];
                    System.arraycopy(tasks, 0, updatedTasks, 0, i);
                    System.arraycopy(tasks, i + 1, updatedTasks, i, tasks.length - i - 1);
                    this.tasks = updatedTasks;
                    return;
                }
            }
            throw new Exception("Task not found");
        } finally {
            lock.unlock();
        }
    }

    public void updateTask(int taskId, String taskData) throws Exception {
        lock.lock();
        try {
            for (int i = 0; i < tasks.length; i++) {
                if (tasks[i].taskId == taskId) {
                    String[] dataParts = taskData.split(",");
                    // Validate and assign updated task fields
                    tasks[i].dueDate = dataParts[1].trim();
                    tasks[i].priorityLevel = Integer.parseInt(dataParts[2].trim());
                    tasks[i].resourceAllocations = dataParts[3].trim();
                    return;
                }
            }
            throw new Exception("Task not found");
        } finally {
            lock.unlock();
        }
    }

    public void printTasks() throws Exception {
        for (TaskSchedule task : tasks) {
            System.out.println(task.taskId + ": " + task.dueDate + ", Priority: " + task.priorityLevel + ", Resource Allocations: " + task.resourceAllocations);
        }
    }
}
