#define MAX_CACHE_SIZE 10000
#define OBJECT_TYPE_COUNT 5 // FILE, DIRECTORY, PROCESS, THREAD, etc.

typedef struct {
    int id;
    time_t creation_timestamp;
    time_t last_access_timestamp;
} OBJECT_INFO;

// Thread-safe cache management
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
OBJECT_INFO* cache = NULL;
int cache_size = 0;

void update_object_id(OBJECT_INFO* obj) {
    // Update object ID to ensure uniqueness
    int new_id = 1;
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].id == obj->id) {
            new_id++;
        }
    }
    obj->id = new_id;
}

void* allocate_object_info() {
    OBJECT_INFO* obj = (OBJECT_INFO*)malloc(sizeof(OBJECT_INFO));
    if (!obj) {
        // Handle memory allocation failure
        return NULL;
    }
    return obj;
}

int add_object_to_cache(OBJECT_INFO* obj) {
    pthread_mutex_lock(&cache_lock);

    if (cache_size >= MAX_CACHE_SIZE) {
        // Handle cache overflow error
        pthread_mutex_unlock(&cache_lock);
        return -1; // Error: Cache size exceeded
    }

    update_object_id(obj);
    cache[cache_size] = *obj;
    cache_size++;

    pthread_mutex_unlock(&cache_lock);

    return 0; // Success: Object added to cache
}

void print_cache() {
    pthread_mutex_lock(&cache_lock);

    for (int i = 0; i < cache_size; i++) {
        printf("Object ID: %d, Creation Timestamp: %ld, Last Access Timestamp: %ld\n",
               cache[i].id, cache[i].creation_timestamp, cache[i].last_access_timestamp);
    }

    pthread_mutex_unlock(&cache_lock);
}
