// Function to add a new session configuration
void addUserSession(UserSession** sessions, int size, int id, char* username, char* password, long last_activity_timestamp, char** permissions) {
    // Check if there is enough space in the array
    if (size <= 0) {
        printf("Error: Array is full.\n");
        return;
    }

    UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));
    new_session->id = id;
    new_session->username = strdup(username);
    new_session->password = strdup(password);
    new_session->last_activity_timestamp = last_activity_timestamp;
    int num_permissions = 0;
    for (int i = 0; permissions[i]; i++) {
        num_permissions++;
    }
    new_session->permissions = (char**)malloc((num_permissions + 1) * sizeof(char*));
    for (int i = 0; permissions[i]; i++) {
        new_session->permissions[i] = strdup(permissions[i]);
    }
    new_session->permissions[num_permissions] = NULL;

    // Add the new session to the array
    sessions[size - 1] = new_session;
    size++;
}

// Function to remove a session configuration
void removeUserSession(UserSession** sessions, int* size) {
    if (*size <= 0) {
        printf("Error: Array is empty.\n");
        return;
    }

    free(sessions[*size - 1]->permissions);
    free(sessions[*size - 1]->username);
    free(sessions[*size - 1]->password);

    free(sessions[*size - 1]);
    sessions[*size - 1] = NULL;

    (*size)--;
}

// Function to update a session configuration
void updateUserSession(UserSession** sessions, int* size, int id, char* username, char* password, long last_activity_timestamp, char** permissions) {
    for (int i = 0; i < *size; i++) {
        if (sessions[i]->id == id) {
            // Update the existing session
            free(sessions[i]->username);
            free(sessions[i]->password);

            sessions[i]->username = strdup(username);
            sessions[i]->password = strdup(password);

            int num_permissions = 0;
            for (int j = 0; permissions[j]; j++) {
                num_permissions++;
            }
            sessions[i]->permissions = (char**)malloc((num_permissions + 1) * sizeof(char*));
            for (int j = 0; permissions[j]; j++) {
                sessions[i]->permissions[j] = strdup(permissions[j]);
            }
            sessions[i]->permissions[num_permissions] = NULL;

            return;
        }
    }

    printf("Error: Session not found.\n");
}

// Function to free memory allocated for user sessions
void freeUserSessions(UserSession** sessions, int size) {
    for (int i = 0; i < size; i++) {
        free(sessions[i]->permissions);
        free(sessions[i]->username);
        free(sessions[i]->password);

        free(sessions[i]);
    }

    free(sessions);
