    if (!*keys) {
        printf("Error: Memory allocation failed for keys.\n");
        free(records);
        free(*offsets);
        return;
    }

    // Validate integrity of records
    int seenKeys[10000];  // Assume max number of distinct keys is 10,000
    memset(seenKeys, 0, sizeof(int) * 10000);

    for (int i = 0; i < numRecords; i++) {
        int randomValue = rand() % 100;  // Random value within a given range

        while (1) {  // Find a unique key
            int key = rand() % 10000;
            if (!seenKeys[key]) {
                seenKeys[key] = 1;
                break;
            }
        }

        records[i].value = randomValue;
        for (int j = 0; j < 10; j++) {
            records[i].offset[j] = rand() % 10000;  // Random offset value
        }
        records[i].key = key;
    }

    // Validate records have unique keys
    for (int i = 0; i < numRecords; i++) {
        int foundDuplicate = 0;

        for (int j = 0; j < i; j++) {
            if (records[j].key == records[i].key) {
                foundDuplicate = 1;
                break;
            }
        }

        if (foundDuplicate) {
            printf("Error: Duplicate key detected.\n");
            return;
        }
    }

    // Log performance metrics
    printf("Records initialized successfully. Memory usage: %d bytes.\n", numRecords * sizeof(Record));
}

