#include <unistd.h>

// Structure to hold record information
typedef struct {
    int value;
} record;

// Custom memory pool allocator structure
typedef struct {
    void** segments;
    size_t segment_size;
    size_t total_allocated;
    pthread_mutex_t mutex;
} memory_pool;

// Initialize memory pool with initial allocation size and number of segments
memory_pool* init_memory_pool(size_t initial_allocation, size_t segment_count) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    pool->segment_size = initial_allocation;
    pool->total_allocated = 0;
    pool->segments = (void**)malloc(segment_count * sizeof(void*));

    // Initialize mutex for thread safety
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

// Allocate memory from the pool and update the allocated size
void* alloc_memory(memory_pool* pool, size_t allocation_size) {
    void* allocation = NULL;

    // Try to find an unused segment
    for (size_t i = 0; i < pool->segment_size; ++i) {
        if (!pool->segments[i]) {
            allocation = (void*)malloc(allocation_size);
            pool->segments[i] = allocation;
            break;
        }
    }

    // If no unused segments found, allocate a new segment
    if (!allocation) {
        allocation = (void*)malloc(pool->segment_size * sizeof(void*));
        for (size_t i = 0; i < pool->segment_size; ++i) {
            allocation = (void*)((char*)allocation + i);
            ((void**)(allocation))[i] = NULL;
        }
        pool->segments[pool->total_allocated++] = allocation;
    }

    return allocation;
}

// Free allocated memory and update the segment
void free_memory(memory_pool* pool, void* allocation) {
    // Find the corresponding segment in the pool
    for (size_t i = 0; i < pool->segment_size; ++i) {
        if (pool->segments[i] == allocation) {
            // Free the allocated memory and update the segment
            free(allocation);
            pool->segments[i] = NULL;
            return;
        }
    }
}

// Function to manage memory allocation for multiple data structures
void* allocate_memory_segments(memory_pool* pool, size_t n) {
    void** offset_values = (void**)alloc_memory(pool, n * sizeof(long));
    void** keys = (void**)alloc_memory(pool, n * sizeof(int));

    // Initialize the arrays with default values
    for (size_t i = 0; i < n; ++i) {
        ((long*)offset_values)[i] = i;
        ((int*)keys)[i] = i;
    }

    return offset_values;
}

// Function to set record values to random numbers
void set_record_values(record* records, size_t m, int minValue, int maxValue) {
    for (size_t i = 0; i < m; ++i) {
        ((record*)records)[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

// Function to log memory operations
void log_memory_operation(int operation, size_t allocated_size) {
    // Open the log file for appending
    int fd = open("memory_operations.log", O_APPEND | O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        printf("Error opening log file.\n");
        return;
    }

    // Write to the log file
    char buffer[1024];
    sprintf(buffer, "%d: %ld bytes allocated/deallocated\n", operation, allocated_size);
    write(fd, buffer, strlen(buffer));

    // Close the log file
    close(fd);
}

// Function to validate memory deallocation
void validate_memory_deallocation(memory_pool* pool) {
    for (size_t i = 0; i < pool->segment_size; ++i) {
        if (pool->segments[i]) {
            printf("Memory leak detected at segment %ld\n", i);
            return;
        }
    }

    printf("No memory leaks found.\n");
}

int main() {
    // Initialize the memory pool
    memory_pool* pool = init_memory_pool(1024, 10);

    // Allocate and deallocate memory
    void* allocated_memory = allocate_memory_segments(pool, 1000);
    log_memory_operation(1, sizeof(long) * 1000);
    free_memory(pool, allocated_memory);
    log_memory_operation(2, sizeof(long) * 1000);

    // Set record values to random numbers
    record records[2000];
    set_record_values(records, 2000, 0, 100);

    // Validate memory deallocation
    validate_memory_deallocation(pool);

    return 0;
}
