void populate_user_profiles(user_profile** profiles, int* num_profiles) {
    // Simulate data
    for (int i = 0; i < *num_profiles; i++) {
        user_profile* profile = &profiles[i];
        profile->user_id = i + 1;
        profile->profile_name = malloc(16);
        sprintf(profile->profile_name, "User-%d", i + 1);
        int role_count = rand() % 3 + 1;
        profile->roles = malloc(role_count * sizeof(char*));
        for (int j = 0; j < role_count; j++) {
            char* role = malloc(16);
            sprintf(role, "Role-%d", j + 1);
            profile->roles[j] = role;
        }
    }
