void populate_sensor_data(sensor_data** sensors, int* num_sensors) {
    // Simulate data
    for (int i = 0; i < *num_sensors; i++) {
        sensor_data* sensor = &sensors[i];
        sensor->measurement = rand() / (double)RAND_MAX;
        sensor->timestamp = (float)time(NULL);
