    // Update existing profile or create new one if not found
    for (int i = 0; i < *num_profiles; i++) {
        if (profiles[i]->user_id == user_id) {
            // Update existing profile
            free(profiles[i]->profile_name);
            strcpy(profiles[i]->profile_name, request_body);
            break;
        } else {
            // Create new profile
            int role_count = rand() % 3 + 1;
            char** new_roles = malloc(role_count * sizeof(char*));
            for (int j = 0; j < role_count; j++) {
                char* role = malloc(16);
                sprintf(role, "Role-%d", j + 1);
                new_roles[j] = role;
            }
            profiles[i]->user_id = user_id;
            free(profiles[i]->profile_name);
            strcpy(profiles[i]->profile_name, request_body);
            profiles[i]->roles = new_roles;
        }
    }
}

void delete_user_profile(user_profile** profiles, int user_id) {
    // Delete existing profile or return default values if not found
    for (int i = 0; i < *num_profiles; i++) {
        if (profiles[i]->user_id == user_id) {
            free(profiles[i]->profile_name);
            strcpy(profiles[i]->profile_name, "Deleted");
