typedef struct {
    int key;
    int min_value;
    int max_value;
    int* offsets;
    int offset_count;
} Record;

Record* init_records(int record_count, int** offset_pointers) {
    Record* records = (Record*)malloc(record_count * sizeof(Record));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < record_count; i++) {
        records[i].key = i;
        records[i].min_value = 0;
        records[i].max_value = 100; // Default range
        records[i].offsets = NULL;
        if (!(*offset_pointers)) {
            continue; // No offsets for this record, skip
        }
        int offset_count = (*offset_pointers)[i];
        records[i].offsets = (int*)malloc(offset_count * sizeof(int));
        if (!records[i].offsets) {
            free(records);
            return NULL; // Handle memory allocation failure
        }
        memcpy(&records[i].offsets, (*offset_pointers), offset_count * sizeof(int));
    }

    // Validate record structure integrity
    for (int i = 0; i < record_count; i++) {
        if (!records[i].offsets) continue;
        for (int j = 0; j < records[i].offset_count; j++) {
            if (records[i].offsets[j] < 0 || records[i].offsets[j] >= INT_MAX) {
                free(records);
                return NULL; // Out-of-bounds access detected
            }
        }
    }

    return records;
}

void free_records(Record* records, int record_count) {
    for (int i = 0; i < record_count; i++) {
        if (!records[i].offsets) continue;
        free(records[i].offsets);
    }
    free(records);
}
