// Function to initialize and allocate memory for a collection of records
Record** initRecords(int numRecords, int minKey, int maxKey, int probabilityThreshold, void (*fetchDoubleValue)(int*, double*)) {
    Record** records = (Record**)calloc(numRecords, sizeof(Record*));

    // Initialize each record
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));

        // Generate random key within the specified range
        records[i]->key = rand() % (maxKey - minKey + 1) + minKey;

        int numValuesToFetch = (rand() % 10) + 1;  // Randomly select a subset of values to fetch
        double* fetchedValues = (double*)malloc(numValuesToFetch * sizeof(double));

        // Fetch a random subset of values based on the probability threshold
        for (int j = 0; j < numValuesToFetch; j++) {
            if (rand() % 100 > probabilityThreshold) {
                fetchDoubleValue(&i, &fetchedValues[j]);  // Fetch default value if failure occurs
            } else {
                fetchDoubleValue(&i, &fetchedValues[j]);
            }
        }

        records[i]->values = fetchedValues;
        records[i]->numValues = numValuesToFetch;
    }

    return records;
}

// Function to free memory allocated for the record collection
void freeRecords(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i] != NULL) {
            free(records[i]->values);
            free(records[i]);
        }
    }

    free(records);
}

// Function to validate the integrity of the record collection
void validateRecords(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i] != NULL && records[i]->key >= 0 && records[i]->numValues > 0) {
            printf("Record %d: Key - %d, Values - %d\n", i, records[i]->key, records[i]->numValues);
        } else {
            printf("Error in record %d.\n", i);
        }
    }
}

int main() {
    int numRecords = 5;
    int minKey = 1;
    int maxKey = 10;
    int probabilityThreshold = 50;

    // Initialize and validate the record collection
    Record** records = initRecords(numRecords, minKey, maxKey, probabilityThreshold, NULL);
    validateRecords(records, numRecords);

    // Free memory allocated for the record collection
    freeRecords(records, numRecords);

    return 0;
}
