    struct Record* records = (struct Record*)malloc(size * sizeof(struct Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int* keys = (int*)malloc(max_keys * sizeof(int));
    for (int i = 0; i < max_keys; i++) {
        keys[i] = i + 1;
    }
    srand(time(NULL));

    long* offsets = (long*)malloc(size * sizeof(long));
    int* ids = (int*)malloc(size * sizeof(int));

    if (!offsets || !ids) {
        free(records);
        free(keys);
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i].timestamp = time(NULL) * 1000 + i;
        ids[i] = rand() % max_keys;
        while (keys[ids[i]]-- > 0) {
            ids[i] = rand() % max_keys;
        }
        keys[ids[i]]++;
        sprintf(records[i].data, "Record %d", i);
    }

    free(offsets);
    free(keys);

    return records;
}

void deallocate(void* ptr) {
    if (ptr) {
        struct Record* records = ptr;
        free(records);
    }
}
