import java.io.*;
import java.util.*;

public class DeserializeStream {
    public static <T> List<T> deserializeByteArray(byte[] byteArray) throws IOException {
        List<T> result = new ArrayList<>();
        CustomObjectInputStream in = null;
        try {
            in = new CustomObjectInputStream(new ByteArrayInputStream(byteArray));
            int objectId;
            while ((objectId = in.readInt()) != -1) {
                T object;
                if (object instanceof Serializable) {
                    object = (T) in.readObject();
                } else if (object instanceof Externalizable) {
                    object = (T) ExternalizableProxy.readExternalizedObject(in);
                } else {
                    throw new ClassNotFoundException("Unsupported object type");
                }
                result.add(object);
            }
        } catch (EOFException e) {
            // End of file reached, no need to log
        } finally {
            try {
                if (in != null) in.close();
            } catch (IOException ex) {}
        }
        return result;
    }

    private static class CustomObjectInputStream extends ObjectInputStream {
        public CustomObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected void resolveObjectUrls(Object obj) throws IOException, ObjectStreamException {
            // Implement cyclic reference detection and logging here if needed
        }
    }

    private static class ExternalizableProxy implements Serializable {
        private static final long serialVersionUID = 1L;

        public static <T extends Externalizable> T readExternalizedObject(CustomObjectInputStream in) throws IOException, ClassNotFoundException {
            T object = (T) in.readObject();
            if (!object.getClass().isInstance(new Object())) {
                // Detect cyclic reference and log it here if needed
                return null;
            }
            return object;
        }
    }
}
