// Define the custom data structure for network interface configuration settings
typedef struct {
    char *interface_name;
    char *ip_address;
    char *subnet_mask;
    int num_ports;
    char **port_configs;
} ConfigSettings;

// Define a dynamic array to store multiple configurations
typedef struct {
    int size;
    ConfigSettings *config_array;
} ConfigArray;

ConfigArray *create_config_array() {
    ConfigArray *array = (ConfigArray *)malloc(sizeof(ConfigArray));
    array->size = 0;
    array->config_array = NULL;
    return array;
}

void add_config(ConfigArray *array, char *interface_name, char *ip_address, char *subnet_mask) {
    // Allocate memory for a new configuration
    ConfigSettings *new_config = (ConfigSettings *)malloc(sizeof(ConfigSettings));
    new_config->interface_name = interface_name;
    new_config->ip_address = ip_address;
    new_config->subnet_mask = subnet_mask;
    new_config->num_ports = 0;
    new_config->port_configs = NULL;

    // Reallocate the array to accommodate the new configuration
    array->config_array = (ConfigSettings *)realloc(array->config_array, (array->size + 1) * sizeof(ConfigSettings));
    array->config_array[array->size] = new_config;
    array->size++;
}

void remove_config(ConfigArray *array, int index) {
    // Check for out-of-bounds access
    if (index >= array->size || index < 0) {
        printf("Error: Invalid configuration index\n");
        return;
    }

    // Remove the configuration at the specified index
    free(array->config_array[index]->port_configs);
    free(array->config_array[index]);
    memmove(&array->config_array[index], &array->config_array[index + 1], (array->size - index - 1) * sizeof(ConfigSettings));
    array->size--;
}

void update_config(ConfigArray *array, int index, char *new_interface_name, char *new_ip_address, char *new_subnet_mask) {
    // Check for out-of-bounds access
    if (index >= array->size || index < 0) {
        printf("Error: Invalid configuration index\n");
        return;
    }

    // Update the configuration at the specified index
    free(array->config_array[index]->port_configs);
    free(array->config_array[index]);
    ConfigSettings *new_config = (ConfigSettings *)malloc(sizeof(ConfigSettings));
    new_config->interface_name = new_interface_name;
    new_config->ip_address = new_ip_address;
    new_config->subnet_mask = new_subnet_mask;
    new_config->num_ports = 0;
    new_config->port_configs = NULL;

    array->config_array[index] = new_config;
}

void free_config_array(ConfigArray *array) {
    for (int i = 0; i < array->size; i++) {
        free(array->config_array[i]->port_configs);
        free(array->config_array[i]);
    }
    free(array->config_array);
    free(array);
}
