// Function to add a new network interface configuration
void add_interface(char* name, char* ip_address, char* subnet_mask) {
    NetworkInterface* new_interface = malloc(sizeof(NetworkInterface));
    if (new_interface == NULL) {
        perror("Error allocating memory");
        return;
    }

    new_interface->name = strdup(name);
    new_interface->ip_address = strdup(ip_address);
    new_interface->subnet_mask = strdup(subnet_mask);
    new_interface->num_ports = 0;
    new_interface->ports = NULL;
    new_interface->status = 'A'; // Initialize to active

    if (interfaces == NULL) {
        interfaces = new_interface;
    } else {
        NetworkInterface* temp = interfaces;
        while (temp != NULL && temp->name != NULL) {
            temp = temp->next;
        }
        temp->next = new_interface;
    }

    num_interfaces++;
}

// Function to remove a network interface configuration
void remove_interface(char* name) {
    if (interfaces == NULL || interfaces->name == NULL) return;

    NetworkInterface* current = interfaces;
    while (current != NULL && current->name != NULL) {
        if (strcmp(current->name, name) == 0) {
            // Find and remove the interface from the linked list
            if (current->next != NULL) {
                NetworkInterface* temp = current;
                current = current->next;
                free(temp);
            } else {
                interfaces = current->next;
            }

            num_interfaces--;
            return;
        }

        current = current->next;
    }
}

