// Define the record structure
typedef struct {
    int key;
    int value;
} record;

// Define the function to dynamically allocate memory for records
record** init_records(int num_records, int max_key, int range) {
    // Calculate the total number of records considering 10% overhead for metadata
    int total_records = num_records + (num_records / 10);

    // Allocate memory for the record array and its metadata
    record** records = (record**)malloc(total_records * sizeof(record*));
    if (!records) {
        printf("Failed to allocate memory for record array.\n");
        return NULL;
    }

    // Initialize the key and value arrays
    int* keys = (int*)malloc(total_records * sizeof(int));
    if (!keys) {
        free(records);
        printf("Failed to allocate memory for key array.\n");
        return NULL;
    }
    int* values = (int*)malloc(total_records * sizeof(int));
    if (!values) {
        free(keys);
        free(records);
        printf("Failed to allocate memory for value array.\n");
        return NULL;
    }

    // Initialize the record metadata and set initial values
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < total_records; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            printf("Failed to allocate memory for a single record.\n");
            free(keys);
            free(values);
            free(records);
            return NULL;
        }
        keys[i] = rand() % max_key + 1; // Random key
        values[i] = (rand() % range) - (range / 2); // Random value within the specified range

        // Initialize the record
        records[i]->key = keys[i];
        records[i]->value = values[i];
    }

    // Purge old records periodically
    int purge_threshold = num_records * 0.5;
    pthread_t purge_thread;
    pthread_create(&purge_thread, NULL, purge_records, (void*)records);
    pthread_join(purge_thread);

    return records;
}

// Define the function to purge old records
void* purge_records(void* arg) {
    record** records = (record**)arg;

    while (1) {
        // Calculate the timestamp of the oldest record
        int oldest_timestamp = time(NULL);

        // Iterate through the records and remove those older than the threshold
        for (int i = 0; i < num_records; i++) {
            if ((records[i]->key * 10000 + values[i]) <= oldest_timestamp) {
                free(records[i]);
                records[i] = NULL;
            }
        }

        // Sleep for a certain period before purging again
        sleep(5);
    }
}
