#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a record structure
typedef struct {
    int value;
    long* offset_ptr;
} record;

// Function to manage memory allocation and initialization for multiple data structures
record** init_records(int n, int seed) {
    // Calculate the total allocated size based on n and limit it to 1 MB
    int total_size = sizeof(record*) * n + (n * sizeof(long)) + (n * sizeof(int));
    if(total_size > 1024*1024) {
        printf("Error: Total allocation size exceeds 1MB.\n");
        return NULL;
    }

    // Allocate memory for an array of int integers
    int* keys = (int*)malloc(n * sizeof(int));

    // Initialize the record structure with random value and offset pointer
    record** records = (record**)malloc(n * sizeof(record));
    for(int i=0; i<n; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = rand_r(&seed) % 1000 + 1;
        records[i]->offset_ptr = (long*)malloc(sizeof(long));
    }

    // Initialize the keys array
    for(int i=0; i<n; i++) {
        keys[i] = rand_r(&seed) % n;
    }

    // Return a pointer to the dynamically allocated array of record structures
    return records;
}

// Function to free all allocated memory
void free_records(record** records, int n) {
    for(int i=0; i<n; i++) {
        if(records[i]) {
            free(records[i]->offset_ptr);
            free(records[i]);
        }
    }
    free(records);
}

// Function to reset the data structures without freeing memory
void reset_records(record** records, int n) {
    for(int i=0; i<n; i++) {
        if(records[i]) {
            records[i]->value = rand_r(&seed) % 1000 + 1;
            *records[i]->offset_ptr = (long)i;
        }
    }
}

// Function to deallocate memory when the last reference is destroyed
void record_destructor(record** records, int n) {
    free_records(records, n);
}

// Example code snippet demonstrating how to safely use the function in multi-threaded environments
int main() {
    int n = 10;
    int seed = time(NULL);

    pthread_t thread1, thread2;

    // Initialize the record structures in separate threads
    record** records1 = init_records(n, seed);
    record** records2 = (record**)malloc(n * sizeof(record));
    for(int i=0; i<n; i++) {
        records2[i] = (record*)malloc(sizeof(record));
    }

    // Perform thread-safe operations on the record structures
    pthread_create(&thread1, NULL, (void*(*)(void*))init_records, n);
    pthread_create(&thread2, NULL, (void*(*)(void*))reset_records, &records2, n);

    // Deallocate memory when the last reference is destroyed
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);
    record_destructor(records1, n);

    return 0;
}
