const CONFIG_FILE_NAME: &str = "config.json";

struct Config {
    allowed_dirs: Vec<String>,
}

impl Config {
    fn new() -> Self {
        let config_file_path = Path::new(CONFIG_FILE_NAME);
        let mut file = match fs::File::open(&config_file_path) {
            Ok(file) => file,
            Err(_) => return Config { allowed_dirs: vec![] },
        };
        let contents = match file.read_to_string() {
            Ok(contents) => contents,
            Err(_) => return Config { allowed_dirs: vec![] },
        };
        serde_json::from_str(&contents).unwrap_or(Config { allowed_dirs: vec![] })
    }
}

fn get_config() -> Arc<Config> {
    let config = Config::new();
    Arc::new(config)
}

struct DirLocker {
    lock_id: AtomicUsize,
}

impl DirLocker {
    fn new() -> Self {
        DirLocker { lock_id: AtomicUsize::new(0) }
    }

    fn acquire_lock(&self, dir_path: &Path) -> bool {
        let mut i = self.lock_id.fetch_add(1, Ordering::Relaxed);
        for _ in 0..10 {
            if i % 2 == 0 {
                match fs::metadata(dir_path) {
                    Ok(_) => return false,
                    Err(_) => break,
                }
            } else {
                // wait for a bit
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        true
    }

    fn release_lock(&self, dir_path: &Path) {
        self.lock_id.fetch_sub(1, Ordering::Relaxed);
    }
}

fn main() {
    let config = get_config();
    let dir_path = PathBuf::from("my_dir");
    if !config.allowed_dirs.iter().any(|allowed_dir| allowed_dir == dir_path.file_name().unwrap().to_string_lossy()) {
        warn!("Invalid directory name or path provided.");
        return;
    }
    if DirLocker { lock_id: AtomicUsize::new(0) }.acquire_lock(&dir_path) {
        info!("Acquired lock on the directory");
        // create the directory
        match fs::create_dir_all(dir_path.clone()) {
            Ok(_) => {
                info!("Directory created successfully");
            }
            Err(err) => warn!("Failed to create directory: {}", err),
        };
    } else {
        warn!("Failed to acquire lock on the directory. Directory might have been created by another process.");
    }

    if let Some(current_dir_path) = env::var(ENV_VAR_NAME).ok() {
        if current_dir_path == dir_path.as_path().to_string_lossy() {
            info!("Environment variable already set with the correct path");
        } else {
            warn!("Environment variable is set with an outdated path. Updating the environment variable...");
            env::set_var(ENV_VAR_NAME, dir_path.as_path().to_string_lossy());
        }
