typedef struct {
    int id;
    double value;
    float* weights;
    struct task* head;
} Job;

// Define the structure for task
typedef struct task {
    Job* job;
    struct task* next;
} Task;

Job* setupDataProcessingPipeline(int numJobs, int seed) {
    // Initialize memory for jobs and tasks
    Job* jobs = (Job*)malloc(numJobs * sizeof(Job));
    Task* head = NULL;
    Task* tail = NULL;

    // Initialize random number generator
    srand(seed);

    // Initialize job properties
    for (int i = 0; i < numJobs; i++) {
        jobs[i].id = rand();
        jobs[i].value = (double)i;
        jobs[i].weights = (float*)malloc(10 * sizeof(float));
        for (int j = 0; j < 10; j++) {
            jobs[i].weights[j] = (float)(i + j);
        }
    }

    // Initialize task dependencies
    for (int i = 0; i < numJobs; i++) {
        Task* newTask = (Task*)malloc(sizeof(Task));
        newTask->job = &jobs[i];
        if (tail == NULL) {
            head = newTask;
            tail = newTask;
        } else {
            tail->next = newTask;
            tail = newTask;
        }
    }

    return jobs;
}

