void* readThread(void* arg);
void* writeThread(void* arg);

int main() {
    int maxFileSize = MAX_FILE_SIZE;
    int numThreads = 4; // adjust according to system resources

    pthread_t threads[numThreads];
    FileNode* fileNodes = (FileNode*)malloc(numThreads * sizeof(FileNode));

    for(int i = 0; i < numThreads; i++) {
        fileNodes[i].data = NULL;
        fileNodes[i].size = 0;

        pthread_create(&threads[i], NULL, readThread, &fileNodes[i]);
    }

    // wait for all threads to finish
    for(int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(fileNodes);

    return 0;
}

FileNode* fileProcessingManager(int maxFileSize, int numThreads) {
    // initialize memory structures
    FileNode* fileNodes = (FileNode*)malloc(numThreads * sizeof(FileNode));

    for(int i = 0; i < numThreads; i++) {
        fileNodes[i].data = NULL;
        fileNodes[i].size = 0;
    }

    return fileNodes;
}

void* readThread(void* arg) {
    FileNode* fileNode = (FileNode*)arg;

    // read from file and store in linked list
    FILE* file = fopen("example.txt", "r");
    if(file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    while(fgets(buffer, BUFFER_SIZE, file)) {
        // process line
        printf("%s", buffer);

        // update linked list
        if(fileNode->size >= maxFileSize) {
            // implement overflow handling
            perror("File size exceeded");
            exit(EXIT_FAILURE);
        }
        fileNode->data = (char*)realloc(fileNode->data, fileNode->size + strlen(buffer) + 1);
        strcat(fileNode->data, buffer);
        fileNode->size += strlen(buffer);
    }

    fclose(file);

    return NULL;
}

void* writeThread(void* arg) {
    FileNode* fileNode = (FileNode*)arg;

    // write to file
    FILE* file = fopen("output.txt", "w");
    if(file == NULL) {
        perror("Error opening output file");
        exit(EXIT_FAILURE);
    }

    fwrite(fileNode->data, 1, fileNode->size, file);

    fclose(file);

    return NULL;
}
