void add_data_unit(double data, char info) {
    DataUnit* new_unit = (DataUnit*)malloc(sizeof(DataUnit));
    if (!new_unit) {
        printf("Memory error: unable to allocate memory for new unit.\n");
        return;
    }

    new_unit->data = data;
    new_unit->info = info;
    new_unit->next = NULL;

    if (!head) { // If the list is empty, make this the head
        head = new_unit;
    } else {
        DataUnit* current = head;
        while (current->next) {
            current = current->next; // Move to the last unit in the list
        }
        current->next = new_unit; // Add the new unit after the last one
    }
}

void traverse_and_print() {
    DataUnit* current = head;
    printf("Data units:\n");
    while (current) {
        printf("  Data: %f, Info: '%c'\n", current->data, current->info);
        current = current->next;
    }
}

void free_data_units() {
    DataUnit* current = head;
    DataUnit* next_unit;

    while (current) {
        next_unit = current->next;
        free(current); // Free the current unit
        current = next_unit; // Move to the next unit
    }
}
