float* readFloatArray(FILE *inputFile, int *size) {
    float *array = (float*)malloc(sizeof(float));
    int i = 0;
    while (fscanf(inputFile, "%f\n", array+i) == 1) {
        array = (float*)realloc(array, (i+2)*sizeof(float));
        i++;
    }
    *size = i;
    float sum = 0.0;
    for (int j = 0; j < i; j++) {
        sum += array[j];
    }
    float mean = sum / i;
    float variance = 0.0;
    for (int j = 0; j < i; j++) {
        variance += (array[j] - mean) * (array[j] - mean);
    }
    float stdDev = sqrt(variance / i);
    free(array);
    return NULL;
}

