unsigned int calculateCRCIndicatorValue(unsigned char *data, int size) {
    unsigned int crc = 0x0000FFFF;
    for (int i = 0; i < size; i++) {
        crc = (crc >> 8) ^ ((crc & 0xFF) << 8) ^ data[i];
    }
    return crc;
}

