            printf("Error: Identifiers not unique.\n");
            return;
        }
        // Validate the CRC indicator value
        unsigned int crcIndicatorValue = calculateCRCIndicatorValue((unsigned char*)pduList[i]->data, pduList[i]->size);
        if (crcIndicatorValue != pduList[i]->crcIndicatorValue) {
            printf("Error: CRC indicator value not valid.\n");
            return;
        }
    }
}

// Function to check for unique identifiers
int checkForUniqueIdentifiers(unsigned int *identifiers, int size) {
    for (int i = 0; i < size; i++) {
        if (findIdentifier(identifiers[i], &identifiers)) {
            printf("Error: Identifiers not unique.\n");
            return 1;
        }
    }
    return 0;
}

// Function to find an identifier in the array
int findIdentifier(unsigned int identifier, unsigned int *identifiers, int size) {
    for (int i = 0; i < size; i++) {
        if (identifiers[i] == identifier) {
            return i;
        }
    }
    return -1;
}
