        fseek(file, 0, SEEK_END);
        size_t fileSize = ftell(file);
        rewind(file);

        buffer* bufferToWrite = &buffers[i];
        bufferToWrite->buffer = malloc(bufferLength);
        fread(bufferToWrite->buffer, 1, fileSize, file);
