        cache[i]->expiration_time = 3600; // Example expiration time in seconds
        cache[i]->usage_stats = 1;
    }
}

// Function to invalidate expired entries and clean up unused entries from the recently_used list
void manage_cache(cache_entry** cache, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        // Check if an entry has expired
        if (cache[i]->expiration_time <= 0) {
            free(cache[i]->data); // Free memory allocated for the data
