package com.example.mostrythemanager;

import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.zip.DataFormatException;

public class MoSTStateLoader {
    private static final String DEFAULT_THEME_DIR = "default_theme_dir";
    private static final int BUFFER_SIZE = 4096;
    private static final ConcurrentMap<String, MoSTState> themeCache = new ConcurrentHashMap<>();
    private static final ThemeService themeService = new ThemeService();

    public static MoSTState loadMoSTStateFromBinaryFile(String filePath) {
        try (InputStream is = new FileInputStream(filePath)) {
            if (!is.available() > 0) {
                return null;
            }
            ObjectInput in = new ObjectInputStream(new BufferedInputStream(is, BUFFER_SIZE));
            MoSTState state = (MoSTState) in.readObject();
            in.close();
            is.close();

            // Validate the loaded object
            if (!(state instanceof MoSTState)) {
                return null;
            }

            // Load theme data from external service or local cache
            String themeName = state.getThemeName();
            MoSTState cachedState = themeCache.putIfAbsent(themeName, state);
            if (cachedState != null) {
                state = cachedState; // Use the cached state instead of reloading
            } else {
                try {
                    // Load theme data from external service
                    Bitmap themeBitmap = themeService.getThemeBitmap(themeName);
                    if (themeBitmap != null) {
                        state.setThemeBitmap(themeBitmap);
                    }
                } catch (Exception e) {
                    logger.error("Failed to load theme bitmap: " + e.getMessage());
                }
            }

            return state;
        } catch (IOException | DataFormatException e) {
            logger.error("Failed to load MoSTState from binary file: " + e.getMessage());
            return null;
        }
    }
}
