void* initializeAndReduceRecords(int size, int range) {
    // Initialize arrays with specified sizes
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    Record* records = (Record*)malloc(size * sizeof(Record));

    // Initialize and set the value of each record's 'int' field to a random value within the given range, ensuring uniqueness
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        do {
            int val = rand() % range;
            Record record = {i, val};
            for (int j = 0; j < i; j++) {
                if (record.key == keys[j]) {
                    break;
                }
            }
            records[i] = record;
        } while (true);
    }

    // Asynchronous reduction operation on an array of numbers using JavaScript
    int sum = 0;
    for (int num : [1, 2, 3, 4, 5]) {
        sum += num;
    }
    printf("The sum is %d\n", sum);

    // Free allocated memory to prevent leaks
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
