#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a struct for each data structure field type
typedef struct {
    int int_field;
} IntField;

typedef struct {
    float float_field;
} FloatField;

typedef struct {
    double double_field;
} DoubleField;

typedef struct {
    char char_field[1024];
} CharField;

// Define a struct to represent a single record
typedef struct {
    IntField* int_fields;
    FloatField* float_fields;
    DoubleField* double_fields;
    CharField* char_fields;
    int num_fields;
} Record;

// Function to dynamically allocate and initialize a flexible number of data structures
Record* create_record(int num_int_fields, int num_float_fields, int num_double_fields, int num_char_fields) {
    // Allocate memory for the record structure
    Record* record = (Record*) malloc(sizeof(Record));

    if (!record) {
        return NULL;
    }

    // Allocate memory for the fields
    record->int_fields = (IntField*) malloc(num_int_fields * sizeof(IntField));
    record->float_fields = (FloatField*) malloc(num_float_fields * sizeof(FloatField));
    record->double_fields = (DoubleField*) malloc(num_double_fields * sizeof(DoubleField));
    record->char_fields = (CharField*) malloc(num_char_fields * sizeof(CharField));

    if (!record->int_fields || !record->float_fields || !record->double_fields || !record->char_fields) {
        free(record);
        return NULL;
    }

    // Initialize the fields
    record->num_int_fields = num_int_fields;
    record->num_float_fields = num_float_fields;
    record->num_double_fields = num_double_fields;
    record->num_char_fields = num_char_fields;

    return record;
}

// Function to free the memory allocated for a record
void free_record(Record* record) {
    if (record) {
        // Free the fields
        free(record->int_fields);
        free(record->float_fields);
        free(record->double_fields);
        free(record->char_fields);

        // Free the record structure
        free(record);
    }
}

// Function to create a new record and add it to an existing list of records
void add_record_to_list(Record** record_list, int* num_records) {
    // Create a new record with default values (0 for ints, 0.0 for floats, etc.)
    Record* new_record = create_record(5, 3, 2, 1);

    if (!new_record) {
        return;
    }

    // Add the new record to the list
    (*num_records)++;
    *record_list = (Record*) realloc(*record_list, (*num_records) * sizeof(Record));

    if (*record_list) {
        (*record_list)[*num_records - 1] = new_record;
    } else {
        free(new_record);
    }
}

int main() {
    // Initialize an empty list of records
    Record* record_list = NULL;
    int num_records = 0;

    // Add some records to the list
    add_record_to_list(&record_list, &num_records);
    add_record_to_list(&record_list, &num_records);
    add_record_to_list(&record_list, &num_records);

    // Free the memory allocated for each record
    for (int i = 0; i < num_records; i++) {
        free_record(record_list[i]);
    }

    // Free the list of records itself
    free(record_list);

    return 0;
}
