void processAndAnalyzeNetworkTraffic(int num_input_streams) {
    // Initialize statistics and memory tracking
    double total_packets = 0.0;
    double avg_packet_size = 0.0;
    int protocol_freq[256] = {0};
    size_t min_packet_size = SIZE_MAX, max_packet_size = 0;

    // Allocate memory for packet headers and payloads
    PacketHeader** packets = (PacketHeader**)malloc(num_input_streams * sizeof(PacketHeader*));
    void** payload_data = (void**)malloc(num_input_streams * sizeof(void*));

    pthread_mutex_init(&memory_usage_lock, NULL);
    int memory_usage = 0;

    // Process input streams concurrently
    pthread_t threads[num_input_streams];
    for (int i = 0; i < num_input_streams; i++) {
        packets[i] = (PacketHeader*)malloc(sizeof(PacketHeader));
        payload_data[i] = malloc(1024); // Initialize with a reasonable size
        pthread_create(&threads[i], NULL, processStream, &packets[i]);
    }

    // Wait for all threads to finish and calculate statistics
    for (int i = 0; i < num_input_streams; i++) {
        pthread_join(threads[i], NULL);
        total_packets += packets[i]->payload_size;
        avg_packet_size += packets[i]->payload_size;
        protocol_freq[atoi(packets[i]->protocol)]++;
        if (packets[i]->payload_size < min_packet_size) min_packet_size = packets[i]->payload_size;
        if (packets[i]->payload_size > max_packet_size) max_packet_size = packets[i]->payload_size;

        free(packets[i]);
        free(payload_data[i]);
    }

    // Calculate and log statistics
    avg_packet_size /= total_packets;
    printf("Total packets: %f\n", total_packets);
