#include <stdint.h>
#include <time.h>

typedef enum {
    TCP,
    UDP,
    ICMP
} ProtocolType;

struct PacketHeader {
    ProtocolType protocol;
    uint32_t src_ip, dst_ip;
    int payload_size;
};

void manage_packet_headers(int num_headers, size_t pool_size) {
    // Initialize memory pool for efficient allocation
    void* memory_pool = malloc(pool_size);
    if (!memory_pool) {
        printf("Failed to allocate memory pool.\n");
        return;
    }

    struct PacketHeader** packet_headers = (struct PacketHeader**)malloc(num_headers * sizeof(struct PacketHeader*));
    if (!packet_headers) {
        free(memory_pool);
        printf("Failed to allocate packet headers.\n");
        return;
    }

    // Initialize packet headers with random data
    srand(time(NULL));
    for (int i = 0; i < num_headers; i++) {
        struct PacketHeader* header = (struct PacketHeader*)malloc(sizeof(struct PacketHeader));
        if (!header) {
            printf("Failed to allocate packet header.\n");
            return;
        }

        header->protocol = (ProtocolType)(rand() % 3);
        header->src_ip = rand() % UINT32_MAX;
        header->dst_ip = rand() % UINT32_MAX;
        header->payload_size = rand() % INT_MAX;

        // Store packet headers in memory pool
        size_t offset = i * sizeof(struct PacketHeader);
        memcpy((char*)memory_pool + offset, &header, sizeof(struct PacketHeader));
    }

    // Print initialized packet headers for debugging
    printf("Packet Headers:\n");
    for (int i = 0; i < num_headers; i++) {
        struct PacketHeader* header = (struct PacketHeader*)((char*)memory_pool + i * sizeof(struct PacketHeader));
        printf("Protocol: %s, Source IP: 0x%X, Destination IP: 0x%X, Payload Size: %d\n",
               header->protocol == TCP ? "TCP" : (header->protocol == UDP ? "UDP" : "ICMP"),
               header->src_ip, header->dst_ip, header->payload_size);
    }

    // Free memory pool and packet headers
    for (int i = 0; i < num_headers; i++) {
        free((struct PacketHeader*)((char*)memory_pool + i * sizeof(struct PacketHeader)));
    }
    free(memory_pool);
}
