    char* ip_address;
    char* subnet_mask;
    int num_ports;
    struct {
        char* port_name;
        // Add more port configuration fields as needed
    } ports[];
} NetworkConfig;

// Define a struct to represent the dynamic array of network configurations
typedef struct {
    NetworkConfig* configs;
    int capacity;
    int size;
} NetworkConfigArray;

NetworkConfigArray* network_config_array_new(int initial_capacity) {
    NetworkConfigArray* arr = malloc(sizeof(NetworkConfigArray));
    arr->configs = malloc(initial_capacity * sizeof(NetworkConfig));
    arr->capacity = initial_capacity;
    arr->size = 0;
    return arr;
}

void network_config_array_free(NetworkConfigArray* arr) {
    if (arr == NULL) return;
    for (int i = 0; i < arr->size; i++) {
        free(arr->configs[i].name);
        free(arr->configs[i].ip_address);
        free(arr->configs[i].subnet_mask);
        // Free port configuration arrays
    }
    free(arr->configs);
    free(arr);
}

void network_config_array_add(NetworkConfigArray* arr, NetworkConfig* config) {
    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        arr->configs = realloc(arr->configs, arr->capacity * sizeof(NetworkConfig));
    }
    arr->configs[arr->size] = *config;
    arr->size++;
}

void network_config_array_remove(NetworkConfigArray* arr, int index) {
    if (index >= arr->size || index < 0) return; // Handle out-of-bounds error
    memmove(&arr->configs[index], &arr->configs[index + 1], (arr->size - index - 1) * sizeof(NetworkConfig));
