    int* keys = NULL;
    long* offsets = NULL;

    while (true) {
        size_t new_size = sizeof(long) * 2; // Initial capacity
        if ((offsets = reallocate(&offsets, &new_size)) == NULL) {
            return; // Memory allocation failed
        }

        new_size = sizeof(int) * 2;
        if ((keys = reallocate(&keys, &new_size)) == NULL) {
            log_error("Memory allocation failed");
            safe_free(offsets);
            return; // Memory allocation failed
        }
    }
