import java.util.*;
import java.io.*;

public class ProcessAndTransformData {

    public static void processAndTransformData(int size) {
        Map<String, List<Map.Entry<String, Integer>>> nestedMap = new HashMap<>();

        for (int i = 0; i < size; i++) {
            String key = "map" + i;
            nestedMap.putIfAbsent(key, new ArrayList<>());

            Random random = new Random();
            for (int j = 0; j < 10; j++) { // assuming 10 entries per map
                String identifier = "id" + j;
                Integer value = random.nextInt(100); // random value between 0-99

                Map.Entry<String, Integer> entry = new AbstractMap.SimpleEntry<>(identifier, value);
                nestedMap.get(key).add(entry);

                validateIntegrity(nestedMap);
            }
        }
    }

    private static void validateIntegrity(Map<String, List<Map.Entry<String, Integer>>> nestedMap) {
        for (String key : nestedMap.keySet()) {
            Set<String> identifiers = new HashSet<>();

            for (Map.Entry<String, Integer> entry : nestedMap.get(key)) {
                if (!identifiers.add(entry.getKey())) {
                    System.out.println("Error: Duplicate identifier found in map " + key);
                    return;
                }
            }
        }
    }

    public static void main(String[] args) {
        processAndTransformData(5); // example usage with size 5
    }
}
