    for (int i = 0; i < size; i++) {
        if (strcmp(interfaces[i]->name, name) == 0) {
            // Shift all elements after the removed element one position to the left
            memmove(&interfaces[i], &interfaces[i + 1], sizeof(NetworkInterface*) * (size - i));
            break;
        }
