// Function to process and filter data
void processAndFilterData(int numPoints, FILE* file) {
    // Allocate memory for arrays
    DataPoint* points = malloc(numPoints * sizeof(DataPoint));
    long* offsets = malloc((numPoints + 1) * sizeof(long));
    int* keys = malloc(numPoints * sizeof(int));
    Record* records = malloc(numPoints * sizeof(Record));

    // Initialize pointers and indices
    int i, j;
    for (i = 0; i < numPoints; i++) {
        points[i].measurement = 0.0;
        points[i].timestamp = 0;
        points[i].description = NULL;
        offsets[i] = 0;
        keys[i] = 0;
        records[i].value = 0;
    }
    offsets[numPoints] = 0;

    // Read data from file and store in arrays
    for (i = 0; i < numPoints; i++) {
        fscanf(file, "%lf %d %s", &points[i].measurement, &points[i].timestamp, points[i].description);
        j = i;
        while (keys[j] == 0) {
            keys[j] = i;
            i++;
        }
    }

    // Release allocated memory
    free(points);
    free(offsets);
    free(keys);
    free(records);
}
