typedef struct {
    int key;
    float value;
    char status;
    int* offset;
} Record;

typedef struct {
    Record* records;
    int numRecords;
    int maxKey;
} Database;

void initDatabase(Database* db, int recordCount) {
    db->numRecords = recordCount;
    db->records = (Record*)malloc(recordCount * sizeof(Record));

    for(int i = 0; i < recordCount; i++) {
        db->records[i].key = rand() % ((1 << 31) - 1); // Generate random key within 32-bit range
        db->records[i].value = (float)rand() / RAND_MAX; // Random float value between 0 and 1
        db->records[i].status = 'N'; // Initialize status flag as "Not Found"

        int offsetIndex = rand() % recordCount;
        while(db->records[offsetIndex].offset != NULL) {
            offsetIndex = rand() % recordCount;
        }
        db->records[i].offset = &db->records[offsetIndex].key; // Validate offset index and assign pointer
    }
}

void databaseLog(Database* db, char action) {
    printf("Database %s: numRecords=%d, maxKey=%d\n", action == 'i' ? "initialized" : "modified", db->numRecords, db->maxKey);

    for(int i = 0; i < db->numRecords; i++) {
        printf("%d: key=%d, value=%.2f, status='%c', offset=0x%08X\n", i, db->records[i].key, db->records[i].value, db->records[i].status, (unsigned int)db->records[i].offset);
    }
}

Database* createDatabase(int recordCount) {
    Database* db = (Database*)malloc(sizeof(Database));
    initDatabase(db, recordCount);

    return db;
}
