    // Dynamically allocate memory for arrays
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    if (!records || !offsets || !keys) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize and populate the arrays
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 100; // Random value within range [0, 99]
        offsets[i] = (long)i * 2 + 1;
        keys[i] = i;
    }

    return (void*)records;
}

// Function to compute the MD5 hash of a string
void* compute_md5_hash(char* str) {
    // Initialize MD5 context and calculate the hash
    md5_context ctx;
    md5_init(&ctx);
    md5_update(&ctx, str, strlen(str));
    char* hash = (char*)malloc(16 * sizeof(char)); // 128-bit hash requires 16 bytes
    md5_finish(&ctx, hash);

    return (void*)hash;
}

// Function to persist the initialized data using an external data management system
