#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000000 // Maximum number of records
#define HASH_TABLE_SIZE 1024   // Hash table size (power of 2)

typedef struct {
    long offset;
    int key;
    double value;
} Record;

Record* recordArray = NULL;     // Array of records
unsigned long hashTable[HASH_TABLE_SIZE] = {0};  // Hash table

void initDatabase() {
    if ((recordArray = (Record*)malloc(MAX_RECORDS * sizeof(Record))) == NULL) {
        printf("Error: Memory allocation failed for record array.\n");
        return;
    }

    memset(recordArray, 0, MAX_RECORDS * sizeof(Record));
}

int insertRecord(int key, long offset, double value) {
    int index = key % HASH_TABLE_SIZE;  // Calculate hash table index

    while (hashTable[index] != 0 && hashTable[index] != key) {
        // Handle collisions using open addressing
        index = (index + 1) % HASH_TABLE_SIZE;
    }

    recordArray[key].offset = offset;
    recordArray[key].key = key;
    recordArray[key].value = value;

    return 0;  // Successful insertion
}

double findRecord(int key) {
    int index = key % HASH_TABLE_SIZE;

    while (hashTable[index] != 0 && hashTable[index] != key) {
        index = (index + 1) % HASH_TABLE_SIZE;
    }

    if (recordArray[key].key == key)
        return recordArray[key].value;  // Found the record
    else
        return -1.0;  // Record not found
}

int deleteRecord(int key) {
    int index = key % HASH_TABLE_SIZE;

    while (hashTable[index] != 0 && hashTable[index] != key) {
        index = (index + 1) % HASH_TABLE_SIZE;
    }

    if (recordArray[key].key == key)
        recordArray[key] = (Record){0};  // Mark the record as deleted
    else
        return -1;  // Record not found

    return 0;  // Successful deletion
}

int main() {
    initDatabase();

    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % HASH_TABLE_SIZE;
        long offset = rand() % 10000;
        double value = (double)rand() / RAND_MAX;

        insertRecord(key, offset, value);
    }

    // Perform lookups and deletions
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % HASH_TABLE_SIZE;
        double value = findRecord(key);

        if (value != -1.0) {
            printf("Found record: key=%d, offset=%ld, value=%.2f\n", key, recordArray[key].offset, value);
        } else
            printf("Record not found: key=%d\n", key);

        deleteRecord(key);
    }

    free(recordArray);  // Release memory

    return 0;
}
