#define MAX_NICS 256
#define DEFAULT_LOSS 0.5f
#define DEFAULT_THROUGHPUT 1000.f
#define DEFAULT_LATENCY 10.f

typedef struct {
    float packet_loss;
    float throughput;
    float latency;
} NICStats;

typedef struct {
    int num_nics;
    NICStats *stats[MAX_NICS];
} NICStatsArray;

NICStatsArray* nic_stats_init() {
    NICStatsArray* arr = (NICStatsArray*)malloc(sizeof(NICStatsArray));
    arr->num_nics = 0;
    for(int i=0; i<MAX_NICS; i++) {
        arr->stats[i] = NULL;
    }
    return arr;
}

void nic_stats_free(NICStatsArray* arr) {
    for(int i=0; i<arr->num_nics; i++) {
        if(arr->stats[i]) free(arr->stats[i]);
    }
    free(arr);
}

int nic_stats_add(NICStatsArray* arr, int nic_idx, float packet_loss, float throughput, float latency) {
    if(arr->num_nics >= MAX_NICS) return -1; // Array full
    NICStats* stats = (NICStats*)malloc(sizeof(NICStats));
    stats->packet_loss = packet_loss;
    stats->throughput = throughput;
    stats->latency = latency;
    arr->stats[arr->num_nics++] = stats;
    return 0;
}

int nic_stats_sort(NICStatsArray* arr, int (*cmp)(const void*, const void*)) {
    qsort(arr->stats, arr->num_nics, sizeof(NICStats*), cmp);
    return 0;
}

int nic_stats_filter(NICStatsArray* arr, float min_throughput, float max_latency) {
    for(int i=0; i<arr->num_nics; i++) {
        NICStats* stats = arr->stats[i];
        if(stats && (stats->throughput < min_throughput || stats->latency > max_latency)) {
            free(stats);
            memmove(&arr->stats[i], &arr->stats[i+1], sizeof(NICStats*) * (arr->num_nics - i));
            arr->num_nics--;
            i--;
        }
    }
    return 0;
}

int nic_stats_clear(NICStatsArray* arr, int nic_idx) {
    for(int i=0; i<arr->num_nics; i++) {
        if(arr->stats[i] && i == nic_idx) {
            free(arr->stats[i]);
            memmove(&arr->stats[i], &arr->stats[i+1], sizeof(NICStats*) * (arr->num_nics - i));
            arr->num_nics--;
            return 0;
        }
    }
    return -1; // NIC not found
}

// Example comparison function for sorting
int compare_stats(const void* a, const void* b) {
    NICStats* stats_a = *(NICStats**)a;
    NICStats* stats_b = *(NICStats**)b;
    if(stats_a->packet_loss > stats_b->packet_loss) return 1;
    if(stats_a->packet_loss < stats_b->packet_loss) return -1;
    return 0;
}
