typedef struct {
    int id;
    int priority;
    time_t due_date;
    char status[20];
} Task;

// Node of linked list for task collection
typedef struct Node {
    Task task;
    struct Node* next;
} Node;

// Task management system structure
typedef struct {
    Node* head; // Head of the linked list
    int size; // Current size of the task collection
} TaskSystem;

// Function to create a new task node
Node* createTaskNode(Task task) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }
    newNode->task = task;
    newNode->next = NULL;
    return newNode;
}

// Function to add a new task to the system
void addTask(TaskSystem* system, Task task) {
    Node* newNode = createTaskNode(task);
    if (!system->head) { // If the list is empty, set the head
        system->head = newNode;
    } else {
        Node* current = system->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }
    system->size++;
}

// Function to remove a task by its ID
void removeTask(TaskSystem* system, int id) {
    if (!system->head) return; // If the list is empty, exit

    Node* current = system->head;
    Node* prev = NULL;
    while (current && current->task.id != id) {
        prev = current;
        current = current->next;
    }
    if (!current) return; // Task not found

    if (prev) {
        prev->next = current->next;
    } else {
        system->head = current->next;
    }
    free(current);
    system->size--;
}

// Function to retrieve a task by its status
Task* getTaskByStatus(TaskSystem* system, char* status) {
    Node* current = system->head;
    while (current) {
        if (!strcmp(current->task.status, status)) {
            return &current->task;
        }
        current = current->next;
    }
    return NULL; // Task not found
}

