    time_t expiration_time;
    char *authorized_resources[10];
    char *security_profile;
} Session;

#define MAX_RECORDS 100
#define MAX_SESSIONS 1000

typedef struct {
    Record records[MAX_RECORDS];
    int record_count;
    Session sessions[MAX_SESSIONS];
    int session_count;
    pthread_mutex_t mutex;
} Database;

Database* initialize_database() {
    Database *db = (Database*)malloc(sizeof(Database));
    db->record_count = 0;
    db->session_count = 0;
    pthread_mutex_init(&db->mutex, NULL);
    return db;
}

void insert_record(Database *db, Record record) {
    pthread_mutex_lock(&db->mutex);
    if (db->record_count < MAX_RECORDS) {
        db->records[db->record_count] = record;
        db->record_count++;
    }
    pthread_mutex_unlock(&db->mutex);
}

Record* find_record(Database *db, int key) {
    pthread_mutex_lock(&db->mutex);
    for (int i = 0; i < db->record_count; i++) {
        if (db->records[i].key == key) {
            Record* record = &db->records[i];
            pthread_mutex_unlock(&db->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&db->mutex);
    return NULL;
}

void delete_record(Database *db, int key) {
    pthread_mutex_lock(&db->mutex);
    for (int i = 0; i < db->record_count; i++) {
        if (db->records[i].key == key) {
            memmove(&db->records[i], &db->records[i + 1], (db->record_count - i - 1) * sizeof(Record));
            db->record_count--;
            break;
        }
    }
    pthread_mutex_unlock(&db->mutex);
}

Session* create_session(Database *db, int user_id, time_t login_time, time_t expiration_time) {
    Session *session = (Session*)malloc(sizeof(Session));
    session->session_id = rand();
    session->user_id = user_id;
    session->login_time = login_time;
    session->expiration_time = expiration_time;
    return session;
}

void insert_session(Database *db, Session *session) {
    pthread_mutex_lock(&db->mutex);
    if (db->session_count < MAX_SESSIONS) {
        db->sessions[db->session_count] = session;
        db->session_count++;
    }
    pthread_mutex_unlock(&db->mutex);
}

Session* find_session(Database *db, int user_id) {
    pthread_mutex_lock(&db->mutex);
    for (int i = 0; i < db->session_count; i++) {
        if (db->sessions[i]->user_id == user_id) {
            Session* session = &db->sessions[i];
            pthread_mutex_unlock(&db->mutex);
            return session;
        }
    }
    pthread_mutex_unlock(&db->mutex);
    return NULL;
}

void delete_session(Database *db, int user_id) {
    pthread_mutex_lock(&db->mutex);
    for (int i = 0; i < db->session_count; i++) {
        if (db->sessions[i]->user_id == user_id) {
            memmove(&db->sessions[i], &db->sessions[i + 1], (db->session_count - i - 1) * sizeof(Session));
            db->session_count--;
            break;
