import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class DynamicDataManager {
    private Lock lock = new ReentrantLock();
    private Condition condition = lock.newCondition();

    private long[] offsets;
    private int[] keys;
    private recordRecord[] records;

    public void init(int offsetSize, int keySize, int recordSize) {
        offsets = new long[offsetSize];
        keys = new int[keySize];
        records = new recordRecord[recordSize];

        // Initialize the data structures
        for (int i = 0; i < offsetSize; i++) {
            offsets[i] = i;
        }
        for (int i = 0; i < keySize; i++) {
            keys[i] = i;
        }
    }

    public void addRecord(int recordIndex, long offset, int key) {
        lock.lock();
        try {
            // Validate the data before committing changes
            if (offsets.length <= recordIndex || keys.length <= recordIndex) {
                throw new RuntimeException("Invalid record index");
            }

            records[recordIndex] = new recordRecord(offset, key);

            // Notify other threads that a new record has been added
            condition.signal();
        } finally {
            lock.unlock();
        }
    }

    public void removeRecord(int recordIndex) {
        lock.lock();
        try {
            if (records.length <= recordIndex) {
                throw new RuntimeException("Invalid record index");
            }

            // Reclaim memory for the removed record
            records[recordIndex] = null;

            // Notify other threads that a record has been removed
            condition.signal();
        } finally {
            lock.unlock();
        }
    }

    public void processRecords() {
        lock.lock();
        try {
            while (true) {
                if (!hasRecords()) {
                    break;
                }

                // Process the records
                for (recordRecord record : records) {
                    // Perform operations on the record data
                }

                // Wait for new records to be added or removed
                condition.await();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            lock.unlock();
        }
    }

    public boolean hasRecords() {
        lock.lock();
        try {
            return Arrays.stream(records).anyMatch(Objects::nonNull);
        } finally {
            lock.unlock();
        }
    }

    // Custom record type implementation
    public static class recordRecord {
        private long offset;
        private int key;

        public recordRecord(long offset, int key) {
            this.offset = offset;
            this.key = key;
        }

        public long getOffset() {
            return offset;
        }

        public int getKey() {
            return key;
        }
    }
}
