#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define MAX_MESSAGES 100000
#define MAX_THREADS 10

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t buffer_not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t buffer_full = PTHREAD_COND_INITIALIZER;
int message_count = 0;
NFAPI_CRC_INDICATION_PDU_T *buffer[MAX_MESSAGES];
int buffer_index = 0;
int buffer_size = 0;

void *producer_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&buffer_lock);
        if (buffer_size == MAX_MESSAGES) {
            pthread_cond_signal(&buffer_full);
        } else {
            NFAPI_CRC_INDICATION_PDU_T *message;
            message = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Initialize message fields
            message->rx_ue_info.tag = rand();
            message->rnti = (int)rand();
            message->crc_indication_rel8.tag = rand();
            message->crcflag = rand() % 2;
            buffer[buffer_index] = message;
            buffer_index = (buffer_index + 1) % MAX_MESSAGES;
            message_count++;
            pthread_cond_signal(&buffer_not_empty);
        }
        pthread_mutex_unlock(&buffer_lock);
    }
    return NULL;
}

void *consumer_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&buffer_lock);
        while (message_count == 0) {
            pthread_cond_wait(&buffer_not_empty, &buffer_lock);
        }
        if (message_count > 0) {
            NFAPI_CRC_INDICATION_PDU_T *message = buffer[0];
            // Process message
            free(message);
            buffer_size--;
            buffer_index = (buffer_index + 1) % MAX_MESSAGES;
            message_count--;
            pthread_cond_signal(&buffer_full);
        }
        pthread_mutex_unlock(&buffer_lock);
    }
    return NULL;
}

void init_buffer() {
    for (int i = 0; i < MAX_MESSAGES; i++) {
        buffer[i] = NULL;
    }
    pthread_create(NULL, NULL, producer_thread, NULL);
    pthread_create(NULL, NULL, consumer_thread, NULL);
}

void free_buffer() {
    pthread_mutex_lock(&buffer_lock);
    while (message_count > 0) {
        pthread_cond_wait(&buffer_full, &buffer_lock);
    }
    for (int i = 0; i < MAX_MESSAGES; i++) {
        if (buffer[i] != NULL) {
            free(buffer[i]);
        }
    }
    message_count = 0;
    buffer_size = 0;
    pthread_mutex_unlock(&buffer_lock);
}

void process_messages() {
    // Initialize and start the thread pool
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, consumer_thread, NULL);
    }

    // Start processing messages
    while (message_count > 0) {
        // Wait for messages to be processed
    }

    // Stop and join the threads
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
}
