#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTERFACES 1000
#define MAX_PORTS 10
#define MAX_SECURITY_PROFILES 5

typedef struct {
    char interface_name[16];
    char ip_address[16];
    char subnet_mask[16];
    int num_ports;
    struct {
        int port_number;
        char protocol[4]; // (TCP, UDP, etc.)
    } ports[MAX_PORTS];
    int num_security_profiles;
    struct {
        char algorithm[8]; // (AES, Camellia, etc.)
        char hash_function[4]; // (MD5, SHA, etc.)
        char digital_signature[3]; // (RSA, etc.)
    } security_profiles[MAX_SECURITY_PROFILES];
} NetworkInterfaceConfig;

NetworkInterfaceConfig *interface_configs;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void add_interface_config(const char *interface_name, const char *ip_address, 
                           const char *subnet_mask, int num_ports, int num_security_profiles) {
    pthread_mutex_lock(&config_lock);

    // Allocate memory for the new interface configuration
    NetworkInterfaceConfig *new_config = (NetworkInterfaceConfig *)malloc(sizeof(NetworkInterfaceConfig));
    if (!new_config) {
        perror("Memory allocation failed");
        return;
    }

    strcpy(new_config->interface_name, interface_name);
    strcpy(new_config->ip_address, ip_address);
    strcpy(new_config->subnet_mask, subnet_mask);
    new_config->num_ports = num_ports;
    for (int i = 0; i < num_ports; i++) {
        // Initialize ports and security profiles
        new_config->ports[i].port_number = 0;
        strcpy(new_config->ports[i].protocol, "");

        if (i < num_security_profiles) {
            strcpy(new_config->security_profiles[i].algorithm, "");
            strcpy(new_config->security_profiles[i].hash_function, "");
            strcpy(new_config->security_profiles[i].digital_signature, "");
        }
    }

    new_config->num_security_profiles = num_security_profiles;

    pthread_mutex_unlock(&config_lock);
}

void remove_interface_config(const char *interface_name) {
    pthread_mutex_lock(&config_lock);

    // Find and free the memory of the interface configuration to be removed
    for (int i = 0; i < MAX_INTERFACES; i++) {
        if (!strcmp(interface_configs[i].interface_name, interface_name)) {
            free(interface_configs[i]);
            memmove(&interface_configs[i], &interface_configs[i + 1], sizeof(NetworkInterfaceConfig) * (MAX_INTERFACES - i - 1));
            break;
        }
    }

    pthread_mutex_unlock(&config_lock);
}

void update_interface_config(const char *interface_name, const char *ip_address, 
                             const char *subnet_mask, int num_ports, int num_security_profiles) {
    pthread_mutex_lock(&config_lock);

    // Find the interface configuration to be updated
    for (int i = 0; i < MAX_INTERFACES; i++) {
        if (!strcmp(interface_configs[i].interface_name, interface_name)) {
            strcpy(interface_configs[i].ip_address, ip_address);
            strcpy(interface_configs[i].subnet_mask, subnet_mask);
            interface_configs[i].num_ports = num_ports;
            for (int j = 0; j < num_ports; j++) {
                // Update ports and security profiles
                interface_configs[i].ports[j].port_number = 0;
                strcpy(interface_configs[i].ports[j].protocol, "");

                if (j < num_security_profiles) {
                    strcpy(interface_configs[i].security_profiles[j].algorithm, "");
                    strcpy(interface_configs[i].security_profiles[j].hash_function, "");
                    strcpy(interface_configs[i].security_profiles[j].digital_signature, "");
                }
            }

            interface_configs[i].num_security_profiles = num_security_profiles;
            break;
        }
    }

    pthread_mutex_unlock(&config_lock);
}

void manage_interface_configurations() {
    // Initialize the list of interface configurations
    interface_configs = (NetworkInterfaceConfig *)malloc(sizeof(NetworkInterfaceConfig) * MAX_INTERFACES);
    if (!interface_configs) {
        perror("Memory allocation failed");
        return;
    }

    for (int i = 0; i < MAX_INTERFACES; i++) {
        // Initialize ports and security profiles
        interface_configs[i].num_ports = 0;
        interface_configs[i].num_security_profiles = 0;

        for (int j = 0; j < MAX_PORTS; j++) {
            interface_configs[i].ports[j].port_number = 0;
            strcpy(interface_configs[i].ports[j].protocol, "");

            if (j < MAX_SECURITY_PROFILES) {
                strcpy(interface_configs[i].security_profiles[j].algorithm, "");
                strcpy(interface_configs[i].security_profiles[j].hash_function, "");
                strcpy(interface_configs[i].security_profiles[j].digital_signature, "");
            }
        }
    }
}

int main() {
    manage_interface_configurations();

    // Test the functions
    add_interface_config("eth0", "192.168.1.100", "255.255.255.0", 2, 1);
    update_interface_config("eth0", "192.168.1.101", "255.255.255.0", 3, 2);
    remove_interface_config("eth0");

    return 0;
}
