#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000
#define MAX_DESCRIPTIONS 500
#define MIN_TRANSACTION_VALUE 10.0f
#define MAX_TRANSACTION_VALUE 1000.0f
#define DESC_MIN_LENGTH 5
#define DESC_MAX_LENGTH 20

void processAndSortData(int numTransactions, const char* dataFile) {
    // Initialize arrays for transactions and descriptions
    double* transactions = (double*)malloc(numTransactions * sizeof(double));
    char** descriptions = (char**)malloc(MAX_DESCRIPTIONS * sizeof(char*));

    if (!transactions || !descriptions) {
        // Handle memory allocation failure
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }

    // Initialize arrays with specified sizes
    for (int i = 0; i < numTransactions; i++) {
        transactions[i] = (double)(rand() % (MAX_TRANSACTION_VALUE - MIN_TRANSACTION_VALUE)) + MIN_TRANSACTION_VALUE;
    }

    FILE* file = fopen(dataFile, "r");
    if (!file) {
        // Handle file opening failure
        printf("Failed to open file '%s'. Exiting...\n", dataFile);
        exit(1);
    }

    // Read descriptions from the file
    int descriptionIndex = 0;
    char buffer[DESC_MAX_LENGTH + 1];
    while (fgets(buffer, sizeof(buffer), file)) {
        buffer[strcspn(buffer, "\n")] = '\0';  // Remove trailing newline
        descriptions[descriptionIndex++] = strdup(buffer);
    }

    fclose(file);

    // Validate transaction data consistency
    for (int i = 0; i < numTransactions; i++) {
        if (strcmp(descriptions[i], "") == 0) {
            printf("Error: Empty description found.\n");
            exit(1);
        }
    }

    // Sort descriptions alphabetically
    qsort(descriptions, MAX_DESCRIPTIONS, sizeof(char*), compareDescriptions);

    // Log performance metrics and errors
    FILE* logFile = fopen("processAndSort.log", "a");
    if (logFile) {
        fprintf(logFile, "Transactions processed: %d\n", numTransactions);
        for (int i = 0; i < numTransactions; i++) {
            fprintf(logFile, "Transaction %d: %.2f - %s\n", i + 1, transactions[i], descriptions[i]);
        }
        fclose(logFile);
    }

    // Release allocated memory
    free(transactions);
    for (int i = 0; i < MAX_DESCRIPTIONS; i++) {
        free(descriptions[i]);
    }
    free(descriptions);

    printf("Data processing complete.\n");
}

int compareDescriptions(const void* a, const void* b) {
    return strcmp(*(char**)a, *(char**)b);
}
