    char *tags;
} EventTypeConfig;

typedef struct {
    pthread_mutex_t lock;
    void **event_type_configs;
    size_t num_event_types;
    size_t pool_size;
    void *pool;
} LoggingFramework;

void *create_memory_pool(size_t size) {
    return malloc(size);
}

void destroy_memory_pool(void *pool, size_t size) {
    free(pool);
}

LoggingFramework *initialize_logging_framework() {
    LoggingFramework *logging_framework = (LoggingFramework *)malloc(sizeof(LoggingFramework));
    logging_framework->num_event_types = 0;
    logging_framework->pool_size = 1024;
    logging_framework->pool = create_memory_pool(logging_framework->pool_size);

    pthread_mutex_init(&logging_framework->lock, NULL);
    return logging_framework;
}

void configure_logging_framework(LoggingFramework *logging_framework, EventTypeConfig *event_type_config) {
    void **temp_pool = (void **)realloc(logging_framework->event_type_configs, (logging_framework->num_event_types + 1) * sizeof(void *));
    if (!temp_pool) {
        // Handle memory allocation error
        return;
    }
    logging_framework->event_type_configs = temp_pool;

    EventTypeConfig *new_config = (EventTypeConfig *)malloc(sizeof(EventTypeConfig));
    new_config->log_level = event_type_config->log_level;
    new_config->tags = strdup(event_type_config->tags);
    logging_framework->event_type_configs[logging_framework->num_event_types] = new_config;
    logging_framework->num_event_types++;

    // Periodic cleanup of unused event type configurations
    if (logging_framework->num_event_types > logging_framework->pool_size) {
        size_t i;
        for (i = 0; i < logging_framework->num_event_types; i++) {
            free((void *)logging_framework->event_type_configs[i]);
        }
        free(logging_framework->event_type_configs);
        logging_framework->event_type_configs = NULL;
        logging_framework->pool_size *= 2;
        logging_framework->pool = create_memory_pool(logging_framework->pool_size);
    }
}

void cleanup_logging_framework(LoggingFramework *logging_framework) {
    int i;
    for (i = 0; i < logging_framework->num_event_types; i++) {
        free((void *)logging_framework->event_type_configs[i]);
    }
    free(logging_framework->event_type_configs);
    destroy_memory_pool(logging_framework->pool, logging_framework->pool_size);
}

