    }

    printf("Task Schedules (%d):\n", collection->num_task_schedules);
    for (int i = 0; i < collection->num_task_schedules; i++) {
        printf("Priority Level: %d, Resource Allocations: ", collection->task_schedules[i]->priority_level);
        for (int j = 0; j < 3; j++) {
            printf("%d ", collection->task_schedules[i]->resource_allocations[j]);
        }
        printf(", Metadata Dependencies: %s, Task Management Metadata: %s\n", collection->task_schedules[i]->metadata_dependencies, collection->task_schedules[i]->task_management_metadata);
    }
}

// Function to version the collection
void version_collection(DynamicCollection *collection) {
    // Versioning logic here
}

int main() {
    DynamicCollection collection;

    // Initialize the collection
    collection.network_configs = NULL;
    collection.task_schedules = NULL;
    collection.num_network_configs = 0;
    collection.num_task_schedules = 0;

    // Add some configurations and schedules
    add_network_config(&collection, "eth0", "192.168.1.1", "255.255.255.0");
    add_network_config(&collection, "wlan0", "10.0.0.1", "255.255.255.0");
    add_task_schedule(&collection, 1, {1, 2, 3}, "dependencies.txt", "metadata.txt");

    // Print the collection
    print_collection(&collection);

    return 0;
}

