enum attackType { ATTACK_A, ATTACK_B };

struct actionRecord {
    long* valuePointer;
    int key;
    char description[20];
    attackType attackType;
    int cooldownTime;
};

struct gameSession {
    int numPlayers;
    long* playerOffsets;
    int* actionKeys;
    actionRecord** actionRecords;
};

void executeGameActions(const std::string& sessionLabel, const std::function<void()>& f, const std::shared_ptr<dataSource>& dataSource, int maxConcurrentTests, concurrencyManager& cm) {
    gameSession* session = new gameSession();

    // Initialize arrays
    session->numPlayers = 5;
    session->playerOffsets = new long[session->numPlayers];
    session->actionKeys = new int[session->numPlayers];

    // Fill player offsets and action keys
    for (int i = 0; i < session->numPlayers; i++) {
        session->playerOffsets[i] = static_cast<long>(i);
        session->actionKeys[i] = i % 2;
    }

    // Initialize action records
    session->actionRecords = new actionRecord*[session->numPlayers];

    for (int i = 0; i < session->numPlayers; i++) {
        actionRecord* record = new actionRecord();

        // Set description, attack type, and cooldown time
        record->description[0] = 'T';
        record->attackType = (i % 2 == 0) ? ATTACK_A : ATTACK_B;
        record->cooldownTime = rand() % 15 + 1;

        session->actionRecords[i] = record;
    }

    // Execute tests
    for (int i = 0; i < maxConcurrentTests; i++) {
        cm.addTask([&f, &session]() {
            f();
        });
    }

    // Clean up
    delete[] session->playerOffsets;
    delete[] session->actionKeys;
    delete[] session->actionRecords;

    delete session;

    std::cout << "Module: " << sessionLabel << ", Test: " << __func__ << std::endl;
}

