    if (index < 0 || index >= num_interfaces) {
        printf("Invalid index. Please try again.\n");
        return -1;
    }

    // Reallocate memory without the removed interface
    *interfaces = realloc(*interfaces, (num_interfaces - 1) * sizeof(network_interface));
    if (*interfaces == NULL) {
        printf("Memory reallocation failed.\n");
        return -1;
    }

    // Reset the number of interfaces
    num_interfaces--;

    return 0;
}

