DataItem* processAndTransformData(int dataSize, int logSize) {
    // Initialize a pointer for the data item array
    DataItem* dataItems = (DataItem*)malloc(dataSize * sizeof(DataItem));

    // Initialize a counter for the data item index
    int i;

    // Loop through each data item
    for (i = 0; i < dataSize; i++) {
        // Allocate memory for the log entry array
        dataItems[i].logEntries = (LogEntry**)malloc(logSize * sizeof(LogEntry*));

        // Initialize a counter for the log entry index
