Resource* resource_init(int id, char* name, size_t quota) {
    Resource* res = (Resource*)malloc(sizeof(Resource));
    res->id = id;
    res->name = (char*)malloc(strlen(name) + 1);
    strcpy(res->name, name);
    res->data = NULL;
    res->quota = quota;
    return res;
}

void resource_free(Resource* res) {
    if (!res)
        return;

    free(res->name);
    free(res);

    pthread_mutex_unlock(&res->mutex);
}

Resource* resource_create_nested(Resource* parent, char* name, size_t quota) {
    Resource* child = (Resource*)malloc(sizeof(Resource));
    child->id = parent->id * 2;
    child->name = (char*)malloc(strlen(name) + 1);
    strcpy(child->name, name);
    child->data = NULL;
    child->quota = quota;
    child->parent = parent;

    parent->children++;

    return child;
}

void resource_destroy_nested(Resource* node) {
    if (!node)
        return;

    Resource* current = node;
    while (current) {
        Resource* next = current->next;
        free(current->name);
        free(current);
        current = next;
    }
}

