```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_SIZE 1024

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void init_random_state() {
    srand(time(NULL));
}

bool is_valid_input(size_t N, size_t initialSize) {
    return N <= MAX_SIZE && initialSize > 0;
}

int manage_dynamic_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t *N, size_t initialSize) {
    if (!is_valid_input(*N, initialSize)) {
        return -1; // invalid input
    }

    *array = realloc(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * initialSize);
    if (*array == NULL) {
        return -2; // memory allocation failed
    }

    for (size_t i = 0; i < *N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &((*array)[i]);
        pdu->RX_UE_INFORMATION_TAG = (uint8_t) rand() % 256;
        pdu->RNTI = (uint16_t) rand() % 65536;
        pdu->CRC_INDICATION_REL8_TAG = (uint32_t) rand() % 4294967296;
        pdu->CRCFLAG = (rand() % 2 == 0); // at least one CRCFLAG set to true
    }

    size_t actualUsedSize = *N;
    while (*N > initialSize) {
        NFAPI_CRC_INDICATION_PDU_T* tempArray = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*N + 1));
        if (tempArray == NULL) {
            return -2; // memory allocation failed
        }
        free(*array);
        *array = tempArray;
        initialSize += 1;
    }

    for (size_t i = 0; i < actualUsedSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &((*array)[i]);
        if (pdu->RX_UE_INFORMATION_TAG > 255 || pdu->RNTI > 65535 || pdu->CRC_INDICATION_REL8_TAG > 4294967295) {
            return -3; // array contents invalid
        }
    }

    printf("Array size: %zu, initialSize: %zu\n", *N, initialSize);

    return 0;
}
