    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new interface status report to the dynamic list
void add_interface_status(InterfaceStatusList* list, char* id, int received_bytes, int packets, int errors) {
    pthread_mutex_lock(&list->lock);

    // Check if the list needs to be resized
    if (list->length >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        InterfaceStatus* new_interfaces = (InterfaceStatus*)realloc(list->interfaces, new_capacity * sizeof(InterfaceStatus));
        list->interfaces = new_interfaces;
        list->capacity = new_capacity;
    }

    // Create a new interface status report
    InterfaceStatus* new_status = (InterfaceStatus*)malloc(sizeof(InterfaceStatus));
    strcpy(new_status->id, id);
    new_status->received_bytes = received_bytes;
    new_status->packets = packets;
    new_status->errors = errors;
    new_status->packet_loss_percentage = 0.0; // calculate later

    // Add the new status report to the list
    list->interfaces[list->length] = new_status;
    list->length++;

    pthread_mutex_unlock(&list->lock);
}

// Filter the interface status reports based on a specified minimum threshold for packet loss percentage
void filter_interface_statuses(InterfaceStatusList* list, float min_packet_loss_percentage) {
    pthread_mutex_lock(&list->lock);

    // Iterate over the interface status reports and remove those with packet loss percentage below the threshold
    size_t i;
    for (i = 0; i < list->length; i++) {
        InterfaceStatus* current_status = &list->interfaces[i];
        if (current_status->packet_loss_percentage >= min_packet_loss_percentage) {
            // Keep the interface status report with packet loss percentage above the threshold
        } else {
            // Remove the interface status report with packet loss percentage below the threshold
            for (; i < list->length - 1; i++) {
                list->interfaces[i] = list->interfaces[i + 1];
            }
            list->length--;
            free(list->interfaces[list->length]);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Periodically update the interface statuses and ensure data consistency across multiple threads
void* periodic_update(void* arg) {
    InterfaceStatusList* list = (InterfaceStatusList*)arg;
    while (1) {
        // Update the interface statuses from the external monitoring service
        // ...

        // Calculate the packet loss percentage for each interface status report
        size_t i;
        for (i = 0; i < list->length; i++) {
            InterfaceStatus* current_status = &list->interfaces[i];
            float packet_loss_percentage = (float)current_status->errors / current_status->packets * 100.0;
            current_status->packet_loss_percentage = packet_loss_percentage;
        }

        // Ensure data consistency across multiple threads
        pthread_mutex_lock(&list->lock);
        list->length = i + 1; // Update the length of the interface status list
        pthread_mutex_unlock(&list->lock);

        // Simulate a delay in data retrieval from the external service
        usleep(1000); // wait for 1 second

    }
}

// Initialize and start the periodic update thread
void start_periodic_update(InterfaceStatusList* list) {
    pthread_t thread;
    pthread_create(&thread, NULL, periodic_update, (void*)list);
}

// Clean up resources when the program terminates
void clean_up_resources(InterfaceStatusList* list) {
    size_t i;
    for (i = 0; i < list->length; i++) {
        free(list->interfaces[i]);
    }
    free(list->interfaces);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    InterfaceStatusList* list = init_interface_status_list();

    // Add interface status reports
    add_interface_status(list, "eth0", 10000, 500, 10);
    add_interface_status(list, "wlan0", 20000, 1000, 20);

    // Filter the interface status reports based on a specified minimum threshold for packet loss percentage
    filter_interface_statuses(list, 5.0); // keep only interfaces with packet loss percentage above 5.0

    // Start the periodic update thread
    start_periodic_update(list);

    // Clean up resources when the program terminates
    clean_up_resources(list);

    return 0;
}

