    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
int pdu_count = 0;

// Function to manage the PDU list
void nfa_pi_crc_indication_pdu_list_mgmt(int cmd, void* param) {
    int i;
    char log_str[1024];

    // Validate command and parameter
    if (cmd < 1 || cmd > 3) {
        printf("Invalid command\n");
        return;
    }

    switch (cmd) {
        case 1: // Add PDU
            if (pdu_count >= MAX_PDU_COUNT) {
                printf("PDU list is full\n");
                return;
            }
            NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_pdu) {
                printf("Memory allocation failed\n");
                return;
            }
            memcpy(new_pdu, param, sizeof(NFAPI_CRC_INDICATION_PDU_T));

            // Check for duplicate RNTI
            for (i = 0; i < pdu_count; i++) {
                if (strcmp(((NFAPI_CRC_INDICATION_PDU_T*)pdus[i]).rnti, new_pdu->rnti) == 0) {
                    printf("Duplicate RNTI\n");
                    free(new_pdu);
                    return;
                }
            }

            // Add PDU to the list
            pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (pdu_count + 1));
            if (!pdus) {
                printf("Memory allocation failed\n");
                return;
            }
            pdus[pdu_count] = *new_pdu;
            pdu_count++;

            // Log the operation
            sprintf(log_str, "Added PDU with RNTI %s", new_pdu->rnti);
            printf("%s\n", log_str);

            break;

        case 2: // Remove PDU
            int index_to_remove = (int)param;
            if (index_to_remove < 0 || index_to_remove >= pdu_count) {
                printf("Invalid PDU index\n");
                return;
            }

            // Update the list and free memory for removed PDU
            pdus[index_to_remove] = pdus[pdu_count - 1];
            pdus[pdu_count - 1].rnti[0] = '\0'; // Mark as removed
            pdu_count--;

            // Log the operation
            sprintf(log_str, "Removed PDU at index %d", index_to_remove);
            printf("%s\n", log_str);

            break;

        case 3: // Update CRC flag for a specific PDU
            int pdu_index = (int)param;
            if (pdu_index < 0 || pdu_index >= pdu_count) {
                printf("Invalid PDU index\n");
                return;
            }

            pdus[pdu_index].crcflag = *(CRCFLAG*)param;

            // Log the operation
            sprintf(log_str, "Updated CRC flag for PDU at index %d", pdu_index);
            printf("%s\n", log_str);

            break;
    }
}

int main() {
    // Initialize logging framework
    // ...

    nfa_pi_crc_indication_pdu_list_mgmt(1, &pdus[0]); // Add a new PDU
    nfa_pi_crc_indication_pdu_list_mgmt(2, 0); // Remove the first PDU
    nfa_pi_crc_indication_pdu_list_mgmt(3, &pdus[0].crcflag); // Update CRC flag

    return 0;
}
