```java
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class TaskManager {

    private List<TaskSchedule> taskSchedules = new CopyOnWriteArrayList<>();
    private static final String TASK_SEPARATOR = ",";

    public void addTask(String taskData) {
        try {
            TaskSchedule task = parseTaskData(taskData);
            taskSchedules.add(task);
        } catch (InvalidTaskDataException e) {
            System.out.println("Error adding task: " + e.getMessage());
        }
    }

    public void removeTask(int taskId) {
        taskSchedules.removeIf(task -> task.getTaskId() == taskId);
    }

    public void updateTask(int taskId, String taskData) {
        try {
            TaskSchedule task = parseTaskData(taskData);
            taskSchedules.set(taskSchedules.indexOf(new TaskSchedule(taskId)), task);
        } catch (InvalidTaskDataException e) {
            System.out.println("Error updating task: " + e.getMessage());
        }
    }

    public List<TaskSchedule> getTaskSchedules() {
        return taskSchedules;
    }

    private TaskSchedule parseTaskData(String taskData) throws InvalidTaskDataException {
        String[] dataParts = taskData.split(TASK_SEPARATOR);
        if (dataParts.length != 4) {
            throw new InvalidTaskDataException("Invalid task data format");
        }
        int taskId = Integer.parseInt(dataParts[0]);
        long dueDate = Long.parseLong(dataParts[1]);
        int priorityLevel = Integer.parseInt(dataParts[2]);
        String resourceAllocations = dataParts[3];
        return new TaskSchedule(taskId, dueDate, priorityLevel, resourceAllocations);
    }
}
