typedef struct {
    int entityId;
    char** linkStatuses;
    double latencyMetric;
} NetworkEntityStatus;

// Define the number of entities and links to initialize
#define INITIAL_ENTITY_COUNT 1000
#define INITIAL_LINK_STATUS_COUNT 5

// Initialize a dynamic array of NetworkEntityStatus structures
void* allocateNetworkEntities(int count) {
    return calloc(count, sizeof(NetworkEntityStatus));
}

// Calculate the overall network latency based on aggregated metrics
double calculateOverallLatency(NetworkEntityStatus** entities, int entityCount) {
    double totalLatency = 0;
    for (int i = 0; i < entityCount; i++) {
        totalLatency += entities[i]->latencyMetric;
    }
    return totalLatency / entityCount;
}

// Add a new network entity with its associated link statuses and latency metric
void addNetworkEntity(NetworkEntityStatus** entities, int* entityCount, int entityId, char** linkStatuses, double latencyMetric) {
    NetworkEntityStatus* newEntity = (NetworkEntityStatus*)malloc(sizeof(NetworkEntityStatus));
    newEntity->entityId = entityId;
    newEntity->linkStatuses = linkStatuses;
    newEntity->latencyMetric = latencyMetric;

    // Handle potential network partitioning by skipping missing data
    if (entities[*entityCount] != NULL) {
        free(entities[(*entityCount)++]);
    }

    entities[(*entityCount)++] = newEntity;
}

// Update the latency metric of an existing network entity
void updateLatencyMetric(NetworkEntityStatus** entities, int entityCount, int entityId, double newLatencyMetric) {
    for (int i = 0; i < entityCount; i++) {
        if (entities[i]->entityId == entityId) {
            entities[i]->latencyMetric = newLatencyMetric;
            break;
        }
    }
}

// Calculate the average latency over a specific time interval
double calculateAverageLatency(NetworkEntityStatus** entities, int entityCount, double timeInterval) {
    double totalLatency = 0;
    for (int i = 0; i < entityCount; i++) {
        totalLatency += entities[i]->latencyMetric * timeInterval;
    }
    return totalLatency / (entityCount * timeInterval);
}

// Initialize a concurrent-safe list to manage network entities
void initializeEntityList(pthread_rwlock_t* lock) {
    pthread_rwlock_init(lock, NULL);
}

// Clean up resources upon thread exit
void cleanup(void* entity) {
    free(entity);
}

// Define the number of threads for concurrent updates and calculations
#define THREAD_COUNT 4

int main() {
    // Initialize the dynamic array of network entities
    NetworkEntityStatus** entities = (NetworkEntityStatus**)allocateNetworkEntities(INITIAL_ENTITY_COUNT);

    // Initialize the lock for concurrent access to the entity list
    pthread_rwlock_t lock;
    initializeEntityList(&lock);

    // Add new network entities with their associated link statuses and latency metrics
    for (int i = 0; i < INITIAL_ENTITY_COUNT; i++) {
        char* linkStatuses[] = {"Link1", "Link2"};
        addNetworkEntity(entities, &i, i + 1, linkStatuses, i * 10.5);
    }

    // Perform concurrent updates and calculations
    pthread_t threads[THREAD_COUNT];
    for (int i = 0; i < THREAD_COUNT; i++) {
        pthread_create(&threads[i], NULL, &updateLatencyMetric, entities);
    }

    // Calculate the overall network latency based on aggregated metrics
    double averageLatency = calculateAverageLatency(entities, INITIAL_ENTITY_COUNT, 10.5);

    // Clean up resources
    for (int i = 0; i < THREAD_COUNT; i++) {
        pthread_join(threads[i], NULL);
    }

    free(entities);
    pthread_rwlock_destroy(&lock);
}
