void* manage_memory(int offset_size, int key_size, int record_count, int min_value, int max_value, int parallelize_threads, int limit_threads) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));
    record* records = (record*)malloc(record_count * sizeof(record));

    // Initialize arrays
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = i;
    }

    // Initialize records with random values
    pthread_t threads[parallelize_threads];
    int thread_count = record_count / parallelize_threads + ((record_count % parallelize_threads) ? 1 : 0);
    for (int t = 0; t < thread_count; t++) {
        int start = t * parallelize_threads;
        int end = (t == thread_count - 1) ? record_count : (start + parallelize_threads);
        pthread_create(&threads[t], NULL, init_records, &records[start]);
