    int numEntries = 10; // configurable data source size
    double* doubles = (double*)initMemory(numEntries * sizeof(double));
    char* chars = (char*)initMemory(numEntries * sizeof(char));
    entry* entries = (entry*)initMemory(numEntries * sizeof(entry));

    // Initialize arrays with example values
    for (int i = 0; i < numEntries; i++) {
        doubles[i] = i;
        chars[i] = 'A' + i % 26;
        entries[i].d = i;
        entries[i].c = chars[i];
        entries[i].i = i * 2;
