#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    int value;
} record_t;

// Hash table structure
typedef struct {
    record_t** records;
    int capacity;
    int size;
} hash_table_t;

// Function to initialize and manage the hash table
hash_table_t* hash_table_init(int initial_capacity) {
    hash_table_t* table = (hash_table_t*)malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->records = (record_t**)calloc(initial_capacity, sizeof(record_t*));
    if (!table->records) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;

    return table;
}

// Function to insert a record into the hash table
int hash_table_insert(hash_table_t* table, int key, int value) {
    int index = key % table->capacity;
    while (table->records[index]) {
        // Linear probing for collision resolution
        index = (index + 1) % table->capacity;
    }

    table->records[index] = (record_t*)malloc(sizeof(record_t));
    if (!table->records[index]) return -1; // Memory allocation failure

    table->records[index]->key = key;
    table->records[index]->value = value;

    table->size++;

    // Resizing logic: double the capacity when 75% full
    if (table->size > (table->capacity * 3) / 4) {
        hash_table_t* new_table = hash_table_init(table->capacity * 2);
        if (!new_table) return -1; // Memory allocation failure

        for (int i = 0; i < table->capacity; i++) {
            record_t* record = table->records[i];
            while (record) {
                int new_index = record->key % new_table->capacity;
                record_t* next_record = new_table->records[new_index];
                while (next_record) {
                    // Linear probing for collision resolution
                    new_index = (new_index + 1) % new_table->capacity;
                    next_record = new_table->records[new_index];
                }

                new_table->records[new_index] = record;
                table->records[i] = record = record->next;
            }
        }

        free(table);
        table = new_table;
    }

    return 0; // Success
}

// Function to iterate over all records and print their key-value pairs
void hash_table_iterate(hash_table_t* table) {
    for (int i = 0; i < table->capacity; i++) {
        record_t* record = table->records[i];
        while (record) {
            printf("%d: %d\n", record->key, record->value);
            record = record->next;
        }
    }
}

// Function to free the hash table and its records
void hash_table_free(hash_table_t* table) {
    for (int i = 0; i < table->capacity; i++) {
        record_t* record = table->records[i];
        while (record) {
            record_t* next_record = record->next;
            free(record);
            record = next_record;
        }
    }

    free(table->records);
    free(table);
}
