int manage_arrays() {
    // Set initial memory limits based on system memory availability and expected processing load.
    long offsets_size = 0, keys_size = 0, total_records = 0;
    size_t total_memory_available = sysconf(_SC_PAGE_SIZE) * (sysconf(_SC_PHYS_PAGES));

    // Dynamically calculate array sizes based on user input, current system memory availability, and expected processing load.
    long heuristic_offsets_size = 1024; // Calculate using a suitable heuristic
    long heuristic_keys_size = 2048; // Calculate using a suitable heuristic

    if (heuristic_offsets_size > total_memory_available || heuristic_keys_size > total_memory_available) {
        // Handle out-of-memory error
        fprintf(stderr, "Insufficient memory available.\n");
        return -1;
    }

    offsets_size = heuristic_offsets_size;
    keys_size = heuristic_keys_size;

    // Calculate the number of record structures based on the sum of array sizes divided by a constant factor.
    total_records = (offsets_size + keys_size) / 8;

    // Allocate memory for arrays and record structures.
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    if (!(offsets = malloc(offsets_size * sizeof(long)))) {
        // Handle memory allocation error
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return -1;
    }

    if (!(keys = malloc(keys_size * sizeof(int)))) {
        // Handle memory allocation error
        free(offsets);
        return -1;
    }

    if (!(records = malloc(total_records * sizeof(record)))) {
        // Handle memory allocation error
        free(offsets);
        free(keys);
        return -1;
    }

    // Initialize record structures with random values.
    srand(time(NULL));
    for (int i = 0; i < total_records; i++) {
        records[i].value = rand() % 256;
    }

    // Ensure no two adjacent records have the same value.
    int prev_value = -1;
    for (int i = 0; i < total_records; i++) {
        while (records[i].value == prev_value) {
            records[i].value = rand() % 256;
        }
        prev_value = records[i].value;
