// Define the structure of a record
typedef struct {
    int key;
    int id;
    void* data; // dynamically allocated payload
} Record;

// Define the structure of the hash table node
typedef struct HashNode {
    Record* record;
    struct HashNode* next;
} HashNode;

// Define the hash table structure
typedef struct {
    int capacity;
    HashNode** buckets;
} HashTable;

// Function to initialize a new hash table with a given capacity
HashTable* hash_table_init(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->buckets = (HashNode**)malloc(capacity * sizeof(HashNode*));
    for (int i = 0; i < capacity; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

// Function to insert a new record into the hash table
void hash_table_insert(HashTable* table, Record* record) {
    int index = record->key % table->capacity;
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;
}

// Function to search for a record by its key in the hash table
Record* hash_table_search(HashTable* table, int key) {
    int index = key % table->capacity;
    HashNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->record->key == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

// Define the structure of a doubly linked list node
typedef struct DLLNode {
    Record* record;
    struct DLLNode* prev;
    struct DLLNode* next;
} DLLNode;

// Define the doubly linked list structure
typedef struct {
    int size;
    DLLNode* head;
    DLLNode* tail;
} DoublyLinkedList;

// Function to initialize a new doubly linked list
DoublyLinkedList* dll_init() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    return list;
}

// Function to insert a new record into the doubly linked list
void dll_insert(DoublyLinkedList* list, Record* record) {
    DLLNode* node = (DLLNode*)malloc(sizeof(DLLNode));
    node->record = record;
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        node->next = NULL;
        list->tail->next = node;
        list->tail = node;
    }
}

// Function to search for a record by its key in the doubly linked list
Record* dll_search(DoublyLinkedList* list, int key) {
    DLLNode* node = list->head;
    while (node != NULL) {
        if (node->record->key == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

// Function to purge inactive records from the dataset
void purge_inactive_records(HashTable* table, DoublyLinkedList* list) {
    // implementation details omitted for brevity
}

// Function to iterate over all records and print their keys and IDs
void iterate_records(HashTable* table, DoublyLinkedList* list) {
    // implementation details omitted for brevity
}

// Function to search for a specific record by its key
Record* search_record_by_key(HashTable* table, int key) {
    return hash_table_search(table, key);
}
