    set_record_values(records, 1, 10);

    return 0;
}

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && size < CHUNK_SIZE) {
        // Try to allocate in smaller chunks
        for (size_t i = size / 2; i > 0; i /= 2) {
            ptr = malloc(i * sizeof(void*));
            if (ptr) break;
        }
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

record_t* init_records(int m, int n) {
    record_t* records = (record_t*)my_malloc(m * RECORD_SIZE);
    if (!records) {
        // Manage excess records in a separate segment
        size_t excess_size = (m - n) * RECORD_SIZE;
        void* excess_ptr = my_malloc(excess_size);
        memcpy((void*)records + n * RECORD_SIZE, excess_ptr, excess_size);
        free(excess_ptr);
    }
    return records;
}

int set_record_values(record_t* records, int min_value, int max_value) {
    // Implement random number generation and record value assignment
    // ...
}

void log_memory_operation(const char* operation, void* ptr) {
    pthread_mutex_lock(&lock);
    fprintf(log_file, "%s: %p\n", operation, ptr);
    total_allocated_memory += RECORD_SIZE;
    pthread_mutex_unlock(&lock);
}

void rotate_log_file() {
    FILE* temp_file = tmpfile();
    if (temp_file) {
        fseek(temp_file, 0, SEEK_END);
        size_t bytes_written = ftell(log_file);
        fwrite(log_file, sizeof(char), bytes_written, temp_file);
        fclose(log_file);
        log_file = temp_file;
    }
}

void close_log_file() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}
