void initializeDatabase(int numOffsets, int numKeys) {
    // Dynamic memory allocation for arrays
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    if (!offsets) return; // Handle memory allocation failure

    int* keys = (int*)malloc(numKeys * sizeof(int));
    if (!keys) {
        free(offsets);
        return;
    }

    struct record* records = (struct record*)malloc(numKeys * sizeof(struct record));
    if (!records) {
        free(keys);
        free(offsets);
        return;
    }

    // Initialize arrays
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = i * 2; // Initialize with incrementing values
    }

    for (int i = 0; i < numKeys; i++) {
        keys[i] = i % 5; // Randomize key values
        records[i].value = rand() % 100; // Set record value to random number
        records[i].valuePointer = &offsets[rand() % numOffsets]; // Assign pointer within offsets array
    }

    // Validate integrity of records
    for (int i = 0; i < numKeys; i++) {
        for (int j = 0; j < i; j++) {
            if (records[i].value == records[j].value || records[i].valuePointer == &offsets[j]) {
                printf("Error: Duplicate record found!\n");
                return;
            }
        }
    }

    // Verify integrity
    printf("Database initialized successfully!\n");

    struct record* database = records; // Return the allocated memory

    // Release allocated memory when no longer needed
    free(keys);
    free(offsets);
    free(database);

    return;
}

int main() {
    int numOffsets, numKeys;

    // Read configuration file and initialize variables
    FILE* configFile = fopen("config.txt", "r");
    if (!configFile) {
        printf("Error: Unable to open configuration file!\n");
        return 1;
    }

    fscanf(configFile, "%d %d", &numOffsets, &numKeys);
    fclose(configFile);

    initializeDatabase(numOffsets, numKeys);

    return 0;
}
