import com.google.gson.Gson;
import com.google.gson.GsonBuilder;

public class SessionManager {
    private Map<String, Session> sessions = new ConcurrentHashMap<>();
    private File sessionFile;
    private RNTIService rntiService;

    public SessionManager(File sessionFile, RNTIService rntiService) {
        this.sessionFile = sessionFile;
        this.rntiService = rntiService;
    }

    public void addSession(String userId, String sessionToken, long expirationTimestamp, long lastActivityTimestamp, List<String> activeRequests) throws IOException {
        Session session = new Session(userId, sessionToken, expirationTimestamp, lastActivityTimestamp, activeRequests);
        sessions.put(sessionToken, session);

        // Serialize session data to JSON file
        Gson gson = new GsonBuilder().create();
        String json = gson.toJson(sessions);
        FileWriter writer = new FileWriter(sessionFile);
        writer.write(json);
        writer.close();

        // Allocate RNTI for NFAPI CRC indication PDU T structures
        rntiService.allocateRNTI(sessionToken, session.getActiveRequests());
    }

    public void removeSession(String sessionToken) {
        sessions.remove(sessionToken);

        // Update JSON file with removed session data
        Gson gson = new GsonBuilder().create();
        String json = gson.toJson(sessions);
        FileWriter writer = new FileWriter(sessionFile);
        writer.write(json);
        writer.close();

        // Release RNTI for NFAPI CRC indication PDU T structures
        rntiService.releaseRNTI(sessionToken);
    }

    public void updateSession(String sessionToken, String userId, long expirationTimestamp, long lastActivityTimestamp, List<String> activeRequests) {
        Session session = sessions.get(sessionToken);
        if (session != null) {
            session.setUserId(userId);
            session.setExpirationTimestamp(expirationTimestamp);
            session.setLastActivityTimestamp(lastActivityTimestamp);
            session.setActiveRequests(activeRequests);

            // Update JSON file with updated session data
            Gson gson = new GsonBuilder().create();
            String json = gson.toJson(sessions);
            FileWriter writer = new FileWriter(sessionFile);
            writer.write(json);
            writer.close();

            // Re-allocate RNTI for NFAPI CRC indication PDU T structures if necessary
            rntiService.updateRNTI(sessionToken, activeRequests);
        }
    }

    public class Session {
        private String userId;
        private String sessionToken;
        private long expirationTimestamp;
        private long lastActivityTimestamp;
        private List<String> activeRequests;

        public Session(String userId, String sessionToken, long expirationTimestamp, long lastActivityTimestamp, List<String> activeRequests) {
            this.userId = userId;
            this.sessionToken = sessionToken;
            this.expirationTimestamp = expirationTimestamp;
            this.lastActivityTimestamp = lastActivityTimestamp;
            this.activeRequests = activeRequests;
        }

        public String getUserId() {
            return userId;
        }

        public void setUserId(String userId) {
            this.userId = userId;
        }

        public String getSessionToken() {
            return sessionToken;
        }

        public void setSessionToken(String sessionToken) {
            this.sessionToken = sessionToken;
        }

        public long getExpirationTimestamp() {
            return expirationTimestamp;
        }

        public void setExpirationTimestamp(long expirationTimestamp) {
            this.expirationTimestamp = expirationTimestamp;
        }

        public long getLastActivityTimestamp() {
            return lastActivityTimestamp;
