typedef struct {
    int key;
    int id;
    void* data;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
} HashTable;

HashTable* hash_table_create(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->records = (Record*)calloc(initial_capacity, sizeof(Record));
    table->capacity = initial_capacity;
    table->count = 0;
    return table;
}

int hash_function(int key, size_t capacity) {
    return key % capacity;
}

size_t probe(size_t i, size_t capacity) {
    return i * i % capacity;
}

void* hash_table_insert(HashTable* table, int key, void* data) {
    size_t index = hash_function(key, table->capacity);
    for (int i = 0; i < table->capacity; i++) {
        if (!table->records[index].data) {
            table->records[index].key = key;
            table->records[index].id = -1; // Initialize ID
            table->records[index].data = data;
            table->count++;
            return &table->records[index];
        }
        index = (index + probe(i, table->capacity)) % table->capacity;
    }
    return NULL;
}

void hash_table_remove(HashTable* table, int key) {
    size_t index = hash_function(key, table->capacity);
    for (int i = 0; i < table->capacity; i++) {
        if (table->records[index].key == key && !table->records[index].data) {
            table->records[index].key = -1;
            table->count--;
            return;
        }
        index = (index + probe(i, table->capacity)) % table->capacity;
    }
}

void* hash_table_search(HashTable* table, int key) {
    size_t index = hash_function(key, table->capacity);
    for (int i = 0; i < table->capacity; i++) {
        if (table->records[index].key == key && !table->records[index].data) {
            return &table->records[index];
        }
        index = (index + probe(i, table->capacity)) % table->capacity;
    }
    return NULL;
}

