void sortOffsets() {
    pthread_mutex_lock(&lock);
    Record* tempRecords[numRecords];
    memcpy(tempRecords, records, sizeof(Record*) * numRecords);
    pthread_mutex_unlock(&lock);

    // use a stable sorting algorithm
    qsort(tempRecords, numRecords, sizeof(Record*), compareOffsets);
}

int compareOffsets(const void* a, const void* b) {
    Record* recA = *(Record**) a;
    Record* recB = *(Record**) b;
    return (recA->offset - recB->offset);
}

void serializeToFile() {
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        // handle error
    }
    pthread_mutex_lock(&lock);
    for (int i = 0; i < numRecords; i++) {
        fwrite((void*) records[i], sizeof(Record), 1, file);
    }
    pthread_mutex_unlock(&lock);
    fclose(file);
}

void deserializeFromFile() {
    FILE* file = fopen("data.bin", "rb");
    if (!file) {
        // handle error
    }
    int numRecordsLoaded;
    fread(&numRecordsLoaded, sizeof(int), 1, file);
    pthread_mutex_lock(&lock);
    records = (Record**) realloc(records, sizeof(Record*) * (numRecords + numRecordsLoaded));
    for (int i = 0; i < numRecordsLoaded; i++) {
        Record* newRecord = allocRecord(NULL);
        fread(newRecord, sizeof(Record), 1, file);
        records[numRecords++] = newRecord;
    }
    pthread_mutex_unlock(&lock);
    fclose(file);
}

void init() {
    // initialize memory pool or custom allocator
    numRecords = 0;
    records = NULL;
}

void destroy() {
    for (int i = 0; i < numRecords; i++) {
        freeRecord(records[i]);
    }
    free(records);
    records = NULL;
}
