void *device_malloc(size_t size);
void device_free(void *ptr);

// Error handling macros:
#define CHECK_NULL(ptr) if (ptr == NULL) { fprintf(stderr, "Error: Null pointer!\n"); return 1; }
#define CHECK_OUT_OF_BOUNDS(index) if ((index < 0) || (index >= sizeof)) { fprintf(stderr, "Error: Index out of bounds!\n"); return 1; }

// Implement the functions:
void *device_malloc(size_t size) {
    // Allocate memory using malloc
    void *ptr = malloc(size);
    CHECK_NULL(ptr); // Check for null pointer
    return ptr;
}

void device_free(void *ptr) {
    // Deallocate memory using free
    if (ptr != NULL) {
        free(ptr);
    }
}

DeviceProfile *create_device_profile(const char *name, uint32_t vendor_id, 
                                       uint32_t product_id, const char *serial_number,
                                       int num_firmware_versions) {
    DeviceProfile *profile = device_malloc(sizeof(DeviceProfile));
    profile->name = malloc(strlen(name) + 1);
    strcpy(profile->name, name);
    profile->vendor_id = vendor_id;
    profile->product_id = product_id;
    profile->serial_number = malloc(strlen(serial_number) + 1);
    strcpy(profile->serial_number, serial_number);
    profile->num_firmware_versions = num_firmware_versions;
    profile->firmware_versions = device_malloc(num_firmware_versions * sizeof(char *));
    for (int i = 0; i < num_firmware_versions; i++) {
        profile->firmware_versions[i] = malloc(strlen("default") + 1);
        strcpy(profile->firmware_versions[i], "default");
    }
    return profile;
}

void add_firmware_version(DeviceProfile *profile, const char *firmware_version) {
    // Check if the firmware version already exists
    for (int i = 0; i < profile->num_firmware_versions; i++) {
        if (strcmp(profile->firmware_versions[i], firmware_version) == 0) {
            return;
        }
    }

    // Add the new firmware version
    profile->firmware_versions[profile->num_firmware_versions] = malloc(strlen(firmware_version) + 1);
    strcpy(profile->firmware_versions[profile->num_firmware_versions], firmware_version);
    profile->num_firmware_versions++;

    // Reallocate memory if necessary
    while (profile->num_firmware_versions > sizeof(profile->firmware_versions) / sizeof(*profile->firmware_versions)) {
        profile->firmware_versions = device_malloc((profile->num_firmware_versions + 1) * sizeof(char *));
        for (int i = 0; i < profile->num_firmware_versions; i++) {
            profile->firmware_versions[i] = malloc(strlen(profile->firmware_versions[i]) + 1);
            strcpy(profile->firmware_versions[i], profile->firmware_versions[i]);
        }
    }
}

void remove_firmware_version(DeviceProfile *profile, const char *firmware_version) {
    // Find the firmware version to be removed
    for (int i = 0; i < profile->num_firmware_versions; i++) {
        if (strcmp(profile->firmware_versions[i], firmware_version) == 0) {
            // Shift all subsequent firmware versions down one position
            for (int j = i + 1; j < profile->num_firmware_versions; j++) {
                strcpy(profile->firmware_versions[j - 1], profile->firmware_versions[j]);
            }

            // Free the removed firmware version and decrement the count
            free(profile->firmware_versions[i]);
            profile->num_firmware_versions--;
        }
    }
}

void update_serial_number(DeviceProfile *profile, const char *new_serial_number) {
    free(profile->serial_number);
    profile->serial_number = malloc(strlen(new_serial_number) + 1);
    strcpy(profile->serial_number, new_serial_number);
}

void get_device_info(const DeviceProfile *profile, char **name_out, uint32_t *vendor_id_out) {
    *name_out = profile->name;
    *vendor_id_out = profile->vendor_id;
}

void print_device_profile(const DeviceProfile *profile) {
    printf("Device Name: %s\n", profile->name);
    printf("Vendor ID: %u\n", profile->vendor_id);
    printf("Product ID: %u\n", profile->product_id);
    printf("Serial Number: %s\n", profile->serial_number);
    for (int i = 0; i < profile->num_firmware_versions; i++) {
        printf("Firmware Version %d: %s\n", i, profile->firmware_versions[i]);
    }
}

// Library's main function to manage device profiles:
int device_profiles_init() {
    // Initialize the library
    return 0;
}

int device_profiles_deinit() {
    // Deinitialize the library
    return 0;
}
