record* networkConfigManager(int size) {
    record* config = (record*)malloc(size * sizeof(record));
    if (!config) {
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        config[i].offset = -1;
        config[i].key = -1;
        config[i].value = -1;
    }

    // Read list of integers from standard input and find the largest integer
    int max = readInput();

    // Validate integrity of records
    for (int i = 0; i < size; i++) {
        if (config[i].offset < 0 || config[i].key < 0 || config[i].value < 0) {
            printf("Invalid configuration: offset=%ld, key=%d, value=%d\n", config[i].offset, config[i].key, config[i].value);
            return NULL;
        }
    }

    // Return the configured network interface
    return config;
}

int readInput() {
    int max = -1;
    int num;

    while (scanf("%d", &num) == 1) {
        if (num > max) {
            max = num;
        }
    }

    return max;
}
