typedef struct {
    char *interface_name;
    char *ip_address;
    char *subnet_mask;
    int num_ports;
    struct port_config *port_configs;
    double latency;
    double throughput;
} network_interface_t;

typedef struct {
    network_interface_t *interfaces;
    int size;
    pthread_mutex_t lock;
} network_configuration_t;

void init_network_configuration(network_configuration_t *conf) {
    conf->size = 0;
    conf->interfaces = NULL;
    pthread_mutex_init(&conf->lock, NULL);
}

network_interface_t *add_network_interface(network_configuration_t *conf) {
    if (conf->size == 0) {
        conf->interfaces = (network_interface_t *)malloc(sizeof(network_interface_t));
    } else {
        network_interface_t **new_interfaces = (network_interface_t **)realloc(conf->interfaces, (conf->size + 1) * sizeof(network_interface_t *));
        conf->interfaces = new_interfaces;
    }
    pthread_mutex_lock(&conf->lock);
    conf->interfaces[conf->size] = malloc(sizeof(network_interface_t));
    conf->size++;
    pthread_mutex_unlock(&conf->lock);
    return conf->interfaces[conf->size - 1];
}

void remove_network_interface(network_configuration_t *conf, int index) {
    if (index < 0 || index >= conf->size) {
        printf("Invalid interface index\n");
        return;
    }
    pthread_mutex_lock(&conf->lock);
    free(conf->interfaces[index]);
    memmove(&conf->interfaces[index], &conf->interfaces[index + 1], sizeof(network_interface_t *) * (conf->size - index - 1));
    conf->size--;
    pthread_mutex_unlock(&conf->lock);
}

void update_network_interface(network_configuration_t *conf, int index, network_interface_t *new_config) {
    if (index < 0 || index >= conf->size) {
        printf("Invalid interface index\n");
        return;
    }
    pthread_mutex_lock(&conf->lock);
    free(conf->interfaces[index]);
    conf->interfaces[index] = new_config;
    pthread_mutex_unlock(&conf->lock);
}

network_interface_t *get_network_interface(network_configuration_t *conf, int index) {
    if (index < 0 || index >= conf->size) {
        printf("Invalid interface index\n");
        return NULL;
    }
    pthread_mutex_lock(&conf->lock);
    network_interface_t *interface = conf->interfaces[index];
    pthread_mutex_unlock(&conf->lock);
    return interface;
}

void compact_network_configuration(network_configuration_t *conf) {
    int new_size = 0;
    for (int i = 0; i < conf->size; i++) {
        if (conf->interfaces[i] != NULL) {
            new_size++;
        }
    }
    network_interface_t **new_interfaces = (network_interface_t **)malloc(new_size * sizeof(network_interface_t *));
    int j = 0;
    for (int i = 0; i < conf->size; i++) {
        if (conf->interfaces[i] != NULL) {
            new_interfaces[j] = conf->interfaces[i];
            j++;
        }
    }
    free(conf->interfaces);
    conf->interfaces = new_interfaces;
    conf->size = new_size;
}

