    Session* sessions = (Session*)malloc(MAX_SESSIONS * sizeof(Session));
    int numSessions = 0;

    while (true) {
        printf("1. Add session\n");
        printf("2. Remove session\n");
        printf("3. Update session\n");
        printf("4. Handle stale sessions\n");
        printf("5. Exit\n");

        int choice = -1;
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                // Add a new session
                addSession(123, (char**)malloc(MAX_PERMISSIONS * sizeof(char*)));
                break;

            case 2:
                // Remove a session
                removeSession(456);
