            case 3:
                // Update a session's permissions or audit log
                updateSession(789, (char**)malloc(MAX_PERMISSIONS * sizeof(char*)), "Updated audit log");
                break;

            case 4:
                // Handle stale sessions
                handleStaleSessions();
                break;

            case 5:
                // Exit the program
                free(sessions);
                return 0;
        }
    }
}

