record* initialize_records(int numRecords) {
    if (numRecords > 10000) {
        return NULL; // handling extreme input values
    }

    srand(time(NULL)); // seedable random number generator

    record* records = (record*)malloc(numRecords * sizeof(record));
    if (records == NULL) {
        return NULL; // handle memory allocation failure
    }

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (offsets == NULL) {
        free(records); // free allocated record array to prevent leak
        return NULL;
    }

    int* keys = (int*)malloc(numRecords * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        free(records);
        return NULL; // handle memory allocation failure and clean up
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].offset = offsets + i;
        records[i].key = i;
    }

    long offsetMax = 1000;
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % (offsetMax + 1);
    }

    for (int i = 0; i < numRecords; i++) {
        keys[i] = i + 1;
    }

    free(offsets);
    free(keys);

    return records;
}

