// Structure to hold NFAPI_CRC_INDICATION_PDU_T information
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to dynamically create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
int createNFAPIList(int N, Node** head) {
    *head = NULL;
    for (int i = 0; i < N; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            return -1;
        }

        newNode->data.RX_UE_INFORMATION_TAG = rand() % 100; // Randomly set RX_UE_INFORMATION_TAG
        newNode->data.RNTI = rand() % 256; // Randomly set RNTI
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 1000; // Randomly set CRC_INDICATION_REL8_TAG
        newNode->data.CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        if (*head) {
            Node* current = *head;
            while (current->next) {
                current = current->next;
            }
            current->next = newNode;
        } else {
            *head = newNode;
        }
    }

    return 0;
}

// Function to validate unique RNTI values within the linked list
int validateRNTI(Node* head) {
    Node* current = head;
    while (current) {
        int rnti = current->data.RNTI;
        Node* next = current->next;
        while (next) {
            if (rnti == next->data.RNTI) {
                // Duplicate RNTI detected
                printf("Error: Duplicate RNTI value found.\n");

                // Free allocated memory and return an error status
                Node* temp = head;
                while (temp) {
                    Node* nextTemp = temp->next;
                    free(temp);
                    temp = nextTemp;
                }
                return -1;
            }
            next = next->next;
        }
        current = current->next;
    }

    return 0;
}
