// Define a struct for session objects
typedef struct {
    int sessionId;
    time_t lastActivity;
    int authenticated;
} Session;

// Define the function to manage dynamic list of sessions
void manageSessions(Session** sessions, int* size) {
    // Create a lock for synchronization (lock-based approach)
    pthread_mutex_lock(&sessionLock);

    // Add a new session with a unique ID
    void addSession(Session* session) {
        if (*size == 0) {
            *sessions = malloc(sizeof(Session));
            (*sessions)->sessionId = 1;
            (*sessions)->lastActivity = time(NULL);
            (*sessions)->authenticated = 1;
            (*size)++;
        } else {
            int prevSize = *size;
            for (int i = 0; i < prevSize; i++) {
                if ((*sessions)[i]->sessionId == session->sessionId) {
                    printf("Session ID already exists: %d\n", session->sessionId);
                    return;
                }
            }

            *sessions = realloc(*sessions, sizeof(Session) * (*size + 1));
            (*sessions)[prevSize].sessionId = session->sessionId;
            (*sessions)[prevSize].lastActivity = time(NULL);
            (*sessions)[prevSize].authenticated = session->authenticated;
            (*size)++;
        }
    }

    // Remove a session by ID
    void removeSession(int id) {
        for (int i = 0; i < *size; i++) {
            if ((*sessions)[i]->sessionId == id) {
                for (int j = i + 1; j < *size; j++) {
                    (*sessions)[j - 1] = (*sessions)[j];
                }
                free((*sessions)[--*size]);
                break;
            }
        }
    }

    // Get a session by ID
    Session* getSession(int id) {
        for (int i = 0; i < *size; i++) {
            if ((*sessions)[i]->sessionId == id) {
                return &(*sessions)[i];
            }
        }
        return NULL;
    }

    // Check and clean up expired sessions every minute
    void cleanupExpiredSessions() {
        pthread_mutex_lock(&sessionLock);
        time_t now = time(NULL);
        for (int i = 0; i < *size; i++) {
            if ((now - (*sessions)[i]->lastActivity) > 60) {
                removeSession((*sessions[i])->sessionId);
                i--;
            }
        }
        pthread_mutex_unlock(&sessionLock);
    }

    // Handle concurrent access and potential network delays or failures
    int validateAndRenewSession(int sessionId, time_t lastActivity) {
        Session* session = getSession(sessionId);
        if (session == NULL) return -1; // Not found

        if ((lastActivity - session->lastActivity) > 60) {
            // Renew the session
            pthread_mutex_lock(&sessionLock);
            session->lastActivity = time(NULL);
            pthread_mutex_unlock(&sessionLock);
            return 0;
        } else {
            return 1; // Still valid
        }
    }

    // Add a new session with a unique ID and validate it (validateAndRenewSession)
    int addNewSession(int sessionId, time_t lastActivity) {
        Session* session = getSession(sessionId);
        if (session != NULL) return -2; // Already exists

        pthread_mutex_lock(&sessionLock);
        session = malloc(sizeof(Session));
        session->sessionId = sessionId;
        session->lastActivity = lastActivity;
        session->authenticated = 1;

        (*size)++;
        *sessions = realloc(*sessions, sizeof(Session) * (*size));

        int result = validateAndRenewSession(sessionId, lastActivity);
        pthread_mutex_unlock(&sessionLock);

        if (result == -2) {
            free(session); // Free the session
            return -3; // Already exists with different status
        } else if (result < 0) {
            printf("Failed to add new session: %d\n", sessionId);
            free(session); // Free the session
            return -1; // Failed to validate and renew
        }

        return 0;
    }

    // Clean up expired sessions periodically
    void startCleanup() {
        pthread_create(&cleanupThread, NULL, (void*)cleanupExpiredSessions, NULL);
    }
}

// Define a lock for synchronization
pthread_mutex_t sessionLock;

int main() {
    Session* sessions = NULL;
    int size = 0;

    // Initialize the lock and start cleanup in the background
    pthread_mutex_init(&sessionLock, NULL);
    manageSessions(&sessions, &size);
    startCleanup();

    return 0;
}

