typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_ARRAY_T;

// Function to initialize and return a new dynamic array
NFAPI_CRC_INDICATION_PDU_ARRAY_T* nfapi_crc_indication_pdu_array_init(int initial_capacity) {
    NFAPI_CRC_INDICATION_PDU_ARRAY_T* array = (NFAPI_CRC_INDICATION_PDU_ARRAY_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_ARRAY_T));
    array->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Function to add an element to the dynamic array
void nfapi_crc_indication_pdu_array_add(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->elements, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    array->elements[array->size] = new_element;
    array->size++;
    pthread_mutex_unlock(&array->lock);
}

// Function to update an element in the dynamic array
void nfapi_crc_indication_pdu_array_update(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array, int index, NFAPI_CRC_INDICATION_PDU_T updated_element) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        array->elements[index] = updated_element;
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to delete an element from the dynamic array
void nfapi_crc_indication_pdu_array_delete(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array, int index) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        memmove(&array->elements[index], &array->elements[index + 1], (array->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->size--;
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to free the dynamic array
void nfapi_crc_indication_pdu_array_free(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array) {
    if (array != NULL) {
        pthread_mutex_destroy(&array->lock);
        free(array->elements);
        free(array);
    }
}
