void manageShapesAndProfiles(int gridSize, Shape** shapes, Profile** profiles) {
    // Allocate memory for grid of shapes and profiles
    Shape** shapeGrid = (Shape**)malloc(gridSize * sizeof(Shape*));
    Profile** profileGrid = (Profile**)malloc(gridSize * sizeof(Profile*));

    for (int i = 0; i < gridSize; i++) {
        shapeGrid[i] = (Shape*)malloc(sizeof(Shape));
        profileGrid[i] = (Profile*)malloc(sizeof(Profile));

        // Initialize shape and profile with default values
        strcpy(shapeGrid[i]->type, "default");
        shapeGrid[i]->x = 0.0;
        shapeGrid[i]->y = 0.0;

        strcpy(profileGrid[i]->name, "default");
        profileGrid[i]->email = "";
    }

    // Validate and sort shapes by area
    for (int i = 0; i < gridSize; i++) {
        double area = shapeGrid[i]->x * shapeGrid[i]->y;
        // Comparator to sort shapes by area in ascending order
        int compareFunc(const void* a, const void* b) {
            Shape* s1 = *(Shape**)a;
            Shape* s2 = *(Shape*)b;
            return (s1->x * s1->y - s2->x * s2->y);
        }

        qsort(shapeGrid, gridSize, sizeof(Shape*), compareFunc);

