            updatedProfile->email = "new_email";
            for (int j = 0; j < updatedProfile->numRoles; j++) {
                free(profileGrid[i]->roles[j]);
            }
            free(profileGrid[i]->roles);
        }

    }

    // Delete profiles with HTTP DELETE method
    for (int i = 0; i < gridSize; i++) {
        // Handle HTTP DELETE method request
        if (/*DELETE request received*/) {
            free(shapeGrid[i]);
            free(profileGrid[i]);
        }
    }

    // Persist data to external database
    for (int i = 0; i < gridSize; i++) {
        // Database operations to store shapes and profiles
        // ...
    }

    return shapeGrid[0]; // Return pointer to the first element of the struct record array
}

