#define LOG_EVENT_RECORD_T_MAX 1000

typedef struct {
    int log_source_id;
    int log_level;
    long log_timestamp;
} LOG_EVENT_RECORD_T;

typedef struct {
    LOG_EVENT_RECORD_T* events;
    int size;
    pthread_mutex_t mutex;
} LOG_EVENT_MANAGER_T;

LOG_EVENT_MANAGER_T* log_event_manager = NULL;
int log_frequency = 100; // in milliseconds

void log_event_manager_init() {
    if (log_event_manager == NULL) {
        log_event_manager = (LOG_EVENT_MANAGER_T*) malloc(sizeof(LOG_EVENT_MANAGER_T));
        log_event_manager->events = (LOG_EVENT_RECORD_T*) calloc(LOG_EVENT_RECORD_T_MAX, sizeof(LOG_EVENT_RECORD_T));
        log_event_manager->size = 0;
        pthread_mutex_init(&log_event_manager->mutex, NULL);
    }
}

void log_event_record(const LOG_EVENT_RECORD_T* event) {
    if (event == NULL)
        return;

    pthread_mutex_lock(&log_event_manager->mutex);

    // Add new event
    if (log_event_manager->size >= LOG_EVENT_RECORD_T_MAX) {
        printf("Error: Out of memory\n");
        exit(-1);
    }

    log_event_manager->events[log_event_manager->size] = *event;
    log_event_manager->size++;

    pthread_mutex_unlock(&log_event_manager->mutex);

    // Log operation
    if (rand() % log_frequency == 0) {
        printf("Logged event at timestamp: %ld\n", event->log_timestamp);
    }
}

int main() {
    int i;
    LOG_EVENT_RECORD_T events[5];

    for (i = 0; i < 5; i++) {
        events[i].log_source_id = i + 1;
        events[i].log_level = i % 2 ? LOG_LEVEL_ERROR : LOG_LEVEL_INFO;
        events[i].log_timestamp = time(NULL);
    }

    log_event_manager_init();

    for (i = 0; i < 5; i++) {
        log_event_record(&events[i]);
    }
}
