#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int *values;
    long *offsets;
    int key;
} entry;

void* initializeDataStore(int size, int numValuesPerEntry) {
    // Initialize arrays with specified sizes
    entry **entries = (entry **)malloc(size * sizeof(entry *));
    for (int i = 0; i < size; i++) {
        entries[i] = (entry *)malloc(sizeof(entry));
        entries[i]->values = (int *)malloc(numValuesPerEntry * sizeof(int));
        entries[i]->offsets = (long *)malloc((numValuesPerEntry + 1) * sizeof(long));
    }

    // Initialize key and offset values
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < numValuesPerEntry; j++) {
            entries[i]->values[j] = i;
        }
        entries[i]->offsets[0] = i * numValuesPerEntry;
        for (int j = 1; j <= numValuesPerEntry; j++) {
            entries[i]->offsets[j] = entries[i]->offsets[j - 1] + 1;
        }
    }

    // Initialize keys
    for (int i = 0; i < size; i++) {
        entries[i]->key = i;
    }

    return entries;
}
