#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent an object with unique identifier, timestamp, and status flag
typedef struct {
    int id;
    time_t timestamp;
    char status;
} Object;

// Define a linked list node for dynamic list of objects
typedef struct Node {
    Object obj;
    struct Node* next;
} Node;

// Create a new linked list node with given object
Node* create_node(Object obj) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        return NULL; // Handle memory allocation failure
    }
    new_node->obj = obj;
    new_node->next = NULL;
    return new_node;
}

// Initialize the dynamic list with a sentinel node
Node* init_list() {
    Node* head = (Node*) malloc(sizeof(Node));
    if (!head) {
        return NULL; // Handle memory allocation failure
    }
    head->obj.id = -1; // Sentinel node
    head->next = NULL;
    return head;
}

// Add an object to the dynamic list with concurrency-safe locking
void add_object(Node** head, Object obj) {
    Node* new_node = create_node(obj);
    if (!new_node) {
        return; // Handle memory allocation failure
    }

    pthread_mutex_lock(&mutex); // Acquire lock for thread safety

    Node* current = *head;
    while (current && current->next) {
        current = current->next;
    }

    new_node->next = current->next;
    current->next = new_node;

    pthread_mutex_unlock(&mutex); // Release lock
}

// Remove an object from the dynamic list with concurrency-safe locking
void remove_object(Node** head, int id) {
    Node* current = *head;
    Node* prev = NULL;

    pthread_mutex_lock(&mutex); // Acquire lock for thread safety

    while (current && current->next) {
        if (current->obj.id == id) {
            if (!prev) {
                *head = current->next; // Update head if node to remove is sentinel
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&mutex); // Release lock
}

// Print the dynamic list of objects
void print_list(Node* head) {
    Node* current = head;
    while (current && current->next) {
        printf("ID: %d, Timestamp: %ld, Status: %c\n", current->obj.id, current->obj.timestamp, current->obj.status);
        current = current->next;
    }
}

// Main function to demonstrate usage and testing
int main() {
    Node* head = init_list();

    // Add objects with unique identifiers
    add_object(&head, (Object){1, time(NULL), 'A'});
    add_object(&head, (Object){2, time(NULL), 'B'});
    add_object(&head, (Object){3, time(NULL), 'C'});

    // Print the dynamic list of objects
    print_list(head);

    return 0;
}

