    }

    // Define the Union-Find data structure

    std::vector<int> parent(numRequests);
    for (int i = 0; i < numRequests; ++i) {
        parent[i] = -1;  // Each element is its own set
    }

    auto find = [&](int x) {
        if (parent[x] < 0) return x;
        return parent[x] = find(parent[x]);
    };

    auto unionSet = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootY] = rootX;
