    // Read the person's age
    fread(&person->age, sizeof(int), 1, file);
    // Read the person's email
    person->email = malloc(strlen("default_email") + 1); // Assume default email if not specified
    fread(person->email, strlen("default_email"), 1, file);
    // Read the person's phone number
    person->phoneNumber = malloc(strlen("default_phone_number") + 1); // Assume default phone number if not specified
    fread(person->phoneNumber, strlen("default_phone_number"), 1, file);
    return person;
}

