    Connection connections[16];
} NIC;

NIC* configureNetworkInterfaces(int num_nics) {
    if (num_nics > 8) {
        return NULL; // Error: too many NICs
    }

    for (int i = 0; i < num_nics; i++) {
        NIC* nic = malloc(sizeof(NIC));

        if (!nic) {
            return NULL; // Error: insufficient memory
        }

        nic->mac_address = malloc(18); // 17 characters + null terminator
        nic->ip_address = malloc(16); // 15 characters + null terminator

        if (!(nic->mac_address && nic->ip_address)) {
