#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_USERS 1000

typedef struct {
    char* username;
    char* email;
    char* password_hash;
    char* role;
    int session_tokens_count;
    char** session_tokens;
} User;

void addAccount(User** users, int* size) {
    if (*size >= MAX_USERS) {
        printf("Memory overflow. Cannot add more accounts.\n");
        return;
    }

    *users = (User*) realloc(*users, sizeof(User) * (*size + 1));
    if (!*users) {
        printf("Memory allocation failed. Cannot add account.\n");
        return;
    }

    User new_user = ({ /* Initialize new user fields */ 
                       .username = "new_username",
                       .email = "new_email",
                       .password_hash = "hashed_password",
                       .role = "admin",
                       .session_tokens_count = 0,
                       .session_tokens = NULL
                     });

    (*users)[*size] = new_user;
    (*size)++;
}

void removeAccount(User** users, int* size, char* username) {
    for (int i = 0; i < *size; i++) {
        if (!strcmp(users[i]->username, username)) {
            // Shift all remaining accounts down
            memmove(users + i, users + i + 1, sizeof(User) * (*size - i));
            (*size)--;

            return;
        }
    }

    printf("Username not found. Cannot remove account.\n");
}

void updateAccount(User** users, int* size, char* username, char* new_username, char* new_email) {
    for (int i = 0; i < *size; i++) {
        if (!strcmp(users[i]->username, username)) {
            users[i]->username = new_username;
            users[i]->email = new_email;

            return;
        }
    }

    printf("Username not found. Cannot update account.\n");
}

void printUsers(User** users, int size) {
    for (int i = 0; i < size; i++) {
        printf("Username: %s, Email: %s\n", users[i]->username, users[i]->email);
    }
}

int main() {
    User* users = NULL;
    int size = 0;

    addAccount(&users, &size);
    addAccount(&users, &size);

    printUsers(users, size);

    removeAccount(&users, &size, "new_username");

    printUsers(users, size);

    updateAccount(&users, &size, "new_email", "updated_username", "updated_email");

    printUsers(users, size);

    return 0;
}
