    int MAX_KEYS = 20;
    int COOLDOWN_TIME_MAX = 15;

    // Initialize memory allocation limit
    size_t MEM_LIMIT = 1024 * 1024; // 1 MB

    // Allocate memory for offsets and keys arrays
    long* offsets = new long[MAX_RECORDS];
    int* keys = new int[MAX_RECORDS];

