        offsets[i] = i;
        keys[i] = i % MAX_KEYS;
        char description[20];
        sprintf(description, "Action %d: %s", keys[i], data_source.getActionTypes()[keys[i]].c_str());
        records[i].valuePointer = &offsets[i];
        records[i].key = keys[i];
        strcpy(records[i].description, description);
        records[i].attackType = (rand() % 2) ? AttackType::ATTACK_A : AttackType::ATTACK_B;
        records[i].cooldownTime = rand() % COOLDOWN_TIME_MAX + 1;

        // Ensure no consecutive identical attacks and respect cooldown period
        while ((records[i-1].attackType == records[i].attackType && i > 0) || records[i].cooldownTime <= 0) {
            records[i].attackType = (rand() % 2) ? AttackType::ATTACK_A : AttackType::ATTACK_B;
            records[i].cooldownTime = rand() % COOLDOWN_TIME_MAX + 1;
        }
    }

    // Initialize Union-Find data structure
    std::vector<int> parent(MAX_RECORDS, -1);
    int rank[MAX_RECORDS];

    // Implement the Union-Find algorithm
    void unionFind(int x, int y) {
        if (parent[x] == parent[y]) {
            parent[x] = y;
        } else if (parent[y] != -1) {
            parent[x] = y;
        }
    }

    // Measure processing time for each pair and print to console
    double start_time = std::clock();
    for (int i = 0; i < MAX_RECORDS; ++i) {
        for (int j = i + 1; j < MAX_RECORDS; ++j) {
            if (records[i].key == records[j].key || records[i].attackType == records[j].attackType) {
                unionFind(i, j);
                std::cout << "Disjoint pair: (" << i << ", " << j << ")" << std::endl;
            }
        }
    }
    double end_time = std::clock();
    std::cout << "Processing time for pairs: " << (end_time - start_time) / CLOCKS_PER_SEC * 1000.0 << " ms" << std::endl;

    // Clean up allocated memory
    delete[] offsets;
    delete[] keys;
}

// Record structure definition
struct Record {
    long* valuePointer;
    int key;
    char description[20];
    AttackType attackType;
    int cooldownTime;
};
