        connections[i].client_addresses[0] = (char *)malloc(16); // client_address
        connections[i].command_count = rand() % 5 + 1; // random command count

        connections[i].command_handlers = (void **)calloc(connections[i].command_count, sizeof(void *));
    }

    // Validate connections
    for (int i = 0; i < num_connections; i++) {
        // Check for duplicate client addresses
        for (int j = 0; j < i; j++) {
            if (!strcmp(connections[j].client_addresses[0], connections[i].client_addresses[0])) {
                printf("Duplicate client address found\n");
                return;
