#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef enum {
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} MESSAGE_LEVEL;

typedef struct {
    int ENTRY_ID;
    time_t LOG_TIMESTAMP;
    MESSAGE_LEVEL MESSAGE_LEVEL;
} LOG_ENTRY;

struct log_pool {
    LOG_ENTRY* entries;
    int entry_count;
    pthread_mutex_t mutex;
};

LOG_POOL* init_log_pool(int max_entries) {
    LOG_POOL* pool = malloc(sizeof(LOG_POOL));
    if (pool == NULL) return NULL;
    pool->entries = malloc(max_entries * sizeof(LOG_ENTRY));
    if (pool->entries == NULL) {
        free(pool);
        return NULL;
    }
    pool->entry_count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

int add_log_entry(LOG_POOL* pool, int new_id, time_t timestamp, MESSAGE_LEVEL level) {
    if (pool == NULL || new_id < 0) return -1; // invalid log pool or entry ID

    LOG_ENTRY* entry = &pool->entries[pool->entry_count];
    pthread_mutex_lock(&pool->mutex);

    for (int i = 0; i <= pool->entry_count; i++) {
        if (i == pool->entry_count || pool->entries[i].ENTRY_ID != new_id) {
            // no duplicate found or reached the end of the list
            entry->ENTRY_ID = new_id;
            entry->LOG_TIMESTAMP = timestamp;
            entry->MESSAGE_LEVEL = level;
            break;
        }
    }

    if (pool->entry_count == pool->entries - 1) return -2; // max entries exceeded

    pool->entry_count++;
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

void free_log_pool(LOG_POOL* pool) {
    if (pool != NULL) {
        pthread_mutex_destroy(&pool->mutex);
        free(pool->entries);
        free(pool);
    }
}
