#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Define a structure to represent user-defined objects
typedef struct {
    char* name;
    int age;
    long id;
} UserObject;

// Function to manage the dynamic list of user-defined objects
void manageDynamicList(size_t size) {
    // Dynamically allocate memory for the list
    UserObject** list = (UserObject**)malloc(size * sizeof(UserObject*));

    // Initialize pointers in the list
    for (size_t i = 0; i < size; i++) {
        list[i] = NULL;
    }

    int uniqueIdCount = 0;

    // Function to add objects at specific positions while maintaining order by age
    void addObjectAtPosition(int position, char* name, int age, long id) {
        // Check if the object is unique and valid
        if (id > 0 && age >= 0) {
            UserObject* obj = (UserObject*)malloc(sizeof(UserObject));
            obj->name = strdup(name);
            obj->age = age;
            obj->id = id;

            // Insert the object at the specified position while maintaining order by age
            for (size_t i = 0; i < position; i++) {
                if (list[i]->age > age) {
                    // Shift existing objects to make room for the new object
                    for (size_t j = i + 1; j < size; j++) {
                        list[j] = list[j - 1];
                    }
                    list[i] = obj;
                    break;
                } else if (i == size - 1) {
                    // Add the object to the end of the list
                    list[size - 1] = obj;
                }
            }
        } else {
            printf("Invalid user object.\n");
        }
    }

    // Function to remove objects based on their unique identifier
    void removeObject(long id) {
        for (size_t i = 0; i < size; i++) {
            if (list[i]->id == id) {
                free(list[i]->name);
                free(list[i]);
                list[i] = NULL;
                break;
            }
        }
    }

    // Function to reverse iterate through the list of objects
    void reverseIterate() {
        for (int i = size - 1; i >= 0; i--) {
            printf("Object %d: Name - %s, Age - %d, ID - %ld\n", uniqueIdCount++, (*list[i]).name, (*list[i]).age, (*list[i]).id);
        }
    }

    // Comparator function to sort the list of objects by age in ascending order
    int compare(const void* a, const void* b) {
        UserObject* obj1 = *(UserObject**)a;
        UserObject* obj2 = *(UserObject**)b;

        if (obj1->age < obj2->age) {
            return -1;
        } else if (obj1->age > obj2->age) {
            return 1;
        } else {
            return 0;
        }
    }

    // Initialize the list
    for (size_t i = 0; i < size; i++) {
        printf("Enter object details (name, age, id): ");
        char name[256];
        int age;
        long id;
        scanf("%s %d %ld", name, &age, &id);

        // Add the object to the list
        addObjectAtPosition(i, name, age, id);
    }

    // Sort the list of objects by age in ascending order using qsort
    qsort(list, size, sizeof(UserObject*), compare);

    // Print the list of objects in reverse order
    reverseIterate();
}

int main() {
    // Set the desired dynamic list size
    int size = 5;
    manageDynamicList(size);
    return 0;
}
