// Define a custom data structure for server instance configurations
typedef struct {
    int id;
    int connection_timeout;
    int health_check_interval;
    char **endpoints; // Array of application endpoints
} ServerConfig;

// Function to manage the dynamic array of server configurations
ServerConfig *server_configs = NULL;
int num_server_configs = 0;

void add_server_config(int id, int connection_timeout, int health_check_interval, char **endpoints) {
    ServerConfig *new_config = (ServerConfig *)malloc(sizeof(ServerConfig));
    new_config->id = id;
    new_config->connection_timeout = connection_timeout;
    new_config->health_check_interval = health_check_interval;
    new_config->endpoints = endpoints;

    // Reallocate memory for the dynamic array if necessary
    if (num_server_configs == 0) {
        server_configs = (ServerConfig *)malloc(sizeof(ServerConfig));
    } else {
        ServerConfig *temp = (ServerConfig *)realloc(server_configs, (num_server_configs + 1) * sizeof(ServerConfig));
        server_configs = temp;
    }

    server_configs[num_server_configs++] = new_config;
}

void remove_server_config(int id) {
    for (int i = 0; i < num_server_configs; i++) {
        if (server_configs[i]->id == id) {
            // Update the dynamic array to skip over removed element
            memmove(&server_configs[i], &server_configs[i + 1], (num_server_configs - i - 1) * sizeof(ServerConfig));
            num_server_configs--;
            free(server_configs[i]);
            return;
        }
    }
}

void update_server_config(int id, int connection_timeout, int health_check_interval, char **endpoints) {
    for (int i = 0; i < num_server_configs; i++) {
        if (server_configs[i]->id == id) {
            server_configs[i]->connection_timeout = connection_timeout;
            server_configs[i]->health_check_interval = health_check_interval;
            free(server_configs[i]->endpoints);
            server_configs[i]->endpoints = endpoints;
            return;
        }
    }
}

void print_server_configs() {
    for (int i = 0; i < num_server_configs; i++) {
        printf("Server %d:\n", server_configs[i]->id);
        printf("  Connection timeout: %d\n", server_configs[i]->connection_timeout);
        printf("  Health check interval: %d\n", server_configs[i]->health_check_interval);
        for (int j = 0; server_configs[i]->endpoints[j]; j++) {
            printf("  Endpoint: %s\n", server_configs[i]->endpoints[j]);
        }
    }
}
