// Initialize task list
TaskList* taskListInit() {
    TaskList* taskList = (TaskList*) malloc(sizeof(TaskList));
    taskList->tasks = NULL;
    taskList->size = 0;
    pthread_mutex_init(&taskList->lock, NULL);
    return taskList;
}

// Add task to the list
void taskListAdd(TaskList* taskList, Task* task) {
    pthread_mutex_lock(&taskList->lock);

    // Reallocate memory if necessary
    if (taskList->size == taskList->tasks) {
        taskList->tasks = realloc(taskList->tasks, (taskList->size + 1) * sizeof(Task*));
    }

    taskList->tasks[taskList->size] = task;
    taskList->size++;

    pthread_mutex_unlock(&taskList->lock);
}

// Remove task from the list
void taskListRemove(TaskList* taskList, int id) {
    pthread_mutex_lock(&taskList->lock);

    for (int i = 0; i < taskList->size; i++) {
        if (taskList->tasks[i]->id == id) {
            free(taskList->tasks[i]);
            taskList->tasks[i] = taskList->tasks[--taskList->size];
            break;
        }
    }

    pthread_mutex_unlock(&taskList->lock);
}

