    pthread_mutex_lock(&taskList->lock);

    for (int i = 0; i < taskList->size; i++) {
        if (taskList->tasks[i]->id == id) {
            free(taskList->tasks[i]);
            taskList->tasks[i] = newTask;
            break;
        }
    }

    pthread_mutex_unlock(&taskList->lock);
}

