#define MAX_PROFILES 10000
#define MAX_PERMISSIONS 10

typedef struct {
    char* username;
    char* email;
    time_t date_of_birth;
    int permissions[MAX_PERMISSIONS];
} UserProfile;

void* user_profiles = NULL;
int num_profiles = 0;

// Custom garbage collector to deallocate unused profiles
void gc() {
    for (int i = 0; i < num_profiles; i++) {
        UserProfile* profile = user_profiles + i * sizeof(UserProfile);
        if (profile->username == NULL) {
            free(user_profiles + i * sizeof(UserProfile));
            num_profiles--;
            i--; // Decrement i to recheck the same index
        }
    }
}

// Function to add a new user profile
int addUserProfile(const char* username, const char* email, time_t date_of_birth, int permissions[]) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    profile->username = strdup(username);
    profile->email = strdup(email);
    profile->date_of_birth = date_of_birth;
    for (int i = 0; i < MAX_PERMISSIONS; i++) {
        profile->permissions[i] = permissions[i];
    }
    if (user_profiles == NULL) {
        user_profiles = profile;
    } else {
        UserProfile* last_profile = user_profiles + (num_profiles - 1) * sizeof(UserProfile);
        for (int i = num_profiles; i > 0; i--) {
            last_profile->username = profile->username;
            last_profile->email = profile->email;
            last_profile->date_of_birth = profile->date_of_birth;
            last_profile->permissions[i-1] = profile->permissions[i-1];
        }
    }
    num_profiles++;
    gc();
    return 0;
}

// Function to remove a user profile
int removeUserProfile(int index) {
    if (index < 0 || index >= num_profiles) {
        printf("Invalid index\n");
        return -1;
    }
    UserProfile* profile = user_profiles + index * sizeof(UserProfile);
    free(profile->username);
    free(profile->email);
    free(user_profiles + index * sizeof(UserProfile));
    for (int i = index; i < num_profiles - 1; i++) {
        user_profiles[i * sizeof(UserProfile)] = user_profiles[(i+1) * sizeof(UserProfile)];
    }
    num_profiles--;
    gc();
    return 0;
}

// Function to update a user profile
int updateUserProfile(int index, const char* username, const char* email, time_t date_of_birth, int permissions[]) {
    if (index < 0 || index >= num_profiles) {
        printf("Invalid index\n");
        return -1;
    }
    UserProfile* profile = user_profiles + index * sizeof(UserProfile);
    free(profile->username);
    free(profile->email);
    profile->username = strdup(username);
    profile->email = strdup(email);
    profile->date_of_birth = date_of_birth;
    for (int i = 0; i < MAX_PERMISSIONS; i++) {
        profile->permissions[i] = permissions[i];
    }
    return 0;
}

// Function to export user profiles in JSON format
int exportProfilesToJson(const char* filename) {
    json_object* jobj = json_object_new_object();
    for (int i = 0; i < num_profiles; i++) {
        UserProfile* profile = user_profiles + i * sizeof(UserProfile);
        json_object* subobj = json_object_new_object();
        json_object_object_add(subobj, "username", json_string_new(profile->username));
        json_object_object_add(subobj, "email", json_string_new(profile->email));
        json_object_object_add(subobj, "date_of_birth", json_real_new((double)profile->date_of_birth));
        for (int j = 0; j < MAX_PERMISSIONS; j++) {
            json_object_object_add(subobj, sprintf("permissions[%d]", j), json_integer_new(profile->permissions[j]));
        }
        json_object_object_add(jobj, sprintf("profile_%d", i), subobj);
    }
    FILE* file = fopen(filename, "w");
    if (file != NULL) {
        json_write_file(file, jobj, 0);
        fclose(file);
    } else {
        printf("Error writing to file\n");
    }
    json_object_free(jobj);
    return 0;
}

// Function to import user profiles from JSON format
int importProfilesFromJson(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return -1;
    }
    json_object* jobj = json_read_file(file, 0);
    fclose(file);
    for (int i = 0; i < num_profiles; i++) {
        UserProfile* profile = user_profiles + i * sizeof(UserProfile);
        free(profile->username);
        free(profile->email);
    }
    num_profiles = 0;
    json_object_object_foreach(jobj, key, val) {
        int index = atoi(strstr(key, "profile_") + 7);
        UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
        profile->username = strdup(json_string_get(val));
        profile->email = strdup(json_string_get(val));
        profile->date_of_birth = json_real_get_double(val);
        for (int j = 0; j < MAX_PERMISSIONS; j++) {
            profile->permissions[j] = json_integer_get_int(val, sprintf("permissions[%d]", j));
        }
        if (user_profiles == NULL) {
            user_profiles = profile;
        } else {
            UserProfile* last_profile = user_profiles + (num_profiles - 1) * sizeof(UserProfile);
            for (int i = num_profiles; i > index; i--) {
                last_profile->username = profile->username;
                last_profile->email = profile->email;
                last_profile->date_of_birth = profile->date_of_birth;
                last_profile->permissions[i-1] = profile->permissions[i-1];
            }
        }
        num_profiles++;
        gc();
    }
    json_object_free(jobj);
    return 0;
}

int main() {
    // Initialize user profiles
    addUserProfile("user1", "user1@example.com", 1643723400, (int []){1, 2, 3});
    addUserProfile("user2", "user2@example.com", 1654323000, (int []){4, 5});

    // Remove a user profile
    removeUserProfile(0);

    // Update a user profile
    updateUserProfile(0, "new_user1", "new_user1@example.com", 1664122600, (int []){6, 7});

    // Export user profiles to JSON file
    exportProfilesToJson("user_profiles.json");

    // Import user profiles from JSON file
    importProfilesFromJson("user_profiles.json");

    return 0;
}
