void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle allocation failure
        return NULL;
    }
    return ptr;
}

int my_free(void* ptr) {
    free(ptr);
    return 0;
}

// Dynamic array of record structures with memory pool management
record** init_array(int size, int max_records) {
    record** arr = (record**)my_malloc(size * sizeof(record*));
    if (!arr) {
        // Handle allocation failure
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        arr[i] = (record*)my_malloc(sizeof(record));
        if (!arr[i]) {
            // Handle allocation failure
            int j;
            for (j = 0; j <= i; j++) {
                my_free(arr[j]->str);
                my_free((void*)arr[j]);
            }
            for (int k = 0; k < size; k++) {
                my_free((void*)arr[k]);
            }
            return NULL;
        }
    }

    // Initialize each record's value to a random number within a specified range
    int min_val = 1, max_val = 100;
    for (int i = 0; i < size; i++) {
        arr[i]->value = rand() % (max_val - min_val + 1) + min_val;
    }

    return arr;
}

void free_array(record** arr, int size) {
    for (int i = 0; i < size; i++) {
        my_free((void*)arr[i]);
    }
    my_free(arr);
}
