#define MAX_TASKS 1000
#define TASK_POOL_SIZE (1024 * 1024) // 1MB pool size

typedef enum {
    STATUS_PENDING,
    STATUS_IN_PROGRESS,
    STATUS_COMPLETE,
    STATUS_FAILED
} task_status;

struct task {
    char* name;
    int priority;
    task_status* status;
};

task_pool_t* task_pool = NULL;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* my_malloc(size_t size) {
    return malloc(size);
}

void* my_free(void* ptr) {
    free(ptr);
    return NULL;
}

int create_task(task_pool_t** pool, char* name, int priority) {
    task_pool_t* new_task = (task_pool_t*)my_malloc(sizeof(task_pool_t));
    if (!new_task) {
        return -1; // Out of memory
    }

    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->status = &STATUS_PENDING;

    pthread_mutex_lock(&lock);
    (*pool)->tasks[(*pool)->size++] = new_task;
    pthread_mutex_unlock(&lock);

    return 0; // Success
}

int update_task(task_pool_t* pool, char* name) {
    for (int i = 0; i < pool->size; i++) {
        if (strcmp(pool->tasks[i]->name, name) == 0) {
            pthread_mutex_lock(&lock);
            pool->tasks[i]->status = &STATUS_IN_PROGRESS;
            pthread_mutex_unlock(&lock);
            return 0; // Success
        }
    }

    return -1; // Task not found
}

void free_task(task_pool_t* task) {
    if (task) {
        free(task->name);
        my_free(task);
    }
}
