#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_UPDATE_DURATION 3600000 // 1 hour in milliseconds
#define MEMORY_THRESHOLD 50 // percentage

typedef struct {
    union {
        long l;
        int i;
    } data;
    uint64_t timestamp;
    char metadata[16];
} record_t;

record_t* records[MAX_RECORDS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t empty_slots, full_records;

void network_interface_manager() {
    // Initialize mutex and semaphores
    pthread_mutex_init(&lock, NULL);
    sem_init(&empty_slots, 0, MAX_RECORDS);
    sem_init(&full_records, 0, 0);

    // Dynamically allocate memory for records
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = malloc(sizeof(record_t));
        if (!records[i]) {
            printf("Error allocating memory\n");
            return;
        }
    }

    // Initialize random number generator
    srand(time(NULL));

    while (1) {
        // Handle concurrent updates and invalid inputs
        pthread_mutex_lock(&lock);
        int key = get_next_key();
        if (key < 0 || key >= MAX_RECORDS) {
            printf("Invalid input range\n");
            return;
        }
        record_t* rec = &records[key];
        sem_wait(&empty_slots);
        if (rec->data.l > 1000) {
            printf("Invalid data value\n");
            sem_post(&empty_slots);
            pthread_mutex_unlock(&lock);
            continue;
        }

        // Update record with new data
        rec->timestamp = time(NULL);
        rec->metadata[0] = 'A';

        // Clean up unused records
        int i = 0;
        while (i < MAX_RECORDS) {
            if (records[i]->timestamp + MAX_UPDATE_DURATION < time(NULL)) {
                free(records[i]);
                memmove(&records[i], &records[i+1], sizeof(record_t*) * (MAX_RECORDS - i - 1));
                sem_post(&full_records);
                i++;
            } else {
                break;
            }
        }

        // Re-allocate memory if necessary
        int total_records = MAX_RECORDS - i;
        record_t** new_records = realloc(records, sizeof(record_t*) * total_records);
        if (!new_records) {
            printf("Memory allocation failed\n");
            return;
        }
        records = new_records;

        sem_post(&empty_slots);

        pthread_mutex_unlock(&lock);
    }

    // Clean up and free memory
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i]);
    }
    free(records);
    pthread_mutex_destroy(&lock);
    sem_destroy(&empty_slots);
