// Define the custom data structure for network interface configuration settings
typedef struct {
    char *name;
    char *ip_address;
    char *subnet_mask;
    int port_config;
    double latency;
    double throughput;
} NetworkInterfaceConfig;

// Define the dynamic array of network interface configurations
typedef struct {
    size_t capacity;
    size_t length;
    NetworkInterfaceConfig **configs;
    pthread_mutex_t lock;
} NetworkInterfaceConfigs;

// Initialize and return a new dynamic array for managing network interfaces
NetworkInterfaceConfigs *network_interface_configs_init(size_t initial_capacity) {
    NetworkInterfaceConfigs *configs = (NetworkInterfaceConfigs *)malloc(sizeof(NetworkInterfaceConfigs));
    configs->capacity = initial_capacity;
    configs->length = 0;
    configs->configs = (NetworkInterfaceConfig **)calloc(configs->capacity, sizeof(NetworkInterfaceConfig *));
    pthread_mutex_init(&configs->lock, NULL);
    return configs;
}

// Resize the dynamic array to accommodate additional network interfaces
void network_interface_configs_resize(NetworkInterfaceConfigs *configs, size_t new_capacity) {
    NetworkInterfaceConfigs *new_configs = (NetworkInterfaceConfigs *)malloc(sizeof(NetworkInterfaceConfigs));
    new_configs->capacity = new_capacity;
    new_configs->length = configs->length;
    new_configs->configs = (NetworkInterfaceConfig **)calloc(new_configs->capacity, sizeof(NetworkInterfaceConfig *));

    // Copy existing configurations to the new array
    for (size_t i = 0; i < configs->length; i++) {
        NetworkInterfaceConfig *config = configs->configs[i];
        new_configs->configs[i] = config;
    }

    // Free old array and replace with new one
    free(configs);
    pthread_mutex_lock(&configs->lock);
    configs = new_configs;
    pthread_mutex_unlock(&configs->lock);
}

// Add a new network interface configuration to the dynamic array
void network_interface_configs_add(NetworkInterfaceConfigs *configs, NetworkInterfaceConfig *config) {
    pthread_mutex_lock(&configs->lock);

    // Check if there is space in the array for the new configuration
    if (configs->length >= configs->capacity) {
        size_t new_capacity = configs->capacity * 2;
        network_interface_configs_resize(configs, new_capacity);
    }

    // Add the new configuration to the end of the array
    configs->configs[configs->length] = config;
    configs->length++;

    pthread_mutex_unlock(&configs->lock);
}

// Remove a network interface configuration from the dynamic array
void network_interface_configs_remove(NetworkInterfaceConfigs *configs, NetworkInterfaceConfig *config) {
    pthread_mutex_lock(&configs->lock);

    // Find and remove the specified configuration from the array
    for (size_t i = 0; i < configs->length; i++) {
        if (configs->configs[i] == config) {
            // Move all remaining configurations to fill the gap
            for (size_t j = i + 1; j < configs->length; j++) {
                configs->configs[j - 1] = configs->configs[j];
            }

            // Decrement the length and free the removed configuration
            configs->length--;
            free(config);
            break;
        }
    }

    pthread_mutex_unlock(&configs->lock);
}

