record** allocateMemory(long seed, int numOffsets, int numRecords, int minValue, int maxValue) {
    // Allocate memory for offsets
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = i * seed;
    }

    // Allocate memory for keys
    int* keys = (int*)malloc(numRecords * sizeof(int));
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        while ((keys[i] = rand() % (maxValue - minValue + 1)) + minValue <= minValue) {}
    }

    // Allocate memory for records
    record** records = (record**)malloc(numRecords * sizeof(record));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->offset = &offsets[i % numOffsets];
        records[i]->key = &keys[i];
        // Random value within the range
        int randValue = rand() % (maxValue - minValue + 1) + minValue;
        records[i]->value = randValue;
    }

    return records;
}

void deallocateMemory(record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}

int main() {
    // Example usage
    long seed = 42;
    int numOffsets = 100;
    int numRecords = 500;
    int minValue = 1;
    int maxValue = 1000;

    record** records = allocateMemory(seed, numOffsets, numRecords, minValue, maxValue);

    // Use the allocated memory

    deallocateMemory(records, numRecords);

    return 0;
}

