// Define the TCP connection record structure
typedef struct {
    unsigned short conn_id;
    char remote_addr[16];
    char local_addr[16];
    int conn_status;
} TCP_CONNECTION_RECORD;

// Define the linked list node structure
typedef struct _node {
    TCP_CONNECTION_RECORD data;
    struct _node* next;
} NODE;

// Function to create a new node with initialized data
NODE* create_node(TCP_CONNECTION_RECORD data) {
    NODE* node = (NODE*)malloc(sizeof(NODE));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the beginning of the list
void insert_node(NODE** head, TCP_CONNECTION_RECORD data) {
    NODE* node = create_node(data);
    if (*head) {
        node->next = *head;
        *head = node;
    } else {
        *head = node;
    }
}

// Function to print the linked list
void print_list(NODE* head) {
    while (head) {
        printf("Conn ID: %hu, Remote Addr: %s, Local Addr: %s, Conn Status: %d\n",
            head->data.conn_id, head->data.remote_addr, head->data.local_addr, head->data.conn_status);
        head = head->next;
    }
}

// Function to serialize the linked list to a binary file
void serialize_list(NODE* head, FILE* file) {
    unsigned int node_count = 0;
    while (head) {
        fwrite(&node_count, sizeof(unsigned int), 1, file);
        fwrite(&head->data.conn_id, sizeof(short), 1, file);
        fwrite(head->data.remote_addr, sizeof(char), strlen(head->data.remote_addr)+1, file);
        fwrite(head->data.local_addr, sizeof(char), strlen(head->data.local_addr)+1, file);
        fwrite(&head->data.conn_status, sizeof(int), 1, file);
        head = head->next;
    }
}

// Function to deserialize the linked list from a binary file
NODE* deserialize_list(FILE* file) {
    NODE* head = NULL;
    unsigned int node_count;
    while (fread(&node_count, sizeof(unsigned int), 1, file)) {
        TCP_CONNECTION_RECORD data;
        fread(&data.conn_id, sizeof(short), 1, file);
        data.remote_addr[0] = '\0';
        fgets(data.remote_addr, sizeof(data.remote_addr), file);
        data.local_addr[0] = '\0';
        fgets(data.local_addr, sizeof(data.local_addr), file);
        fread(&data.conn_status, sizeof(int), 1, file);
        insert_node(&head, data);
    }
    return head;
}

// Function to compress the serialized linked list
unsigned char* compress_serialized_list(NODE* head) {
    unsigned long size = 0;
    while (head) {
        size += sizeof(unsigned int) + sizeof(short) + strlen(head->data.remote_addr) + strlen(head->data.local_addr) + sizeof(int);
        head = head->next;
    }
    unsigned char* compressed = (unsigned char*)malloc(size + zlibs_compressed_size(size));
    if (!compressed) return NULL;
    // Use zlib to compress the serialized list
    // ...
    return compressed;
}

// Function to decompress the compressed linked list
NODE* decompress_list(unsigned char* compressed, unsigned long size) {
    NODE* head = NULL;
    unsigned char* p = compressed;
    while (p < compressed + size) {
        unsigned int node_count;
        memcpy(&node_count, p, sizeof(node_count));
        p += sizeof(node_count);
        // Uncompress the serialized data
        // ...
        insert_node(&head, data);
        p += size - sizeof(node_count);
    }
    return head;
}

