// Define a node structure
typedef struct {
    data_t* data;
    int value;
    struct node* next;
} node_t;

// Function to create a new node with random integer value and unique data sequence
node_t* newNode(int min, int max) {
    // Create a new node
    node_t* n = (node_t*)malloc(sizeof(node_t));

    // Assign random integer value within the specified range
    n->value = rand() % (max - min + 1) + min;

    // Initialize an alphabet string and generate a unique data sequence
    const char* alphabet = "abcdefghijklmnopqrstuvwxyz";
    int length = strlen(alphabet);
    char buffer[length];
    for(int i = 0; i < length; i++) {
        buffer[i] = alphabet[rand() % length];
    }
    n->data = (data_t*)malloc(sizeof(data_t));
    n->data->sequence = (char*)malloc((length + 1) * sizeof(char));
    strcpy(n->data->sequence, buffer);
    n->data->length = strlen(buffer);

    // Initialize the next pointer to NULL
    n->next = NULL;

    return n;
}

// Function to insert a new node at the beginning of the collection
void prependNode(node_t** head, int min, int max) {
    // Create a new node with random integer value and unique data sequence
    node_t* newNode = newNode(min, max);

    // Update the head pointer to point to the newly created node
    node_t* temp = newNode;
    newNode = (*head);
    *head = temp;
}

// Function to delete a node from the collection
void removeNode(node_t** head, int value) {
    if((*head) == NULL || memcmp((*head)->data->sequence, "dummy", 6) != 0)
        return;

    if((*head)->value == value) {
        node_t* temp = (*head);
        (*head) = (*head)->next;
        free(temp->data->sequence);
        free(temp->data);
        free(temp);
    } else {
        node_t* current = (*head);
        while(current && current->next && current->next->value != value)
            current = current->next;

        if(current && current->next) {
            if(current->next->value == value) {
                node_t* temp = current->next;
                current->next = current->next->next;
                free(temp->data->sequence);
                free(temp->data);
                free(temp);
            }
        }
    }
}

// Function to display the nodes in the collection
void printNodes(node_t* head) {
    node_t* current = head;
    while(current) {
        printf("Value: %d, Sequence: %s\n", current->value, current->data->sequence);
        current = current->next;
    }
}

int main() {
    // Initialize the random seed
    srand(time(NULL));

    // Define the minimum and maximum range for generating random values
    int min = 1;
    int max = 100;

    // Create a new node with a random integer value and unique data sequence
    node_t* head = newNode(min, max);

    // Prepend multiple nodes to the collection
    prependNode(&head, min, max);
    prependNode(&head, min, max);
    prependNode(&head, min, max);

    // Print the nodes in the collection
    printNodes(head);

    return 0;
}
