node* create_node(data d, config c) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        // logging mechanism
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->d = d;
    new_node->c = c;
    new_node->next = NULL;
    return new_node;
}

void insert_data(data* data, node** head_ref) {
    node* new_node = create_node(*data, config);
    if (!new_node)
        return;

    new_node->next = *head_ref;
    *head_ref = new_node;
}

void delete_data(node** head_ref) {
    node* temp = *head_ref;
    *head_ref = (*head_ref)->next;
    free(temp);
}

void serialize_data(node* head, FILE* file) {
    while (head) {
        fwrite(&head->d, sizeof(data), 1, file);
        fwrite(&head->c.config_value, sizeof(double), 1, file);
        fwrite(&head->c.config_func, sizeof(void (*)(void*, ...)), 1, file);
        head = head->next;
    }
}

node* deserialize_data(FILE* file) {
    node* head = NULL;
    data temp_data;
    config temp_config;

    while (fread(&temp_data, sizeof(data), 1, file) == 1) {
        node* new_node = create_node(temp_data, temp_config);
        if (!new_node)
            return NULL;

        if (head) {
            node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        } else
            head = new_node;
    }

    return head;
}

void config_func(void* param, ...) {
    // implement the function pointer here
}

int main() {
