    char* hashed_password;
    int account_status;
    char** session_tokens;
} Account;

Account* create_account(char* username, char* email, char* hashed_password) {
    Account* new_account = (Account*)malloc(sizeof(Account));
    new_account->username = strdup(username);
    new_account->email = strdup(email);
    new_account->hashed_password = strdup(hashed_password);
    new_account->account_status = 0;
    new_account->session_tokens = NULL;
    return new_account;
}

void add_account(Account** accounts, int* size, Account* new_account) {
    *size += 1;
    *accounts = (Account*)realloc(*accounts, sizeof(Account) * (*size));
    memcpy(&(*accounts)[*size - 1], &new_account, sizeof(Account));
}

void remove_account(Account** accounts, int* size, char* username) {
    for (int i = 0; i < *size; i++) {
        if (strcmp(accounts[i]->username, username) == 0) {
            for (int j = i + 1; j < *size; j++) {
                accounts[j - 1] = accounts[j];
            }
            free(accounts[*size - 1]);
            *size -= 1;
            return;
        }
    }
}

void update_account(Account** accounts, int* size, char* username, char* new_email, char* new_hashed_password) {
    for (int i = 0; i < *size; i++) {
        if (strcmp(accounts[i]->username, username) == 0) {
            free(accounts[i]->email);
            free(accounts[i]->hashed_password);
            accounts[i]->email = strdup(new_email);
            accounts[i]->hashed_password = strdup(new_hashed_password);
            return;
        }
    }
}

void update_session_tokens(Account** accounts, int* size, char* username, char** new_tokens) {
    for (int i = 0; i < *size; i++) {
        if (strcmp(accounts[i]->username, username) == 0) {
            free(accounts[i]->session_tokens);
            accounts[i]->session_tokens = new_tokens;
            return;
        }
    }
}

void print_account(Account* account) {
    printf("Username: %s\n", account->username);
    printf("Email: %s\n", account->email);
    printf("Hashed Password: %s\n", account->hashed_password);
    printf("Account Status: %d\n", account->account_status);
    printf("Session Tokens:\n");
    for (int i = 0; account->session_tokens[i]; i++) {
        printf("%s\n", account->session_tokens[i]);
    }
}

int main() {
    // Example usage
    Account* accounts = NULL;
    int size = 0;

    Account* new_account1 = create_account("user1", "user1@example.com", "hashed_password_1");
    add_account(&accounts, &size, new_account1);
    print_account(accounts[0]);

    Account* new_account2 = create_account("user2", "user2@example.com", "hashed_password_2");
    add_account(&accounts, &size, new_account2);
    print_account(accounts[1]);

    remove_account(&accounts, &size, "user1");
    print_account(accounts[0]);

    update_account(&accounts, &size, "user2", "new_user2@example.com", "hashed_password_3");
