['```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

// Structure to represent the database
typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} Database;

Database* create_database(size_t initial_capacity) {
    Database* db = (Database*)malloc(sizeof(Database));
    db->records = (Record*)calloc(initial_capacity, sizeof(Record));
    db->capacity = initial_capacity;
    db->size = 0;
    pthread_mutex_init(&db->mutex, NULL);
    return db;
}

void init_database(Database* db) {
    pthread_mutex_lock(&db->mutex);
    for (size_t i = 0; i < db->size; i++) {
        // Set the value of each record's integer field to a random value within a given range
        srand(time(NULL));
        int random_key = rand() % 1000000;
        Record* record = &db->records[i];
        record->key = random_key;
        record->offset = (long)i; // Assuming offset is an index-based value
    }
    pthread_mutex_unlock(&db->mutex);
}

int validate_records(Database* db) {
    pthread_mutex_lock(&db->mutex);
    for (size_t i = 0; i < db->size; i++) {
        Record* record = &db->records[i];
        if (record->key == -1 || record->offset > db->size) {
            // Record is invalid, return error code
            pthread_mutex_unlock(&db->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&db->mutex);
    return 0;
}

void add_record(Database* db, int key, long offset) {
    pthread_mutex_lock(&db->mutex);
    if (db->size >= db->capacity) {
        // Resize the array if initial capacity is exceeded
        db->capacity *= 2;
        db->records = (Record*)realloc(db->records, sizeof(Record) * db->capacity);
    }
    Record* new_record = &db->records[db->size];
    new_record->key = key;
    new_record->offset = offset;
    db->size++;
    pthread_mutex_unlock(&db->mutex);
}

void save_to_disk(Database* db, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        // Error opening file
        return;
    }
    for (size_t i = 0; i < db->size; i++) {
        Record* record = &db->records[i];
        fwrite(&record, sizeof(Record), 1, file);
    }
    fclose(file);
}

Database* load_from_disk(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        // Error opening file
        return NULL;
    }
    Database* db = create_database(10); // Initial capacity of 10
    size_t record_count = 0;
    while (fread(&db->records[record_count], sizeof(Record), 1, file) > 0) {
        record_count++;
    }
    db->size = record_count;
    fclose(file);
    return db;
}

void free_database(Database* db) {
    pthread_mutex_lock(&db->mutex);
    if (db != NULL) {
        free(db->records);
        pthread_mutex_unlock(&db->mutex);
    }
}
