#include <string.h>

typedef struct {
    int size;
    void* ptr;
} MemoryBlock;

void* my_malloc(size_t size, char type) {
    // Log memory allocation request
    FILE* log = fopen("memory.log", "a");
    fprintf(log, "Allocating %zu bytes of type '%c'...\n", size, type);
    fclose(log);

    void* ptr = malloc(size);
    if (!ptr) {
        // Handle allocation failure
        printf("Memory allocation failed!\n");
        return NULL;
    }

    MemoryBlock block;
    block.size = size;
    block.ptr = ptr;

    return &block;
}

void my_free(void* mem_block) {
    // Cast the void pointer back to the actual type (MemoryBlock)
    MemoryBlock* block = (MemoryBlock*)mem_block;

    if (!block->ptr) return; // Don't free null pointers

    // Log memory deallocation request
    FILE* log = fopen("memory.log", "a");
    fprintf(log, "Deallocating %zu bytes of type '%c'...\n", block->size, (char)0);
    fclose(log);

    free(block->ptr);
}

int main() {
    void* int_arr = my_malloc(1024, 'i');
    void* long_arr = my_malloc(2048, 'l');
    // Custom user-defined data type
    void* custom_arr = my_malloc(512, (char)0);

    // Use the allocated memory...
    // ...and then release it when done
    my_free(int_arr);
    my_free(long_arr);
    my_free(custom_arr);

    return 0;
}
