#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    float value;
    char label;
    int timestamp;
    bool valid;
} sensor_data;

void manage_sensor_data(sensor_data** data, size_t* num_data) {
    // Initialize a priority queue to store the valid structs
    void** queue = (void**)malloc(sizeof(void*) * 1000);
    size_t queue_size = 0;

    for (size_t i = 0; i < *num_data; i++) {
        if (!data[i]->valid) continue; // Filter out invalid data

        // Insert the valid struct into the priority queue
        void* node = malloc(sizeof(sensor_data));
        memcpy(node, data[i], sizeof(sensor_data));
        queue[queue_size++] = node;
    }

    // Sort the valid structs in ascending order based on timestamp
    qsort(queue, queue_size, sizeof(void*), compare_timestamp);

    *num_data = queue_size; // Update the number of valid structs

    // Free the memory allocated for the priority queue
    for (size_t i = 0; i < queue_size; i++) {
        free((void*)queue[i]);
    }
    free(queue);
}

int compare_timestamp(const void* a, const void* b) {
    sensor_data* data_a = (sensor_data*)a;
    sensor_data* data_b = (sensor_data*)b;

    if (data_a->timestamp < data_b->timestamp)
        return -1;
    else if (data_a->timestamp > data_b->timestamp)
        return 1;
    else
        return 0; // Timestamps are equal, use a stable sorting algorithm
}

int main() {
    sensor_data* data = malloc(sizeof(sensor_data) * 100);
    size_t num_data = 100;

    // Initialize the data structures with some example values
    for (size_t i = 0; i < num_data; i++) {
        data[i].value = rand();
        data[i].label = 'A' + i % 26;
        data[i].timestamp = i * 1000;
        data[i].valid = i % 2 == 0 ? true : false;
    }

    manage_sensor_data(&data, &num_data);

    // Print the sorted valid structs
    for (size_t i = 0; i < num_data; i++) {
        printf("Timestamp: %d, Value: %.2f, Label: %c\n", data[i].timestamp, data[i].value, data[i].label);
    }

    free(data);
    return 0;
}

