typedef struct {
    char* id;
    float value;
} Entry;

typedef struct {
    int size;
    int capacity;
    Entry** entries;
} List;

List* list_create() {
    List* list = (List*) malloc(sizeof(List));
    if (!list) return NULL; // handle memory allocation failure
    list->size = 0;
    list->capacity = 1;
    list->entries = (Entry**) malloc(sizeof(Entry*) * list->capacity);
    if (!list->entries) {
        free(list); // handle memory allocation failure
        return NULL;
    }
    return list;
}

void list_destroy(List* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->entries[i]->id); // deallocate id strings
        free(list->entries[i]); // deallocate entries
    }
    free(list->entries); // deallocate array of entries pointers
    free(list); // deallocate list structure itself
}

int list_add(List* list, char* id, float value) {
    if (list->size >= list->capacity) { // resize the array when necessary
        list->capacity *= 2;
        list->entries = (Entry**) realloc(list->entries, sizeof(Entry*) * list->capacity);
        if (!list->entries) return -1; // handle memory reallocation failure
    }
    Entry* entry = (Entry*) malloc(sizeof(Entry));
    if (!entry) return -1; // handle memory allocation failure
    entry->id = strdup(id); // allocate and copy id string
    entry->value = value;
    list->entries[list->size] = entry;
    list->size++;
    return 0;
}

int list_update(List* list, char* id, float value) {
    for (int i = 0; i < list->size; i++) {
        if (!strcmp(list->entries[i]->id, id)) { // find matching id
            list->entries[i]->value = value;
            return 0;
        }
    }
    return -1; // entry not found in the list
}

int list_iterate(List* list, void (*operation)(Entry*)) {
    for (int i = 0; i < list->size; i++) {
        operation(list->entries[i]);
    }
    return 0;
}
