#include <string.h>
#include <time.h>

typedef struct {
    char* id;
    int priority;
    struct node* next;
} node;

node* init_node(char* id, int priority) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return NULL;
    new_node->id = strdup(id);
    new_node->priority = priority;
    new_node->next = NULL;
    return new_node;
}

void free_node(node* node) {
    if (!node) return;
    free(node->id);
    free(node);
}

node** array_of_nodes(int size) {
    node** nodes = (node**)malloc(sizeof(node*) * size);
    for (int i = 0; i < size; ++i)
        nodes[i] = NULL;
    return nodes;
}

void free_array(node** array, int size) {
    for (int i = 0; i < size; ++i)
        if (array[i])
            free_node(array[i]);
    free(array);
}

node* add_to_end(node** head, node* new_node) {
    if (!*head) {
        *head = new_node;
        return new_node;
    }
    node* current = *head;
    while (current->next)
        current = current->next;
    current->next = new_node;
    return *head;
}

void print_list(node* head) {
    node* current = head;
    while (current) {
        printf("%s, priority: %d\n", current->id, current->priority);
        current = current->next;
    }
}

int main() {
    srand(time(NULL));
    int num_nodes = 10;
    node** nodes = array_of_nodes(num_nodes);

    for (int i = 0; i < num_nodes; ++i) {
        char id[20];
        sprintf(id, "Node_%d", i);
        node* new_node = init_node(id, rand() % 100);
        if (!new_node) break;
        nodes[i] = new_node;
    }

    for (int i = 0; i < num_nodes - 1; ++i)
        add_to_end(&nodes[0], nodes[i]);

    print_list(nodes[0]);
}
