#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    long timestamp;
} CacheEntry;

typedef struct {
    CacheEntry* entries;
    size_t capacity;
    size_t size;
    size_t lru_index;
    pthread_mutex_t lock;
} LRU_Cache;

void cache_init(LRU_Cache* cache, size_t capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->lru_index = -1;
    pthread_mutex_init(&cache->lock, NULL);
}

LRU_Cache* lru_cache_new(size_t capacity) {
    LRU_Cache* cache = (LRU_Cache*)malloc(sizeof(LRU_Cache));
    if (!cache) return NULL;
    cache_init(cache, capacity);
    return cache;
}

void cache_add_entry(LRU_Cache* cache, int key, long timestamp) {
    pthread_mutex_lock(&cache->lock);

    // Check for LRU eviction
    while (cache->size == cache->capacity) {
        CacheEntry* oldest = &cache->entries[cache->lru_index];
        // Evict the oldest entry and update the index
        cache->lru_index = (cache->lru_index + 1) % cache->capacity;
        free(oldest);
        cache->size--;
    }

    // Add new entry at LRU position
    CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    if (!new_entry) {
        pthread_mutex_unlock(&cache->lock);
        return; // Out of memory, error handling needed
    }
    new_entry->key = key;
    new_entry->timestamp = timestamp;

    cache->entries[cache->lru_index] = new_entry;
    cache->size++;
    cache->lru_index = (cache->lru_index + 1) % cache->capacity;

    pthread_mutex_unlock(&cache->lock);
}

void* cache_get_entry(LRU_Cache* cache, int key) {
    pthread_mutex_lock(&cache->lock);

    // Search for the entry
    size_t i;
    for (i = 0; i < cache->size; i++) {
        if (cache->entries[i].key == key) {
            // Update the timestamp and mark as most recent
            cache->entries[i].timestamp = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return &cache->entries[i];
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL; // Entry not found
}

void lru_cache_free(LRU_Cache* cache) {
    if (!cache) return;
    pthread_mutex_destroy(&cache->lock);

    for (size_t i = 0; i < cache->capacity; i++) {
        free(cache->entries[i]);
    }
    free(cache);
}
