#include <unistd.h>

typedef struct {
    char *id;
    double value;
    char *path;
    off_t size;
    time_t lastModified;
} DataEntry;

typedef struct {
    DataEntry *entries;
    int capacity, size;
} DataList;

DataList *dataListCreate(int initialCapacity) {
    DataList *list = (DataList *)malloc(sizeof(DataList));
    list->capacity = initialCapacity;
    list->size = 0;
    list->entries = (DataEntry *)calloc(initialCapacity, sizeof(DataEntry));
    return list;
}

void dataListDestroy(DataList *list) {
    if (list == NULL)
        return;
    for (int i = 0; i < list->size; i++)
        free(list->entries[i].id);
    free(list->entries);
    free(list);
}

int dataListAdd(DataList *list, DataEntry *entry) {
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->entries = (DataEntry *)realloc(list->entries, sizeof(DataEntry) * list->capacity);
    }
    list->entries[list->size] = *entry;
    list->size++;
    return 0;
}

int dataListGet(DataList *list, int index, DataEntry *entry) {
    if (index < 0 || index >= list->size)
        return -1; // out of bounds
    *entry = list->entries[index];
    return 0;
}

void dataListUpdate(DataList *list, int index, DataEntry *entry) {
    if (index < 0 || index >= list->size)
        return; // out of bounds
    memcpy(&list->entries[index], entry, sizeof(DataEntry));
}

int dataListReadFile(DataList *list, int index) {
    DataEntry entry;
    if (dataListGet(list, index, &entry)) {
        int fd = open(entry.path, O_RDONLY);
        if (fd < 0)
            return -1; // file not found
        struct stat sb;
        fstat(fd, &sb);
        entry.size = sb.st_size;
        close(fd);
    }
    return 0;
}
