void filter_dom_tree(Node* root, char* selector, int threshold) {
    // Traverse the DOM tree and apply filtering conditions
    for (Node* node = root; node != NULL; node = node->next) {
        if (node->tag == 1 && strstr(node->name, selector)) { // Check element matches CSS selector
            char* text = node->text;
            size_t len = strlen(text);
            if (len < threshold) {
                char* formatted_text = malloc(len + 2); // Allocate memory for formatted text
                sprintf(formatted_text, "%s-", text);
                free(text);
                node->text = formatted_text; // Update the text content
            } else {
                node->text = strdup(""); // Return an empty string for elements exceeding the limit
            }
        }
    }
}

