#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_JOBS 1000
#define MAX_ENV_VARS 10
#define JOB_STATUS_NEW 0
#define JOB_STATUS_RUNNING 1
#define JOB_STATUS_COMPLETED 2
#define JOB_STATUS_CANCELLED 3

typedef struct Job {
    pthread_t thread_id;
    int status;
    char *command;
    int env_vars[MAX_ENV_VARS];
    int max_cpu_usage;
    int max_memory_usage;
} Job;

sem_t job_queue_sem;
sem_t job_status_update_sem;

Job jobs[MAX_JOBS];

void add_job(int job_index, char *command, int env_vars[], int max_cpu_usage, int max_memory_usage) {
    sem_wait(&job_queue_sem);
    jobs[job_index].status = JOB_STATUS_NEW;
    jobs[job_index].command = command;
    for (int i = 0; i < MAX_ENV_VARS; i++) {
        jobs[job_index].env_vars[i] = env_vars[i];
    }
    jobs[job_index].max_cpu_usage = max_cpu_usage;
    jobs[job_index].max_memory_usage = max_memory_usage;
    sem_post(&job_queue_sem);
}

int get_job_status(int job_index) {
    sem_wait(&job_status_update_sem);
    int status = jobs[job_index].status;
    sem_post(&job_status_update_sem);
    return status;
}

void cancel_job(int job_index) {
    sem_wait(&job_queue_sem);
    if (jobs[job_index].status == JOB_STATUS_NEW || jobs[job_index].status == JOB_STATUS_RUNNING) {
        pthread_cancel(jobs[job_index].thread_id);
        jobs[job_index].status = JOB_STATUS_CANCELLED;
    }
    sem_post(&job_queue_sem);
}

void *job_thread(void *args) {
    int job_index = *(int *)args;
    // Execute the job command and update its status
    printf("Job %d is running...\n", job_index);
    sleep(2); // Simulate job execution time
    jobs[job_index].status = JOB_STATUS_COMPLETED;
    printf("Job %d has completed.\n", job_index);
    free(args);
    return NULL;
}

int main() {
    sem_init(&job_queue_sem, 0, MAX_JOBS);
    sem_init(&job_status_update_sem, 0, 1);

    // Create a thread pool for concurrent job execution
    pthread_t threads[MAX_JOBS];
    for (int i = 0; i < MAX_JOBS; i++) {
        pthread_create(&threads[i], NULL, job_thread, &i);
    }

    add_job(0, "command1", {10, 20}, 100, 200);
    add_job(1, "command2", {30, 40}, 150, 250);

    // Example usage: cancel a specific job
    cancel_job(1);

    // Monitor job status updates and handle job completion or cancellation
    for (int i = 0; i < MAX_JOBS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&job_queue_sem);
    sem_destroy(&job_status_update_sem);

    return 0;
}
