    }
}

void freeArrays(int* arraysSize, long** offsets, int** keys, Record** records) {
    free(*arraysSize);
    free(**offsets);
    free(**keys);
    free(*records);
}

int main() {
    const int maxRecords = 10000;
    const int maxSize = (maxRecords * sizeof(Record)) + (2 * maxRecords * sizeof(int)) + (maxRecords * sizeof(long));
    const int logThreshold = 5000000;

    int arraysSize = 0;
    long* offsets = NULL;
    int* keys = NULL;
    Record* records = NULL;

    srand(time(NULL));

