typedef enum status_type {
    PENDING,
    COMPLETED,
    FAILED
} status_type;

typedef struct transaction {
    time_t timestamp;
    double amount;
    status_type status;
} transaction;

transaction* transactions = NULL;
int transaction_count = 0;
FILE* log_file = NULL;

void* log_transaction(void* ptr) {
    transaction* t = (transaction*) ptr;
    char buffer[LOG_BUFFER_SIZE];
    strftime(buffer, LOG_BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", localtime(&t->timestamp));
    fprintf(log_file, "%s | amount: %.2lf | status: %s\n", buffer, t->amount, (t->status == PENDING) ? "PENDING" : (t->status == COMPLETED) ? "COMPLETED" : "FAILED");
    return NULL;
}

void log_transactions() {
    pthread_t* threads = (pthread_t*) malloc(transaction_count * sizeof(pthread_t));
    for(int i = 0; i < transaction_count; i++) {
        pthread_create(&threads[i], NULL, log_transaction, &transactions[i]);
    }
    for(int i = 0; i < transaction_count; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
}

double calculate_total_amount() {
    double total = 0;
    for(int i = 0; i < transaction_count; i++) {
        total += transactions[i].amount;
    }
    return total;
}

void add_transaction(transaction t) {
    if(transaction_count >= MAX_TRANSACTION_COUNT) {
        printf("Transaction limit reached. Cannot add more.\n");
        return;
    }
    transactions[transaction_count] = t;
    transaction_count++;
    log_transactions();
}

int main() {
    // Initialize logging
    log_file = fopen("transactions.log", "a+");
    if(log_file == NULL) {
        printf("Failed to open log file.\n");
        exit(1);
    }

    return 0;
}
