void dataManagementSystem(int numRecords, int minRNTI, int maxRNTI, int minTag, int maxTag, int budget) {
    // Initialize random number generator
    srand(time(NULL));

    // Calculate the total size of each record in bytes
    int recordSize = sizeof(record);

    // Calculate the total size of metadata structure in bytes
    int metaDataSize = sizeof(metadata);

    // Calculate the total memory needed for records and metadata
    int totalMemoryNeeded = numRecords * (recordSize + metaDataSize);

    if (totalMemoryNeeded > budget) {
        printf("Error: Insufficient memory. Requested %d bytes, but only %d bytes available.\n", totalMemoryNeeded, budget);
        return;
    }

    // Allocate memory for records and metadata
    record* records = malloc(numRecords * recordSize);
    metadata* metadataArray = malloc(numRecords * metaDataSize);

    if (!records || !metadataArray) {
        printf("Error: Memory allocation failed.\n");
        free(records);
        free(metadataArray);
        return;
    }

    // Initialize records and metadata
    for (int i = 0; i < numRecords; i++) {
        record* currentRecord = &records[i];
        metadata* currentMetadata = &metadataArray[i];

        // Assign random values to RNTI, RX_UE_INFORMATION_TAG, and CRC_INDICATION_REL8_TAG
        currentRecord->RNTI = rand() % (maxRNTI - minRNTI + 1) + minRNTI;
        currentRecord->RX_UE_INFORMATION_TAG = rand() % (maxTag - minTag + 1) + minTag;
        currentRecord->CRC_INDICATION_REL8_TAG = rand();

        // Initialize metadata flag
        currentMetadata->flag = 0;

        // Set pointer to record in metadata structure
        currentMetadata->ptr = currentRecord;
    }

    // Free allocated memory
    free(records);
    free(metadataArray);
}
