// Struct to hold a single measurement
typedef struct {
    float temperature;
    char* location;
} measurement_t;

// Struct to represent a report
typedef struct {
    time_t timestamp;
    int size; // Size of the report (number of measurements)
    measurement_t* measurements;
} report_t;

// Function to generate and analyze reports
void generateAndAnalyzeReports(int numReports, int maxMeasurementsPerReport) {
    // Allocate memory for reports array
    report_t* reports = (report_t*) malloc(numReports * sizeof(report_t));

    // Initialize report sizes and timestamps
    for (int i = 0; i < numReports; i++) {
        reports[i].timestamp = time(NULL);
        reports[i].size = 0;
    }

    // Read data from standard input and store in measurements array
    float* temperatures = (float*) malloc(maxMeasurementsPerReport * sizeof(float));
    char** locations = (char**) malloc(maxMeasurementsPerReport * sizeof(char*));

    // Process data, calculating average temperature for each report
    int totalMeasurements = 0;
    for (int i = 0; i < numReports; i++) {
        // Read measurements for this report
        int currentReportSize = 0;
        while (currentReportSize < maxMeasurementsPerReport) {
            scanf("%f %s", &temperatures[currentReportSize], locations[currentReportSize]);
            currentReportSize++;
        }

        // Calculate average temperature and identify location with highest temp
        float avgTemp = 0.0f;
        char* bestLocation = NULL;
        for (int j = 0; j < currentReportSize; j++) {
            avgTemp += temperatures[j];
            if (j == 0 || temperatures[j] > *bestLocation) {
                bestLocation = locations[j];
            }
        }

        // Store report data
        reports[i].size = currentReportSize;
        reports[i].measurements = (measurement_t*) malloc(currentReportSize * sizeof(measurement_t));
        for (int j = 0; j < currentReportSize; j++) {
            reports[i].measurements[j].temperature = temperatures[j];
            reports[i].measurements[j].location = locations[j];
        }
    }

    // Validate report integrity, checking for duplicate locations
    for (int i = 0; i < numReports; i++) {
        for (int j = 0; j < reports[i].size; j++) {
            bool found = false;
            for (int k = 0; k < i; k++) {
                if (strcmp(reports[k].measurements[j].location, reports[i].measurements[j].location) == 0) {
                    found = true;
                    break;
                }
            }
            if (!found) continue;

            // Duplicate location found; print error message and exit
            printf("Error: Duplicate location '%s' in report %d\n", reports[i].measurements[j].location, i);
            return;
        }
    }

    // Free allocated memory
    for (int i = 0; i < numReports; i++) {
        free(reports[i].measurements);
    }
    free(temperatures);
    free(locations);
    free(reports);
}
