#define MAX_RECORDS 1000
#define MAX_STRING_LENGTH 20
#define GROWTH_FACTOR 2
#define FLOATING_POINT_RANGE -1.0, 1.0

typedef struct {
    double value;
    char identifier[MAX_STRING_LENGTH];
} Record;

Record* create_list(int initial_size) {
    return malloc(initial_size * sizeof(Record));
}

void resize_list(Record** list, int new_size) {
    Record* new_list = realloc(*list, new_size * sizeof(Record));
    if (new_list == NULL) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
    *list = new_list;
}

int get_next_power_of_two(int n) {
    int result = 1;
    while (result < n) {
        result <<= 1;
    }
    return result;
}

void add_record(Record** list, int* size, char* identifier) {
    if (*size >= MAX_RECORDS) {
        printf("List is full\n");
        return;
    }

    Record* new_list = create_list(*get_next_power_of_two(*size + 1));
    for (int i = 0; i < *size; i++) {
        new_list[i] = (*list)[i];
    }
    free(*list);
    *list = new_list;

    if (!identifier) {
        identifier = "record";
    }

    (*list)[*size].value = (double)rand() / RAND_MAX;
    strncpy((*list)[*size].identifier, identifier, MAX_STRING_LENGTH - 1);

    (*size)++;
}

void print_list(Record* list, int size) {
    for (int i = 0; i < size; i++) {
        printf("Value: %f, Identifier: %s\n", list[i].value, list[i].identifier);
    }
}

int main() {
    Record* list = create_list(1);
    int size = 1;
    char characters[] = "abcdefghijklmnopqrstuvwxyz";
    srand(time(NULL));

    for (int i = 0; i < 10; i++) {
        add_record(&list, &size, i % sizeof(characters) / sizeof(characters[0]) ? characters : NULL);
    }

    print_list(list, size);

    return 0;
}

