} NFAPI_LTE_ue_context;

void* nfapi_lte_allocate(int size) {
    // Implement custom memory pool allocator to handle repeated allocations
    static void* mem_pool = NULL;
    if (mem_pool == NULL) {
        mem_pool = malloc(1024 * 1024); // Reserve initial 1MB for the memory pool
    }

    // Check if sufficient space available in the memory pool
    if (mem_pool + size > mem_pool + 1024 * 1024) {
        // Not enough space, allocate from system heap and adjust mem_pool accordingly
        void* allocation = malloc(size);
        memcpy(allocation, mem_pool, size - 1);
        mem_pool += size;
        return allocation;
    }

    // Sufficient space available in the memory pool
    void* allocation = mem_pool + (size % 1024 * 1024 == 0 ? (size / 1024) : ((size / 1024) + 1));
    return allocation;
}

int nfapi_lte_ue_context_count = 0;

NFAPI_LTE_ue_context* nfapi_lte_allocate_ue_context(int n) {
    NFAPI_LTE_ue_context* ue_contexts = NULL;

    for (int i = 0; i < n; i++) {
        // Dynamically adjust resource usage based on system load
        if (ue_context_count >= 50,000) { // Queue allocations during high demand periods
            // Implement queueing mechanism here
        }

        NFAPI_LTE_ue_context* ue_context = (NFAPI_LTE_ue_context*)nfapi_lte_allocate(sizeof(NFAPI_LTE_ue_context));
        if (ue_context == NULL) {
            return NULL; // Handle insufficient memory condition
        }

        ue_context->pci = i;
        ue_context->fbi = 0;
        ue_context->pdcch_candidate_indications = NULL;

        // Track the number of successfully allocated UE contexts
        if (ue_context_count == 0) {
            ue_contexts = ue_context;
        } else {
            NFAPI_LTE_ue_context* temp = ue_contexts;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = ue_context;
        }

        ue_context_count++;
    }

    return ue_contexts;
}

void nfapi_lte_free_ue_context(NFAPI_LTE_ue_context* ue_context) {
    if (ue_context == NULL)
        return;

    // Implement mechanism to track and free dynamically allocated resources
    while (ue_context->pdcch_candidate_indications != NULL) {
        NFAPI_LTE_ue_context* temp = ue_context->pdcch_candidate_indications;
        ue_context->pdcch_candidate_indications = temp->next;
        free(temp);
    }

    free(ue_context);
}

void nfapi_lte_free_ue_contexts(NFAPI_LTE_ue_context* ue_contexts) {
    if (ue_contexts == NULL)
