using System.Text;

public class AesGcmDecryptor
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] associatedData = null, byte[] nonce = null)
    {
        using (var aesAlg = CreateAesAlgorithm(encryptionKey))
        {
            if (nonce == null)
                nonce = GenerateRandomNonce();

            // Encrypt the nonce
            using (var encryptor = aesAlg.CreateEncryptor())
            {
                var encryptedNonce = encryptor.TransformFinalBlock(nonce, 0, nonce.Length);
                associatedData = CombineByteArrays(associatedData, encryptedNonce);
            }

            using (var decryptor = aesAlg.CreateDecryptor())
            {
                try
                {
                    var decryptedBytes = DecryptStream(decryptor, ciphertext, associatedData);
                    return decryptedBytes;
                }
                catch (CryptographicException ex)
                {
                    // Handle decryption errors
                    throw new Exception("Decryption failed: " + ex.Message);
                }
                finally
                {
                    aesAlg.Dispose();
                }
            }
        }
    }

    private static Aes GcmAes { get; set; }

    private static Aes CreateAesAlgorithm(byte[] encryptionKey)
    {
        if (GcmAes == null)
        {
            using (var aesAlg = Aes.Create())
            {
                aesAlg.Key = encryptionKey;
                aesAlg.Mode = CipherMode.GCM;
                GcmAes = aesAlg;
            }
        }

        return GcmAes;
    }

    private static byte[] GenerateRandomNonce()
    {
        var nonceBytes = new byte[12]; // 96-bit random nonce
        using (var rngCryptoServiceProvider = RNGCryptoServiceProvider.Create())
        {
            rngCryptoServiceProvider.GetBytes(nonceBytes);
        }
        return nonceBytes;
    }

    private static byte[] CombineByteArrays(byte[] arr1, byte[] arr2)
    {
        var combined = new byte[arr1.Length + arr2.Length];
        Array.Copy(arr1, 0, combined, 0, arr1.Length);
        Array.Copy(arr2, 0, combined, arr1.Length, arr2.Length);
        return combined;
    }

    private static byte[] DecryptStream(Aes aesAlg, byte[] ciphertext, byte[] associatedData)
    {
        using (var ms = new MemoryStream(ciphertext))
        {
            using (var cs = new CryptoStream(ms, aesAlg.CreateDecryptor(), CryptoStreamMode.Read))
            {
                var decryptedBytes = new byte[ciphertext.Length];
                cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                return decryptedBytes;
            }
        }
    }
}
