    int **edges = (int **)malloc((nodeId + 1) * sizeof(int *));
    for (int i = 0; i <= nodeId; i++) {
        edges[i] = (int *)malloc((numEdges) * sizeof(int));
    }

    // Add edges to node
    for (int i = 0; i < numEdges; i++) {
        int edgeId = rand() % 100;
        edges[nodeId][i] = edgeId;
    }

    return graph;
}

void serializeGraph(void *graph, char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Failed to open file.\n");
        return;
    }
    fwrite(graph, 1, sizeof(int), fp);
    fclose(fp);
}
