#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MIN_KEY 1
#define MAX_KEY 1000000

typedef struct {
    int key;
    long* offset;
    // add more metadata as needed
} record;

record** records = NULL;
int numRecords = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateRecord() {
    record* newRecord = (record*)malloc(sizeof(record));
    if (!newRecord) {
        return NULL; // memory allocation failed
    }
    newRecord->key = -1; // initialize with invalid key value
    newRecord->offset = (long*)malloc(sizeof(long));
    if (!newRecord->offset) {
        free(newRecord);
        return NULL; // memory allocation failed
    }
    return newRecord;
}

void freeRecord(record* recordToFree) {
    if (recordToFree) {
        free(recordToFree->offset);
        free(recordToFree);
    }
}

int findAvailableKey() {
    for (int i = MIN_KEY; i <= MAX_KEY; i++) {
        int isAvailable = 1;
        for (int j = 0; j < numRecords; j++) {
            if (records[j]->key == i) {
                isAvailable = 0;
                break;
            }
        }
        if (isAvailable) {
            return i;
        }
    }
    return -1; // all keys used up
}

void sortOffsets(record** records, int numRecords) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numRecords - 1; i++) {
        for (int j = 0; j < numRecords - i - 1; j++) {
            if (records[j]->offset > records[j + 1]->offset) {
                record* tempRecord = *records++;
                *records-- = tempRecord;
            }
        }
    }
    pthread_mutex_unlock(&mutex);
}

void addRecord(int key, long offset) {
    pthread_mutex_lock(&mutex);
    int newKey = findAvailableKey();
    if (newKey == -1) {
        printf("Error: all keys in use.\n");
        return;
    }
    record* newRecord = (record*)malloc(sizeof(record));
    newRecord->key = newKey;
    newRecord->offset = (long*)malloc(sizeof(long));
    *newRecord->offset = offset;
    if (!records) {
        records = (record**)malloc(sizeof(record*));
    }
    records[numRecords++] = newRecord;
    sortOffsets(records, numRecords);
    pthread_mutex_unlock(&mutex);
}

void removeRecord(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->key == key) {
            freeRecord(records[i]);
            for (int j = i + 1; j < numRecords; j++) {
                records[j - 1] = records[j];
            }
            numRecords--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void printRecords() {
    pthread_mutex_lock(&mutex);
    printf("Records:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("%d: %ld\n", records[i]->key, *records[i]->offset);
    }
    pthread_mutex_unlock(&mutex);
}

void* threadFunction(void* arg) {
    // example usage
    int key = 5;
    long offset = 123456789;
    addRecord(key, offset);
    printRecords();
    removeRecord(key);
    printRecords();
    return NULL;
}

int main() {
    pthread_t threads[2];
    for (int i = 0; i < 2; i++) {
        pthread_create(&threads[i], NULL, threadFunction, NULL);
    }
    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
