            // Remove existing configuration from the dynamic array
            for (int i = 0; i < poolSize - 1; i++) {
                memoryPool[i] = memoryPool[i + 1];
            }
            free(memoryPool[poolSize - 1]);
            poolSize--;
        } else if (updateNetworkConfig()) {
            // Update existing configuration in the dynamic array
            for (int i = 0; i < poolSize; i++) {
                if (memoryPool[i]->interfaceName == currentInterface) {
                    memcpy(memoryPool[i], updatedConfig, sizeof(struct networkConfig));
                }
            }
        }

        // Handle concurrent access and updates to shared resources
        pthread_mutex_lock(&mutex);
        // Update the dynamic array as needed
        pthread_mutex_unlock(&mutex);

        // Perform garbage collection to reclaim memory for unused records
        void **garbage = (void **)malloc(poolSize * sizeof(void *));
        memcpy(garbage, memoryPool, poolSize * sizeof(void *));
        for (int i = 0; i < poolSize - 1; i++) {
            free(memoryPool[i]);
        }
        memoryPool = garbage;
        poolSize--;
    }

    // Free dynamically allocated memory
    for (int i = 0; i < poolSize; i++) {
        free(memoryPool[i]);
    }
    free(memoryPool);

    // Close cryptographic primitives
    EVP_remove_cipher(NULL, "AES");
    EVP_remove_digest(NULL, "MD5");
}
