#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 10000000 // 10 million records
#define TABLE_SIZE 1024
#define PROBE_DEPTH 5

typedef struct {
    int key;
    int value;
} record;

record* initRecords(int capacity) {
    return (record*) malloc(capacity * sizeof(record));
}

int hash(int key) {
    return key % TABLE_SIZE;
}

void insert(record* records, int capacity, int key, int value) {
    int index = hash(key);
    for (int i = 0; i < PROBE_DEPTH && records[index].key != -1; i++) {
        if (records[index].key == key) {
            // Key already exists, update its value
            records[index].value = value;
            return;
        }
        index = (index + 1) % TABLE_SIZE;
    }
    if (records[index].key == -1) {
        // Slot empty, insert new record
        int j;
        for (j = capacity; j > 0; j--) {
            records[j-1] = records[--j];
        }
        records[0].key = key;
        records[0].value = value;
    } else {
        // Collision occurred, probe further
        index = hash(key);
        int k;
        for (k = PROBE_DEPTH; k > 0; k--) {
            if (records[(index + k) % TABLE_SIZE].key == -1) {
                records[(index + k) % TABLE_SIZE].key = key;
                records[(index + k) % TABLE_SIZE].value = value;
                return;
            }
        }
    }
}

record* getRecord(record* records, int capacity, int key) {
    int index = hash(key);
    for (int i = 0; i < PROBE_DEPTH && records[index].key != -1; i++) {
        if (records[index].key == key) {
            return &records[index];
        }
        index = (index + 1) % TABLE_SIZE;
    }
    return NULL; // Key not found
}

void freeRecords(record* records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        free(&records[i]);
    }
    free(records);
}
