#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    int id;
    char name[64];
    char email[64];
    char password[64];
} User;

// Cache for frequently accessed user data
static json_object *user_cache = NULL;
sem_t *cache_sem = 0;

// Database for storing user accounts
sqlite3 *db = NULL;

void init_cache() {
    if (user_cache == NULL) {
        user_cache = json_object_new();
        sem_init(cache_sem, 0, 1);
    }
}

int update_account(int id, char* name, char* email, char* password) {
    sqlite3_stmt *stmt;
    const char *sql = "UPDATE users SET name=?, email=?, password=? WHERE id=?";
    int rc;

    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing statement: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    sqlite3_bind_text(stmt, 1, name, strlen(name), NULL);
    sqlite3_bind_text(stmt, 2, email, strlen(email), NULL);
    sqlite3_bind_text(stmt, 3, password, strlen(password), NULL);
    sqlite3_bind_int(stmt, 4, id);

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        printf("Error updating account: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    sqlite3_finalize(stmt);
    return 1;
}

int create_account(char* name, char* email, char* password) {
    sqlite3_stmt *stmt;
    const char *sql = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
    int rc;

    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing statement: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    sqlite3_bind_text(stmt, 1, name, strlen(name), NULL);
    sqlite3_bind_text(stmt, 2, email, strlen(email), NULL);
    sqlite3_bind_text(stmt, 3, password, strlen(password), NULL);

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        printf("Error creating account: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    sqlite3_finalize(stmt);
    return 1;
}

int delete_account(int id) {
    sqlite3_stmt *stmt;
    const char *sql = "DELETE FROM users WHERE id=?";
    int rc;

    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing statement: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    sqlite3_bind_int(stmt, 1, id);

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        printf("Error deleting account: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    sqlite3_finalize(stmt);
    return 1;
}

json_object *process_account(char* action, User user) {
    json_object *response = json_object_new();

    if (action == NULL || strcmp(action, "create") == 0) {
        int rc = create_account(user.name, user.email, user.password);

        if (!rc) {
            json_object_object_add(response, "status", json_object_new_string("error"));
            json_object_object_add(response, "message", json_object_new_string("Failed to create account"));
        } else {
            json_object_object_add(response, "status", json_object_new_string("success"));
            json_object_object_add(response, "message", json_object_new_string("Account created successfully"));
        }
    } else if (action == NULL || strcmp(action, "update") == 0) {
        int rc = update_account(user.id, user.name, user.email, user.password);

        if (!rc) {
            json_object_object_add(response, "status", json_object_new_string("error"));
            json_object_object_add(response, "message", json_object_new_string("Failed to update account"));
        } else {
            json_object_object_add(response, "status", json_object_new_string("success"));
            json_object_object_add(response, "message", json_object_new_string("Account updated successfully"));
        }
    } else if (action == NULL || strcmp(action, "delete") == 0) {
        int rc = delete_account(user.id);

        if (!rc) {
            json_object_object_add(response, "status", json_object_new_string("error"));
            json_object_object_add(response, "message", json_object_new_string("Failed to delete account"));
        } else {
            json_object_object_add(response, "status", json_object_new_string("success"));
            json_object_object_add(response, "message", json_object_new_string("Account deleted successfully"));
        }
    }

    return response;
}

int main() {
    // Initialize database and cache
    db = sqlite3_open_v2("user_database.db", NULL);
    if (db == NULL) {
        printf("Error opening database: %s\n", sqlite3_errmsg(db));
        return 0;
    }

    init_cache();

    // Handle user requests
    User user;
    char* action = "create";
    json_object *response;

    user.id = 1;
    user.name = "John Doe";
    user.email = "johndoe@example.com";
    user.password = "password123";

    response = process_account(action, user);

    // Log actions and close database
    sqlite3_close(db);

    return 0;
}
