// Initialize graph database with dynamic record sizes and validate integrity
void initializeGraphDatabase(int numRecords, int maxValuesPerRecord) {
    // Allocate memory for array of records
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Error: Memory allocation failed for records.\n");
        return;
    }

    // Initialize offset and key arrays for each record
    for (int i = 0; i < numRecords; i++) {
        records[i].values = (int*)malloc(maxValuesPerRecord * sizeof(int));
        if (!records[i].values) {
            printf("Error: Memory allocation failed for values in record %d.\n", i);
            return;
        }

        records[i].offsets = (long*)malloc((maxValuesPerRecord + 1) * sizeof(long));
        if (!records[i].offsets) {
            printf("Error: Memory allocation failed for offsets in record %d.\n", i);
            return;
        }
    }

    // Validate integrity of records
    for (int i = 0; i < numRecords; i++) {
        // Check for duplicate keys
        int keyCount = 0;
        for (int j = 0; j < maxValuesPerRecord; j++) {
            if (!records[i].values[j]) break;
            if (keyCount == 0 || records[i].values[j] != records[i].keys[keyCount - 1]) {
                keyCount++;
            } else {
                printf("Error: Duplicate key in record %d.\n", i);
                return;
            }
        }

        // Check for consistent offset values
        long prevOffset = -1;
        for (int j = 0; j < maxValuesPerRecord + 1; j++) {
            if (records[i].offsets[j] <= prevOffset) {
                printf("Error: Inconsistent offset value in record %d.\n", i);
                return;
            }
            prevOffset = records[i].offsets[j];
        }

        // Check for total number of elements in offsets matching sum of elements in keys
        long totalOffsets = 0;
        for (int j = 0; j < maxValuesPerRecord + 1; j++) {
            totalOffsets += records[i].offsets[j];
        }
        if (totalOffsets != keyCount) {
            printf("Error: Total number of elements in offsets does not match sum of elements in keys.\n");
            return;
        }
    }

    // Initialize graph database component
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        int vertexId = (int)(hash((const void*)(&records[i]), sizeof(Record)) % 10000);
        for (int j = 0; j < maxValuesPerRecord; j++) {
