pthread_mutex_t mutex_max_rnti = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* generate_nfastructures(int num_structures) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!structures) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_structures; i++) {
        structures[i].RX_UE_INFORMATION_TAG = rand();
        int rnti = rand() % 100000 + 1;

        while (rnti <= max_rnti) {
            rnti = rand() % 100000 + 1;
        }

        structures[i].RNTI = rnti;
        structures[i].CRC_INDICATION_REL8_TAG = rand();
        int crcflag = rand() & 1;
        structures[i].CRCFLAG = crcflag;
        structures[i].TX_POWER_LEVEL = rand() % 100 + 1;

        pthread_mutex_lock(&mutex_total_created);
        total_created++;
        pthread_mutex_unlock(&mutex_total_created);

        pthread_mutex_lock(&mutex_max_rnti);
        if (rnti > max_rnti) {
            max_rnti = rnti;
        }
        pthread_mutex_unlock(&mutex_max_rnti);
    }

    return structures;
}

void log_statistics(int num_structures, int interval) {
    static int last_logged = 0;
    static double avg_power_level = 0.0;
    static int total_logs = 0;

    if (total_logged >= interval) {
        printf("Total structures created: %d\n", total_created);
        printf("Average transmit power level: %.2f dBm\n", avg_power_level / interval);

        last_logged += interval;
        total_logs++;
        avg_power_level = 0.0;
    }

    if (total_logged < interval) {
        avg_power_level += log_total_TX_Power_Level(num_structures);
    }
}

int main() {
    int num_structures = 10000;
    int interval = 10;

    NFAPI_CRC_INDICATION_PDU_T* structures = generate_nfastructures(num_structures);

    if (!structures) {
        return -1;
    }

    log_statistics(num_structures, interval);

    free(structures);
    return 0;
}
