#include <random>
#include <chrono>

enum class AttackType {
    Melee,
    Ranged,
    Magic
};

struct ActionRecord {
    AttackType attackType;
    int cooldownTime;
};

class CombatStrategyModule {
public:
    virtual ~CombatStrategyModule() {}
    virtual std::vector<ActionRecord> generateActions() = 0;
};

class RandomAttackStrategy : public CombatStrategyModule {
public:
    std::vector<ActionRecord> generateActions() override {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> cooldownDist(1, 15);
        std::uniform_real_distribution<double> attackTypeProb(0.5);

        std::vector<ActionRecord> actions;

        for (int i = 0; i < 10; ++i) {
            if (attackTypeProb(gen) > 0.3) {
                actions.push_back({AttackType::Melee, cooldownDist(gen)});
            } else if (attackTypeProb(gen) > 0.2) {
                actions.push_back({AttackType::Ranged, cooldownDist(gen)});
            } else {
                actions.push_back({AttackType::Magic, cooldownDist(gen)});
            }
        }

        return actions;
    }
};

class DataRetrievalInterface {
public:
    virtual ~DataRetrievalInterface() {}
    virtual AttackType retrieveActionType() = 0;
};

class ActionExecutor {
public:
    ActionExecutor(CombatStrategyModule* strategyModule, DataRetrievalInterface* dataSource)
        : strategyModule_(strategyModule), dataSource_(dataSource) {}

    void executeActions(int iterations) {
        int totalActions = 0;

        for (int i = 0; i < iterations; ++i) {
            std::vector<ActionRecord> actions = strategyModule_->generateActions();

            for (const auto& action : actions) {
                AttackType attackType;
                int cooldownTime;

                if (dataSource_ != nullptr) {
                    attackType = dataSource_->retrieveActionType();
                    cooldownTime = 5; // hardcoded for now
                } else {
                    attackType = action.attackType;
                    cooldownTime = action.cooldownTime;
                }

                std::cout << "Executing action: " << getAttackTypeName(attackType) << " with cooldown time: " << cooldownTime << std::endl;

                if (dataSource_ != nullptr) {
                    // handle data source issues gracefully
                }
            }

            totalActions += actions.size();

            if ((i % 10 == 0 || i == iterations - 1) && dataSource_ != nullptr) {
                std::cout << "Total actions executed: " << totalActions << std::endl;
            }
        }
    }

private:
    CombatStrategyModule* strategyModule_;
    DataRetrievalInterface* dataSource_;

    std::string getAttackTypeName(AttackType attackType) {
        switch (attackType) {
            case AttackType::Melee:
                return "Melee";
            case AttackType::Ranged:
                return "Ranged";
            case AttackType::Magic:
                return "Magic";
        }
    }
};

// Load combat strategy modules
std::vector<std::unique_ptr<CombatStrategyModule>> loadModules() {
    std::vector<std::unique_ptr<CombatStrategyModule>> modules;

    // Add strategies here...
    modules.push_back(std::make_unique<RandomAttackStrategy>());

    return modules;
}

int main(int argc, char* argv[]) {
    std::vector<std::unique_ptr<CombatStrategyModule>> modules = loadModules();

    for (const auto& module : modules) {
        ActionExecutor executor(nullptr, nullptr);

        // Run tests
        for (int i = 0; i < 10; ++i) {
            executor.executeActions(5);
        }
    }

    return 0;
}
