```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure to represent tasks
typedef struct {
    char *name;
    int priority;
    time_t due_date;
    int status;
} Task;

// Define a structure to represent the task list
typedef struct {
    Task **tasks;
    int capacity;
    int size;
    int *hash_values;
} TaskList;

// Function to initialize the task list with a specified capacity
TaskList* init_task_list(int capacity) {
    TaskList *task_list = (TaskList*)malloc(sizeof(TaskList));
    task_list->capacity = capacity;
    task_list->size = 0;
    task_list->tasks = (Task**)malloc(capacity * sizeof(Task*));
    task_list->hash_values = (int*)calloc(capacity, sizeof(int));
    return task_list;
}

// Function to add a task to the list
void add_task(TaskList *task_list, char *name, int priority, time_t due_date) {
    Task *new_task = (Task*)malloc(sizeof(Task));
    new_task->name = name;
    new_task->priority = priority;
    new_task->due_date = due_date;
    new_task->status = 0;

    // Calculate the hash value for the task
    int hash_value = (int)name[0] + priority + due_date;
    int index = hash_value % task_list->capacity;

    // Check if the task list is full and needs to be resized
    if (task_list->size >= task_list->capacity / 2) {
        capacity *= 2;
        Task **new_tasks = (Task**)realloc(task_list->tasks, capacity * sizeof(Task*));
        int *new_hash_values = (int*)realloc(task_list->hash_values, capacity * sizeof(int));

        // Rehash the existing tasks
        for (int i = 0; i < task_list->size; i++) {
            new_tasks[index] = task_list->tasks[i];
            new_hash_values[index] = hash_value;
            index = (index + 1) % capacity;
        }
    }

    // Add the new task to the list
    task_list->tasks[task_list->size++] = new_task;
    task_list->hash_values[index] = hash_value;
}

// Function to remove a task from the list
void remove_task(TaskList *task_list, char *name) {
    for (int i = 0; i < task_list->size; i++) {
        if (strcmp(task_list->tasks[i]->name, name) == 0) {
            free(task_list->tasks[i]);
            memmove(&task_list->tasks[i], &task_list->tasks[i+1], (task_list->size - i - 1) * sizeof(Task*));
            task_list->size--;
        }
    }
}

// Function to view tasks in the list
void view_tasks(TaskList *task_list) {
    for (int i = 0; i < task_list->size; i++) {
        printf("Task %d: Name - %s, Priority - %d, Due Date - %lu\n", i+1, task_list->tasks[i]->name, task_list->tasks[i]->priority, task_list->tasks[i]->due_date);
    }
}

// Function to check the status of a task
int get_task_status(TaskList *task_list, char *name) {
    for (int i = 0; i < task_list->size; i++) {
        if (strcmp(task_list->tasks[i]->name, name) == 0) {
            return task_list->tasks[i]->status;
        }
    }
    return -1; // Task not found
}

// Function to update the status of a task
void update_task_status(TaskList *task_list, char *name, int new_status) {
    for (int i = 0; i < task_list->size; i++) {
        if (strcmp(task_list->tasks[i]->name, name) == 0) {
            task_list->tasks[i]->status = new_status;
        }
    }
}

// Function to handle errors and exceptions
void handle_error(const char *message) {
    printf("Error: %s\n", message);
    exit(1);
}

int main() {
    TaskList *task_list = init_task_list(10);

    add_task(task_list, "Task 1", 5, time(NULL));
    add_task(task_list, "Task 2", 3, time(NULL) + 3600);
    add_task(task_list, "Task 3", 4, time(NULL) + 7200);

    view_tasks(task_list);

    int status = get_task_status(task_list, "Task 1");
    if (status == -1) {
        handle_error("Task not found");
    }

    update_task_status(task_list, "Task 2", 1);

    return 0;
}
