void insert_sensor(double measurement, float timestamp) {
    Sensor* new_sensor = (Sensor*)malloc(sizeof(Sensor));
    new_sensor->measurement = measurement;
    new_sensor->timestamp = timestamp;
    new_sensor->identifier = malloc(strlen("sensor") + 1);
    strcpy(new_sensor->identifier, "sensor");
    pthread_mutex_lock(&lock);
    if (sensors == NULL) {
        sensors = new_sensor;
    } else {
        Sensor* current = sensors;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_sensor;
    }
    pthread_mutex_unlock(&lock);
}

void delete_sensor(char* identifier) {
    pthread_mutex_lock(&lock);
    Sensor* current = sensors;
    Sensor* previous = NULL;
    while (current != NULL) {
        if (strcmp(current->identifier, identifier) == 0) {
            if (previous == NULL) {
                sensors = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->identifier);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

