    records_serialize(records, file);
    fclose(file);

    file = fopen("records.bin", "rb");
    int deserialization_result = records_deserialize(records, file);
    fclose(file);

    if (deserialization_result < 0) {
        printf("Deserialization failed\n");
        return -1;
    }

    // Filter records based on key ranges
    int min_key = 5;
    int max_key = 15;
    int* filtered_keys = records_filter(records, min_key, max_key);

    // Handle concurrent access from multiple threads
    pthread_t thread;
    pthread_create(&thread, NULL, records_concurrent_access, NULL);
    pthread_join(thread);

    // Get statistics on memory usage and allocations
    int statistics_result = records_get_statistics(records);

    return 0;
}
