const fs = promisify(require('fs').promises);
const path = require('path');

async function processDirectory(dirPath) {
  const allowedExtensions = ['.txt', '.js'];
  const logService = require('./log-service');
  const retry = require('./retry');
  let totalProcessedFiles = 0;
  let failedFiles = [];

  await fs.readdir(dirPath).forEach(async (file) => {
    const filePath = path.join(dirPath, file);
    try {
      const stats = await fs.stat(filePath);
      if (stats.size > 10240 && allowedExtensions.includes(path.extname(file))) {
        const content = await fs.readFile(filePath, 'utf8', { encoding: 'buffer' });
        const parsedContent = parseContent(content);
        logService.log(`Processed file ${file} with size ${stats.size} and content ${parsedContent}`);
      }
    } catch (error) {
      if (error.code === 'ENOENT') {
        logService.log(`File not found: ${filePath}`);
      } else if (error.code === 'EACCES') {
        logService.log(`Access denied: ${filePath}`);
      } else {
        failedFiles.push({ filePath, error });
        await retry(() => fs.readFile(filePath), 3);
      }
    } finally {
      totalProcessedFiles++;
      console.log(`Processed files so far: ${Math.round((totalProcessedFiles / (await fs.readdir(dirPath).length)) * 100)}%`);
    }
  });

  return { successfulFiles: totalProcessedFiles, failedFiles };
}

function parseContent(content) {
