public class SensorDataProcessor {
    private static final int INITIAL_BUFFER_SIZE = 1000;
    private static final int BUFFER_GROWTH_RATE = 2;

    private ConcurrentHashMap<String, CopyOnWriteArrayList<SensorReading>> sensorReadingsMap;
    private DataPersistenceLayer dataPersistenceLayer;
    private CommandLineInterface commandLineInterface;

    public SensorDataProcessor() {
        this.sensorReadingsMap = new ConcurrentHashMap<>();
        this.dataPersistenceLayer = new DataPersistenceLayer();
        this.commandLineInterface = new CommandLineInterface();
    }

    public void manageSensorDataStream(SensorReading reading) {
        // Add the reading to the map
        sensorReadingsMap.computeIfAbsent(reading.getDeviceId(), k -> new CopyOnWriteArrayList<>()).add(reading);

        // Check if buffer needs to be resized
        if (sensorReadingsMap.size() * 2 > INITIAL_BUFFER_SIZE * BUFFER_GROWTH_RATE) {
            INITIAL_BUFFER_SIZE *= BUFFER_GROWTH_RATE;
            sensorReadingsMap = new ConcurrentHashMap<>(INITIAL_BUFFER_SIZE);
        }

        // Process and transform the readings
        processAndTransformReadings();

        // Persist the processed data
        persistData();
    }

    private void processAndTransformReadings() {
        // Implement your processing logic here
    }

    private void persistData() {
        // Write to data persistence layer
        dataPersistenceLayer.write(sensorReadingsMap.values().stream()
                .flatMap(list -> list.stream())
                .collect(Collectors.toList()));
    }
}

