#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Structure for record
typedef struct {
    int key;
    char* str;
    long offset;
} record_t;

// Dynamic array structure
typedef struct {
    record_t* records;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} dynamic_array_t;

// Function to initialize the dynamic array with specified sizes and randomize the keys
dynamic_array_t* init_dynamic_array(size_t num_records, int min_key, int max_key, long offset_max) {
    dynamic_array_t* arr = (dynamic_array_t*)malloc(sizeof(dynamic_array_t));
    if (!arr) return NULL;

    // Initialize dynamic array properties
    arr->records = (record_t*)malloc((num_records + (num_records / 4)) * sizeof(record_t));
    if (!arr->records) {
        free(arr);
        return NULL;
    }
    arr->capacity = num_records + (num_records / 4);
    arr->length = 0;

    // Initialize mutex for thread-safe access
    if (pthread_mutex_init(&arr->lock, NULL)) {
        free(arr->records);
        free(arr);
        return NULL;
    }

    // Randomize keys and populate records array
    for (size_t i = 0; i < arr->capacity; i++) {
        record_t* rec = &arr->records[i];
        int key = rand() % ((max_key - min_key) + 1) + min_key;
        rec->key = key;

        // Ensure unique keys and total sum does not exceed limit
        while (rec->key != key || (i > 0 && rec->key < arr->records[i-1].key)) {
            rec->key = rand() % ((max_key - min_key) + 1) + min_key;
        }

        // Initialize offset and string
        rec->offset = i;
        char str[20];
        sprintf(str, "Record %zu", i);
        rec->str = (char*)malloc(strlen(str) + 1);
        strcpy(rec->str, str);

        // Validate record integrity
        if (!rec->str || rec->key < 0 || rec->offset < 0) {
            free(rec->str);
            return NULL;
        }
    }

    return arr;
}

// Function to insert a new record into the dynamic array
int insert_record(dynamic_array_t* arr, int key, char* str, long offset) {
    pthread_mutex_lock(&arr->lock);

    // Check for capacity before insertion
    if (arr->length >= arr->capacity) {
        printf("Array full. Cannot insert more records.\n");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    record_t* rec = &arr->records[arr->length];
    rec->key = key;
    rec->str = (char*)malloc(strlen(str) + 1);
    strcpy(rec->str, str);
    rec->offset = offset;

    arr->length++;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Function to delete a record from the dynamic array
int delete_record(dynamic_array_t* arr, int key) {
    pthread_mutex_lock(&arr->lock);

    // Find and remove the record with the specified key
    for (size_t i = 0; i < arr->length; i++) {
        if (arr->records[i].key == key) {
            free(arr->records[i].str);
            memmove(&arr->records[i], &arr->records[i+1], (arr->length - i - 1) * sizeof(record_t));
            arr->length--;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Function to destroy the dynamic array and free allocated memory
void destroy_dynamic_array(dynamic_array_t* arr) {
    pthread_mutex_lock(&arr->lock);

    // Free records array and individual record strings
    for (size_t i = 0; i < arr->length; i++) {
        free(arr->records[i].str);
    }
    free(arr->records);

    // Release mutex and destroy
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);

    free(arr);
}

// Example usage:
int main() {
    srand(time(NULL));

