    pthread_attr_setscope(&attr, PTHREAD_SCOPE_SYSTEM);

    for (int i = 0; i < buffer_size; i++) {
        int* packet_id = (int*)malloc(sizeof(int));
        *packet_id = i;

        // Create a new thread to process each packet
        pthread_create(&thread_handles[i], &attr, packetProcessor, (void*)packet_id);

        // Wait for the thread to finish processing the packet
