#include <string.h>
#include <time.h>

// Define the transaction structure
typedef struct {
    int id;
    time_t timestamp;
    double amount;
} Transaction;

// Function to manage memory for transactions
Transaction** allocate_transactions(int num_transactions) {
    // Dynamically allocate memory for transactions
    Transaction** transactions = (Transaction**)malloc(num_transactions * sizeof(Transaction*));

    // Initialize each transaction structure
    for (int i = 0; i < num_transactions; i++) {
        transactions[i] = (Transaction*)malloc(sizeof(Transaction));
        transactions[i]->id = -1;
        transactions[i]->timestamp = 0;
        transactions[i]->amount = 0.0;
    }

    return transactions;
}

// Function to validate and initialize transactions
void init_transactions(Transaction** transactions, int num_transactions) {
    // Validate transaction integrity by checking for duplicate IDs
    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i]->id != -1) {
            printf("Error: Duplicate ID found in transaction %d\n", i);
            exit(1);  // Handle error gracefully
        }

        // Initialize timestamp and amount fields
        transactions[i]->timestamp = time(NULL);
        transactions[i]->amount = 0.0;
    }
}

// Function to sort transactions by timestamp
void sort_transactions(Transaction** transactions, int num_transactions) {
    qsort(transactions, num_transactions, sizeof(Transaction*), compare_transactions);
}

int compare_transactions(const void* a, const void* b) {
    Transaction* trans_a = *(Transaction**)a;
    Transaction* trans_b = *(Transaction**)b;

    if (trans_a->timestamp < trans_b->timestamp)
        return -1;
    else if (trans_a->timestamp > trans_b->timestamp)
        return 1;
    else
        return 0;  // IDs are equal, timestamps are the same
}

// Function to filter transactions by time range
Transaction** filter_transactions(Transaction** transactions, int num_transactions, time_t start_time, time_t end_time) {
    Transaction** filtered_transactions = (Transaction**)malloc((num_transactions + 1) * sizeof(Transaction*));

    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i]->timestamp >= start_time && transactions[i]->timestamp <= end_time) {
            filtered_transactions[i] = transactions[i];
        } else {
            filtered_transactions[i] = NULL;
        }
    }

    return filtered_transactions;
}

// Function to free allocated memory for transactions
void deallocate_transactions(Transaction** transactions, int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i]) {
            free(transactions[i]);
        }
    }
    free(transactions);
}
