// Define the structure for a product
typedef struct {
    int id;
    char name[50];
    float price;
    int quantity;
} Product;

// Function to initialize products with specified sizes and validate integrity
Product** initializeProducts(int numProducts) {
    Product** products = (Product**)malloc(numProducts * sizeof(Product*));
    for (int i = 0; i < numProducts; i++) {
        products[i] = (Product*)malloc(sizeof(Product));
        // Initialize product fields with default values or user-provided input
        products[i]->id = i + 1;
        strcpy(products[i]->name, "Default Name");
        products[i]->price = 0.0f;
        products[i]->quantity = 0;
    }
    for (int i = 0; i < numProducts - 1; i++) {
        for (int j = i + 1; j < numProducts; j++) {
            if (products[i]->id == products[j]->id) {
                printf("Error: Duplicate ID found. Product %d has the same ID as product %d.\n", i, j);
                return NULL;
            }
        }
    }
    return products;
}

// Function to sort products by price in ascending order
void sortProducts(Product** products, int numProducts) {
    for (int i = 0; i < numProducts - 1; i++) {
        for (int j = i + 1; j < numProducts; j++) {
            if (products[i]->price > products[j]->price) {
                Product* temp = products[i];
                products[i] = products[j];
                products[j] = temp;
            }
        }
    }
}

// Function to filter products by price range
Product** filterProducts(Product** products, int numProducts, float minPrice, float maxPrice) {
    int filteredNumProducts = 0;
    Product** filteredProducts = (Product**)malloc(numProducts * sizeof(Product*));
    for (int i = 0; i < numProducts; i++) {
        if (products[i]->price >= minPrice && products[i]->price <= maxPrice) {
            filteredProducts[filteredNumProducts] = products[i];
            filteredNumProducts++;
        }
    }
    filteredProducts = (Product**)realloc(filteredProducts, (filteredNumProducts + 1) * sizeof(Product*));
    return filteredProducts;
}

// Function to print product information
void printProducts(Product** products, int numProducts) {
    for (int i = 0; i < numProducts; i++) {
        printf("ID: %d, Name: %s, Price: %.2f, Quantity: %d\n", products[i]->id, products[i]->name, products[i]->price, products[i]->quantity);
    }
}

int main() {
    int numProducts = 10;
    Product** products = initializeProducts(numProducts);
    if (products == NULL) {
        printf("Error initializing products.\n");
        return -1;
    }
    sortProducts(products, numProducts);
    float minPrice = 0.0f;
    float maxPrice = 100.0f;
    Product** filteredProducts = filterProducts(products, numProducts, minPrice, maxPrice);
    printProducts(filteredProducts, numProducts);
    return 0;
}

