import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class DynamicDataManager {
    private final int INITIAL_RECORD_CAPACITY = 10000;
    private final int MAX_RECORD_CAPACITY = 1000000;
    private final long MIN_KEY_VALUE = 0L;
    private final long MAX_KEY_VALUE = 10000000L;

    private ConcurrentHashMap<Integer, Record> records;
    private CopyOnWriteArrayList<Record> recordList;
    private long currentOffset;
    private int currentKey;

    public DynamicDataManager(int initialCapacity) {
        this.records = new ConcurrentHashMap<>();
        this.recordList = new CopyOnWriteArrayList<>();
        this.currentOffset = MIN_KEY_VALUE;
        this.currentKey = 0;

        for (int i = 0; i < initialCapacity; i++) {
            addRecord();
        }
    }

    public void addRecord() {
        Record record = new Record(currentKey);
        records.put(currentKey, record);
        recordList.add(record);

        currentOffset += record.getSerializedSize();
        currentKey++;
    }

    // ... other methods for record manipulation and query
}
