```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    char* username;
    time_t login_timestamp;
    time_t logout_timestamp;
    int resource_count;
    char** resources;
} UserSessionLog;

// Function to create a new session log
UserSessionLog* create_session_log(int id, char* username) {
    UserSessionLog* log = (UserSessionLog*) malloc(sizeof(UserSessionLog));
    log->id = id;
    log->username = username;
    log->login_timestamp = 0;
    log->logout_timestamp = 0;
    log->resource_count = 0;
    log->resources = NULL;
    return log;
}

// Function to add a resource to the session log
void add_resource(UserSessionLog* log, char* resource) {
    if (log->resources == NULL) {
        log->resources = (char**) malloc(sizeof(char*));
        log->resource_count = 1;
    } else {
        log->resources = (char**) realloc(log->resources, (log->resource_count + 1) * sizeof(char*));
        log->resource_count++;
