#include <random>

union Find {
    int value;
    struct Node *ptr;
};

struct Node {
    union Find data;
    Node *next;
};

enum class AcknowledgmentType { ACK_A, ACK_B };

void handleNetworkSession(const std::string& sessionLabel,
                             const std::function<void()>& f,
                             const std::shared_ptr<trafficSourceInterface>& trafficSource,
                             const std::function<void()>& retransmissionHandler,
                             const std::shared_ptr<performanceMonitorInterface>& performanceMonitor) {
    networkSession* session = new networkSession();

    // Initialize the session's data structures
    session->sequenceNumbers = new long[trafficSource->getPacketCount()];
    session->timestamps = new int[trafficSource->getPacketCount()];
    session->packets = new packet*[trafficSource->getPacketCount()];

    for (int i = 0; i < trafficSource->getPacketCount(); ++i) {
        // Create and initialize a new packet
        packet* packet = new packet();

        packet->dataPointer = &session->sequenceNumbers[i];
        packet->timestamp = session->timestamps[i];
        packet->payload = new char[rand() % 100 + 1]; // Initialize with random payload

        int randAck = rand() % 2; // Randomly set acknowledgment type
        if (randAck == 0) {
            packet->acknowledgmentType = AcknowledgmentType::ACK_A;
        } else {
            packet->acknowledgmentType = AcknowledgmentType::ACK_B;
        }

        int randTimeout = rand() % 30 + 1; // Randomly set timeout duration
        packet->timeoutDuration = randTimeout;

        session->packets[i] = packet;
    }

    // Set up the union-find data structure
    Find* findData = new Find[trafficSource->getPacketCount()];

    for (int i = 0; i < trafficSource->getPacketCount(); ++i) {
        findData[i].value = i;
    }

    Node* nodes = new Node[trafficSource->getPacketCount()];

    // Run the test
    f();

    // Clean up and destroy any dynamically allocated data structures

    delete[] session->sequenceNumbers;
    delete[] session->timestamps;
    delete[] session->packets;
    delete[] findData;

    for (int i = 0; i < trafficSource->getPacketCount(); ++i) {
        delete[] nodes[i].data.ptr;
    }

    delete[] nodes;
}

