        try {
            // Initialize the processing queue and executor
            transactionQueue = new LinkedBlockingDeque<>(MAX_PROCESSING_THREADS);
            executorService = Executors.newFixedThreadPool(MAX_PROCESSING_THREADS, rejectedExecutionHandler);

            // Add transactions to the processing queue
            for (Transaction transaction : transactions) {
                transactionQueue.put(transaction);
            }

            // Start processing transactions in parallel
            while (!transactionQueue.isEmpty()) {
                Transaction transaction = transactionQueue.take();
                executorService.submit(() -> processTransaction(transaction));
