typedef struct {
    int id;
    double amount;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction* transactions;
    int capacity;
    int size;
} DynamicList;

void dynamic_list_init(DynamicList* list, int initial_capacity) {
    list->transactions = (Transaction*)malloc(initial_capacity * sizeof(Transaction));
    list->capacity = initial_capacity;
    list->size = 0;
}

int dynamic_list_insert(DynamicList* list, Transaction transaction) {
    if (list->size >= list->capacity) {
        // resize the list
        int new_capacity = list->capacity * 2;
        Transaction* new_transactions = (Transaction*)realloc(list->transactions, new_capacity * sizeof(Transaction));
        list->transactions = new_transactions;
        list->capacity = new_capacity;
    }

    if (!validate_transaction(&transaction)) {
        // error handling: duplicate transaction ID or invalid timestamp
        return -1;
    }

    list->transactions[list->size] = transaction;
    list->size++;
    return 0;
}

int dynamic_list_validate(DynamicList* list) {
    for (int i = 0; i < list->size; i++) {
        if (has_duplicate_id(list, i)) {
            // error handling: duplicate transaction ID
            return -1;
        }
    }

    for (int i = 1; i < list->size; i++) {
        if (list->transactions[i].timestamp <= list->transactions[i-1].timestamp) {
            // error handling: timestamps are not in chronological order
            return -2;
        }
    }

    return 0;
}

int main() {
    DynamicList list;
    dynamic_list_init(&list, 10);

    Transaction transaction1 = {12345, 100.00, time(NULL)};
    Transaction transaction2 = {67890, 500.00, time(NULL) + 60};
    Transaction transaction3 = {12345, 200.00, time(NULL) + 120};

    dynamic_list_insert(&list, transaction1);
    dynamic_list_insert(&list, transaction2);
    dynamic_list_insert(&list, transaction3);

    int error_code = dynamic_list_validate(&list);
    if (error_code != 0) {
        printf("Error: %d\n", error_code);
    } else {
        printf("Validation successful!\n");
    }

    return 0;
}
