typedef struct {
    int key;
    char name[33]; // 32 chars + null terminator
    double value;
} Record;

// Function to create and initialize records dynamically
Record* createRecords(int numRecords, int minKey, int maxKey, double multiplier) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for the array of records
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error allocating memory for records.\n");
        return NULL;
    }

    // Log the creation of each record
    int i;
    for (i = 0; i < numRecords; i++) {
        Record* record = &records[i];

        // Generate a random key within the specified range
        record->key = minKey + rand() % (maxKey - minKey + 1);

        // Generate a random name with varying lengths
        char* name = (char*)malloc((rand() % 32) + 1);
        for (int j = 0; j < strlen(name); j++) {
            name[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        name[strlen(name)] = '\0'; // Null-terminate the string

        record->name[32] = '\0'; // Null-terminate the string
        strcpy(record->name, name);

        // Calculate the double value as a function of the int key and the constant multiplier
        record->value = (double)record->key * multiplier;

        // Log the creation of the record
        printf("Created record with key %d, name '%s', and value %.2f\n", record->key, record->name, record->value);

        free(name);
    }

    return records;
}

// Function to safely release allocated memory
void cleanupRecords(Record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i].name);
    }
    free(records);
}
