pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int nfapi_count = 0;

void initialize_nfapi(int idx) {
    NFAPI_CRC_INDICATION_PDU_T *nfapi = &nfapis[idx];
    nfapi->crcflag = rand();
    nfapi->sequence_number = idx;
    nfapi->buffer = (char*)malloc(BUFFER_SIZE);
}

void cleanup_nfapi(int idx) {
    if (idx < 0 || idx >= nfapi_count) return;
    NFAPI_CRC_INDICATION_PDU_T *nfapi = &nfapis[idx];
    free(nfapi->buffer);
}

int add_nfapi(NFAPI_CRC_INDICATION_PDU_T *new_nfapi) {
    pthread_mutex_lock(&lock);
    if (nfapi_count >= MAX_NFAPIS) {
        pthread_mutex_unlock(&lock);
        return -1;
    }
    nfapis[nfapi_count++] = new_nfapi;
    pthread_mutex_unlock(&lock);
    return 0;
}

int delete_nfapi(int idx) {
    pthread_mutex_lock(&lock);
    if (idx < 0 || idx >= nfapi_count) {
        pthread_mutex_unlock(&lock);
        return -1;
    }
    cleanup_nfapi(idx);
    memmove(&nfapis[idx], &nfapis[idx + 1], (nfapi_count - idx - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapi_count--;
    pthread_mutex_unlock(&lock);
    return 0;
}

