// Function to manage dynamic list of transactions
Transaction** initializeTransactions(int initialCapacity) {
    // Initialize array with initial capacity
    Transaction** transactions = (Transaction**)malloc(initialCapacity * sizeof(Transaction*));

    // Validate integrity of transactions after initialization
    for (int i = 0; i < initialCapacity; i++) {
        transactions[i] = NULL;
    }

    return transactions;
}

// Function to insert a new transaction into the list
void insertTransaction(Transaction** transactions, int capacity, Transaction* newTransaction) {
    // Check if memory needs to be allocated
    if (capacity == 0 || transactions[capacity - 1] != NULL) {
        capacity *= 2; // Double the capacity

        // Reallocate array with new capacity
        transactions = (Transaction**)realloc(transactions, capacity * sizeof(Transaction*));

        // Initialize remaining slots to NULL
        for (int i = capacity / 2; i < capacity; i++) {
            transactions[i] = NULL;
        }
    }

    // Find the first empty slot and insert new transaction
    for (int i = 0; i < capacity; i++) {
        if (transactions[i] == NULL) {
            transactions[i] = newTransaction;
            return;
        }
    }
}

// Function to validate integrity of transactions
void validateTransactions(Transaction** transactions, int capacity) {
    // Check for duplicate transaction IDs
    for (int i = 0; i < capacity; i++) {
        if (transactions[i] != NULL && 
            findTransaction(transactions, capacity, transactions[i]->id) != NULL) {
            printf("Error: Duplicate transaction ID found.\n");
            exit(1);
        }
    }

    // Check timestamps for chronological order
    for (int i = 0; i < capacity - 1; i++) {
        if (transactions[i] != NULL && 
            transactions[i]->timestamp >= transactions[i + 1]->timestamp) {
            printf("Error: Timestamps are not in chronological order.\n");
            exit(1);
        }
    }
}

// Function to find a transaction by ID
Transaction* findTransaction(Transaction** transactions, int capacity, int id) {
    for (int i = 0; i < capacity; i++) {
        if (transactions[i] != NULL && transactions[i]->id == id) {
            return transactions[i];
        }
    }
    return NULL;
}

// Function to render dynamic list of transactions as a footer on a web page
char* renderTransactionsAsFooter(Transaction** transactions, int capacity) {
    char* html = (char*)malloc(1024 * sizeof(char));
    strcpy(html, "<footer>");

    for (int i = 0; i < capacity; i++) {
        if (transactions[i] != NULL) {
            sprintf(html + strlen(html), 
                    "    <script key=\"%d\" innerHTML=\"%lf\">\n", 
                    transactions[i]->id, transactions[i]->amount);
            strcat(html, "</script>\n");
        }
    }

    strcat(html, "</footer>");
    return html;
}
