    for(int i = 0; i < count; i++) {
        transactions[i].timestamp = 0;
        transactions[i].status_code = AVERAGE_STATUS_CHANGES;
    }

    pthread_mutex_init(&lock, &attr);
    pthread_mutex_destroy(&lock);

    return transactions;
