void* nfaPI_crc_indication_pdu_allocate(pthread_mutex_t* lock);
void nfaPI_crc_indication_pdu_free(void* ptr, pthread_mutex_t* lock);
void nfaPI_crc_indication_pdu_pool_statistics_update();
int nfaPI_crc_indication_pdu_pool_get_active_count();
double nfaPI_crc_indication_pdu_pool_get_average_allocation_time();

// Initialize the pool with a fixed size
void nfaPI_crc_indication_pdu_pool_init(int poolSize, pthread_mutex_t* lock) {
    // Allocate memory for the pool
    NFAPI_CRC_INDICATION_PDU_T** pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(poolSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Initialize each structure in the pool
    for (int i = 0; i < poolSize; i++) {
        pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*pool[i]).CRCFLAG = rand();
        (*pool[i]).RNTI = rand();
        (*pool[i]).sequenceNumber = i;
        (*pool[i]).buffer = NULL;

        // Initialize the lock
        pthread_mutex_init(lock, NULL);
    }
}

// Allocate a structure from the pool
void* nfaPI_crc_indication_pdu_allocate(pthread_mutex_t* lock) {
    NFAPI_CRC_INDICATION_PDU_T** pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(lock);
    for (int i = 0; i < poolSize; i++) {
        if ((*pool[i]).buffer == NULL) {
            // Structure not in use, return it
            pthread_mutex_unlock(lock);
            return *pool[i];
        }
    }
    pthread_mutex_unlock(lock);

    // No free structure found, grow the pool if necessary
    pool = (NFAPI_CRC_INDICATION_PDU_T**)realloc(pool, (poolSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pool[poolSize] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*pool[poolSize]).CRCFLAG = rand();
    (*pool[poolSize]).RNTI = rand();
    (*pool[poolSize]).sequenceNumber = poolSize;
