// Function to allocate memory and initialize arrays
int initArrays(int numRecords, int maxOffsetValue, int minKey) {
    // Calculate total size of each array
    int recordSize = sizeof(Record);
    int metadataSize = sizeof(Metadata);

    // Set maximum allowed memory usage for system performance
    const int MAX_MEMORY_USAGE = 1024 * 1024; // 1MB

    // Check if requested memory exceeds the limit
    if (numRecords * recordSize + numRecords * metadataSize > MAX_MEMORY_USAGE) {
        return -1; // Return error status and free allocated resources on failure
    }

    // Allocate memory for arrays
    Record* records = (Record*) malloc(numRecords * recordSize);
    Metadata* metadata = (Metadata*) malloc(numRecords * metadataSize);

    if (!records || !metadata) {
        // Memory allocation failed, free allocated resources and return error status
        free(records);
        free(metadata);
        return -1;
    }

    // Initialize records with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        int key = rand() % (maxOffsetValue + 1) + minKey;
        record->value = rand();
        record->offset = (long*) malloc(sizeof(long)); // Allocate memory for offset
    }

    // Initialize metadata with pointers to records
    for (int i = 0; i < numRecords; i++) {
        Metadata* meta = &metadata[i];
        meta->rec_ptr = &records[i];
    }

    return numRecords;
}

// Example usage of the function
int main() {
    int numRecords = 10;
    int maxOffsetValue = 10000;
    int minKey = 0;

    int numInitializedRecords = initArrays(numRecords, maxOffsetValue, minKey);

    if (numInitializedRecords < 0) {
        printf("Error: Memory allocation failed.\n");
    } else {
        printf("Successfully initialized %d records.\n", numInitializedRecords);
    }

