#include <string.h>
#include <pthread.h>

typedef struct {
    int CRCFLAG;
    int sequence_number;
    char* buffer;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* list[10000];
int list_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void nfapi_crc_indication_pdu_t_init(NFAPI_CRC_INDICATION_PDU_T* pdu, int CRCFLAG, int sequence_number) {
    pdu->CRCFLAG = CRCFLAG;
    pdu->sequence_number = sequence_number;
}

int nfapi_crc_indication_pdu_t_insert(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lock);
    list[list_size++] = pdu;
    pthread_mutex_unlock(&lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_t_search(int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < list_size; i++) {
        if ((list[i]->RNTI == RNTI) && (list[i]->CRCFLAG == CRCFLAG)) {
            return list[i];
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int nfapi_crc_indication_pdu_t_remove(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < list_size; i++) {
        if (list[i] == pdu) {
            memmove(list + i, list + i + 1, (list_size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            list_size--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return 0;
}

int nfapi_crc_indication_pdu_t_cleanup() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < list_size; i++) {
        if (list[i]->buffer != NULL) {
            free(list[i]->buffer);
            list[i]->buffer = NULL;
        }
    }
    for (int i = 0; i < list_size; i++) {
        free(list[i]);
        list[i] = NULL;
    }
    list_size = 0;
    pthread_mutex_unlock(&lock);
    return 0;
}

void* nfapi_crc_indication_pdu_t_report() {
    pthread_mutex_lock(&lock);
    int active_count = 0;
    for (int i = 0; i < list_size; i++) {
        if (list[i]->buffer != NULL) {
            active_count++;
        }
    }
    pthread_mutex_unlock(&lock);
    return (void*) (active_count + " structures, " + (10000 - list_size) + " available memory");
}

int main() {
    // Initialize the list
    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfapi_crc_indication_pdu_t_init(pdu, rand(), i);
        nfapi_crc_indication_pdu_t_insert(pdu);
    }

    // Perform operations
    NFAPI_CRC_INDICATION_PDU_T* pdu1 = nfapi_crc_indication_pdu_t_search(0x12345678, 0x0001);
    if (pdu1 != NULL) {
        printf("PDU found: %d, %d\n", pdu1->RNTI, pdu1->CRCFLAG);
    }

    // Cleanup
    nfapi_crc_indication_pdu_t_cleanup();

    return 0;
}

