class DynamicLogManager {
private:
    std::list<struct LogEntry> logs;
    std::mutex logMutex;

public:
    struct LogEntry {
        int id;
        std::string message;
        int severityLevel;
        long timestamp;
    };

    DynamicLogManager(int initialCapacity) : logs(initialCapacity) {}

    bool insertLog(const LogEntry& entry) {
        try {
            if (findDuplicate(entry.id)) {
                return false; // Duplicate log ID
            }
            if (!validateTimestamp(entry.timestamp)) {
                return false; // Timestamp not in chronological order
            }
            std::lock_guard<std::mutex> lock(logMutex);
            logs.push_back(entry);
            return true;
        } catch (...) {
            return false; // Error during insertion or validation
        }
    }

    bool deleteLog(int logId) {
        try {
            std::lock_guard<std::mutex> lock(logMutex);
            auto it = logs.begin();
            while (it != logs.end()) {
                if (it->id == logId) {
                    logs.erase(it);
                    return true;
                }
                ++it;
            }
            return false; // Log ID not found
        } catch (...) {
            return false; // Error during deletion or iteration
        }
    }

    bool findDuplicate(int logId) {
        for (const auto& entry : logs) {
            if (entry.id == logId) {
                return true;
            }
        }
        return false;
    }

    bool validateTimestamp(long timestamp) {
        long prevTimestamp = -1;
        for (const auto& entry : logs) {
            if (entry.timestamp < prevTimestamp) {
                return false; // Timestamp not in chronological order
            }
            prevTimestamp = entry.timestamp;
        }
        return true;
    }

    void printLogs() {
        std::cout << "Log entries:\n";
        for (const auto& log : logs) {
            std::cout << "ID: " << log.id << ", Message: " << log.message
                      << ", Severity Level: " << log.severityLevel
                      << ", Timestamp: " << log.timestamp << "\n";
        }
    }
};

int main() {
    DynamicLogManager logManager(10);

    LogEntry entry1 = {1, "Error: System failure", 3, 1643723400};
    LogEntry entry2 = {2, "Warning: Resource utilization high", 2, 1643723500};
    LogEntry entry3 = {1, "Info: System startup complete", 1, 1643723600}; // Duplicate log ID
    LogEntry entry4 = {3, "Error: Network connection lost", 3, 1643723700};

    if (logManager.insertLog(entry1)) {
        std::cout << "Inserted log successfully.\n";
    } else {
        std::cout << "Error inserting log.\n";
    }

    if (logManager.insertLog(entry2)) {
        std::cout << "Inserted log successfully.\n";
    } else {
        std::cout << "Error inserting log.\n";
    }

    // Attempt to insert duplicate log
    if (!logManager.insertLog(entry3)) {
        std::cout << "Duplicate log ID detected.\n";
    }

    if (logManager.insertLog(entry4)) {
        std::cout << "Inserted log successfully.\n";
    } else {
        std::cout << "Error inserting log.\n";
    }

    logManager.printLogs();

    return 0;
}

