#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define the maximum capacity of the dynamic list
#define MAX_CAPACITY 1000

// Define the structure for a record with metadata
typedef struct Record {
    int id;
    int value;
    char* metadata;
    struct Record* next;
} Record;

// Function to initialize the dynamic list with a specified capacity
Record* initializeList(int capacity) {
    Record* head = (Record*)malloc(sizeof(Record));
    head->id = 0;
    head->value = rand() % 100; // Initialize value within [0,99]
    head->metadata = NULL;
    head->next = NULL;

    Record* current = head;
    for(int i = 1; i < capacity; i++) {
        Record* newRecord = (Record*)malloc(sizeof(Record));
        newRecord->id = i;
        newRecord->value = rand() % 100; // Initialize value within [0,99]
        newRecord->metadata = NULL;
        newRecord->next = NULL;

        current->next = newRecord;
        current = newRecord;
    }

    return head;
}

// Function to validate the integrity of the record list
void validateList(Record* head) {
    int hashValue = 0;
    Record* current = head;
    while(current != NULL) {
        hashValue += current->id * current->value;
        current = current->next;
    }

    printf("Hash value: %d\n", hashValue);
}

// Function to add a new record with metadata
void addRecord(Record** head, int id, int value, char* metadata) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->id = id;
    newRecord->value = value;
    newRecord->metadata = metadata;
    newRecord->next = *head;
    *head = newRecord;
}

// Function to remove a record by ID
void removeRecord(Record** head, int id) {
    Record* current = *head;
    Record* previous = NULL;

    while(current != NULL && current->id != id) {
        previous = current;
        current = current->next;
    }

    if(current == NULL) {
        printf("Record not found!\n");
        return;
    }

    if(previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

// Function to display the record list
void displayList(Record* head) {
    Record* current = head;
    while(current != NULL) {
        printf("ID: %d, Value: %d, Metadata: %s\n", current->id, current->value, current->metadata);
        current = current->next;
    }
}

// Function to handle errors and recover from memory allocation failures
void handleError(int errorCode) {
    if(errorCode == 0) {
        printf("Memory allocation failed!\n");
    } else {
        printf("Unknown error occurred: %d\n", errorCode);
    }
}

int main() {
    Record* head = initializeList(MAX_CAPACITY);
    validateList(head);

    addRecord(&head, 1, 50, "Metadata for record 1");
    addRecord(&head, 2, 75, "Metadata for record 2");

    displayList(head);

    removeRecord(&head, 1);

    displayList(head);

    return 0;
}
