typedef struct sensor_data_t {
    int sensor_id;
    long timestamp;
    float temperature;
    float humidity;
    char battery_status;
} sensor_data_t;

typedef struct sensor_array_t {
    sensor_data_t* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} sensor_array_t;

void array_init(sensor_array_t* array, size_t initial_capacity) {
    array->data = (sensor_data_t*)malloc(initial_capacity * sizeof(sensor_data_t));
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

void addSensorReading(sensor_array_t* array, sensor_data_t* reading) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        // Resize the array to double its capacity
        array->data = (sensor_data_t*)realloc(array->data, 2 * array->capacity * sizeof(sensor_data_t));
        array->capacity *= 2;
    }

    array->data[array->size++] = *reading;

    pthread_mutex_unlock(&array->lock);
}

void removeSensorReading(sensor_array_t* array) {
    pthread_mutex_lock(&array->lock);

    if (array->size > 0) {
        // Move the last element to the first position, effectively removing it
        sensor_data_t temp = array->data[0];
        memmove(array->data, &array->data[1], (array->size - 1) * sizeof(sensor_data_t));
        array->data[array->size--] = temp;
    }

    pthread_mutex_unlock(&array->lock);
}

void updateSensorReading(sensor_array_t* array, size_t index, sensor_data_t* reading) {
    pthread_mutex_lock(&array->lock);

    if (index < array->size) {
        array->data[index] = *reading;
    }

    pthread_mutex_unlock(&array->lock);
}

sensor_data_t getSensorReading(sensor_array_t* array, size_t index) {
    pthread_mutex_lock(&array->lock);

    sensor_data_t reading = array->data[index];

    pthread_mutex_unlock(&array->lock);

    return reading;
}
