        if (!temp) return -1; // error: memory allocation failed
        memset(&manager->bandConfigs[newSize], 0, (manager->size - newSize) * sizeof(NR_UARFCN_BANDCONFIG_T));
    }

    manager->size = newSize;
    updateUarfcnValues(manager, newBandConfigs);
    checkUniqueUarfcns(manager);

    // monitor allocations and deallocations for performance tuning
    printf("Allocations: %d\n", ++manager->maxAllocations);
