enum attackType { ATTACK_A, ATTACK_B };

struct action {
    long valuePointer;
    int key;
    char description[20];
    attackType attackType;
    int cooldownTime;
};

void executeGameActions(std::string label, std::function<void()> f, void* dataSource, std::vector<std::function<void()>> testSuite) {
    // Initialize game state
    gameState* currentState = new gameState();

    // Initialize action array
    action* actions = new action[100]; // assume 100 max actions

    // Initialize cooldown map
    std::map<int, int> cooldownMap;

    // Main game loop
    while (true) {
        // Execute test suite
        for (auto& test : testSuite) {
            test();
        }

        // Get next action from data source
        action* nextAction = nullptr;
        if (!getActionFromDataSource(dataSource, &nextAction)) {
            std::cout << "Error: failed to get next action" << std::endl;
            continue; // skip this iteration
        }

        // Check cooldown period
        if (cooldownMap.find(nextAction->key) != cooldownMap.end()) {
            int cooldownRemaining = cooldownMap[nextAction->key];
            if (cooldownRemaining > 0) {
                std::cout << "Cooldown remaining: " << cooldownRemaining << std::endl;
                continue; // skip this iteration
            }
        }

        // Execute action
        f();

        // Update game state
        currentState->offsets[nextAction->key] = nextAction->valuePointer;

        // Add action to queue (async execution)
        std::mutex mtx;
        std::condition_variable cv;
        std::vector<std::function<void()>> actionQueue;

        {
            std::unique_lock<std::mutex> lock(mtx);
            actionQueue.push_back([nextAction]() {
                executeAction(nextAction->valuePointer, nextAction->key, nextAction->description, nextAction->attackType, nextAction->cooldownTime);
            });
        }
        cv.notify_one();

        // Process actions in queue
        std::vector<std::function<void()>> processedActions;
        while (!actionQueue.empty()) {
            std::unique_lock<std::mutex> lock(mtx);
            actionQueue.front()(); // execute the next action
            processedActions.push_back(actionQueue.front());
            actionQueue.pop_front();
            cv.notify_one();
        }

        // Verify game state integrity
        if (verifyGameState(currentState)) {
            std::cout << "Game state verified" << std::endl;
        } else {
            std::cout << "Error: game state corrupted" << std::endl;
            break; // exit loop
        }
    }

    // Clean up memory
    delete[] actions;
    delete currentState;
}

// Mock setup for testing
void require(std::string module) {
    std::cout << "Loading module: " << module << std::endl;
}
