typedef struct {
    int phy_frame_type;
    int frame_number;
    int subframe_number;
} LTE_PHY_FRAME_PARAMETERS;

void* allocate_frames(int capacity) {
    void *frames = calloc(capacity, sizeof(LTE_PHY_FRAME_PARAMETERS));
    return frames;
}

int get_next_frame_number(void *frames, int current_capacity) {
    int next_frame_number = 1;
    for (int i = 0; i < current_capacity; i++) {
        if (((LTE_PHY_FRAME_PARAMETERS *)frames)[i].frame_number == next_frame_number) {
            next_frame_number++;
        }
    }
    return next_frame_number;
}

void update_frames(void **frames, int *current_capacity, LTE_PHY_FRAME_PARAMETERS *new_frame, int timeout) {
    if (*current_capacity < (int)(*frames)->frame_number + 1) {
        void *tmp = allocate_frames(*current_capacity * 2);
        memcpy(tmp, *frames, *current_capacity * sizeof(LTE_PHY_FRAME_PARAMETERS));
        free(*frames);
        *frames = tmp;
        *current_capacity *= 2;
    }
    if (timeout > 0) {
        int frame_number = get_next_frame_number(*frames, *current_capacity);
        new_frame->frame_number = frame_number;
    } else {
        memcpy(new_frame, (*frames + (*current_capacity - 1)), sizeof(LTE_PHY_FRAME_PARAMETERS));
    }
}

void validate_frames(void *frames, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (!validate_phy_frame((LTE_PHY_FRAME_PARAMETERS *)frames + i)) {
            printf("Invalid frame detected at index %d\n", i);
        }
    }
}

