        new_frame.phy_frame_type = 1;
        new_frame.subframe_number = 2;
        if (i > 20) {
            update_frames(&frames, &current_capacity, &new_frame, 5000);
        } else {
            int frame_number = get_next_frame_number(frames, current_capacity);
            new_frame.frame_number = frame_number;
        }
    }
    free(frames);
    return 0;
}
