};

void executeGameActions(const std::string& label, void (*f)(gameAction), const std::function<AttackType()>& dataSource, int maxConcurrentActions, float loadFactor) {
    srand(static_cast<unsigned>(time(nullptr)));

    gameAction* actions = new gameAction();

    // Initialize arrays for offsets and keys
    long* offsets = new long[20];
    int* keys = new int[20];

