        offsets[i] = rand() % 10000;
        keys[i] = i;

        // Initialize description and set attack type/cooldown time
        strcpy(actions->description, "Action ");
        actions->attackType = rand() % 2 == 0 ? ATTACK_A : ATTACK_B;
