        long* valuePointer = &(actions->offsets[i]);

        // Create a new game action with the initialized values
        f(*actions);

        delete[] actions->description;
    }

    // Verify memory integrity and clean up
    if (loadFactor > 0.5f) {
        std::cout << "Memory usage: " << loadFactor * 100 << "%" << std::endl;
    } else {
