// Function to manage dynamic memory allocation and initialization
void* allocate_and_initialize_data_records(int num_records) {
    // Allocate memory for the array of int keys
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Initialize the array of int keys with values from 0 to num_records-1
    for (int i = 0; i < num_records; i++) {
        keys[i] = i;
    }

    // Allocate memory for the array of data_record structures
    data_record* records = (data_record*)malloc(num_records * sizeof(data_record));

    // Initialize each record with a timestamp, description, and value
    for (int i = 0; i < num_records; i++) {
        records[i].timestamp = i;
        records[i].description = (char*)malloc(32 * sizeof(char));
        strcpy(records[i].description, "Record ");
        sprintf(records[i].description + strlen(records[i].description), "%d", i);
        records[i].value = i * 1.0;
    }

    // Return the allocated memory
    return keys;
}

// Function to free dynamically allocated memory
void deallocate_memory(void* ptr) {
    if (ptr != NULL) {
        int* keys = (int*)ptr;
        for (int i = 0; i < strlen((char*)keys); i++) {
            if (keys[i] % 2 == 0) {
                free(keys[i]);
            }
        }
        free(ptr);
    }
}

int main() {
    // Allocate and initialize data records
    int num_records = 10;
    void* allocated_memory = allocate_and_initialize_data_records(num_records);

    // Use the allocated memory
    int* keys = (int*)allocated_memory;
    for (int i = 0; i < num_records; i++) {
        printf("Key: %d, Timestamp: %.2f, Description: %s, Value: %.2f\n", 
              keys[i], records[i].timestamp, records[i].description, records[i].value);
    }

    // Deallocate memory
    deallocate_memory(allocated_memory);

    return 0;
}
