```c
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int timestamp;
    char status[20];
} Record;

Record* recordQueue = NULL;
int recordCount = 0;
pthread_mutex_t recordMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t recordCond = PTHREAD_COND_INITIALIZER;

void initRecordQueue() {
    recordQueue = (Record*)malloc(sizeof(Record) * 100000);
}

int addRecordToQueue(int timestamp, const char* status) {
    pthread_mutex_lock(&recordMutex);

    if(recordCount >= 100000) {
        printf("Error: Record queue is full.\n");
        return -1;
    }

    recordQueue[recordCount].timestamp = timestamp;
    strcpy(recordQueue[recordCount].status, status);
    recordCount++;

    pthread_cond_signal(&recordCond);
    pthread_mutex_unlock(&recordMutex);

    return 0;
}

Record* getRecordFromQueue() {
    Record* record = NULL;
    pthread_mutex_lock(&recordMutex);

    while(recordCount == 0) {
        pthread_cond_wait(&recordCond, &recordMutex);
    }

    record = &recordQueue[0];
    recordCount--;
    pthread_mutex_unlock(&recordMutex);

    return record;
}
