    *offsets = (long*)malloc(numRecords * sizeof(long));
    *keys = (int*)malloc(numRecords * sizeof(int));

    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i] = rand() % MAX_OFFSETS;
        (*keys)[i] = rand() % MAX_KEYS;

        records[i] = (RECORD_STRUCT*)malloc(sizeof(RECORD_STRUCT));
        records[i]->key = (*keys)[i];
        records[i]->profile = &USER_PROFILE_ARRAY[rand() % 10000];  // Randomly select a profile
    }
