#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <pthread.h>

#define MAX_SIZE 1000
#define CRCFLAG_TRUE 1
#define CRCFLAG_FALSE 0

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfaList = NULL;
int nfaSize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addElement(int RX_UE_INFORMATION_TAG, int RNTI, char *CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&mutex);

    if (nfaSize >= MAX_SIZE) {
        printf("Error: List size exceeded. Maximum allowed is %d.\n", MAX_SIZE);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* newElement = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newElement == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    strcpy(newElement->CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);
    newElement->CRCFLAG = (rand() % 2) ? CRCFLAG_TRUE : CRCFLAG_FALSE;

    if (newElement->RNTI < 0 || newElement->RNTI > 65535) {
        printf("Error: RNTI value out of range.\n");
        free(newElement);
        return;
    }

    nfaList = (NFAPI_CRC_INDICATION_PDU_T**)realloc(nfaList, (nfaSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (nfaList == NULL) {
        printf("Error: Memory allocation failed.\n");
        free(newElement);
        return;
    }

    nfaList[nfaSize++] = newElement;

    pthread_mutex_unlock(&mutex);
}

void serializeList(int fd, int size) {
    pthread_mutex_lock(&mutex);

    char *data = (char*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (data == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < nfaSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = nfaList[i];

        *(NFAPI_CRC_INDICATION_PDU_T*)data += size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // serialize RX_UE_INFORMATION_TAG
        ((int*)data)[i * 4 + 0] = htonl(element->RX_UE_INFORMATION_TAG);
        // serialize RNTI
        ((int*)data)[i * 4 + 1] = htonl(element->RNTI);
        // serialize CRC_INDICATION_REL8_TAG
        memcpy(data + i * 20, element->CRC_INDICATION_REL8_TAG, 20);
        // serialize CRCFLAG
        ((int*)data)[i * 4 + 2] = htonl(element->CRCFLAG ? CRCFLAG_TRUE : CRCFLAG_FALSE);
    }

    write(fd, data, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(data);

    pthread_mutex_unlock(&mutex);
}

void deserializeList(int fd) {
    pthread_mutex_lock(&mutex);

    char *data = (char*)malloc(MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (data == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    int bytesRead = read(fd, data, MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    NFAPI_CRC_INDICATION_PDU_T* newElement = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newElement == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < bytesRead / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        // deserialize RX_UE_INFORMATION_TAG
        newElement->RX_UE_INFORMATION_TAG = ntohl(((int*)data)[i * 4 + 0]);
        // deserialize RNTI
        newElement->RNTI = ntohl(((int*)data)[i * 4 + 1]);
        // deserialize CRC_INDICATION_REL8_TAG
        memcpy(newElement->CRC_INDICATION_REL8_TAG, data + i * 20, 20);
        // deserialize CRCFLAG
        newElement->CRCFLAG = (ntohl(((int*)data)[i * 4 + 2]) == CRCFLAG_TRUE) ? CRCFLAG_TRUE : CRCFLAG_FALSE;

        if (newElement->RNTI < 0 || newElement->RNTI > 65535) {
            printf("Error: RNTI value out of range.\n");
            free(newElement);
            return;
        }

        nfaList = (NFAPI_CRC_INDICATION_PDU_T**)realloc(nfaList, (nfaSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (nfaList == NULL) {
            printf("Error: Memory allocation failed.\n");
            free(newElement);
            return;
        }

        nfaList[nfaSize++] = newElement;
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize the list
    nfaList = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (nfaList == NULL) {
        printf("Error: Memory allocation failed.\n");
        return 1;
    }

    // Simulate adding elements to the list
    for (int i = 0; i < 1000; i++) {
        addElement(i, i, "CRC_INDICATION_REL8_TAG");
    }

    // Serialize the list to a file
    int fd = open("nfa_list.bin", O_CREAT | O_TRUNC | O_RDWR, S_IRWXU);
    if (fd == -1) {
        printf("Error: Failed to create file.\n");
        return 1;
    }
    serializeList(fd, nfaSize);

    // Close the file
    close(fd);

    // Deserialize the list from the file
    fd = open("nfa_list.bin", O_RDONLY);
    if (fd == -1) {
        printf("Error: Failed to open file.\n");
        return 1;
    }
    deserializeList(fd);

    // Close the file
    close(fd);

    return 0;
}
