    int end_time;
    int permissions;
} Session;

// Define the structure for the dynamic array of sessions
typedef struct {
    Session* sessions;
    size_t capacity;
    size_t size;
} SessionsArray;

// Function to create a new session array
SessionsArray* create_sessions_array() {
    SessionsArray* array = (SessionsArray*)malloc(sizeof(SessionsArray));
    array->capacity = 10; // Initial capacity of 10
    array->size = 0;
    array->sessions = (Session*)malloc(array->capacity * sizeof(Session));
    return array;
}

// Function to add a new session to the array
int add_session(SessionsArray* array, Session session) {
    if (array->size >= array->capacity) {
        // Reallocate memory if the array is full
        array->capacity *= 2;
        array->sessions = (Session*)realloc(array->sessions, array->capacity * sizeof(Session));
    }
    array->sessions[array->size] = session;
    array->size++;
    return 0;
}

// Function to remove a session from the array
int remove_session(SessionsArray* array, int index) {
    if (index < 0 || index >= array->size) {
        // Return an error if the index is out of bounds
        return -1;
    }
    for (int i = index; i < array->size - 1; i++) {
        array->sessions[i] = array->sessions[i + 1];
    }
    array->size--;
    return 0;
}

// Function to update a session in the array
int update_session(SessionsArray* array, int index, Session new_session) {
    if (index < 0 || index >= array->size) {
        // Return an error if the index is out of bounds
        return -1;
    }
    array->sessions[index] = new_session;
    return 0;
}

// Function to free the session array
void free_sessions_array(SessionsArray* array) {
    free(array->sessions);
    free(array);
}
