#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_EVENTS 10000000 // up to 10 million events

typedef struct Event {
    int eventID;
    time_t timestamp;
} Event;

// Cache settings
#define CACHE_SIZE 1024 // adjustable cache size (default: 1024)
int cacheHits = 0; // cache hit counter
int cacheMisses = 0; // cache miss counter

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // synchronization lock

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int initEvents(int events) {
    Event** eventArray = (Event**) allocateMemory(events * sizeof(Event*));

    // Initialize each array element
    for (int i = 0; i < events; i++) {
        eventArray[i] = (Event*) allocateMemory(sizeof(Event));
        eventArray[i]->eventID = i;
        eventArray[i]->timestamp = time(NULL);
    }

    return events;
}

void freeEvents(int events, Event** eventArray) {
    for (int i = 0; i < events; i++) {
        free(eventArray[i]);
    }
    free(eventArray);
}

int insertEvent(Event* event) {
    // Lock the cache to ensure thread safety
    pthread_mutex_lock(&lock);

    int cacheIndex = event->eventID % CACHE_SIZE;
    if (cacheIndex > 0 && eventArray[cacheIndex]) {
        // Cache hit: Update timestamp and move event to the front of the cache
        eventArray[cacheIndex]->timestamp = time(NULL);
        printf("Cache hit!\n");
    } else {
        // Cache miss: Insert new event into the cache
        if (eventArray[cacheIndex] == NULL) {
            eventArray[cacheIndex] = event;
        }
        printf("Cache miss! New event inserted.\n");
    }

    pthread_mutex_unlock(&lock);
}

Event* retrieveEvent(int eventID) {
    // Lock the cache to ensure thread safety
    pthread_mutex_lock(&lock);

    int cacheIndex = eventID % CACHE_SIZE;
    Event* cachedEvent = eventArray[cacheIndex];

    if (cachedEvent) {
        // Cache hit: Return the retrieved event
        pthread_mutex_unlock(&lock);
        return cachedEvent;
    }

    // Cache miss: Search for the event in the array and retrieve it if found
    for (int i = 0; i < events; i++) {
        if (eventArray[i]->eventID == eventID) {
            Event* retrievedEvent = eventArray[i];
            pthread_mutex_unlock(&lock);
            return retrievedEvent;
        }
    }

    // Event not found: Return NULL
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    int events = initEvents(MAX_EVENTS);

    // Start inserting and retrieving events concurrently
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, (void*)insertAndRetrieveEvent, &events);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    freeEvents(events, eventArray);

    return 0;
}

// Helper function for concurrent event processing
void* insertAndRetrieveEvent(void* ptr) {
    int events = *(int*)ptr;

    // Simulate inserting and retrieving events concurrently
    for (int i = 0; i < events; i++) {
        Event* event = createEvent(i);
        insertEvent(event);

        // Sleep to simulate some processing time
        sleep(1);

        int eventID = i;
        Event* retrievedEvent = retrieveEvent(eventID);
        if (retrievedEvent) {
            printf("Retrieved event %d: timestamp=%ld\n", eventID, retrievedEvent->timestamp);
        } else {
            printf("Event %d not found!\n", eventID);
        }
    }

    return NULL;
}

// Helper function to create a new Event structure
Event* createEvent(int eventID) {
    Event* event = (Event*) allocateMemory(sizeof(Event));
    event->eventID = eventID;
    event->timestamp = time(NULL);

    return event;
}
