// Function to create a new node with random RNTI and CRCFLAG
Node* create_node() {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) return NULL; // Handle memory allocation failure

    node->data.RNTI = rand();
    node->data.CRCFLAG = rand() % 2;
    node->next = NULL;

    return node;
}

// Function to insert a new node at the end of the list
void insert_node(Node** head, Node* node) {
    if (!*head) *head = node;
    else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = node;
    }
}

// Function to print the linked list
void print_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }
}

// Function to check if all RNTIs are unique
int is_unique(Node* head) {
    Node* current = head;
    int seen[RNTI_MAX] = {0};
    while (current) {
        if (seen[current->data.RNTI]) return 0; // Not unique
        seen[current->data.RNTI] = 1;
        current = current->next;
    }
    return 1; // Unique
}

// Function to free the linked list
void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    Node* head = NULL; // Create an empty linked list

    for (int i = 0; i < NFAPI_CRC_INDICATION_PDU_T_MAX; i++) {
        Node* node = create_node();
        if (!node) break; // Handle memory allocation failure
        insert_node(&head, node);
    }

    if (!is_unique(head)) {
        printf("Error: RNTIs are not unique\n");
        free_list(&head); // Clean up before returning error code
        return 1;
    }

    print_list(head);

    free_list(&head); // Free the linked list

    return 0;
}
