                // Handle exceptions with retry logic and exponential backoff
                int retries = 0;
                while (retries++ < 5) {
                    try {
                        // Your external messaging service call here
                        break; // Successful send, exit the retry loop
                    } catch (const std::exception& e) {
                        if (retries < 5) {
                            // Wait before retrying with exponential backoff
                            std::this_thread::sleep_for(std::chrono::milliseconds(retries * 1000));
                        }
                    }
                }
            }
        }

        ++it;
    }

    // If no match found, append the URL to the end of the list
    if (list.empty()) {
        list.assign({url});
    } else {
        list.push_back(url);
    }
}

std::string appendSlashIfWithinLimit(const char* str, int sizeLimit) {
    std::string result = str;

    if (result.length() < sizeLimit - 1) {
        result += '/';
    }

    return result;
}
