// C Function for renaming files by vowel count
#include <stdio.h>
#include <stdlib.h>

void rename_files_by_vowel_count(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_path);
        return;
    }

    int vowel_count = 0;
    char c;
    while ((c = fgetc(file)) != EOF) {
        if (strchr("aeiouAEIOU", c) != NULL) {
            vowel_count++;
        }
    }

    fclose(file);

    const char *new_file_name = malloc(strlen(file_path) + 10);
    sprintf(new_file_name, "%s.%d", file_path, vowel_count);
    rename(file_path, new_file_name);

    free(new_file_name);
}
