        seed = time(NULL);
        srand(seed);  // Initialize thread-safe random number generator
    });

    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = *(int*)my_random();
        void* profile = NULL;  // Initialize to an invalid profile pointer

        Record* record = create_record(key, profile);
        if (!record) {
            printf("Memory allocation failed!\n");
            continue;
        }

        // Update the array and record count
        records = (Record*)realloc(records, sizeof(Record) * (record_count + 1));
        if (!records) {
            printf("Memory reallocation failed!\n");
            free_records(records, record_count);
            return;
        }
        records[record_count].key = key;
        records[record_count++].profile = profile;

        // Monitor memory usage and logging
        printf("Allocated %zu bytes for Record %d\n", sizeof(Record), i);

        if (record_count >= MAX_RECORDS) {
            printf("Maximum record count reached!\n");
            break;
        }
    }

