// Define the record structure
typedef struct {
    int id;
    double weight;
    char* identifier;
} record;

// Thread-safe memory allocation function
void* thread_safe_malloc(size_t size) {
    void* result = malloc(size);
    if (!result) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    return result;
}

// Initialize and allocate records with random values
record** init_records(int num_records) {
    record** records = (record**)thread_safe_malloc(num_records * sizeof(record*));
    for (int i = 0; i < num_records; i++) {
        record* record_ptr = (record*)thread_safe_malloc(sizeof(record));
        record_ptr->id = rand();
        record_ptr->weight = (double)rand() / RAND_MAX;
        int identifier_len = snprintf(NULL, 0, "rec-%d", i) + 1;
        char* identifier = (char*)thread_safe_malloc(identifier_len);
        sprintf(identifier, "rec-%d", i);
        record_ptr->identifier = identifier;
        records[i] = record_ptr;
    }
    return records;
}

// Example usage
int main() {
    int num_records = 1000000; // Initialize with 1 million records
    record** records = init_records(num_records);
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: ID=%d, Weight=%.2f, Identifier=%s\n", i, records[i]->id, records[i]->weight, records[i]->identifier);
    }
    // Release memory
    for (int i = 0; i < num_records; i++) {
        free(records[i]->identifier);
        free(records[i]);
    }
    free(records);
    return 0;
}
