record_t* init_arrays(int offset_size, int key_size, int record_size) {
    // Initialize memory for 'long' offset values
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    if (!offsets) {
        return NULL;  // Memory allocation failed
    }

    // Initialize memory for 'int' keys
    int* keys = (int*)malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);  // Free previously allocated memory
        return NULL;
    }

    // Initialize memory for 'record' structures
    record_t* records = (record_t*)malloc(record_size * sizeof(record_t));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;  // Memory allocation failed
    }

    // Validate the integrity of the records
    srand(time(NULL));  // Seed random number generator
    for (int i = 0; i < record_size; i++) {
        record_t* record = &records[i];
        int key;
        do {
            key = rand() % key_size;
        } while (i > 0 && key == keys[i - 1]);  // Ensure no two records have the same key
        record->value = i;  // Set value of each record's int field to a random value
    }

    return records;
}

void* realloc_if_needed(void* ptr, size_t new_size) {
    if (!ptr || sizeof(long) == new_size) {
        return ptr;  // No need to reallocate memory
    }
    void* new_ptr = realloc(ptr, new_size);
    if (new_ptr) {
        return new_ptr;
    }
    free(ptr);  // Memory allocation failed, return original pointer
    return ptr;
}

void free_arrays(void* records) {
    free(records);  // Free memory for 'record' structures
    free(((record_t*)records)[-1].key);  // Free memory for 'int' keys
    free(((record_t*)records)[-2]);  // Free memory for 'long' offset values
}
