            cacheHits++;
            return NULL;
        }
    }

    // Fetch UE info from external source
    int* ueInfo = (int*)malloc(sizeof(int));
    *ueInfo = rnti + 1; // Simulate actual UE information

    // Cache fetched UE info
    if (ueInfoCacheIndex < CACHE_SIZE) {
        ueInfoCache[ueInfoCacheIndex++] = (void*)ueInfo;
    } else {
        free(ueInfo);
    }

    return NULL;
}

int createNfaApiCrcIndicationPduArray(int numUes) {
    int i, failureCountTemp = 0;

    for (i = 0; i < numUes; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

