            failureCountTemp++;
            free(pdu);
            continue;
        }

        nfaApiCrcIndicationPduArray[i] = pdu;

        totalAllocations++;

        if (numUes > MAX_UES) {
            // Resize array if more UEs are requested
            NFAPI_CRC_INDICATION_PDU_T** newPduArray = (NFAPI_CRC_INDICATION_PDU_T**)realloc(nfaApiCrcIndicationPduArray, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (numUes + 50));
            if (!newPduArray) {
                // Handle memory allocation failure
                for (int j = i; j >= 0; j--) {
                    free(nfaApiCrcIndicationPduArray[j]);
                }
                return -1;
            }
            nfaApiCrcIndicationPduArray = newPduArray;
        }
    }

    numUes = i;

    if (failureCountTemp > 0) {
        failureCount += failureCountTemp;
    }

    return numUes;
}
