// Function to manage memory for dynamic collection of records
Record** initializeRecords(int initialSize, int threshold, int seed) {
    Record** records = (Record**)malloc(initialSize * sizeof(Record*));
    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(seed);

    // Initialize records with random values and keys
    for (int i = 0; i < initialSize; i++) {
        int key = rand() % 10001;
        int value = rand() % 10000;

        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            printf("Error: Memory allocation failed.\n");
            return NULL;
        }

        record->key = key;
        record->value = value;

        // Validate the integrity of the records
        for (int j = 0; j < i; j++) {
            if (customHash(records[j]->key) == customHash(key)) {
                printf("Error: Duplicate key detected.\n");
                free(record);
                return NULL;
            }
        }

        records[i] = record;
    }

    // Implement dynamic resizing when the number of records exceeds the threshold
    while (1) {
        int newSize = initialSize * 2;
        Record** newRecords = (Record**)realloc(records, newSize * sizeof(Record*));
        if (!newRecords) {
            printf("Error: Memory reallocation failed.\n");
            return NULL;
        }

        // Resize the array and reinitialize records
        for (int i = initialSize; i < newSize; i++) {
            int key = rand() % 10001;
            int value = rand() % 10000;

            Record* record = (Record*)malloc(sizeof(Record));
            if (!record) {
                printf("Error: Memory allocation failed.\n");
                return NULL;
            }

            record->key = key;
            record->value = value;

            // Validate the integrity of the records
            for (int j = 0; j < i; j++) {
                if (customHash(records[j]->key) == customHash(key)) {
                    printf("Error: Duplicate key detected.\n");
                    free(record);
                    return NULL;
                }
            }

            newRecords[i] = record;
        }

        // Check if the threshold is exceeded
        if (newSize > threshold) {
            break;
        }

        initialSize = newSize;
    }

    return records;
}

// Function to filter records based on a specific key range
void filterRecords(Record** records, int minKey, int maxKey) {
    for (int i = 0; i < sizeof(*records); i++) {
        if ((records[i]->key < minKey || records[i]->key > maxKey)) {
            printf("Removed record with key %d.\n", records[i]->key);
            free(records[i]);
            break;
        }
    }
}

// Function to get the total count of records
int getTotalCount(Record** records) {
    int count = 0;
    for (int i = 0; i < sizeof(*records); i++) {
        if (records[i] != NULL) {
            count++;
        }
    }
    return count;
}

// Function to free the allocated memory
void freeRecords(Record** records, int initialSize) {
    for (int i = 0; i < initialSize; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }

    free(records);
}
