#define MAX_RECORDS 1000
#define KEY_RANGE 1 // adjust this value based on your requirements
#define STRING_MAX_LENGTH 256

typedef struct {
    int key;
    long offset;
    char* string;
} Record;

Record** manageRecords(int maxRecords, const char** possibleStrings) {
    Record** records = NULL;
    int numRecords = 0;

    // Allocate memory for the record array
    while ((records = (Record**)realloc(records, sizeof(Record*) * ++numRecords)) == NULL || numRecords > maxRecords) {
        printf("Error: Could not allocate memory for %dth record. Returning...\n", numRecords);
        break;
    }

    if (numRecords > 0) {
        // Initialize the records
        for (int i = 0; i < numRecords; i++) {
            Record* record = (Record*)malloc(sizeof(Record));
            if (record == NULL) {
                printf("Error: Could not allocate memory for record %d.\n", i);
                break;
            }

            // Generate random key and offset
            record->key = rand() % KEY_RANGE;
            record->offset = (long)time(NULL); // ensure unique offsets

            // Allocate memory for the string
            char* string = (char*)malloc(STRING_MAX_LENGTH * sizeof(char));
            if (string == NULL) {
                printf("Error: Could not allocate memory for string.\n");
                free(record);
                break;
            }

            int strIndex = rand() % (sizeof(possibleStrings) / sizeof(const char*));
            strncpy(string, possibleStrings[strIndex], STRING_MAX_LENGTH - 1);

            // Check for uniqueness
            bool isUnique = true;
            for (int j = 0; j < i; j++) {
                if (strcmp(string, records[j]->string) == 0) {
                    isUnique = false;
                    break;
                }
            }

            if (!isUnique) {
                printf("Error: Could not find a unique string.\n");
                free(record->string);
                free(record);
                break;
            }

            record->string = string;
            records[i] = record;
        }
    }

    // Report memory usage and fragmentation
    int totalMemoryUsed = 0;
    for (int i = 0; i < numRecords; i++) {
        totalMemoryUsed += sizeof(Record) + strlen(records[i]->string);
    }
    printf("Total memory used: %d bytes\n", totalMemoryUsed);

    return records;
}

void freeRecords(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i] != NULL) {
            free(records[i]->string);
            free(records[i]);
        }
    }

    free(records);
}
