enum AttackType { ATTACK_A, ATTACK_B };

struct Record {
    long* valuePointer;
    int key;
    char description[20];
    AttackType attackType;
    int cooldownTime;
};

class UnionFind {
public:
    UnionFind(int n) : parent_(n), rank_(n, 0) {
        for (int i = 0; i < n; ++i)
            parent_[i] = i;
    }

    int find(int x) {
        if (parent_[x] != x)
            parent_[x] = find(parent_[x]);
        return parent_[x];
    }

    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY)
            return;
        if (rank_[rootX] < rank_[rootY])
            std::swap(rootX, rootY);
        parent_[rootY] = rootX;
        if (rank_[rootX] == rank_[rootY])
            ++rank_[rootX];
    }

private:
    int* parent_;
    int* rank_;
};

void executeGameSystemActions(const std::string& label, const std::function<void(AttackType, int)>& f, const std::shared_ptr<int>& dataSource) {
    // Initialize memory for offsets and keys
    long* offsets = new long[1024];
    int* keys = new int[1024];

    // Populate records
    std::vector<Record> records;
    for (int i = 0; i < 1024; ++i) {
        Record record;
        record.valuePointer = &offsets[i];
        record.key = i;
        sprintf(record.description, "Key %d", i);
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);
        if (dis(gen))
            record.attackType = ATTACK_A;
        else
            record.attackType = ATTACK_B;
        record.cooldownTime = std::rand() % 16;

        // Ensure no consecutive identical attacks and respect cooldown period
        int prevAttackType = -2; // Initialize with invalid value
        for (const auto& r : records) {
            if (r.attackType == record.attackType && r.cooldownTime > 0) {
                --record.cooldownTime;
                while (record.attackType == r.attackType && r.cooldownTime > 0)
                    --r.cooldownTime;
            }
        }

        f(record.attackType, record.key);
    }

    // Initialize Union-Find data structure
    UnionFind uf(1024);

    // Identify disjoint pairs among records and measure processing time
    for (int i = 0; i < 1024; ++i) {
        int rootI = uf.find(i);
        for (int j = i + 1; j < 1024; ++j) {
            if (uf.find(j) != rootI) {
                uf.unite(i, j);
                std::cout << "Disjoint pair found: (" << i << ", " << j << ") in " << (double(std::clock() - clock()) / CLOCKS_PER_SEC * 1000) << " ms.\n";
            }
        }
    }

    // Clean up allocated memory
    delete[] offsets;
    delete[] keys;

    // Handle potential failures from external data source
