import subprocess
import hashlib
import json
import logging

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def validate_config(config):
    template = """
    # Example Kickstart configuration
    root_password={{root_password}}
    user_password={{user_password}}
    # ... rest of the config ...
    """
    for line in template.splitlines():
        if "{{" in line:
            placeholder, value = line.split("{{", 1)
            if not any(v == value for k, v in config.items()):
                raise Exception(f"Missing configuration parameter: {value}")
    return True

def modify_config(input_file, output_file, config):
    try:
        with open(input_file, "r") as f_in, open(output_file, "w") as f_out:
            data = f_in.read()
            for key, value in config.items():
                data = data.replace(f"{{{{{key}}}}}", str(value))
            f_out.write(data)
    except Exception as e:
        logging.error(f"Failed to modify configuration file: {e}")

def main(input_file, output_file, config):
    try:
        # Hash password
        password = hash_password(config.get("password", ""))
        config["root_password"] = password
        config["user_password"] = password

        # Validate configuration
        if not validate_config(config):
            raise Exception("Invalid Kickstart configuration")

        # Modify configuration file
        modify_config(input_file, output_file, config)
    except Exception as e:
        logging.error(f"Failed to process Kickstart configuration: {e}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 3:
        input_file = sys.argv[1]
        output_file = sys.argv[2]
        config_str = sys.argv[3]
        config = json.loads(config_str)
        main(input_file, output_file, config)
