    const size_t MEMORY_LIMIT = 1024 * 1024; // 1MB

    // Dynamically allocate memory for offsets and keys arrays
    long* offsets = nullptr;
    int* keys = nullptr;

    try {
        offsets = (long*)malloc(MEMORY_LIMIT);
        keys = (int*)malloc(sizeof(int) * MEMORY_LIMIT);

        if (!offsets || !keys) throw std::bad_alloc();

        // Initialize memory for records
        size_t recordCount = 0;
        for (int i = 0; i < MEMORY_LIMIT; ++i) {
            // Randomly set attack type and cooldown time
            int randNum = rand() % 2 ? ATTACK_A : ATTACK_B;
            int cooldown = rand() % 16;

            // Ensure no consecutive identical attacks
            while (recordCount > 0 && (randNum == (keys[recordCount - 1] % 2 ? ATTACK_A : ATTACK_B))) {
                randNum = rand() % 2 ? ATTACK_A : ATTACK_B;
                cooldown = rand() % 16;
            }

            // Allocate memory for record
            record* recordPtr = (record*)malloc(sizeof(record));
            if (!recordPtr) throw std::bad_alloc();

            // Initialize record
