#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <random>

struct Device {
    std::string id;
    std::string macAddress;
    bool connectionStatus;
    std::vector<std::string> connectedPorts;

    // Constructor
    Device(const std::string& id, const std::string& macAddress)
        : id(id), macAddress(macAddress), connectionStatus(false) {}
};

class DeviceManager {
public:
    void initialize(int numDevices, int maxPortsPerDevice);
    void updateConnectionStatus();
    void addDevice(const std::string& deviceID, const std::string& macAddress);
    void removeDevice(const std::string& deviceID);
    void updateDeviceConfig(const std::string& deviceID, const std::string& port);
    bool queryDeviceConfig(const std::string& deviceID);

private:
    std::vector<std::unique_ptr<Device>> devices;
    std::random_device rd;
    std::mt19937 gen;
};

void DeviceManager::initialize(int numDevices, int maxPortsPerDevice) {
    for (int i = 0; i < numDevices; ++i) {
        // Allocate memory for the device
        auto device = std::make_unique<Device>(std::to_string(i), "00:11:22:" + std::to_string(i));
        devices.push_back(std::move(device));
    }
}

void DeviceManager::updateConnectionStatus() {
    for (auto& device : devices) {
        if (std::bernoulli_distribution(0.7)(gen)) { // 70% chance of being connected
            device->connectionStatus = true;
        } else {
            device->connectionStatus = false;
        }
    }
}

void DeviceManager::addDevice(const std::string& deviceID, const std::string& macAddress) {
    auto device = std::make_unique<Device>(deviceID, macAddress);
    devices.push_back(std::move(device));
}

void DeviceManager::removeDevice(const std::string& deviceID) {
    for (auto it = devices.begin(); it != devices.end(); ++it) {
        if ((*it)->id == deviceID) {
            devices.erase(it);
            break;
        }
    }
}

void DeviceManager::updateDeviceConfig(const std::string& deviceID, const std::string& port) {
    for (auto& device : devices) {
        if (device->id == deviceID) {
            device->connectedPorts.push_back(port);
            break;
        }
    }
}

bool DeviceManager::queryDeviceConfig(const std::string& deviceID) {
    for (const auto& device : devices) {
        if (device->id == deviceID) {
            return true; // Device found
        }
    }
    return false; // Device not found
}
