#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 1000
#define CRC_RANGE 255

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_array(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    for (int i = 0; i < size; i++) {
        (*array)[i].rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if ((*array)[i].rx_ue_info == NULL) {
            printf("Memory allocation failed\n");
            free(*array);
            *array = NULL;
            return;
        }
    }
}

void validate_array(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    for (int i = 0; i < size; i++) {
        if ((*array)[i].rnti == (*array)[(i+1)%size].rnti) {
            printf("Invalid RNTI value\n");
            return;
        }
        srand(time(NULL));
        (*array)[i].crc_rel8_tag = rand() % CRC_RANGE;
    }
}

void update_array(NFAPI_CRC_INDICATION_PDU_T **array, int old_size, int new_size) {
    if (new_size < old_size) {
        for (int i = 0; i < new_size; i++) {
            free((*array)[i].rx_ue_info);
        }
        free(*array);
        *array = NULL;
        return;
    } else if (new_size > old_size) {
        NFAPI_CRC_INDICATION_PDU_T *temp_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc((new_size - old_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp_array == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        for (int i = 0; i < new_size - old_size; i++) {
            temp_array[i].rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
            if (temp_array[i].rx_ue_info == NULL) {
                printf("Memory allocation failed\n");
                free(temp_array);
                *array = NULL;
                return;
            }
        }
        for (int i = old_size - 1; i >= 0; i--) {
            (*array)[i + (new_size - old_size)] = temp_array[i];
        }
        for (int i = 0; i < old_size; i++) {
            free((*array)[i].rx_ue_info);
        }
        free(*array);
        *array = NULL;
    }
}

void add_element(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    NFAPI_CRC_INDICATION_PDU_T *temp_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*array, (size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (temp_array == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    (*array)[size].rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
    if ((*array)[size].rx_ue_info == NULL) {
        printf("Memory allocation failed\n");
        free(temp_array);
        *array = NULL;
        return;
    }
    srand(time(NULL));
    (*array)[size].rnti = rand() % CRC_RANGE;
    (*array)[size].crc_rel8_tag = rand() % CRC_RANGE;
    *array = temp_array;
}

void remove_element(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    if (size > 0) {
        for (int i = size - 1; i >= 0; i--) {
            free((*array)[i].rx_ue_info);
        }
        free(*array);
        *array = NULL;
    }
}

void query_array(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    for (int i = 0; i < size; i++) {
        printf("RNTI: %d, CRC flag: %d\n", (*array)[i].rnti, (*array)[i].crc_rel8_tag);
    }
}

void update_crc_flag(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    for (int i = 0; i < size; i++) {
        srand(time(NULL));
        (*array)[i].crc_rel8_tag = rand() % CRC_RANGE;
    }
}

void main() {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int size = 5;
    initialize_array(&array, size);
    validate_array(&array, size);
    add_element(&array, size);
    query_array(&array, size + 1);
    update_crc_flag(&array, size + 1);
    remove_element(&array, size + 1);
}
