#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char *str;
} record;

record* create_records(char *sentence, size_t n, size_t offset_max) {
    // Initialize random number generator
    srand(time(NULL));

    // Calculate maximum string length
    size_t max_str_len = 256;
    if (max_str_len > strlen(sentence)) {
        max_str_len = strlen(sentence);
    }

    record *records = (record *)malloc(n * sizeof(record));
    if (!records) return NULL; // Memory allocation failed

    long *offsets = (long *)malloc(n * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL; // Memory allocation failed
    }

    int *keys = (int *)malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        return NULL; // Memory allocation failed
    }

    char **strptrs = (char **)malloc(n * sizeof(char *));
    if (!strptrs) {
        free(keys);
        free(offsets);
        free(records);
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < n; i++) {
        offsets[i] = rand() % offset_max;
        keys[i] = rand() % 100;

        size_t str_len = rand() % max_str_len + 1;
        char *str = (char *)malloc(str_len);
        if (!str) {
            for (size_t j = i; j > 0; j--) {
                free(strptrs[j-1]);
            }
            free(keys);
            free(offsets);
            free(records);
            return NULL; // Memory allocation failed
        }

        strncpy(str, sentence + (rand() % strlen(sentence) - str_len), str_len);

        records[i].value = keys[i];
        records[i].str = str;
        strptrs[i] = str;
    }

    for (size_t i = 0; i < n; i++) {
        free(strptrs[i]);
    }
    free(strptrs);
    free(keys);
    free(offsets);

    return records;
}

void destroy_records(record *records, size_t n) {
    for (size_t i = 0; i < n; i++) {
        free(records[i].str);
    }
    free(records);
}
