NFAPI_RRC_MSG_T *nfapi_rrc_msg_array[MAX_MESSAGES];
int nfapi_rrc_msg_array_size = 0;
int nfapi_rrc_msg_cache[CACHE_SIZE];
int nfapi_rrc_msg_cache_size = 0;
int nfapi_rrc_msg_random_nas_id_seed = time(NULL);

void init_nfaapi_rrc_msg_array(int max_messages, int seed) {
    if (seed != -1)
        nfapi_rrc_msg_random_nas_id_seed = seed;

    for (int i = 0; i < max_messages; i++) {
        NFAPI_RRC_MSG_T *msg = malloc(sizeof(NFAPI_RRC_MSG_T));
        if (msg == NULL) {
            // Handle memory allocation failure
            perror("Memory allocation failed");
            return;
        }
        msg->type = get_random_message_type();
        msg->preamble.nas_id = generate_nas_id(nfapi_rrc_msg_random_nas_id_seed);
        nfaapi_rrc_msg_array[i] = msg;
    }
    nfaapi_rrc_msg_array_size = max_messages;
}

void clear_cache() {
    for (int i = 0; i < nfaapi_rrc_msg_cache_size; i++) {
        free(nfaapi_rrc_msg_array[nfaapi_rrc_msg_cache[i]]);
    }
    nfaapi_rrc_msg_cache_size = 0;
}

PREAMBLE *get_preamble_from_type(RRC_MESSAGE_TYPE type) {
    if (type == -1 || type >= CACHE_SIZE) {
        // Handle cache miss
        PREAMBLE *preamble = malloc(sizeof(PREAMBLE));
        preamble->nas_id = generate_nas_id(nfapi_rrc_msg_random_nas_id_seed);
        return preamble;
    }
    return &nfaapi_rrc_msg_array[nfaapi_rrc_msg_cache[type - 1]]->preamble;
}

int get_message_index_by_type(RRC_MESSAGE_TYPE type) {
    for (int i = 0; i < nfaapi_rrc_msg_array_size; i++) {
        if (nfaapi_rrc_msg_array[i]->type == type)
            return i;
    }
    return -1;
}

void print_nfaapi_rrc_msg_array() {
    for (int i = 0; i < nfapi_rrc_msg_array_size; i++) {
        printf("Type: %d, NAS ID: %u\n", nfaapi_rrc_msg_array[i]->type,
               nfaapi_rrc_msg_array[i]->preamble.nas_id);
    }
}
