typedef struct {
    uint32_t key;
    uint64_t offset;
    int value;
    char* string;
} Record;

Record* addEntry(char* sentence, int maxRecords, int minKeyRange, int maxKeyRange) {
    // Initialize random number generator
    srand(time(NULL));

    Record** records = (Record**)malloc(sizeof(Record*) * maxRecords);
    for (int i = 0; i < maxRecords; i++) {
        if (!records[i]) return NULL; // Memory allocation failed
    }

    int currentOffset = 0;
    for (int i = 0; i < maxRecords; i++) {
        Record* record = records[i] = (Record*)malloc(sizeof(Record));
        if (!record) return NULL; // Memory allocation failed

        record->key = rand() % (maxKeyRange - minKeyRange + 1) + minKeyRange;
        record->offset = currentOffset++;
        int value = rand() % 1000; // Random integer value
        char str[256];
        if (sentence) {
            if (strlen(sentence) < 10) {
                sentence = "This is a test sentence";
            }
            sprintf(str, "%s_%d", sentence, value);
        } else {
            strcpy(str, "No input sentence");
        }

        record->value = value;
        record->string = str;
    }

    return records[0];
}

void freeRecords(Record** records) {
    for (int i = 0; records[i]; i++) {
        Record* record = records[i];
        free(record);
    }
    free(records);
}
