    // Fetch input sentence asynchronously from remote server
    const char* fetched_sentence = fetch_sentence_from_server();
    if (!fetched_sentence) {
        LOG_ERROR("Failed to retrieve input sentence");
        return NULL;
    }

    // Determine maximum length of the fetched sentence
    size_t max_sentence_length = strlen(fetched_sentence);

    // Initialize arrays for storing data structures
    long* offset_array = (long*)malloc(max_keys * sizeof(long));
    int* key_array = (int*)malloc(max_keys * sizeof(int));
    record_t** record_array = (record_t**)malloc(max_keys * sizeof(record_t*));

    // Process the sentence and generate records
    for (size_t i = 0; i < max_keys; i++) {
        const char* substring = fetched_sentence;
        size_t substring_length = strlen(substring);

        // Initialize record structure with random int value
        record_t* record = (record_t*)malloc(sizeof(record_t));
        record->key = rand() % 100;

        // Determine length of the substring and allocate memory for it
        size_t substring_offset = i * 256;
        if (substring_length < i) {
            LOG_WARNING("Insufficient sentence length, using placeholder");
            substring = "PLACEHOLDER";
        } else {
            substring = &fetched_sentence[substring_offset];
        }

        // Allocate memory for the substring and copy it to the record
        char* str = (char*)malloc(257);
        strncpy(str, substring, 256);
        str[256] = '\0';
        record->offset = (long)str;

        // Add the record to the arrays
        offset_array[i] = i;
        key_array[i] = record->key;
        record_array[i] = record;
    }

    // Clean up logging library
    logging_deinit();

    return record_array;
}
