typedef struct {
    uint64_t request_id;
    int status_code;
    char** custom_headers;
    int num_custom_headers;
} ResponseHeader;

ResponseHeader* create_response_header() {
    ResponseHeader* header = (ResponseHeader*)malloc(sizeof(ResponseHeader));
    if (!header) {
        return NULL; // Memory allocation failed
    }

    header->request_id = (uint64_t)time(NULL);
    header->status_code = 200;
    header->num_custom_headers = 0;

    return header;
}

void add_custom_header(ResponseHeader* header, char* name, char* value) {
    if (!header || !name || !value) {
        return; // Invalid arguments
    }

    header->custom_headers = (char**)realloc(header->custom_headers, (header->num_custom_headers + 1) * sizeof(char*));
    if (!header->custom_headers) {
        free(header);
        return; // Memory allocation failed
    }

    header->custom_headers[header->num_custom_headers] = (char*)malloc(strlen(name) + strlen(value) + 2);
    strcpy(header->custom_headers[header->num_custom_headers], name);
    strcat(header->custom_headers[header->num_custom_headers], ": ");
    strcat(strcat(strcpy(header->custom_headers[header->num_custom_headers], ""), value), "\r\n");

    header->num_custom_headers++;
}

void free_response_header(ResponseHeader* header) {
    if (!header) {
        return; // Invalid argument
    }

    for (int i = 0; i < header->num_custom_headers; i++) {
        free(header->custom_headers[i]);
    }

    free(header);
}

