void init_record_array(int initial_size) {
    if (initial_size <= 0) {
        return;
    }

    array_size = initial_size;
    current_capacity = initial_size;
    record_array = malloc(initial_size * sizeof(Record));

    for (int i = 0; i < initial_size; i++) {
        record_array[i].key = rand() % KEY_RANGE_MAX + KEY_RANGE_MIN;
        record_array[i].value = rand();
        record_array[i].timestamp = time(NULL);
    }
}

void resize_record_array(int new_capacity) {
    if (new_capacity <= current_capacity || new_capacity < 2 * current_capacity) {
        return;
    }

    Record* new_array = realloc(record_array, new_capacity * sizeof(Record));
    array_size = new_capacity;

    for (int i = current_capacity; i < new_capacity; i++) {
        new_array[i].key = rand() % KEY_RANGE_MAX + KEY_RANGE_MIN;
        new_array[i].value = rand();
        new_array[i].timestamp = time(NULL);
    }

    free(record_array);
    record_array = new_array;
}

