// Function to initialize and configure a list of LTE UE contexts
void* initialize_ue_contexts(int num_ue_contexts, pthread_mutex_t *mutex) {
    // Dynamically allocate memory for each context
    lte_ue_context **ue_contexts = (lte_ue_context**)malloc(num_ue_contexts * sizeof(lte_ue_context*));

    if (!ue_contexts) {
        return NULL;
    }

    int i;
    for (i = 0; i < num_ue_contexts; i++) {
        ue_contexts[i] = (lte_ue_context*)malloc(sizeof(lte_ue_context));

        // Initialize UE identity and measurement reports
        sprintf(ue_contexts[i]->ue_identity, "UE_%d", i);
        ue_contexts[i]->num_measurement_reports = 5;
        ue_contexts[i]->measurement_reports = (struct measurement_report*)malloc(ue_contexts[i]->num_measurement_reports * sizeof(struct measurement_report));

        // Sort measurement reports by signal strength in descending order
        qsort((void*)ue_contexts[i]->measurement_reports, ue_contexts[i]->num_measurement_reports, sizeof(struct measurement_report), compare_signal_strength);

        pthread_mutex_lock(mutex);
        // Fetch latest network configuration parameters from external data source (may introduce latency)
        fetch_network_config_params();

        pthread_mutex_unlock(mutex);
    }

    return (void*)ue_contexts;
}

// Function to compare signal strengths for sorting
int compare_signal_strength(const void *a, const void *b) {
    struct measurement_report *report_a = (struct measurement_report*)a;
    struct measurement_report *report_b = (struct measurement_report*)b;

    if (report_a->signal_strength > report_b->signal_strength) {
        return -1;
    } else if (report_a->signal_strength < report_b->signal_strength) {
        return 1;
    } else {
        return 0;
    }
}

