    if (size < 0) {
        return NULL; // Return error for negative input
    }

    // Initialize array with NULL values, as we need to dynamically allocate memory
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!arr) {
        return NULL; // Handle memory allocation failure gracefully
    }

    for (int i = 0; i < size; i++) {
        // Initialize RX_UE_INFORMATION_TAG to ensure uniqueness within the array
        arr[i].RX_UE_INFORMATION_TAG = i;

        // Randomly set CRCFLAG in each CRC_INDICATION_REL8_TAG
        srand(time(NULL));
        int randomFlag = rand() % 7 + 1; // Avoid flags that could lead to hardware misinterpretation or performance degradation
        arr[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (uint32_t)randomFlag;
    }

    return arr;
}

// Function to print details of populated array for debugging
void printArray(NFAPI_CRC_INDICATION_PDU_T* arr, int size) {
