use rand::Rng;
use std::collections::HashMap;
use reqwest;

struct Dataset {
    indices: Vec<i32>,
    data_points: Vec<DataPoint>,
    num_data_points: usize,
    min_value: f64,
    max_value: f64,
}

struct DataPoint {
    value: f64,
    label: String,
}

impl Dataset {
    fn new() -> Self {
        Dataset {
            indices: vec![],
            data_points: vec![],
            num_data_points: 0,
            min_value: f64::MAX,
            max_value: f64::MIN,
        }
    }

    fn create_dataset(&mut self) {
        let mut rng = rand::thread_rng();
        for i in 0..10 {
            let value = rng.gen_range(0.0, 1.0);
            let label = format!("Index-{}-Timestamp-{}", i, chrono::Utc::now());
            self.data_points.push(DataPoint { value, label });
            if value < self.min_value {
                self.min_value = value;
            }
            if value > self.max_value {
                self.max_value = value;
            }
            self.num_data_points += 1;
        }
    }

    fn reset(&mut self) {
        self.indices.clear();
        self.data_points.clear();
        self.num_data_points = 0;
        self.min_value = f64::MAX;
        self.max_value = f64::MIN;
    }
}

fn main() {
    let mut dataset = Dataset::new();
    dataset.create_dataset();
    // Use the dataset
    dataset.reset();
}
