#include <sstream>
#include <algorithm>

// Predefined severity levels
enum class Severity {
    DEBUG,
    WARNING,
    ERROR
};

// Custom comparator function for sorting log entries
class LogComparator {
public:
    bool operator()(const std::pair<std::chrono::time_point<std::chrono::system_clock>, std::string>& a, const std::pair<std::chrono::time_point<std::chrono::system_clock>, std::string>& b) {
        return a.first < b.first;
    }
};

// Custom comparator function for sorting log entries by severity
class SeverityComparator {
public:
    bool operator()(const std::pair<Severity, std::string>& a, const std::pair<Severity, std::string>& b) {
        if (a.first == Severity::DEBUG && b.first == Severity::ERROR) {
            return true;
        }
        else if (a.first == Severity::WARNING && b.first == Severity::DEBUG) {
            return false;
        }
        else {
            return a.first > b.first;
        }
    }
};

// Custom struct for log entry management
struct LogEntry {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    Severity severity;
    std::string sourceModule;
    std::string message;

    // Validation check for log entry
    bool isValid() const {
        return (timestamp >= std::chrono::system_clock::now() - std::chrono::hours(24)) && (severity == Severity::DEBUG || severity == Severity::WARNING || severity == Severity::ERROR);
    }
};

// Custom function to manage dynamic collection of log entries
class LogManager {
public:
    // Function to add log entry with memory management and validation checks
    void addLogEntry(std::chrono::time_point<std::chrono::system_clock> timestamp, Severity severity, std::string sourceModule, std::string message) {
        // Allocate memory for new log entry
        LogEntry* logEntry = new LogEntry;
        logEntry->timestamp = timestamp;
        logEntry->severity = severity;
        logEntry->sourceModule = sourceModule;
        logEntry->message = message;

        // Validate log entry
        if (!logEntry->isValid()) {
            delete logEntry;
            throw std::runtime_error("Invalid log entry");
        }

        // Add log entry to dynamic collection
        logEntries_.push_back(logEntry);
    }

    // Function to filter log entries based on user-specified severity levels or time ranges
    void filterLogEntries(Severity minSeverity, Severity maxSeverity, std::chrono::time_point<std::chrono::system_clock> startTime, std::chrono::time_point<std::chrono::system_clock> endTime) {
        // Create filtered log entry list
        std::vector<LogEntry*> filteredLogEntries;

        for (auto& logEntry : logEntries_) {
            if ((logEntry->severity >= minSeverity && logEntry->severity <= maxSeverity) && (logEntry->timestamp >= startTime && logEntry->timestamp <= endTime)) {
                filteredLogEntries.push_back(logEntry);
            }
        }

        // Update original log entry list
        logEntries_ = filteredLogEntries;
    }

    // Function to serialize log entries to a file in JSON format
    void serializeLogEntries(const std::string& fileName) {
        // Open output file stream
        std::ofstream fileStream(fileName, std::ios::out);

        if (fileStream.is_open()) {
            for (auto& logEntry : logEntries_) {
                fileStream << "{\"timestamp\": \"" << logEntry->timestamp.time_since_epoch().count() << "\", \"severity\": \"" << (logEntry->severity == Severity::DEBUG ? "DEBUG" : (logEntry->severity == Severity::WARNING ? "WARNING" : "ERROR")) << "\", \"sourceModule\": \"" << logEntry->sourceModule << "\", \"message\": \"" << logEntry->message << "\"}" << std::endl;
            }
        }

        fileStream.close();
    }

private:
    // Dynamic collection of log entries
    std::vector<LogEntry*> logEntries_;
};

int main() {
    try {
        LogManager logManager;

        // Add log entries with memory management and validation checks
        logManager.addLogEntry(std::chrono::system_clock::now(), Severity::WARNING, "myApp", "Error occurred during initialization");
        logManager.addLogEntry(std::chrono::system_clock::now() - std::chrono::hours(2), Severity::DEBUG, "myModule", "Initialization complete");

        // Filter log entries based on user-specified severity levels or time ranges
        logManager.filterLogEntries(Severity::WARNING, Severity::ERROR, std::chrono::system_clock::now() - std::chrono::days(1), std::chrono::system_clock::now());

        // Serialize log entries to a file in JSON format
        logManager.serializeLogEntries("log_entries.json");
    }
    catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

