sensorReading** processAndAnalyzeSensorData(int numSources, int maxReadingsPerSource) {
    // Initialize dynamic memory allocation for array of sensor readings
    sensorReading** sensorReadings = (sensorReading**)malloc(numSources * sizeof(sensorReading*));

    for (int i = 0; i < numSources; i++) {
        sensorReadings[i] = (sensorReading*)malloc(maxReadingsPerSource * sizeof(sensorReading));

        // Populate sensor readings with measurements from multiple concurrent data sources
        for (int j = 0; j < maxReadingsPerSource; j++) {
            // Read temperature measurement and timestamp from data source i
            float temp = readTemperatureMeasurement(i);
            time_t timestamp = readTimestampFromDataSouce(i);

            // Ensure no two entries have the same timestamp across all sources
            while (findDuplicateTimestamp(timestamp, sensorReadings[i], j)) {
                timestamp = readTimestampFromDataSouce(i);
            }

            // Create and initialize a new sensor reading structure
            sensorReading* reading = (sensorReading*)malloc(sizeof(sensorReading));
            reading->temperature = temp;
            reading->timestamp = timestamp;
            reading->description = getSensorDescription(i, j);

            // Add the new reading to the array of sensor readings
            sensorReadings[i][j] = reading;
        }
    }

    return sensorReadings;
}

// Helper function to process a list of timestamps and find the average temperature over a specified time window
float processTimestamps(sensorReading** sensorReadings, int numSources, int maxReadingsPerSource, time_t startTime, time_t endTime) {
    int totalReadings = 0;
    float totalTemperature = 0.0f;

    for (int i = 0; i < numSources; i++) {
        for (int j = 0; j < maxReadingsPerSource; j++) {
            sensorReading* reading = sensorReadings[i][j];

            // Check if the timestamp falls within the specified time window
            if (reading->timestamp >= startTime && reading->timestamp <= endTime) {
                totalReadings++;
                totalTemperature += reading->temperature;
            }
        }
    }

    return totalTemperature / totalReadings;
}

// Function to detect and log inconsistencies in sensor data
void logSensorDataInconsistencies(sensorReading** sensorReadings, int numSources, int maxReadingsPerSource) {
    for (int i = 0; i < numSources; i++) {
        for (int j = 0; j < maxReadingsPerSource; j++) {
            sensorReading* reading = sensorReadings[i][j];

            // Check for inconsistencies in temperature readings
            if (reading->temperature > MAX_TEMPERATURE || reading->temperature < MIN_TEMPERATURE) {
                logInconsistency(reading);
            }
        }
    }
}

