typedef struct record {
    int value;
    struct record* next;
} Record;

Record* create_record(int key) {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) return NULL;
    rec->value = rand() % 100; // Initialize with a random value
    rec->next = NULL;
    return rec;
}

int compare_records(const void* rec1, const void* rec2) {
    Record* r1 = (Record*)rec1;
    Record* r2 = (Record*)rec2;
    int key_diff = *(((int*)r1) + 1) - *(((int*)r2) + 1);
    return key_diff;
}

void init_data_structure(int size, int* keys, long* offsets, int range_min, int range_max, Record*** records_out) {
    if (!size || !keys || !offsets) return; // Handle invalid input

    *records_out = (Record**)malloc(size * sizeof(Record*));
    for (int i = 0; i < size; i++) {
        (*records_out)[i] = create_record(keys[i]);
        if (!(*records_out)[i]) {
            // Handle allocation failure
            free_records(*records_out);
            return;
        }
    }

    qsort(*records_out, size, sizeof(Record*), compare_records); // Sort records by key

    for (int i = 0; i < size; i++) {
        printf("Offset: %ld, Key: %d, Value: %d\n", offsets[i], keys[i], (*records_out)[i]->value);
    }
}

void free_records(Record** records) {
    if (!records) return;

    for (int i = 0; i < size; i++) {
        Record* current = records[i];
        while (current) {
            Record* next = current->next;
            free(current);
            current = next;
        }
    }

    free(records);
}

int main() {
