typedef struct {
    long timestamp;
    double value;
} entry;

entry* read_entries(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    // Pre-allocate memory for 10 entries to start with
    int num_entries = 0;
    entry* entries = (entry*)malloc(10 * sizeof(entry));

    while (1) {
        entry e;
        if (!fscanf(file, "%ld %lf", &e.timestamp, &e.value)) {
            break; // Reached end of file or error
        }

        // Apply mathematical formula to calculate value
        e.value = sin(e.timestamp / 1000.0);

        // Check for invalid entries (timestamp < 0)
        if (e.timestamp < 0) {
            printf("Skipping invalid entry: %ld %lf\n", e.timestamp, e.value);
            continue;
        }

        // Add new entry to the array
        if (num_entries == 10) {
            int new_size = num_entries * 2 + 1;
            entry* new_entries = (entry*)realloc(entries, new_size * sizeof(entry));
            entries = new_entries;
        }
        entries[num_entries] = e;
        num_entries++;
    }

    fclose(file);

    // Resize the array to the actual number of entries
    entry* new_entries = (entry*)realloc(entries, num_entries * sizeof(entry));
    free(entries);
    return new_entries;
}
