#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 256 // Default table size
#define BUCKETS_PER_BLOCK 4 // Number of buckets per block

typedef struct {
    char* name;
    int quantity;
    double price;
} Item;

typedef struct {
    Item* items;
    int count; // Current number of items in the bucket
} Bucket;

typedef struct {
    Bucket** blocks;
    int table_size; // Actual size of the hash table
    int block_count; // Number of blocks allocated
} HashTable;

// Function to calculate the total value of all items in the inventory
double calculateTotalValue(HashTable* inventory) {
    double total = 0.0;
    for (int i = 0; i < inventory->table_size; i++) {
        Bucket* block = inventory->blocks[i];
        if (block) {
            for (int j = 0; j < BUCKETS_PER_BLOCK; j++) {
                Item* item = block->items + j;
                if (item) {
                    total += item->quantity * item->price;
                }
            }
        }
    }
    return total;
}

// Function to add an item to the inventory
void addItem(HashTable* inventory, char* name, int quantity, double price) {
    int hash = 0;
    Bucket* block;

    // Hash the name to determine which bucket to store the item in
    for (int i = 0; i < strlen(name); i++) {
        hash += name[i];
    }

    // Handle collisions by placing items in separate buckets within a block
    int bucket_index = hash % inventory->table_size;
    if (inventory->blocks[bucket_index] == NULL) {
        // Allocate a new block if the corresponding bucket is empty
        block = malloc(sizeof(Bucket));
        block->items = malloc(sizeof(Item) * BUCKETS_PER_BLOCK);
        block->count = 0;
        inventory->blocks[bucket_index] = block;
    } else {
        block = inventory->blocks[bucket_index];
    }

    // Add the item to the bucket
    Item* item = &block->items[block->count++];
    strcpy(item->name, name);
    item->quantity = quantity;
    item->price = price;
}

// Function to remove an item from the inventory
void removeItem(HashTable* inventory, char* name) {
    int hash = 0;

    // Hash the name to determine which bucket to search in
    for (int i = 0; i < strlen(name); i++) {
        hash += name[i];
    }

    int bucket_index = hash % inventory->table_size;
    Bucket* block = inventory->blocks[bucket_index];

    if (block) {
        for (int j = 0; j < BUCKETS_PER_BLOCK; j++) {
            Item* item = &block->items[j];
            if (item && strcmp(item->name, name) == 0) {
                // Update the bucket's count and remove the item
                block->count--;
                item->quantity = 0;
                return;
            }
        }
    }
}

// Function to dynamically resize the hash table
void resizeTable(HashTable* inventory, int new_size) {
    HashTable* new_inventory = malloc(sizeof(HashTable));
    new_inventory->table_size = new_size;
    new_inventory->block_count = (new_size + BUCKETS_PER_BLOCK - 1) / BUCKETS_PER_BLOCK;

    // Reallocate the blocks
    new_inventory->blocks = malloc(sizeof(Bucket*) * new_inventory->block_count);
    for (int i = 0; i < new_inventory->block_count; i++) {
        new_inventory->blocks[i] = NULL;
    }

    // Copy existing items to the new inventory
    for (int i = 0; i < inventory->table_size; i++) {
        Bucket* block = inventory->blocks[i];
        if (block) {
            int bucket_index = i % new_inventory->table_size;
            Bucket* new_block = &new_inventory->blocks[bucket_index][block->count / BUCKETS_PER_BLOCK];
            for (int j = 0; j < BUCKETS_PER_BLOCK; j++) {
                Item* item = block->items + j;
                if (item) {
                    strcpy(item->name, item->name);
                    item->quantity = item->quantity;
                    item->price = item->price;
                    new_block->count++;
                }
            }
        }
    }

    // Free the old inventory
    free(inventory->blocks);
    for (int i = 0; i < inventory->block_count; i++) {
        Bucket* block = inventory->blocks[i];
        if (block) {
            free(block->items);
            free(block);
        }
    }
    free(inventory);

    // Update the pointer to point to the new inventory
    inventory = new_inventory;
}

int main() {
    HashTable* inventory = malloc(sizeof(HashTable));
    inventory->table_size = TABLE_SIZE;
    inventory->block_count = (inventory->table_size + BUCKETS_PER_BLOCK - 1) / BUCKETS_PER_BLOCK;

    inventory->blocks = malloc(sizeof(Bucket*) * inventory->block_count);
    for (int i = 0; i < inventory->block_count; i++) {
        inventory->blocks[i] = NULL;
    }

    // Test adding and removing items
    addItem(inventory, "Item1", 10, 5.99);
    addItem(inventory, "Item2", 20, 9.99);
    addItem(inventory, "Item3", 30, 7.99);

    printf("Total value: %f\n", calculateTotalValue(inventory));

    removeItem(inventory, "Item1");

    printf("Total value after removing Item1: %f\n", calculateTotalValue(inventory));

    // Test resizing the table
    int new_size = TABLE_SIZE * 2;
    resizeTable(inventory, new_size);

    return 0;
}

