#define MAX_ENTRIES 1024
#define FILE_NAME "nfa_pi_crc_indication_pdu_t_list.bin"

typedef struct {
    uint8_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T_LIST;

NFAPI_CRC_INDICATION_PDU_T_LIST* nfa_pi_crc_indication_pdu_t_list_new() {
    NFAPI_CRC_INDICATION_PDU_T_LIST* list = (NFAPI_CRC_INDICATION_PDU_T_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_LIST));
    if (!list) return NULL;
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = MAX_ENTRIES;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void nfa_pi_crc_indication_pdu_t_list_free(NFAPI_CRC_INDICATION_PDU_T_LIST* list) {
    if (!list) return;
    for (int i = 0; i < list->size; i++) free((void*)(&list->entries[i]));
    free(list->entries);
    free(list);
    pthread_mutex_destroy(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T_LIST* nfa_pi_crc_indication_pdu_t_list_append(NFAPI_CRC_INDICATION_PDU_T_LIST* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!list || !entry) return NULL;
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        // If the current capacity is reached, double it
        list->entries = realloc(list->entries, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->entries) {
            pthread_mutex_unlock(&list->mutex);
            return NULL;
        }
        list->capacity *= 2;
    }
    list->entries[list->size] = *entry;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return list;
}

int nfa_pi_crc_indication_pdu_t_list_serialize(NFAPI_CRC_INDICATION_PDU_T_LIST* list, int fd) {
    if (!list || !fd) return -1;
    struct {
        uint32_t size;
    } header;
    header.size = list->size;
    write(fd, &header, sizeof(header));
    for (int i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T entry = list->entries[i];
        if (write(fd, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == -1) return -1;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T_LIST* nfa_pi_crc_indication_pdu_t_list_deserialize(int fd) {
    NFAPI_CRC_INDICATION_PDU_T_LIST* list = (NFAPI_CRC_INDICATION_PDU_T_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_LIST));
    if (!list) return NULL;
    int32_t size;
    read(fd, &size, sizeof(int32_t));
    list->size = size;
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        read(fd, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->entries[i] = entry;
    }
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T_LIST* list = nfa_pi_crc_indication_pdu_t_list_new();
    if (!list) exit(EXIT_FAILURE);

    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        // Initialize the entry
        entry.rx_ue_information_tag = i;
        entry.rnti = i * 2;
        entry.crc_indication_rel8_tag = i % 2 ? 1 : 0;
        entry.crcflag = i % 2 ? 1 : 0;

        if (!nfa_pi_crc_indication_pdu_t_list_append(list, &entry)) {
            exit(EXIT_FAILURE);
        }
    }

    int fd = open(FILE_NAME, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) exit(EXIT_FAILURE);

    if (nfa_pi_crc_indication_pdu_t_list_serialize(list, fd) == -1) {
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);

    NFAPI_CRC_INDICATION_PDU_T_LIST* deserialized_list = nfa_pi_crc_indication_pdu_t_list_deserialize(fd);
    if (!deserialized_list) {
        printf("Error deserializing the list\n");
        return 1;
    }
    // Use the deserialized list
