typedef struct HashNode {
    Item *item;
    struct HashNode* next;
} HashNode;

// Define the hash table
typedef struct {
    int size;
    HashNode** buckets;
    int used;
    void (*free)(void*);
} HashTable;

// Function to create a new item structure
Item* newItem(char* name, int quantity, double price) {
    Item* item = (Item*)malloc(sizeof(Item));
    strcpy(item->name, name);
    item->quantity = quantity;
    item->price = price;
    return item;
}

// Function to free the memory of an item structure
void freeItem(void* ptr) {
    free(ptr);
}

// Function to create a new hash table with the given size
HashTable* newHashTable(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    table->used = 0;
    return table;
}

// Function to free the memory of a hash table
void freeHashTable(void* ptr) {
    HashTable* table = (HashTable*)ptr;
    for(int i = 0; i < table->size; i++) {
        HashNode* node = table->buckets[i];
        while(node != NULL) {
            HashNode* next = node->next;
            freeItem(node->item);
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

// Function to calculate the hash value of a given string
int hash(char* str, int size) {
    unsigned int hash = 0;
    for(int i = 0; i < strlen(str); i++) {
        hash = (hash * 31 + str[i]) % size;
    }
    return hash;
}

// Function to insert an item into the hash table
void insertItem(HashTable* table, Item* item) {
    int index = hash(item->name, table->size);
    HashNode* node = table->buckets[index];
    while(node != NULL) {
        if(strcmp(node->item->name, item->name) == 0) {
            node->item->quantity += item->quantity;
            return;
        }
        node = node->next;
    }
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->item = item;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    table->used++;
}

// Function to retrieve an item from the hash table
Item* retrieveItem(HashTable* table, char* name) {
    int index = hash(name, table->size);
    HashNode* node = table->buckets[index];
    while(node != NULL) {
        if(strcmp(node->item->name, name) == 0) {
            return node->item;
        }
        node = node->next;
    }
    return NULL;
}

// Function to calculate the total value of all items
double calculateTotalValue(HashTable* table) {
    double total = 0.0;
    for(int i = 0; i < table->size; i++) {
        HashNode* node = table->buckets[i];
        while(node != NULL) {
            total += node->item->quantity * node->item->price;
            node = node->next;
        }
    }
    return total;
}

int main() {
    // Create a new hash table with size 10
    HashTable* table = newHashTable(10);

    // Create some item structures
    Item* item1 = newItem("Item1", 5, 20.0);
    Item* item2 = newItem("Item2", 3, 15.0);
    Item* item3 = newItem("Item3", 8, 25.0);

    // Insert the items into the hash table
    insertItem(table, item1);
    insertItem(table, item2);
    insertItem(table, item3);

    // Retrieve an item from the hash table
    Item* retrievedItem = retrieveItem(table, "Item1");
    printf("Retrieved item name: %s\n", retrievedItem->name);
    printf("Retrieved item quantity: %d\n", retrievedItem->quantity);
    printf("Retrieved item price: %.2f\n", retrievedItem->price);

    // Calculate the total value of all items
    double totalValue = calculateTotalValue(table);
    printf("Total value: %.2f\n", totalValue);

    // Free the memory of the hash table and its items
    freeHashTable(table);

    return 0;
}
