    NFAPI_CRC_INDICATION_PDU_T *head = (NFAPI_CRC_INDICATION_PDU_T *) ptr;
    head->RX_UE_INFORMATION_TAG = -1;  // Mark as empty

    return (void *) head;
}

int nfa_pi_crc_indication_pdu_list_resize(void *list_ptr, size_t new_size) {
    NFAPI_CRC_INDICATION_PDU_T *head = (NFAPI_CRC_INDICATION_PDU_T *) list_ptr;

    if (!new_size || new_size > 100000) {
        // Handle invalid resize request
        printf("Invalid resize request\n");
        return -1;
    }

    void *ptr = realloc(head, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!ptr) {
        // Handle allocation failure and return error
        printf("Memory reallocation failed\n");
        return -2;
    }

    head = (NFAPI_CRC_INDICATION_PDU_T *) ptr;

    return 0;  // Resize successful
}

