    NFAPI_CRC_INDICATION_PDU_T *curr = (NFAPI_CRC_INDICATION_PDU_T *) list_ptr;
    while (curr != NULL && curr->RX_UE_INFORMATION_TAG != pdu_to_remove->RX_UE_INFORMATION_TAG) {
        curr++;
