pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    int array_size;
    pthread_mutex_t lock;
} memory_pool_t;

memory_pool_t *create_memory_pool(int initial_size) {
    memory_pool_t *pool = (memory_pool_t *)malloc(sizeof(memory_pool_t));
    pool->array_size = 0;
    pool->pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void add_pdu(memory_pool_t *pool, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pool->array_size >= MAX_PDU_COUNT) {
        fprintf(stderr, "Error: Maximum PDU count exceeded.\n");
        exit(EXIT_FAILURE);
    }
    pool->pdu_array[pool->array_size] = pdu;
    pool->array_size++;
    pthread_mutex_unlock(&pool->lock);
}

void validate_pdu(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->array_size - 1; i++) {
        if (pool->pdu_array[i].rx_ue_info_tag == pool->pdu_array[i + 1].rx_ue_info_tag) {
            // Remove duplicate PDU
            for (int j = i + 1; j < pool->array_size; j++) {
                pool->pdu_array[j - 1] = pool->pdu_array[j];
            }
            pool->array_size--;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void *garbage_collection_thread(void *arg) {
    while (1) {
        sleep(5); // Periodic garbage collection
        memory_pool_t *pool = (memory_pool_t *)arg;
        pthread_mutex_lock(&pool->lock);
        for (int i = 0; i < pool->array_size - 1; i++) {
            if ((rand() % 2) && i > pool->array_size / 2) { // Consolidate memory
                NFAPI_CRC_INDICATION_PDU_T *temp = (NFAPI_CRC_INDICATION_PDU_T *)malloc((pool->array_size + 10) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                memcpy(temp, pool->pdu_array, (pool->array_size - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                free(pool->pdu_array);
                pool->pdu_array = temp;
            }
        }
        pthread_mutex_unlock(&pool->lock);
    }
}

void start_garbage_collection(memory_pool_t *pool) {
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection_thread, (void *)pool);
}

void print_pdu_info(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->array_size; i++) {
        printf("RX UE Information Tag: %x, RNTI: %d, CRC Indication REL8 Tag: %x\n",
               pool->pdu_array[i].rx_ue_info_tag,
               pool->pdu_array[i].rnti,
               pool->pdu_array[i].crc_indication_rel8_tag);
    }
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    memory_pool_t *pool = create_memory_pool(MAX_PDU_COUNT / 10);

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Initialize PDU fields...
        add_pdu(pool, pdu);
        validate_pdu(pool);

        if (rand() % 2 && pool->array_size > MAX_PDU_COUNT * 0.5) { // Prioritize urgent structures
            for (int i = pool->array_size - 1; i >= 0; i--) {
                if (!pdu rx_ue_info_tag && !pool->pdu_array[i].rnti) {
                    // Process urgent PDU...
                    break;
                }
            }
        }

        pthread_cond_signal(&cond);
    }

    return 0;
}
