#include <string.h>

// Define the structure for a single user account configuration
typedef struct {
    char *username;
    char *email;
    time_t last_login_timestamp;
    int account_status;
    struct session_details {
        char *ip_address;
        time_t login_time;
        time_t logout_time;
    } session;
} UserAccountConfig;

// Define the structure for a node in the dynamic linked list
typedef struct Node {
    UserAccountConfig config;
    struct Node *next;
} Node;

// Function to create a new user account configuration
Node* createUserAccount(char *username, char *email, time_t last_login_timestamp, int account_status) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->config.username = username;
    new_node->config.email = email;
    new_node->config.last_login_timestamp = last_login_timestamp;
    new_node->config.account_status = account_status;
    new_node->next = NULL;
    return new_node;
}

// Function to add a new user account configuration to the linked list
void addUserAccount(Node **head, Node *new_node) {
    if (*head == NULL || strcmp((*head)->config.username, new_node->config.username) > 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL && strcmp(current->next->config.username, new_node->config.username) < 0) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Function to remove a user account configuration from the linked list
void removeUserAccount(Node **head, char *username) {
    if (*head == NULL) return;

    Node *current = *head;
    Node *previous = NULL;

    while (current != NULL && strcmp(current->config.username, username) != 0) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL) {
            *head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
}

// Function to update a user account configuration in the linked list
void updateUserAccount(Node **head, char *username, time_t last_login_timestamp, int account_status) {
    Node *current = *head;

    while (current != NULL && strcmp(current->config.username, username) != 0) {
        current = current->next;
    }

    if (current != NULL) {
        current->config.last_login_timestamp = last_login_timestamp;
        current->config.account_status = account_status;
    }
}

// Function to query a user account configuration from the linked list
void queryUserAccount(Node *head, char *username) {
    Node *current = head;

    while (current != NULL && strcmp(current->config.username, username) != 0) {
        current = current->next;
    }

    if (current != NULL) {
        printf("Username: %s\n", current->config.username);
        printf("Email: %s\n", current->config.email);
        printf("Last Login Timestamp: %ld\n", current->config.last_login_timestamp);
        printf("Account Status: %d\n", current->config.account_status);
        printf("Session Details:\n");
        printf("IP Address: %s\n", current->config.session.ip_address);
        printf("Login Time: %ld\n", current->config.session.login_time);
        printf("Logout Time: %ld\n", current->config.session.logout_time);
    } else {
        printf("User account not found.\n");
    }
}

// Function to free the memory allocated for a user account configuration
void freeUserAccount(Node *node) {
    if (node == NULL) return;

    free(node->config.username);
    free(node->config.email);
    free(node->config.session.ip_address);

    free(node);
}
