// Function to manage a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void nfaPi_crc_indication_pdu_list_management(int max_size) {
    // Initialize the head and tail pointers for the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    int entry_count = 0;  // Count of added entries

    while (1) {
        // Generate a new NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Initialize the CRCFLAG with a random value
        new_pdu->CRCFLAG = rand() % 2;

        // Add the new pdu to the list
        if (head == NULL) {
            head = new_pdu;
            tail = new_pdu;
        } else {
            tail->next = new_pdu;
            tail = new_pdu;
        }

        entry_count++;

        // Periodically clear the list after a specified number of entries have been added
        if (entry_count >= max_size) {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* next = current->next;
                free(current);
                current = next;
            }
            head = NULL;
            tail = NULL;
            entry_count = 0;
        }

        // Perform operations on the list
        printf("Added PDU: RNTI - %d, CRCFLAG - %d\n", new_pdu->RNTI, new_pdu->CRCFLAG);
    }
}

