#define CHUNK_SIZE 1024
#define MAX_VALUE 1000
#define MIN_VALUE 1

typedef struct {
    int val;
} record;

record* records = NULL;
int num_records = 0;
int pool_size = 0;
long* offsets = NULL;
int* keys = NULL;

void init_allocator(int n) {
    if (n > CHUNK_SIZE) {
        printf("Chunk size too small. Increasing to %d\n", n);
        n = CHUNK_SIZE;
    }
    int chunk_count = (n + CHUNK_SIZE - 1) / CHUNK_SIZE;
    pool_size += chunk_count * CHUNK_SIZE;
}

void* my_malloc(size_t size) {
    if (size > CHUNK_SIZE) {
        return NULL; // handle error
    }
    int index = -1;
    for (int i = 0; i < pool_size; i++) {
        if (keys[i] == 0) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        return NULL; // handle error
    }
    void* ptr = ((char*) offsets + index * CHUNK_SIZE);
    keys[index] = 1;
    return ptr;
}

void my_free(void* ptr) {
    int index = (long)ptr / CHUNK_SIZE;
    keys[index] = 0;
}

void log_memory_operation(int operation, char* message) {
    FILE* f = fopen("memory_operations.log", "a");
    if (f == NULL) {
        return; // handle error
    }
    time_t t = time(NULL);
    struct tm* tm = localtime(&t);
    fprintf(f, "[%02d:%02d:%02d][%s] %s\n", tm.tm_hour, tm.tm_min, tm.tm_sec, pthread_self(), message);
    fclose(f);
}

void set_record_values(int min_value, int max_value) {
    for (int i = 0; i < num_records; i++) {
        records[i].val = rand() % (max_value - min_value + 1) + min_value;
    }
}

record* get_records(int m) {
    if (m > num_records) {
        // handle excess records
    }
    return &records[0];
}

void rotate_log_file(size_t max_size) {
    FILE* f = fopen("memory_operations.log", "rb");
    if (f == NULL) {
        return; // handle error
    }
    fseek(f, 0, SEEK_END);
    size_t current_size = ftell(f);
    if (current_size > max_size) {
        rewind(f);
        char buffer[max_size];
        fread(buffer, 1, max_size, f);
        fclose(f);
        FILE* new_f = fopen("memory_operations.log.new", "wb");
        fwrite(buffer, 1, max_size, new_f);
        fclose(new_f);
        rename("memory_operations.log.new", "memory_operations.log");
    }
    fclose(f);
}
