// Define a struct to represent each node in the linked list
typedef struct {
    char* payload;
    struct Node* next;
} Node;

// Function to initialize a dynamic collection of 'node' structures in a singly linked list
Node* initializeList(int numNodes, int stringLength) {
    // Initialize the head and tail of the list
    Node* head = NULL;
    Node* tail = NULL;

    // Allocate memory for each node and its payload
    for (int i = 0; i < numNodes; i++) {
        char* str = malloc((stringLength + 1) * sizeof(char));
        if (!str) {
            printf("Error: Failed to allocate memory for string.\n");
            return NULL;
        }

        // Initialize the payload with a random alphanumeric string
        for (int j = 0; j < stringLength; j++) {
            str[j] = 'a' + rand() % 52;
        }
        str[stringLength] = '\0';  // Terminate the string

        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            printf("Error: Failed to allocate memory for node.\n");
            return NULL;
        }

        newNode->payload = str;
        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    // Validate the integrity of the linked list
    Node* current = head;
    while (current != NULL && current->next != NULL) {
        if (strcmp(current->payload, current->next->payload) == 0) {
            printf("Error: Duplicate strings found in the list.\n");
            return NULL;
        }
        current = current->next;
    }

    // Check for circular references
    if (current != NULL && current->next != NULL) {
        printf("Error: Circular reference detected in the list.\n");
        return NULL;
    }

    return head;
}
