using System;

namespace ValueGeneratorNamespace
{
    public class ValueGenerator
    {
        private double _min;
        private double _max;

        private static Random _random = new Random();

        public ValueGenerator(double min, double max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value cannot exceed maximum value.");
            _min = min;
            _max = max;
        }

        public double GenerateRandomFloat()
        {
            return _random.NextDouble() * (_max - _min) + _min;
        }

        public int GenerateRandomInt()
        {
            return _random.Next((int)_min, (int)_max + 1);
        }

        public double GenerateExclusiveRangeFloat()
        {
            return _random.NextDouble() * (_max - _min) + _min;
        }

        public int GenerateExclusiveRangeInt()
        {
            return _random.Next((int)_min, (int)_max);
        }

        public override string ToString()
        {
            return $"({_min}, {_max})";
        }
    }

    public static class ValueGeneratorExtensions
    {
        public static void ValidateRange(ValueGenerator generator)
        {
            if (generator._min > generator._max)
                throw new ArgumentException("Minimum value cannot exceed maximum value.");
        }
    }
}
