function aggregateUserProfiles(profiles, initialAccumulator, callback) {
    if (!Array.isArray(profiles)) throw new Error('Invalid input: profiles must be an array');
    if (typeof callback !== 'function') throw new Error('Invalid input: callback function is required');

    const queue = [];
    let accumulator = initialAccumulator;
    let count = 0;

    profiles.forEach((profile, index) => {
        if (!profile || typeof profile !== 'object') return; // skip invalid or missing profile
        if (Object.keys(profile).length === 0) return; // skip empty profile

        queue.push({ index, profile });
    });

    const processProfile = () => {
        while (queue.length > 0 && !queue[queue.length - 1].error) {
            const { index, profile } = queue.shift();
            try {
                accumulator = callback(accumulator, profile, index, count);
                count++;
            } catch (err) {
                console.error(`Error processing user profile at index ${index}:`, err);
                // re-add the profile to the end of the queue for retry
                queue.push({ index, profile, error: true });
            }
        }

        if (queue.length > 0 && queue[queue.length - 1].error) {
            setTimeout(processProfile, 10); // retry every 10ms
        } else {
            resolveAccumulator(accumulator);
        }
    };

    const resolveAccumulator = (value) => {
        accumulator = value;
        processProfile();
    };

    processProfile();

    return { accumulator };
}
