    float value;
    char *log_message;
} item_t;

void *malloc_or_die(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

item_t *create_item(int id, float value, char *log_message) {
    item_t *item = (item_t *)malloc_or_die(sizeof(item_t));
    item->id = id;
    item->value = value;
    item->log_message = strdup(log_message);
    return item;
}

void free_items(item_t **items, int num_items) {
    for (int i = 0; i < num_items; i++) {
        free(items[i]->log_message);
        free(items[i]);
    }
    free(items);
}

void *thread_func(void *args) {
    // Handle data from multiple input files
