    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_items; i++) {
        item_t *item = create_item(i, (float)i, "Initial log message");
        items[i] = item;

        // Log memory allocation
        fprintf(log_file, "Allocated %zu bytes at address %p\n", sizeof(item), &item);
    }

    fclose(log_file);
}

void cleanup_memory(int num_items, item_t **items) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_items; i++) {
        free_items(&items[i], 1);
    }

    free(items);

    pthread_mutex_unlock(&mutex);
}

int main() {
    int num_items = 100;
    item_t *items[MAX_ITEMS];

    pthread_t threads[4]; // Assuming 4 input files

    init_memory(num_items, items);

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_memory(num_items, items);

    return 0;
}
