int processImageMetadataAndHandleDynamicRecords(json_object *metadata) {
    // Initialize arrays for storing offsets, keys, and records
    long *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    int *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    record_t *records = (record_t *)malloc(MAX_RECORDS * sizeof(record_t));

    // Parse JSON input for image metadata
    json_object *imageMetadata = json_object_object_get(metadata, "imageMetadata");
    if (!imageMetadata) {
        return 1; // Invalid input
    }

    int i = 0;
    json_object_iterator it;
    json_object_object_foreach(imageMetadata, it, value) {
        long offset = rand() % (LONG_MAX - RAND_MIN); // Generate unique identifier
        int key = json_object_get_int(&it);
        record_t record = {key, 1}; // Assign random value for simplicity

        // Store offsets, keys, and records
        offsets[i] = offset;
        keys[i] = key;
        records[i] = record;

        i++;
    }

    // Validate uniqueness of keys
    for (int j = 0; j < i; j++) {
        for (int k = j + 1; k < i; k++) {
            if (keys[j] == keys[k]) {
                return 1; // Duplicate key found
            }
        }
    }

    // Convert JPEG file to PDF using third-party library
    FILE *inputFile = fopen("input.jpg", "rb");
    if (!inputFile) {
        return 1; // File not found
    }

    FILE *outputFile = fopen("output.pdf", "wb");
    if (!outputFile) {
        fclose(inputFile);
        return 1; // File not found
    }

    // Use third-party library to convert JPEG to PDF
    int conversionResult = convertJPEGToPDF(inputFile, outputFile);

    if (conversionResult != 0) {
        fclose(inputFile);
        fclose(outputFile);
        return 1; // Conversion failed
    }

    fclose(inputFile);
    fclose(outputFile);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}

