// Function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_list(int max_size, int* nfaapi_crc_indication_pdu_t_list) {
    // Define a linked list node structure
    typedef struct {
        NFAPI_CRC_INDICATION_PDU_T data;
        struct node* next;
    } node;

    // Initialize the head of the linked list
    node* head = NULL;

    int size = 0;
    int i = 0;

    while (i < max_size) {
        // Allocate memory for a new node
        node* temp = (node*)malloc(sizeof(node));
        if (!temp) {
            printf("Memory allocation failed!\n");
            return;
        }

        // Initialize the data of the new node
        temp->data.RX_UE_INFORMATION_TAG = rand() % 10000;
        temp->data.RNTI = rand() % 1000;
        temp->data.CRC_INDICATION_REL8_TAG = rand() % 1000000;
        temp->data.CRCFLAG = rand() % 2;

        // Link the new node to the head of the list
        temp->next = head;
        head = temp;

        size++;

        i++;
    }

    // Print the linked list
    printf("Linked List: \n");
    while (head) {
        printf("%d, %d, %d, %d\n", head->data.RX_UE_INFORMATION_TAG,
               head->data.RNTI, head->data.CRC_INDICATION_REL8_TAG, head->data.CRCFLAG);
        head = head->next;
    }

    // Free the memory allocated for the linked list
    node* current = head;
    while (current) {
        node* next = current->next;
        free(current);
        current = next;
    }
}

