#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[10];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[5];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct LLNode {
    NFAPI_CRC_INDATION_PDU_T* data;
    struct LLNode* next;
} LLNode;

// Function to add a new element to the list
LLNode* addElement(LLNode** head, int RNTI, char RX_UE_INFORMATION_TAG[10], char CRC_INDICATION_REL8_TAG[5]) {
    // Create a new node
    LLNode* newNode = (LLNode*)malloc(sizeof(LLNode));
    if (!newNode) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(newData->RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG);
    newData->RNTI = RNTI;
    strcpy(newData->CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);
    newData->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    // Set the new node's data and next pointer
    newNode->data = newData;
    newNode->next = (*head);

    if (!(*head)) *head = newNode;

    return newNode;
}

// Function to update an existing element in the list
LLNode* updateElement(LLNode** head, int RNTI, char RX_UE_INFORMATION_TAG[10], char CRC_INDICATION_REL8_TAG[5]) {
    LLNode* current = *head;
    while (current) {
        if (current->data->RNTI == RNTI) {
            // Update the element
            strcpy(current->data->RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG);
            strcpy(current->data->CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);
            current->data->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to remove an element from the list by RNTI
LLNode* removeElement(LLNode** head, int RNTI) {
    LLNode* current = *head;
    LLNode* previous = NULL;

    while (current && current->data->RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (!current) return *head; // Element not found

    if (previous) {
        previous->next = current->next;
    } else {
        *head = current->next;
    }

    free(current->data);
    free(current);

    return *head;
}

// Function to periodically clear the list after a specified number of entries have been added
void periodicClear(LLNode** head, int maxEntries) {
    LLNode* current = *head;
    int entryCount = 0;

    while (current && entryCount < maxEntries) {
        if (current->next) {
            current = current->next;
            entryCount++;
        } else {
            free(current->data);
            free(current);
            *head = NULL; // Clear the list
            return;
        }
    }

    if (entryCount >= maxEntries) {
        free(current->data);
        free(current);
        *head = NULL; // Clear the list
    }
}

// Function to export the APIs for external modules
void setAPIs(LLNode** head, int (*addElementFunc)(LLNode**, int, char*, char*), int (*updateElementFunc)(LLNode**, int, char*, char*), int (*removeElementFunc)(LLNode*, int)) {
    // Set the add element function
    *addElementFunc = (int (*)(LLNode**, int, char*, char*))addElement;

    // Set the update element function
    *updateElementFunc = (int (*)(LLNode**, int, char*, char*))updateElement;

    // Set the remove element function
    *removeElementFunc = (int (*)(LLNode*, int))removeElement;
}

// Function to handle memory allocation failures gracefully
void* mallocFail() {
    return NULL;
}
