    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);

    for (int i = 0; i < arraySize; ++i) {
        records[i].key = i;
        char description[20];
        std::sprintf(description, "Record %d", i);
        memcpy(records[i].description, description, sizeof(description));

        if (dis(gen) % 2 == 1) {
            records[i].attackType = ATTACK_A;
            records[i].cooldownTime = dis(gen) % 10 + 1;
        } else {
            records[i].attackType = ATTACK_B;
            records[i].cooldownTime = dis(gen) % 5 + 1;
        }
    }

    // Initialize database structure
    record* database = new record[arraySize];

    for (int i = 0; i < arraySize; ++i) {
        database[i] = records[i];
    }

    // Free allocated memory to prevent leaks
    delete[] offsets;
    delete[] keys;
    delete[] records;

    return { database };
