// Function to initialize memory and create a linked list
void initMemory(int size, double rangeStart, double rangeEnd) {
    // Allocate memory for floating-point numbers (double)
    double** doubles = (double**)malloc(size * sizeof(double*));
    for (int i = 0; i < size; i++) {
        doubles[i] = (double*)malloc(sizeof(double));
    }

    // Allocate memory for character strings (char*)
    char** chars = (char**)malloc(size * sizeof(char*));
    for (int i = 0; i < size; i++) {
        chars[i] = (char*)malloc(10 * sizeof(char)); // Assuming max string length is 9
    }

    // Allocate memory for struct node pointers
    Node** nodes = (Node**)malloc(size * sizeof(Node*));
    for (int i = 0; i < size; i++) {
        nodes[i] = (Node*)malloc(sizeof(Node));
    }

    // Allocate memory for enum status flags
    Status** statuses = (Status**)malloc(size * sizeof(Status*));
    for (int i = 0; i < size; i++) {
        statuses[i] = (Status*)malloc(sizeof(Status));
    }

    // Initialize linked list by setting node values and string keys
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < size; i++) {
        nodes[i]->value = (double)rand() / RAND_MAX * (rangeEnd - rangeStart) + rangeStart;
        for (int j = 0; j < 9; j++) { // Generate random string key
            chars[i][j] = 'a' + (rand() % 26);
        }
        chars[i][9] = '\0'; // Null-terminate the string

        // Check if the generated node's double value and string key are unique
        for (int k = 0; k < i; k++) {
            if ((nodes[k]->value == nodes[i]->value) && (strcmp(chars[k], chars[i]) == 0)) {
                printf("Error: Duplicate node values or keys found!\n");
                return;
            }
        }
    }

    // Validate integrity of linked list
    Node* current = nodes[0];
    for (int i = 1; i < size; i++) {
        if (current->next != nodes[i]) {
            printf("Error: Linked list integrity failed!\n");
            return;
        }
        current = nodes[i];
    }

    // Free allocated memory
    for (int i = 0; i < size; i++) {
        free(doubles[i]);
        free(chars[i]);
        free(nodes[i]->key);
        free(nodes[i]);
        free(statuses[i]);
    }
    free(doubles);
    free(chars);
    free(nodes);
    free(statuses);

    printf("Memory initialized successfully!\n");
}
