// Define the struct entry structure
typedef struct {
    int* arr;
    char* id;
    struct entry* next;
} entry_t;

// Function to initialize memory for data structure components
int init_memory(int size) {
    // Initialize memory for integer arrays
    int** arrs = (int**)malloc(size * sizeof(int*));
    for (int i = 0; i < size; i++) {
        arrs[i] = (int*)malloc(10 * sizeof(int)); // Set array size to 10
        for (int j = 0; j < 10; j++) {
            arrs[i][j] = i + j;
        }
    }

    // Initialize memory for struct entry pointers
    entry_t** entries = (entry_t**)malloc(size * sizeof(entry_t*));
    for (int i = 0; i < size; i++) {
        entries[i] = (entry_t*)malloc(sizeof(entry_t));
        entries[i]->arr = arrs[i];
        entries[i]->id = (char*)malloc(10 * sizeof(char)); // Set string length to 10
        strcpy(entries[i]->id, "Entry_");
        itoa(i, entries[i]->id + strlen("Entry_"), 10); // Convert integer to string and append to ID
    }

    // Initialize memory for enumeration flags
    int* flags = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        flags[i] = i;
    }

    return size;
}

// Function to validate the linked list and ensure unique identifiers
void validate_list(entry_t* head) {
    entry_t* current = head;
    while (current != NULL) {
        int found = 0;
        entry_t* temp = head;
        while (temp != NULL) {
            if (strcmp(temp->id, current->id) == 0) {
                found = 1;
                break;
            }
            temp = temp->next;
        }
        if (found == 1) {
            printf("Duplicate identifier: %s\n", current->id);
        }
        current = current->next;
    }
}

// Function to populate the linked list with integer array values
void populate_list(entry_t* head, int size) {
    entry_t* current = head;
    for (int i = 0; i < size; i++) {
        current->arr[i] = i + 1;
        current = current->next;
    }
}

// Function to free memory allocated for data structure components
void free_memory(entry_t* head) {
    entry_t* current = head;
    while (current != NULL) {
        // Free integer arrays
        free(current->arr);
        // Free struct entry pointers
        free(current->id);
        free(current);
        current = current->next;
    }
}

// Function to print the linked list in reverse order
void print_list(entry_t* head) {
    entry_t* current = head;
    while (current != NULL) {
        printf("%s ", current->id);
        for (int i = 0; i < 10; i++) {
            printf("%d ", current->arr[i]);
        }
        printf("\n");
        current = current->next;
    }
}

int main() {
    int size = init_memory(5); // Initialize memory with size 5
    entry_t* head = (entry_t*)malloc(sizeof(entry_t));
    head->id = "Root";
    for (int i = 0; i < size - 1; i++) {
        entry_t* new_entry = (entry_t*)malloc(sizeof(entry_t));
        new_entry->id = (char*)malloc(10 * sizeof(char)); // Set string length to 10
        strcpy(new_entry->id, "Entry_");
        itoa(i + 1, new_entry->id + strlen("Entry_"), 10); // Convert integer to string and append to ID
        head->next = new_entry;
        head = head->next;
    }
    validate_list(head);
    populate_list(head, size);
    print_list(head);
    free_memory(head);
    return 0;
}

