#define CONVERSION_FAILURE_OUT_OF_MEMORY -2

int convert_jpg_to_pdf(const char *input_dir, const char *output_dir,
                       const char *output_file_name, int concurrency_level) {
    // Initialize conversion count and error code
    int conversion_count = 0;
    int error_code = CONVERSION_SUCCESS;

    // Create a thread pool with the specified concurrency level
    pthread_t threads[concurrency_level];
    for (int i = 0; i < concurrency_level; i++) {
        if (pthread_create(&threads[i], NULL, convert_jpg_thread_func, NULL) != 0) {
            error_code = CONVERSION_FAILURE_GENERIC;
            break;
        }
    }

    // Perform file conversions concurrently
    DIR *dir = opendir(input_dir);
    if (dir == NULL) {
        error_code = CONVERSION_FAILURE_GENERIC;
    } else {
        struct dirent *ent;
        while ((ent = readdir(dir)) != NULL) {
            char *file_name = ent->d_name;
            if (strcmp(file_name, ".") == 0 || strcmp(file_name, "..") == 0) {
                continue;
            }
            if (strchr(file_name, '.') != NULL && strcmp(strrchr(file_name, '.'), ".jpg") == 0) {
                // Convert JPEG file to PDF
                char *file_path = malloc(strlen(input_dir) + strlen(file_name) + 2);
                sprintf(file_path, "%s/%s", input_dir, file_name);
                char *output_file_path = malloc(strlen(output_dir) + strlen(file_name) + 4);
                sprintf(output_file_path, "%s/%s.pdf", output_dir, file_name);

                // Create a temporary file for the conversion process
                int fd = mkstemp(file_path);
                if (fd == -1) {
                    error_code = CONVERSION_FAILURE_GENERIC;
                    continue;
                }
                FILE *temp_file = fopen(file_path, "w");
                fclose(temp_file);
                unlink(file_path);

                // Convert the JPEG file to PDF
                pthread_create(&threads[conversion_count], NULL,
                               convert_jpg_thread_func, (void *)output_file_path);
                conversion_count++;

                // Remove temporary files if an error occurs during conversion
                pthread_exit(NULL);
            }
        }
        closedir(dir);
    }

    // Wait for all threads to complete and clean up
    for (int i = 0; i < conversion_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return error_code;
}

