typedef struct {
    int key;
    char name[33]; // 32 characters + null terminator
    double value;
} Record;

// Function to generate a random string of alphanumeric characters with a specified length
void generateRandomString(char* str, int len) {
    for(int i = 0; i < len; i++) {
        if(rand() % 2 == 0)
            str[i] = (char)(rand() % 26 + 65); // uppercase letters
        else
            str[i] = (char)(rand() % 10 + 48); // digits
    }
    str[len-1] = '\0'; // null terminate the string
}

// Function to calculate the double value based on the int key and a constant multiplier
double calculateDoubleValue(int key, double multiplier) {
    return ((double)key * multiplier);
}

// Function to dynamically allocate memory for a flexible number of records, each containing an int key, a char name with a maximum length of 32 characters, and a double value
Record** createRecords(int numRecords, int minKey, int maxKey, double multiplier, FILE* logFile) {
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    if(!records) {
        fprintf(logFile, "Error: Failed to allocate memory for record pointers.\n");
        return NULL;
    }

    // Initialize arrays for offset values and int keys
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    if(!offsets || !keys) {
        fprintf(logFile, "Error: Failed to allocate memory for offset and key arrays.\n");
        free(records);
        return NULL;
    }

    // Initialize each record with a pseudo-randomly generated int key within the specified range, a name composed of characters from a predefined set, and a double value calculated using a linear function
    for(int i = 0; i < numRecords; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if(!record) {
            fprintf(logFile, "Error: Failed to allocate memory for record %d.\n", i);
            while(i--) {
                free(records[i]);
                free(offsets);
                free(keys);
            }
            free(records);
            return NULL;
        }

        // Initialize the int key
        record->key = (rand() % ((maxKey - minKey) + 1)) + minKey;

        // Initialize the name
        generateRandomString(record->name, 32);

        // Calculate and initialize the double value
        record->value = calculateDoubleValue(record->key, multiplier);

        // Store the offset and int key values for this record
        offsets[i] = i;
        keys[i] = record->key;

        records[i] = record;
    }

    free(offsets);
    free(keys);

    return records;
}

// Cleanup function to safely release all allocated memory without causing memory leaks
void cleanupRecords(Record** records, int numRecords) {
    for(int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}
