#include <iostream>
#include <map>
#include <vector>
#include <unordered_map>
#include <mutex>

class Node {
public:
    int id;
    std::string attributes;
    std::vector<int> connectedNodes;

    Node(int _id, const std::string& _attributes) : id(_id), attributes(_attributes) {}
};

class Edge {
public:
    int sourceNode;
    int targetNode;

    Edge(int _sourceNode, int _targetNode) : sourceNode(_sourceNode), targetNode(_targetNode) {}
};

class Graph {
private:
    std::map<int, Node*> nodes;
    std::vector<Edge*> edges;
    std::mutex nodeMutex;

public:
    void addNode(int id, const std::string& attributes) {
        std::unique_lock<std::mutex> lock(nodeMutex);
        if (!nodes.count(id)) {
            nodes[id] = new Node(id, attributes);
        }
    }

    void addEdge(int sourceId, int targetId) {
        std::unique_lock<std::mutex> lock(nodeMutex);
        Edge* edge = new Edge(sourceId, targetId);
        edges.push_back(edge);

        if (!nodes.count(sourceId)) {
            nodes[sourceId] = new Node(sourceId, "");
        }
        if (!nodes.count(targetId)) {
            nodes[targetId] = new Node(targetId, "");
        }

        nodes[sourceId]->connectedNodes.push_back(targetId);
        nodes[targetId]->connectedNodes.push_back(sourceId);
    }

    void removeNode(int id) {
        std::unique_lock<std::mutex> lock(nodeMutex);
        if (nodes.count(id)) {
            for (auto it = edges.begin(); it != edges.end(); ++it) {
                if (it->sourceNode == id || it->targetNode == id) {
                    delete it;
                    it = edges.erase(it);
                    break;
                }
            }
            delete nodes[id];
            nodes.erase(id);
        }
    }

    void removeEdge(int sourceId, int targetId) {
        std::unique_lock<std::mutex> lock(nodeMutex);
        for (auto it = edges.begin(); it != edges.end(); ++it) {
            if ((it->sourceNode == sourceId && it->targetNode == targetId) ||
                (it->sourceNode == targetId && it->targetNode == sourceId)) {
                delete it;
                it = edges.erase(it);
                break;
            }
        }
    }

    void updateAttribute(int id, const std::string& attributes) {
        std::unique_lock<std::mutex> lock(nodeMutex);
        if (nodes.count(id)) {
            nodes[id]->attributes = attributes;
        }
    }

    Node* getNode(int id) {
        std::unique_lock<std::mutex> lock(nodeMutex);
        return nodes[id];
    }
};
