    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    for (int i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_structure) { // allocation failure
            log_error("Allocation failure");
            while (1) {
                if (!structures) break;
                free(structures);
                structures = NULL;
                sleep(TIMEOUT); // wait for timeout before retrying
            }
            return NULL; // failed to allocate all structures
        }
        new_structure->RX_UE_INFORMATION_TAG = rand() % 256;
        new_structure->RNTI = rand() % 512;
        new_structure->CRC_INDICATION_REL8_TAG = rand() % 1024;
        if (!structures) {
            structures = new_structure;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *prev_structure = structures;
            while (prev_structure->next) prev_structure = prev_structure->next;
            prev_structure->next = new_structure;
        }
    }

    return structures;
}

void nfaapi_crc_indication_pdu_manager_free(NFAPI_CRC_INDICATION_PDU_T *structures) {
    NFAPI_CRC_INDICATION_PDU_T *current = structures;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
}
