['```javascript
function streamData(chunks, size) {
  let buffers = [];
  for (const chunk of chunks) {
    if (chunk.length <= size) {
      buffers.push(chunk);
      size -= chunk.length;
    } else {
      buffers.push(chunk.slice(0, size));
      break;
    }
  }

  const buffer = Buffer.allocUnsafe(size);
  let offset = 0;
  for (const buf of buffers) {
    buf.copy(buffer, offset);
    offset += buf.length;
  }

  return buffer;
}
