// Function to manage memory for three arrays: offset values, keys, and records
void *manage_memory(int offset_size, int key_size, int record_size) {
    // Initialize arrays with specified sizes
    long *offsets = (long *)malloc(offset_size * sizeof(long));
    int *keys = (int *)malloc(key_size * sizeof(int));
    record_t *records = (record_t *)malloc(record_size * sizeof(record_t));

