        int key = rand() % (key_size - 1) + 1;
        while (find_key(keys, key) != NULL) {
            key = rand() % (key_size - 1) + 1;
        }
        records[i].key = key;
        records[i].value = rand() % 100; // set random value for the record
    }

    return records;
}

// Function to find a key in the keys array
record_t *find_key(int *keys, int target_key) {
    for (int i = 0; i < key_size; i++) {
        if (keys[i] == target_key) {
            return &records[i];
        }
    }
    return NULL;
}

