#define MAX_CONCURRENT_CIPHERS 10
#define KEY_DERIVATION_ITERATIONS 100000

// Thread-safe pool of cipher contexts
static pthread_mutex_t cipher_ctx_pool_lock = PTHREAD_MUTEX_INITIALIZER;
static AES_CTX **cipher_ctx_pool = NULL;

// Cipher initialization function
void* init_cipher(const char* password, int password_len) {
    // Create a new cipher context if the pool is not full
    if (cipher_ctx_pool == NULL || pthread_mutex_trylock(&cipher_ctx_pool_lock) == EBUSY) {
        return NULL;
    }

    AES_CTX* cipher_ctx = AES_CTX_new();
    if (cipher_ctx == NULL) {
        return NULL;
    }

    // Initialize the cipher context with the given password
    int rc = AES_CTX_set_key(cipher_ctx, password, password_len);
    if (rc != 1) {
        ERR_error_fp(stderr, "AES_CTX_set_key failed");
        AES_CTX_free(cipher_ctx);
        return NULL;
    }

    // Add the cipher context to the pool
    pthread_mutex_unlock(&cipher_ctx_pool_lock);

    return cipher_ctx;
}

// Cipher cleanup function
void cleanup_cipher(void* cipher_ctx) {
    if (cipher_ctx == NULL || cipher_ctx == (void*) 0x0) {
        return;
    }

    AES_CTX_free(cipher_ctx);
}

