// Structure definitions
typedef enum { OK = 0, ERR } Status;
typedef union {
    double dval;
    char *sval;
    struct node *pval;
} UnionData;

typedef struct {
    double value;
    char key[20];
    int ref_count;
    struct node *next;
} Node;

// Function to manage memory for interconnected data structures
Status init_memory(int size, Node **head) {
    // Initialize data structures with specified sizes
    Node *nodes = (Node *)malloc(size * sizeof(Node));
    if (!nodes) return ERR;  // Error handling: out-of-memory condition

    // Initialize 'double' precision floating-point numbers array
    double *doubles = (double *)malloc(size * sizeof(double));
    if (!doubles) {
        free(nodes);
        return ERR;
    }

    // Initialize 'char' strings array
    char **strings = (char **)malloc(size * sizeof(char *));
    for (int i = 0; i < size; i++) {
        strings[i] = (char *)malloc(21);  // +1 for null-terminator
        sprintf(strings[i], "Node_%d", i);
    }

    // Initialize 'struct node' pointers array
    Node **nodes_ptr = (Node **)malloc(size * sizeof(Node *));
    for (int i = 0; i < size; i++) {
        nodes_ptr[i] = &nodes[i];
    }

    // Initialize 'enum status' flags array
    Status *status_flags = (Status *)malloc(size * sizeof(Status));
    for (int i = 0; i < size; i++) {
        status_flags[i] = OK;
    }

    // Initialize 'union data' array
    UnionData *data_union = (UnionData *)malloc(size * sizeof(UnionData));

    // Validate the integrity of the linked list after initialization
    Node *current = *head;
    while (current && current->next) {
        if (!current->ref_count) return ERR;  // Error handling: invalid reference count

        // Populate the linked list by setting each node's 'double' field to a random floating-point number within a given range
        for (int i = 0; i < size; i++) {
            current->value = (double)(rand() % 1000);  // Random float value between 0 and 999.99

            // Ensure no two nodes have identical string keys
            char *temp = (char *)malloc(21);
            sprintf(temp, "Node_%d", i);
            for (int j = 0; j < size; j++) {
                if (strcmp(temp, strings[j]) == 0) {
                    free(temp);
                    return ERR;  // Error handling: duplicate string key
                }
            }

            free(temp);
        }

        current = current->next;
    }

    // Initialize and populate the linked list
    for (int i = 0; i < size; i++) {
        nodes[i].ref_count = 1;
        nodes[i].value = (double)(rand() % 1000);  // Random float value between 0 and 999.99

        // Set node's 'char' string to a random key
        char *temp = (char *)malloc(21);
        sprintf(temp, "Node_%d", i);
        strcpy(nodes[i].key, temp);
        free(temp);

        nodes[i].next = &nodes[(i + 1) % size];  // Circular linked list

        if (i > 0) {
            nodes[i - 1].next = &nodes[i];
        }
    }

    // Clean up memory
    free(doubles);
    for (int i = 0; i < size; i++) {
        free(strings[i]);
        free(nodes_ptr[i]->key);  // Free node's 'char' string
    }
    free(strings);
    free(nodes_ptr);

    return OK;
}

// API to initialize and manage memory for interconnected data structures
Status init_linked_list(int size, Node **head) {
    Status status = init_memory(size, head);
    if (status == ERR) {
        printf("Error: Memory allocation failed.\n");
    } else {
        printf("Memory initialized successfully.\n");
    }

    return status;
}

// API to serialize the linked list structure to a binary file
void serialize_linked_list(Node *head, FILE *file) {
    fwrite(&head->value, sizeof(double), 1, file);
    fwrite(head->key, sizeof(char), strlen(head->key), file);

    // Traverse the linked list and write each node's data to the file
    Node *current = head;
    while (current && current->next) {
        fwrite(&current->value, sizeof(double), 1, file);
        fwrite(current->key, sizeof(char), strlen(current->key), file);

        current = current->next;
    }
}

// API to deserialize the linked list structure from a binary file
Node *deserialize_linked_list(FILE *file) {
    Node *head = (Node *)malloc(sizeof(Node));
    if (!head) return NULL;  // Error handling: out-of-memory condition

    fread(&head->value, sizeof(double), 1, file);
    head->key[20] = '\0';  // Null-terminate the key string
    fread(head->key, sizeof(char), 21, file);

    // Traverse the binary file and deserialize each node's data
    Node *current = head;
    while (fread(&current->value, sizeof(double), 1, file) == 1 && fread(current->key, sizeof(char), 21, file) > 0) {
        current->next = (Node *)malloc(sizeof(Node));
        if (!current->next) return NULL;  // Error handling: out-of-memory condition

        current = current->next;
    }

    return head;
}

int main() {
    Node *head;

    Status status = init_linked_list(5, &head);
    if (status == OK) {
        printf("Linked list initialized successfully.\n");

        // Serialize the linked list to a binary file
        FILE *file = fopen("linked_list.bin", "wb");
        serialize_linked_list(head, file);
        fclose(file);

        // Deserialize the linked list from the binary file
        Node *deserialized_head = deserialize_linked_list(fopen("linked_list.bin", "rb"));
        if (deserialized_head) {
            printf("Linked list deserialized successfully.\n");

            // Clean up memory
            while (deserialized_head && deserialized_head->next) {
                Node *temp = deserialized_head;
                deserialized_head = deserialized_head->next;
                free(temp);
            }
            free(deserialized_head);
        } else {
            printf("Error: Deserialization failed.\n");
        }
    } else {
        printf("Error: Memory initialization failed.\n");
    }

    return 0;
}

