                // update cache again
                let mut cache_client = reqwest::Client::new();
                let request = json!({
                    "key": "your_operation_id",
                    "status": "success"
                });

                cache_client.put(cache_url)
                    .json(&request)
                    .send()
                    .await
                    .unwrap();
            } else {
                // handle error
            }
        } else {
            // handle error
        }
    });
}

