    // Allocate memory for offset array and initialize to zero
    long* offsetArray = (long*)malloc(sizeof(long) * size);
    for (int i = 0; i < size; i++) {
        offsetArray[i] = 0;
    }

    // Allocate memory for key array and initialize to sequential numbers
    int* keyArray = (int*)malloc(sizeof(int) * size);
    for (int i = 0; i < size; i++) {
        keyArray[i] = i + 1;
    }

    // Allocate memory for record structures with unique keys
    record** recordArray = (record**)malloc(sizeof(record*) * size);
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        record* record = (record*)malloc(sizeof(record));
        record->value = rand() % 100;
        recordArray[i] = record;
    }

    // Update record values by key
    void updateRecord(int key, int value) {
        for (int i = 0; i < size; i++) {
            if (key == keyArray[i]) {
                recordArray[i]->value = value;
                return;
            }
        }
    }

    // Log memory usage statistics
    void logMemoryUsage() {
        printf("Allocated %lu bytes for offset array.\n", sizeof(long) * size);
        printf("Allocated %lu bytes for key array.\n", sizeof(int) * size);
        printf("Allocated %lu bytes for record structures.\n", sizeof(record*) * size);
    }

    // Free memory
    void freeMemory() {
        for (int i = 0; i < size; i++) {
            free(offsetArray + i);
            free(keyArray + i);
            free(recordArray[i]);
        }
        free(offsetArray);
        free(keyArray);
        free(recordArray);
    }

