#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    double value;
    char* id;
} item;

typedef struct {
    int size;
    item** items;
} transaction;

transaction* create_transaction(int size) {
    transaction* t = (transaction*)malloc(sizeof(transaction));
    t->size = size;
    t->items = (item**)malloc(size * sizeof(item*));
    for (int i = 0; i < size; i++) {
        t->items[i] = NULL;
    }
    return t;
}

void free_transaction(transaction* t) {
    for (int i = 0; i < t->size; i++) {
        if (t->items[i] != NULL) {
            free(t->items[i]->id);
            free(t->items[i]);
        }
    }
    free(t->items);
    free(t);
}

void initialize_transaction(transaction* t, int num_items) {
    for (int i = 0; i < t->size; i++) {
        item* item = (item*)malloc(sizeof(item));
        item->value = rand() / (double)(RAND_MAX + 1.0);
        item->id = (char*)malloc(10 * sizeof(char)); // assuming max length of 9 characters
        sprintf(item->id, "Item_%d", i);
        t->items[i] = item;
    }
}

void print_transaction(transaction* t) {
    for (int i = 0; i < t->size; i++) {
        printf("Transaction %d: Item Value - %.2f, Item ID - %s\n", i, t->items[i]->value, t->items[i]->id);
    }
}

transaction* manage_transactions(int num_transactions, int num_items_per_transaction) {
    transaction* transactions = (transaction*)malloc(num_transactions * sizeof(transaction));
    for (int i = 0; i < num_transactions; i++) {
        transaction* t = create_transaction(num_items_per_transaction);
        initialize_transaction(t, num_items_per_transaction);
        // randomly assign item pointers to each transaction
        for (int j = 0; j < num_items_per_transaction; j++) {
            int random_index = rand() % num_transactions;
            if (transactions[random_index].items[j] == NULL) {
                transactions[random_index].items[j] = t->items[j];
                break;
            }
        }
    }
    return transactions;
}

int main() {
    srand(time(NULL));
    transaction* transactions = manage_transactions(5, 3);
    for (int i = 0; i < 5; i++) {
        print_transaction(&transactions[i]);
        free_transaction(&transactions[i]);
    }
    free(transactions);
    return 0;
}
