import numpy as np

class Matrix:
    def __init__(self, data):
        self.data = data

    @staticmethod
    def multiply(A, B):
        return np.dot(A.data, B.data)

    @property
    def shape(self):
        return self.data.shape

    @property
    def dtype(self):
        return self.data.dtype

class MatrixLibrary:
    def __init__(self):
        self.config = {}

    def set_config(self, key, value):
        self.config[key] = value

    def get_config(self, key):
        return self.config.get(key)

    def create_matrix(self, shape, dtype):
        data = np.zeros(shape, dtype)
        return Matrix(data)

    def multiply_matrices(self, A, B):
        result_shape = (A.shape[0], B.shape[1])
        result_dtype = A.dtype
        result_data = np.zeros(result_shape, result_dtype)
        for i in range(A.shape[0]):
            for j in range(B.shape[1]):
                for k in range(A.shape[1]):
                    result_data[i, j] += A.data[i, k] * B.data[k, j]
        return Matrix(result_data)

    def parallel_multiply(self, A, B):
        import threading
        results = []

        def worker(a_row, b_col, result):
            for i in range(A.shape[1]):
                result[a_row, b_col] += A.data[a_row, i] * B.data[i, b_col]

        num_threads = self.get_config('num_threads', 4)
        threads = []
        for i in range(num_threads):
            thread = threading.Thread(target=worker,
                                       args=(i % A.shape[0], i // A.shape[0], results[i]))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        return Matrix(results)

    def profile(self, matrix_operation):
        import time
        start_time = time.time()
        result = matrix_operation()
        end_time = time.time()
        execution_time = end_time - start_time
        print(f"Execution time: {execution_time:.2f} seconds")

    def serialize(self, matrix):
        import pickle
        return pickle.dumps(matrix.data)

    def deserialize(self, serialized_data):
        import pickle
        data = pickle.loads(serialized_data)
        return Matrix(data)

    def persist(self, matrix):
        with open("matrix.pkl", "wb") as f:
            f.write(self.serialize(matrix))

    def load_persisted_matrix(self):
        with open("matrix.pkl", "rb") as f:
            serialized_data = f.read()
        return self.deserialize(serialized_data)
