void setup(int* keys, long* offsets, record** records, int numRecords) {
    // Initialize records with random values within a predefined range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i]->value = rand() % 100;
    }
}

void cleanup(record** records, int numRecords) {
    // Free allocated memory and set pointers to NULL
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}

int managePipeline(int* keys, long* offsets, record** records, int numRecords) {
    // Initialize hash table with dynamic resizing
    void** hashTable;
    size_t size = 16;
    int initialized = 0;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        // Resize the hash table as needed
        if (!initialized) {
            hashTable = calloc(size, sizeof(void*));
            initialized = 1;
        } else {
            size *= 2;
            hashTable = realloc(hashTable, size * sizeof(void*));
        }

        for (int i = 0; i < numRecords; i++) {
            // Insert records into the hash table
            pthread_mutex_lock(&lock);
            int index = offsets[i] % size;
            if (!hashTable[index]) {
                hashTable[index] = records[i];
            } else {
                printf("Error: Duplicate key\n");
                return 1;
            }
            pthread_mutex_unlock(&lock);

            // Perform data processing operations
            for (int j = 0; j < numRecords; j++) {
                if (hashTable[j]) {
                    printf("Processing record with value %d\n", ((record*)hashTable[j])->value);
                }
            }
        }

        // Periodically log memory usage statistics
        size_t totalMemoryUsed = 0;
        for (int i = 0; i < size; i++) {
            if (hashTable[i]) {
                totalMemoryUsed += sizeof(void*);
            }
        }
        printf("Total memory used: %zu bytes\n", totalMemoryUsed);

        // Handle errors and cleanup
        if (numRecords == 0) {
            return 0;
        } else {
            cleanup(records, numRecords);
            return 1;
        }
    }

    return 0;
}

int main() {
    int keys[] = {1, 2, 3};
    long offsets[] = {0, 1, 2};
    record* records[3];

    for (int i = 0; i < 3; i++) {
