        // Caching mechanism for frequently accessed struct item pointers within each transaction
        item** cache = (item**)malloc(10 * sizeof(item*));  // Cache size configurable based on performance metrics

        // Ensure each struct item is used at most once across all transactions
        for(int j = 0; j < num_items_in_transaction; j++) {
            int random_index = rand() % 100;
            // Assign random struct item pointer to transaction
            transactions[i].items[j] = items[random_index];
        }
    }

    // Release resources upon function exit
    free(doubles);
    free(strings);
    free(items);
    for(int i = 0; i < num_transactions; i++) {
        free(transactions[i].items);
    }
    free(transactions);

    // Log memory allocation and deallocation activities for debugging and performance analysis purposes
    logging_framework_log_memory_activity("Memory management completed successfully.");
}
