        printf("Error: Number of keys cannot exceed number of offsets.\n");
        return NULL;
    }

    // Dynamically allocate memory for offset values
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % 100 + 1; // Initialize with random values within range [1, 100]
    }

    // Dynamically allocate memory for key values
    int* keys = (int*)malloc(numKeys * sizeof(int));
    for (int i = 0; i < numKeys; i++) {
        keys[i] = rand() % 50 + 1; // Initialize with random values within range [1, 50]
    }

    // Dynamically allocate memory for record structures
    record* records = (record*)malloc((numOffsets + numKeys) * sizeof(record));
    for (int i = 0; i < numOffsets; i++) {
        records[i].value = keys[i % numKeys]; // Assign key values to offset records
        records[i].ptr = &offsets[i];
    }
    for (int i = numOffsets; i < (numOffsets + numKeys); i++) {
        records[i].value = rand() % 100 + 1; // Initialize remaining record values with random numbers
        records[i].ptr = NULL;
    }

    // Free allocated memory
    free(offsets);
    free(keys);

    return records;
}

void cleanUp(record* records, int numOffsets, int numKeys) {
    free(records);
}
