// Define the record structure
typedef struct {
    int key;
    char* value;
} Record;

// Define the linked list node structure
typedef struct Node {
    Record data;
    struct Node* next;
} Node;

// Function to initialize the dynamic linked list
Node* initList() {
    return NULL;
}

// Function to insert a new record at the end of the list
void insertRecord(Node** head_ref, Record* new_record) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->data = *new_record;
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
}

// Function to delete a record from the list
void deleteRecord(Node** head_ref, int key) {
    if (*head_ref == NULL)
        return;

    Node* temp = *head_ref;

    // Check if the node to be deleted is the head node
    if (temp->data.key == key) {
        *head_ref = temp->next;
        free(temp);
        return;
    }

    while (temp->next != NULL && temp->next->data.key != key) {
        temp = temp->next;
    }

    // If node is found then delete it
    if (temp->next != NULL) {
        Node* next = temp->next;
        temp->next = next->next;

        free(next);
    }
}

// Function to traverse the linked list and print records
void traverseList(Node* head) {
    while (head != NULL) {
        printf("Key: %d, Value: %s\n", head->data.key, head->data.value);
        head = head->next;
    }
}
