```java
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class GraphDatabase {
    private final Lock lock = new ReentrantLock();
    private AtomicInteger vertexCount = new AtomicInteger(0);
    private AtomicInteger edgeCount = new AtomicInteger(0);
    private long[] offsetValues;
    private int[][] keyValues;
    private record Record(int value) {}

    public void initializeGraphDatabase(int vertices, int edges) {
        lock.lock();
        try {
            if (vertices > 0 && edges > 0) {
                offsetValues = new long[vertices];
                keyValues = new int[edges][2]; // assuming edge has two vertices
                for (int i = 0; i < vertices; i++) {
                    offsetValues[i] = (long) i;
                }
                for (int i = 0; i < edges; i++) {
                    keyValues[i][0] = (int) Math.random(); // set random properties on edges
                    keyValues[i][1] = (int) Math.random();
                }
            } else {
                throw new RuntimeException("Invalid graph size");
            }
        } finally {
            lock.unlock();
        }
    }

    public void addVertex() {
        lock.lock();
        try {
            vertexCount.incrementAndGet();
            offsetValues = Arrays.copyOf(offsetValues, vertexCount.get());
        } finally {
            lock.unlock();
        }
    }

    public void addEdge(int v1, int v2) {
        lock.lock();
        try {
            edgeCount.incrementAndGet();
            keyValues = Arrays.copyOf(keyValues, edgeCount.get() * 2); // assuming edge has two vertices
            keyValues[edgeCount.get() - 1][0] = v1;
            keyValues[edgeCount.get() - 1][1] = v2;
        } finally {
            lock.unlock();
        }
    }

    public void printGraph() {
        for (int i = 0; i < vertexCount.get(); i++) {
            System.out.println("Vertex " + i + ": " + offsetValues[i]);
        }
        for (int i = 0; i < edgeCount.get(); i++) {
            System.out.println("Edge " + i + ": (" + keyValues[i][0] + ", " + keyValues[i][1] + ")");
        }
    }
}
